        // HAIR v63: catalog complete Hair Presets (.vap), rather than raw .vam
        // components. A single hairstyle can contain several hair/scalp items, so
        // preset-level browsing gives the user coherent styles and lets VaM's native
        // HairPresets storable perform the actual replace/load operation.
        private readonly List<HairPresetEntry> _hairPresetEntries =
            new List<HairPresetEntry>();
        // v149: remember exact Hair component identities learned from presets whose
        // filename/path explicitly identifies them as Facial/Body/Pubic. This lets
        // live components with generic display names (for example separate scrotum
        // hair pieces) survive a head-hairstyle replacement without treating every
        // unknown Hair item as head hair.
        private readonly HashSet<string> _knownNonHeadHairComponentKeys =
            new HashSet<string>(StringComparer.Ordinal);
        // v152: retain the region learned for each concrete Hair component so Head
        // and Facial layers can be edited independently even when a live bank item
        // has a generic display name.
        private readonly Dictionary<string, string> _knownHairComponentRegionByKey =
            new Dictionary<string, string>(StringComparer.Ordinal);
        // v160: exact live-bank display-name aliases learned after a successful Hair
        // switch, kept per Person. Scene/native fallback can expose a target Hair item
        // under a display name that cannot be matched back to geometry (Andi's TKB
        // pubic hair is a confirmed example). These runtime aliases are authoritative
        // for subsequent replace/reset operations, preventing the old target item from
        // being preserved and stacked over the next one.
        private readonly Dictionary<string, Dictionary<string, string>> _runtimeHairRegionByPersonNameKey =
            new Dictionary<string, Dictionary<string, string>>(StringComparer.Ordinal);
        private readonly Dictionary<string, HashSet<string>> _hairPresetRegionsByPath =
            new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
        private readonly HashSet<string> _sceneHairFingerprints =
            new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        // v188 diagnostic: log each structurally interesting but unconfirmed
        // AltFuta INTIMATE HairFemale asset once per catalog scan. This lets us
        // learn additional compatible custom-scalp signatures from the user's
        // actual collection without promoting generic Female pubic hair again.
        private readonly HashSet<string> _altFutaIntimateCandidateDiagLogged =
            new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        private int _altFutaIntimateDiagSeen = 0;
        private int _altFutaIntimateDiagAccepted = 0;
        private string _hairRegion = "Head";
