        private JSONStorableString MakeDerivedString(string name)
        {
            JSONStorableString s = new JSONStorableString(name, "");
            s.isStorable = false;
            s.isRestorable = false;
            RegisterString(s);
            return s;
        }

        private UIDynamicTextField CreateCompactStatusField(JSONStorableString jss, bool rightSide)
        {
            UIDynamicTextField field = CreateTextField(jss, rightSide);
            if (field != null)
            {
                field.height = 48f;
                field.backgroundColor = new Color(0.92f, 0.92f, 0.92f, 0.35f);
                if (field.UItext != null)
                {
                    field.UItext.alignment = TextAnchor.MiddleLeft;
                    field.UItext.supportRichText = false;
                }

                LayoutElement layout = field.GetComponent<LayoutElement>();
                if (layout != null)
                {
                    layout.preferredHeight = 48f;
                    layout.minHeight = 48f;
                }
            }
            return field;
        }

        private void CreateStatusHeader(string text, bool rightSide)
        {
            JSONStorableString header = new JSONStorableString("Status Header", text);
            header.isStorable = false;
            header.isRestorable = false;
            header.hidden = true;

            UIDynamicTextField field = CreateTextField(header, rightSide);
            if (field != null)
            {
                field.height = 38f;
                field.backgroundColor = new Color(0f, 0f, 0f, 0f);
                if (field.UItext != null)
                {
                    field.UItext.alignment = TextAnchor.MiddleLeft;
                    field.UItext.fontStyle = FontStyle.Bold;
                }

                LayoutElement layout = field.GetComponent<LayoutElement>();
                if (layout != null)
                {
                    layout.preferredHeight = 38f;
                    layout.minHeight = 38f;
                }
            }
        }

        // VaM's built-in CreateTextField is display-only. This wraps it with a real
        // Unity InputField so the user can type into it.
        private UIDynamicTextField CreateEditableInputField(JSONStorableString jss, bool rightSide, string placeholderLabel)
        {
            UIDynamicTextField field = CreateTextField(jss, rightSide);
            if (field == null || field.UItext == null)
                return field;

            field.height = 55f;
            field.backgroundColor = Color.white;

            LayoutElement layout = field.GetComponent<LayoutElement>();
            if (layout != null)
            {
                layout.preferredHeight = 55f;
                layout.minHeight = 55f;
            }

            field.UItext.supportRichText = false;
            field.UItext.alignment = TextAnchor.MiddleLeft;
            field.UItext.color = Color.black;

            InputField input = field.UItext.gameObject.AddComponent<InputField>();
            input.textComponent = field.UItext;
            input.lineType = InputField.LineType.SingleLine;
            input.text = jss.val;

            input.onValueChanged.AddListener(delegate(string value)
            {
                jss.val = value;
                OnSelectedButtonNameEdited(value);
            });

            // This public VaM field is the long-standing 1.x way to bind an input
            // field to a JSONStorableString.
            jss.inputField = input;

            return field;
        }

        private UIDynamicTextField CreateGenericEditableInputField(JSONStorableString jss, bool rightSide)
        {
            UIDynamicTextField field = CreateTextField(jss, rightSide);
            if (field == null || field.UItext == null)
                return field;

            field.height = 55f;
            field.backgroundColor = Color.white;

            LayoutElement layout = field.GetComponent<LayoutElement>();
            if (layout != null)
            {
                layout.preferredHeight = 55f;
                layout.minHeight = 55f;
            }

            field.UItext.supportRichText = false;
            field.UItext.alignment = TextAnchor.MiddleLeft;
            field.UItext.color = Color.black;

            InputField input = field.UItext.gameObject.AddComponent<InputField>();
            input.textComponent = field.UItext;
            input.lineType = InputField.LineType.SingleLine;
            input.text = jss.val;

            input.onValueChanged.AddListener(delegate(string value)
            {
                jss.val = value == null ? "" : value.Trim();
                UpdateSpawnStatus();
            });

            jss.inputField = input;
            return field;
        }

        private void OnSelectedButtonNameEdited(string value)
        {
            PersonEntry selected = GetSelectedPerson();
            if (selected == null || string.IsNullOrEmpty(selected.uid))
                return;

            string cleaned = value == null ? "" : value.Replace("\t", " ").Replace("\r", " ").Replace("\n", " ").Trim();

            if (string.IsNullOrEmpty(cleaned) || cleaned == selected.uid)
            {
                _aliases.Remove(selected.uid);
                EnsureFriendlyCharacterNames();
            }
            else
            {
                _aliases[selected.uid] = cleaned;
                SaveAliasesData();
            }

            SyncSelectedButtonName();
            RebuildRosterButtons();
        }

        private void SetCharacterDisplayName(string uid, string displayName)
        {
            if (string.IsNullOrEmpty(uid))
                return;

            string cleaned = displayName == null
                ? ""
                : displayName.Replace("\t", " ")
                             .Replace("\r", " ")
                             .Replace("\n", " ")
                             .Trim();

            if (string.IsNullOrEmpty(cleaned))
                return;

            _aliases[uid] = cleaned;
            SaveAliasesData();

            if (_selectedCharacter != null &&
                string.Equals(
                    _selectedCharacter.val,
                    uid,
                    StringComparison.Ordinal))
            {
                SyncSelectedButtonName();
            }
        }

        private string GetDisplayNameForLookPath(string path)
        {
            AppearanceEntry entry = FindAppearanceEntryByPath(path);

            if (entry != null && !string.IsNullOrEmpty(entry.label))
                return entry.label;

            AppearanceEntry sceneEntry =
                FindSceneAppearanceEntryByTempPath(path);

            if (sceneEntry != null && !string.IsNullOrEmpty(sceneEntry.label))
                return sceneEntry.label;

            return GetPresetLabel(path);
        }

        private void SyncSelectedButtonName()
        {
            if (_selectedButtonName == null)
                return;

            PersonEntry selected = GetSelectedPerson();
            string value = selected == null ? "" : GetDisplayName(selected);
            _selectedButtonName.valNoCallback = value;

            if (_selectedButtonName.inputField != null)
                _selectedButtonName.inputField.text = value;
        }

        private bool IsAutomaticFriendlyName(string value, out int number)
        {
            number = 0;
            if (string.IsNullOrEmpty(value))
                return false;

            const string prefix = "Character ";
            if (!value.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                return false;

            string suffix = value.Substring(prefix.Length).Trim();
            int parsed;
            if (!int.TryParse(suffix, out parsed) || parsed < 1)
                return false;

            number = parsed;
            return true;
        }

        private void EnsureFriendlyCharacterNames()
        {
            if (_persons.Count == 0)
                return;

            // Reserve all existing Character N labels, including manually preserved ones.
            HashSet<int> usedNumbers = new HashSet<int>();
            foreach (KeyValuePair<string, string> kv in _aliases)
            {
                int n;
                if (IsAutomaticFriendlyName(kv.Value, out n))
                    usedNumbers.Add(n);
            }

            bool changed = false;
            int next = 1;

            for (int i = 0; i < _persons.Count; i++)
            {
                PersonEntry person = _persons[i];
                if (person == null || string.IsNullOrEmpty(person.uid))
                    continue;

                string existing;
                if (_aliases.TryGetValue(person.uid, out existing) &&
                    !string.IsNullOrEmpty(existing))
                {
                    continue;
                }

                while (usedNumbers.Contains(next))
                    next++;

                _aliases[person.uid] = "Character " + next;
                usedNumbers.Add(next);
                next++;
                changed = true;
            }

            if (changed)
                SaveAliasesData();
        }

        private void PruneAliasesForMissingPersons()
        {
            // Do not prune while VaM is loading or while CharacterFactory is changing
            // SubScene-qualified UIDs into normal scene UIDs.
            if (SuperController.singleton == null ||
                SuperController.singleton.isLoading ||
                _controlledSpawnInProgress)
            {
                return;
            }

            HashSet<string> live = new HashSet<string>();
            for (int i = 0; i < _persons.Count; i++)
            {
                if (_persons[i] != null && !string.IsNullOrEmpty(_persons[i].uid))
                    live.Add(_persons[i].uid);
            }

            List<string> stale = new List<string>();
            foreach (KeyValuePair<string, string> kv in _aliases)
            {
                if (!live.Contains(kv.Key))
                    stale.Add(kv.Key);
            }

            if (stale.Count == 0)
                return;

            for (int i = 0; i < stale.Count; i++)
                _aliases.Remove(stale[i]);

            SaveAliasesData();
        }

        private string GetDisplayName(PersonEntry person)
        {
            if (person == null)
                return "";

            string alias;
            if (_aliases.TryGetValue(person.uid, out alias) && !string.IsNullOrEmpty(alias))
                return alias;

            return person.uid;
        }

        private void LoadAliasesData()
        {
            if (_aliasesData == null)
                return;

            string raw = _aliasesData.val == null ? "" : _aliasesData.val;
            if (raw == _lastAliasesData)
                return;

            _lastAliasesData = raw;
            _aliases.Clear();

            string[] lines = raw.Split(new char[] { '\n' }, StringSplitOptions.RemoveEmptyEntries);
            for (int i = 0; i < lines.Length; i++)
            {
                string[] pair = lines[i].Split(new char[] { '\t' }, 2);
                if (pair.Length != 2)
                    continue;

                string uid = pair[0].Trim();
                string alias = pair[1].Trim();
                if (!string.IsNullOrEmpty(uid) && !string.IsNullOrEmpty(alias))
                    _aliases[uid] = alias;
            }
        }

        private void SaveAliasesData()
        {
            if (_aliasesData == null)
                return;

            string raw = "";
            foreach (KeyValuePair<string, string> kv in _aliases)
            {
                string uid = kv.Key.Replace("\t", " ").Replace("\r", " ").Replace("\n", " ");
                string alias = kv.Value.Replace("\t", " ").Replace("\r", " ").Replace("\n", " ");
                raw += uid + "\t" + alias + "\n";
            }

