        private void PruneActiveLooksForMissingPersons()
        {
            if (SuperController.singleton == null ||
                SuperController.singleton.isLoading ||
                _controlledSpawnInProgress)
            {
                return;
            }

            HashSet<string> live = new HashSet<string>();

            for (int i = 0; i < _persons.Count; i++)
            {
                PersonEntry person = _persons[i];
                if (person != null && !string.IsNullOrEmpty(person.uid))
                    live.Add(person.uid);
            }

            List<string> stale = new List<string>();

            foreach (KeyValuePair<string, string> kv in _activeLookByPerson)
            {
                if (!live.Contains(kv.Key))
                    stale.Add(kv.Key);
            }

            if (stale.Count == 0)
                return;

            for (int i = 0; i < stale.Count; i++)
                _activeLookByPerson.Remove(stale[i]);

            SaveActiveLooksData();
        }

