        private string NormalizeEditableHairRegion(string region)
        {
            if (string.Equals(region, "Facial", StringComparison.OrdinalIgnoreCase))
                return "Facial";
            if (string.Equals(region, "Body", StringComparison.OrdinalIgnoreCase))
                return "Body";
            if (string.Equals(region, "Pubic", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(region, "Intimate", StringComparison.OrdinalIgnoreCase))
                return "Pubic";
            return "Head";
        }

        private string GetHairRegionDisplayName(string region)
        {
            string normalized = NormalizeEditableHairRegion(region);
            return string.Equals(normalized, "Pubic", StringComparison.OrdinalIgnoreCase)
                ? "INTIMATE"
                : normalized.ToUpperInvariant();
        }

        private string GetHairActiveKey(string uid, string region)
        {
            if (string.IsNullOrEmpty(uid))
                return "";
            string r = NormalizeEditableHairRegion(region);
            return uid + "|" + r;
        }

        private void LoadActiveHairPresetsData()
        {
            if (_activeHairPresetsData == null)
                return;

            string raw = _activeHairPresetsData.val == null
                ? ""
                : _activeHairPresetsData.val;

            if (raw == _lastActiveHairPresetsData)
                return;

            _lastActiveHairPresetsData = raw;
            _activeHairPresetByPerson.Clear();

            string[] lines = raw.Split(
                new char[] { '\n' },
                StringSplitOptions.RemoveEmptyEntries
            );

            for (int i = 0; i < lines.Length; i++)
            {
                string[] pair = lines[i].Split(new char[] { '\t' }, 2);
                if (pair.Length != 2)
                    continue;

                string uid = pair[0].Trim();
                string path = pair[1].Trim();

                if (string.IsNullOrEmpty(uid) || string.IsNullOrEmpty(path))
                    continue;

                // v152 migration: v151 and older stored one active hairstyle per
                // Person under the raw UID. Treat that legacy entry as Head.
                string key = uid.IndexOf("|Head", StringComparison.Ordinal) >= 0 ||
                             uid.IndexOf("|Facial", StringComparison.Ordinal) >= 0 ||
                             uid.IndexOf("|Body", StringComparison.Ordinal) >= 0 ||
                             uid.IndexOf("|Pubic", StringComparison.Ordinal) >= 0
                    ? uid
                    : GetHairActiveKey(uid, "Head");
                _activeHairPresetByPerson[key] = path;
            }
        }

