        private void LoadOriginalHairSnapshotsData()
        {
            if (_originalHairSnapshotsData == null)
                return;

            string raw = _originalHairSnapshotsData.val == null
                ? ""
                : _originalHairSnapshotsData.val;

            if (raw == _lastOriginalHairSnapshotsData)
                return;

            _lastOriginalHairSnapshotsData = raw;
            _originalHairSnapshotByPerson.Clear();
            _originalHairSnapshotJsonByPerson.Clear();

            string[] lines = raw.Split(
                new char[] { '\n' },
                StringSplitOptions.RemoveEmptyEntries
            );

            for (int i = 0; i < lines.Length; i++)
            {
                string[] pair = lines[i].Split(new char[] { '	' }, 2);
                if (pair.Length != 2)
                    continue;

                string uid = pair[0].Trim();
                string path = NormalizePathSlashes(pair[1].Trim());
                if (string.IsNullOrEmpty(uid) || string.IsNullOrEmpty(path))
                    continue;

                // Keep only valid CharacterRouter Hair presets. Old v65-v67
                // guessed file paths that frequently never existed; silently drop
                // those and capture a fresh baseline on the next edit.
                if (path.ToLowerInvariant().Contains("characterrouter_hairreset_") &&
                    path.ToLowerInvariant().Contains("/preset_"))
                {
                    bool exists = false;
                    try { exists = FileManagerSecure.FileExists(path); }
                    catch { }
                    if (exists)
                        _originalHairSnapshotByPerson[uid] = path;
                }
            }
        }

