        private void ClearHairEditStateForPerson(
            string uid,
            bool clearOriginalSnapshot)
        {
            if (string.IsNullOrEmpty(uid))
                return;

            bool activeChanged = false;
            activeChanged = _activeHairPresetByPerson.Remove(GetHairActiveKey(uid, "Head")) || activeChanged;
            activeChanged = _activeHairPresetByPerson.Remove(GetHairActiveKey(uid, "Facial")) || activeChanged;
            activeChanged = _activeHairPresetByPerson.Remove(GetHairActiveKey(uid, "Body")) || activeChanged;
            activeChanged = _activeHairPresetByPerson.Remove(GetHairActiveKey(uid, "Pubic")) || activeChanged;
            // Legacy v151 key, harmless if absent.
            activeChanged = _activeHairPresetByPerson.Remove(uid) || activeChanged;
            bool originalChanged = false;

            if (clearOriginalSnapshot)
            {
                originalChanged = _originalHairSnapshotByPerson.Remove(uid);
                _originalHairSnapshotJsonByPerson.Remove(uid);
                _originalActiveHairItemsByPerson.Remove(uid);
                _originalActiveHairItemsByRegion.Remove(GetHairActiveKey(uid, "Head"));
                _originalActiveHairItemsByRegion.Remove(GetHairActiveKey(uid, "Facial"));
                _originalActiveHairItemsByRegion.Remove(GetHairActiveKey(uid, "Body"));
                _originalActiveHairItemsByRegion.Remove(GetHairActiveKey(uid, "Pubic"));
                _runtimeHairRegionByPersonNameKey.Remove(uid);
                _nativeFutanariHairAdapter.ClearPerson(uid);
                _altFutaHairAdapter.ClearPerson(uid);
                _externalHairAdapter.ClearPerson(uid);
            }

            if (activeChanged)
                SaveActiveHairPresetsData();

            if (originalChanged)
                SaveOriginalHairSnapshotsData();
        }

