        private void RecordRecentLook(string path)
        {
            if (string.IsNullOrEmpty(path))
                return;

            for (int i = _recentLookPaths.Count - 1; i >= 0; i--)
            {
                if (string.Equals(
                    _recentLookPaths[i],
                    path,
                    StringComparison.OrdinalIgnoreCase))
                {
                    _recentLookPaths.RemoveAt(i);
                }
            }

            _recentLookPaths.Insert(0, path);

            while (_recentLookPaths.Count > MAX_RECENT_LOOKS)
                _recentLookPaths.RemoveAt(_recentLookPaths.Count - 1);

            SaveRecentLooksData();
        }

