        private string SanitizeSnapshotName(string uid)
        {
            string value = string.IsNullOrEmpty(uid) ? "Person" : uid;
            char[] invalid = new char[]
            {
                '/', '\\', ':', '*', '?', '"', '<', '>', '|', '#', ' '
            };

            for (int i = 0; i < invalid.Length; i++)
                value = value.Replace(invalid[i], '_');

            return value;
        }

        private JSONStorableString GetAppearanceControlPresetName(
            JSONStorable appearanceControl)
        {
            if (appearanceControl == null)
                return null;

            JSONStorableString presetName =
                appearanceControl.GetStringJSONParam("PresetName");

            if (presetName == null)
                presetName =
                    appearanceControl.GetStringJSONParam("presetName");

            return presetName;
        }

        private bool EnsureOriginalAppearanceSnapshot(
            PersonEntry person,
            out string warning)
        {
            warning = "";

            if (person == null ||
                person.atom == null ||
                string.IsNullOrEmpty(person.uid))
            {
                warning = "No selected Person.";
                return false;
            }

            if (_originalLookByPerson.ContainsKey(person.uid))
                return true;

            // v25/v26 tried to reuse AppearancePresets.presetBrowsePath when possible.
            // In VaM that field can already point at the first preset being selected,
            // so Reset could accidentally capture Look #1 instead of the pre-change
            // appearance. v27 always snapshots the actual current AppearanceControl
            // state before any catalog Look is applied.
            try
            {
                JSONStorable appearanceControl =
                    person.atom.GetStorableByID("AppearanceControl");

                if (appearanceControl == null)
                {
                    warning =
                        "Original appearance could not be snapshotted.";
                    return false;
                }

                JSONStorableString presetName =
                    GetAppearanceControlPresetName(appearanceControl);

                JSONStorableAction storeAction =
                    appearanceControl.GetAction("StorePreset");

                if (presetName == null ||
                    storeAction == null ||
                    storeAction.actionCallback == null)
                {
                    warning =
                        "Original appearance snapshot API is unavailable.";
                    return false;
                }

                string oldName = presetName.val;

                // Stable per-UID snapshot name. If VaM reuses a UID after deletion,
                // v26/v27 clears per-Person state and this StorePreset overwrites that
                // old reset file with the fresh actor's actual baseline.
                string snapshotName =
                    "__CharacterRouter_Reset_" +
                    SanitizeSnapshotName(person.uid);

                presetName.val = snapshotName;

                try
                {
                    storeAction.actionCallback();
                }
                finally
                {
                    presetName.val = oldName;
                }

                _originalLookByPerson[person.uid] =
                    "LEGACY:" + snapshotName;

                SaveOriginalLooksData();
                return true;
            }
            catch (Exception e)
            {
                warning = "Snapshot failed: " + e.Message;
                return false;
            }
        }

        private bool LoadLegacyAppearanceSnapshot(
            Atom person,
            string snapshotName,
            out string error)
        {
            error = "";

            try
            {
                JSONStorable appearanceControl =
                    person.GetStorableByID("AppearanceControl");

                if (appearanceControl == null)
                {
                    error = "AppearanceControl unavailable.";
                    return false;
                }

                JSONStorableString presetName =
                    GetAppearanceControlPresetName(appearanceControl);

                JSONStorableAction loadAction =
                    appearanceControl.GetAction("LoadPreset");

                if (presetName == null ||
                    loadAction == null ||
                    loadAction.actionCallback == null)
                {
                    error = "AppearanceControl LoadPreset unavailable.";
                    return false;
                }

                string oldName = presetName.val;
                presetName.val = snapshotName;

                try
                {
                    loadAction.actionCallback();
                }
                finally
                {
                    presetName.val = oldName;
                }

                return true;
            }
            catch (Exception e)
            {
                error = e.Message;
                return false;
            }
        }

        private void HandleLookResetOrCancel()
        {
            if (IsCharacterCreationMode())
                CancelCharacterCreation();
            else
                ResetSelectedCharacterLook();
        }

        private void ResetSelectedCharacterLook()
        {
            PersonEntry selected = GetSelectedPerson();

            if (selected == null || selected.atom == null)
            {
                UpdateLookHudStatus("LOOKS — no selected Character");
                return;
            }

            string snapshot;

            if (!_originalLookByPerson.TryGetValue(
                    selected.uid,
                    out snapshot) ||
                string.IsNullOrEmpty(snapshot))
            {
                UpdateLookHudStatus(
                    "LOOKS — RESET unavailable: this Character was not created from the Look picker"
                );
                return;
            }

            string path = "";
            string stableLookKey = "";
            string displayName = "";
            string error = "";

            if (snapshot.StartsWith(
                    "LOOKKEY:",
                    StringComparison.OrdinalIgnoreCase))
            {
                stableLookKey = snapshot.Substring(8);
                AppearanceEntry entry =
                    FindAppearanceEntryByPath(stableLookKey);

                if (entry == null ||
                    !ResolveAppearanceLoadPath(
                        entry,
                        out path,
                        out error))
                {
                    UpdateLookHudStatus(
                        "LOOKS — reset failed: source scene Look is unavailable" +
                        (string.IsNullOrEmpty(error) ? "" : ": " + error)
                    );
                    return;
                }

                displayName = entry.label;
            }
            else if (snapshot.StartsWith(
                         "PATH:",
                         StringComparison.OrdinalIgnoreCase))
            {
                path = snapshot.Substring(5);
                stableLookKey = path;

                AppearanceEntry sceneEntry =
                    FindSceneAppearanceEntryByTempPath(path);

                if (sceneEntry != null)
                {
                    stableLookKey = sceneEntry.path;
                    displayName = sceneEntry.label;
                    _originalLookByPerson[selected.uid] =
                        "LOOKKEY:" + sceneEntry.path;
                    SaveOriginalLooksData();
                }
                else
                {
                    displayName = GetDisplayNameForLookPath(path);
                }
            }
            else
            {
                UpdateLookHudStatus(
                    "LOOKS — RESET unavailable: unsupported creation snapshot"
                );
                return;
            }

            // Remove only adapter-owned model plugins from the current Look.
            // User-added Person plugins are intentionally preserved.
            _modelPluginAdapter.ClearManaged(selected.atom);
            _sceneCuaAccessoryAdapter.ClearManaged(selected.atom);

            bool ok = ApplyAppearancePresetWithPath(
                selected.atom,
                path,
                out error
            );

            if (!ok)
            {
                UpdateLookHudStatus(
                    "LOOKS — reset failed: " + error
                );
                return;
            }

            AppearanceEntry resetPluginEntry =
                FindAppearanceEntryByPath(stableLookKey);

            if (resetPluginEntry == null)
                resetPluginEntry =
                    FindSceneAppearanceEntryByTempPath(path);

            if (resetPluginEntry != null)
            {
                StartCoroutine(
                    RestoreResetLookPluginsAndHeadTracking(
                        selected.atom,
                        resetPluginEntry.source,
                        resetPluginEntry.label,
                        resetPluginEntry.path,
                        resetPluginEntry.isSceneLook
                            ? resetPluginEntry.scenePath
                            : "",
                        resetPluginEntry.isSceneLook
                            ? resetPluginEntry.sceneAtomId
                            : ""
                    )
                );
            }
            else
            {
                StartCoroutine(ApplyHeadTrackingPolicy(selected.atom));
            }

            _activeLookByPerson[selected.uid] = stableLookKey;
            SaveActiveLooksData();
            RecordRecentLook(stableLookKey);

            SetCharacterDisplayName(
                selected.uid,
                displayName
            );
            ClearBodyBaselineForPerson(selected.uid);
            ClearFaceBaselineForPerson(selected.uid);
            ClearActiveBodyPresetForPerson(
                selected.uid
            );
            ClearHairEditStateForPerson(selected.uid, true);
            RebuildRosterButtons();

            if (_selectedLookPath != null)
                _selectedLookPath.valNoCallback =
                    "Reset to creation Look: " + path;

            UpdateLookHudStatus("LOOKS — reset to creation Look");
            RebuildLookCatalogPage();
        }

        private IEnumerator RestoreResetLookPluginsAndHeadTracking(
            Atom person,
            string sourcePackage,
            string lookLabel,
            string lookPath,
            string scenePath,
            string sceneAtomId)
        {
            yield return _modelPluginAdapter.ApplyForLook(
                person, sourcePackage, lookLabel, scenePath, sceneAtomId,
                _followCameraWithHead != null && !_followCameraWithHead.val
            );
            yield return StartCoroutine(ApplyHeadTrackingPolicy(person));
            yield return _sceneMorphParityAdapter.ApplyForLook(
                person, sourcePackage, lookPath);
            yield return _sceneCuaAccessoryAdapter.ApplyFromScene(
                person, scenePath, sceneAtomId, sourcePackage, lookLabel);
        }

        private IEnumerator ApplyHeadTrackingPolicy(Atom person)
        {
            if (person == null || _followCameraWithHead == null ||
                _followCameraWithHead.val)
                yield break;

            // Author plugins can finish registering their dynamic storables a few
            // frames after the model plugin adapter returns.
            yield return new WaitForEndOfFrame();
            yield return null;
            yield return new WaitForFixedUpdate();
            _headTrackingAdapter.DisableCameraHeadTracking(person);
        }

        private void ToggleFavoriteLook(string path)
        {
            if (string.IsNullOrEmpty(path))
                return;

            if (_favoriteLookPaths.Contains(path))
                _favoriteLookPaths.Remove(path);
            else
                _favoriteLookPaths.Add(path);

            SaveFavoriteLooksData();
            RebuildLookCatalogPage();
        }

        private void MigrateLookResetStateIfNeeded()
        {
            if (_lookResetSchemaVersion == null)
                return;

            if (string.Equals(
                    _lookResetSchemaVersion.val,
                    LOOK_RESET_SCHEMA_VERSION,
                    StringComparison.Ordinal))
            {
                return;
            }

            // v25-v27 snapshot reset baselines are obsolete in v28. Reset now uses the creation Look path. VaM can reuse the same
            // UID after an atom is deleted, which made a newly-created Person inherit
            // a deleted Person's reset appearance. Existing v25 baselines are therefore
            // unsafe and are discarded once during migration to v26.
            _originalLookByPerson.Clear();
            SaveOriginalLooksData();

            _lookResetSchemaVersion.valNoCallback =
                LOOK_RESET_SCHEMA_VERSION;
        }

        private void ClearPerPersonStateForFreshAtom(string uid)
        {
            if (string.IsNullOrEmpty(uid))
                return;

            bool aliasesChanged = _aliases.Remove(uid);
            bool activeChanged = _activeLookByPerson.Remove(uid);
            bool originalChanged = _originalLookByPerson.Remove(uid);

            if (aliasesChanged)
                SaveAliasesData();

            if (activeChanged)
                SaveActiveLooksData();

            if (originalChanged)
                SaveOriginalLooksData();

            // A recycled Person UID must never inherit a previous Character's
            // FACE/BODY state.
            ClearFaceBaselineForPerson(uid);
            ClearBodyProfileForPerson(uid);
            ClearBodyBaselineForPerson(uid);
            ClearActiveBodyPresetForPerson(uid);
            ClearHairEditStateForPerson(uid, true);
        }

        private void PruneOriginalLooksForMissingPersons()
        {
            if (SuperController.singleton == null ||
                SuperController.singleton.isLoading ||
                _controlledSpawnInProgress)
            {
                return;
            }

            HashSet<string> live = new HashSet<string>();

            for (int i = 0; i < _persons.Count; i++)
            {
                PersonEntry person = _persons[i];

                if (person != null &&
                    !string.IsNullOrEmpty(person.uid))
                {
                    live.Add(person.uid);
                }
            }

            List<string> stale = new List<string>();

            foreach (KeyValuePair<string, string> kv in _originalLookByPerson)
            {
                if (!live.Contains(kv.Key))
                    stale.Add(kv.Key);
            }

            if (stale.Count == 0)
                return;

            for (int i = 0; i < stale.Count; i++)
                _originalLookByPerson.Remove(stale[i]);

            SaveOriginalLooksData();
        }

        private void LoadFavoriteBodyPresetsData()
        {
            if (_favoriteBodyPresetsData == null)
                return;

            string raw =
                _favoriteBodyPresetsData.val == null
                ? ""
                : _favoriteBodyPresetsData.val;

            if (raw == _lastFavoriteBodyPresetsData)
                return;

            _lastFavoriteBodyPresetsData = raw;
            _favoriteBodyPresetPaths.Clear();

            string[] lines = raw.Split(
                new char[] { '\n' },
                StringSplitOptions.RemoveEmptyEntries
            );

            for (int i = 0; i < lines.Length; i++)
            {
                string path = lines[i].Trim();
                if (!string.IsNullOrEmpty(path))
                    _favoriteBodyPresetPaths.Add(path);
            }
        }

        private void SaveFavoriteBodyPresetsData()
        {
            if (_favoriteBodyPresetsData == null)
                return;

            List<string> ordered =
                new List<string>(_favoriteBodyPresetPaths);
            ordered.Sort(StringComparer.OrdinalIgnoreCase);

            string raw = "";
            for (int i = 0; i < ordered.Count; i++)
                raw += ordered[i] + "\n";

            _lastFavoriteBodyPresetsData = raw;
            _favoriteBodyPresetsData.valNoCallback = raw;
        }

        private void LoadRecentBodyPresetsData()
        {
            if (_recentBodyPresetsData == null)
                return;

            string raw =
                _recentBodyPresetsData.val == null
                ? ""
                : _recentBodyPresetsData.val;

            if (raw == _lastRecentBodyPresetsData)
                return;

            _lastRecentBodyPresetsData = raw;
            _recentBodyPresetPaths.Clear();

            string[] lines = raw.Split(
                new char[] { '\n' },
                StringSplitOptions.RemoveEmptyEntries
            );

            for (int i = 0;
                 i < lines.Length &&
                 _recentBodyPresetPaths.Count < MAX_RECENT_BODY_PRESETS;
                 i++)
            {
                string path = lines[i].Trim();

                if (!string.IsNullOrEmpty(path) &&
                    !_recentBodyPresetPaths.Contains(path))
                {
                    _recentBodyPresetPaths.Add(path);
                }
            }
        }

        private void SaveRecentBodyPresetsData()
        {
            if (_recentBodyPresetsData == null)
                return;

            string raw = "";

            for (int i = 0;
                 i < _recentBodyPresetPaths.Count &&
                 i < MAX_RECENT_BODY_PRESETS;
                 i++)
            {
                raw += _recentBodyPresetPaths[i] + "\n";
            }

            _lastRecentBodyPresetsData = raw;
            _recentBodyPresetsData.valNoCallback = raw;
        }

        private void RecordRecentBodyPreset(string path)
        {
            if (string.IsNullOrEmpty(path))
                return;

            for (int i =
                     _recentBodyPresetPaths.Count - 1;
                 i >= 0;
                 i--)
            {
                if (string.Equals(
                        _recentBodyPresetPaths[i],
                        path,
                        StringComparison.OrdinalIgnoreCase))
                {
                    _recentBodyPresetPaths.RemoveAt(i);
                }
            }

            _recentBodyPresetPaths.Insert(0, path);

            while (_recentBodyPresetPaths.Count >
                   MAX_RECENT_BODY_PRESETS)
            {
                _recentBodyPresetPaths.RemoveAt(
                    _recentBodyPresetPaths.Count - 1
                );
            }

            SaveRecentBodyPresetsData();
        }

        private void LoadActiveBodyPresetsData()
        {
            if (_activeBodyPresetsData == null)
                return;

            string raw =
                _activeBodyPresetsData.val == null
                ? ""
                : _activeBodyPresetsData.val;

            if (raw == _lastActiveBodyPresetsData)
                return;

            _lastActiveBodyPresetsData = raw;
            _activeBodyPresetByPerson.Clear();

            string[] lines = raw.Split(
                new char[] { '\n' },
                StringSplitOptions.RemoveEmptyEntries
            );

            for (int i = 0; i < lines.Length; i++)
            {
                string[] pair =
                    lines[i].Split(
                        new char[] { '\t' },
                        2
                    );

                if (pair.Length != 2)
                    continue;

                string uid = pair[0].Trim();
                string path = pair[1].Trim();

                if (!string.IsNullOrEmpty(uid) &&
                    !string.IsNullOrEmpty(path))
                {
                    _activeBodyPresetByPerson[uid] = path;
                }
            }
        }

        private void SaveActiveBodyPresetsData()
        {
            if (_activeBodyPresetsData == null)
                return;

            string raw = "";

            foreach (KeyValuePair<string, string> kv
                     in _activeBodyPresetByPerson)
            {
                string uid =
                    (kv.Key == null ? "" : kv.Key)
                    .Replace("\t", " ")
                    .Replace("\r", " ")
                    .Replace("\n", " ");

                string path =
                    (kv.Value == null ? "" : kv.Value)
                    .Replace("\t", " ")
                    .Replace("\r", " ")
                    .Replace("\n", " ");

                if (!string.IsNullOrEmpty(uid) &&
                    !string.IsNullOrEmpty(path))
                {
                    raw += uid + "\t" + path + "\n";
                }
            }

            _lastActiveBodyPresetsData = raw;
            _activeBodyPresetsData.valNoCallback = raw;
        }

        private void ClearActiveBodyPresetForPerson(string uid)
        {
            if (string.IsNullOrEmpty(uid))
                return;

            if (_activeBodyPresetByPerson.Remove(uid))
                SaveActiveBodyPresetsData();
        }

        private void LoadBodyProfilesData()
        {
            if (_bodyProfilesData == null)
                return;

            string raw =
                _bodyProfilesData.val == null
                ? ""
                : _bodyProfilesData.val;

            if (raw == _lastBodyProfilesData)
                return;

            _lastBodyProfilesData = raw;
            _bodyProfileByPerson.Clear();

            string[] lines = raw.Split(
                new char[] { '\n' },
                StringSplitOptions.RemoveEmptyEntries
            );

            for (int i = 0; i < lines.Length; i++)
            {
                string[] parts = lines[i].Split(
                    new char[] { '\t' },
                    2
                );

                if (parts.Length != 2)
                    continue;

                string code = parts[1].Trim().ToUpperInvariant();

                if (code != "F" &&
                    code != "M" &&
                    code != "X")
                {
                    continue;
                }

                _bodyProfileByPerson[parts[0]] = code;
            }
        }

        private void SaveBodyProfilesData()
        {
            if (_bodyProfilesData == null)
                return;

            string raw = "";

            foreach (KeyValuePair<string, string> kv
                     in _bodyProfileByPerson)
            {
                if (string.IsNullOrEmpty(kv.Key) ||
                    string.IsNullOrEmpty(kv.Value))
                {
                    continue;
                }

                raw +=
                    kv.Key.Replace("\t", " ")
                          .Replace("\r", " ")
                          .Replace("\n", " ") +
                    "\t" +
                    kv.Value +
                    "\n";
            }

            _lastBodyProfilesData = raw;
            _bodyProfilesData.valNoCallback = raw;
        }

        private void ClearBodyProfileForPerson(string uid)
        {
            if (string.IsNullOrEmpty(uid))
                return;

            if (_bodyProfileByPerson.Remove(uid))
                SaveBodyProfilesData();
        }

        private string GetBodyProfile(
            PersonEntry person)
        {
            if (person == null)
                return "F";

            // v141 hard isolation: only NativeFutanariAdapter owns native X.
            // Historical/manual _bodyProfileByPerson values are intentionally
            // ignored so an ordinary Female/Male can never enter Futanari
            // lifecycle because of stale serialized Router state.
            if (IsActiveNativeFutanariPerson(person))
                return "X";

            if (person.sex == "M")
                return "M";

            return "F";
        }

        private bool IsActiveAltFutaPerson(PersonEntry person)
        {
            if (person == null || string.IsNullOrEmpty(person.uid))
                return false;

            string activeLookPath;
            if (!_activeLookByPerson.TryGetValue(person.uid, out activeLookPath))
                return false;

            AppearanceEntry activeEntry =
                FindAppearanceEntryByPath(activeLookPath);

            return activeEntry != null && activeEntry.isAltFuta;
        }

        private bool IsActiveNativeFutanariPerson(PersonEntry person)
        {
            if (person == null)
                return false;

            // Strongest runtime signal: the currently active Look was classified
            // by NativeFutanariAdapter, never by a manually selected BODY profile.
            if (!string.IsNullOrEmpty(person.uid))
            {
                string activeLookPath;
                if (_activeLookByPerson.TryGetValue(
                        person.uid,
                        out activeLookPath))
                {
                    AppearanceEntry activeEntry =
                        FindAppearanceEntryByPath(activeLookPath);

                    if (activeEntry != null &&
                        !activeEntry.isAltFuta &&
                        activeEntry.sex == "X")
                    {
                        return true;
                    }
                }
            }

            // Fallback for a live native-Futa Person that existed before Router
            // recorded an active Look. This adapter never classifies AltFuta.
            return person.atom != null &&
                   _nativeFutanariAdapter.IsNativeFutanariAtom(person.atom);
        }

        private string GetBodyEditorProfile(PersonEntry person)
        {
            // Editor-only logical profile. AltFuta gets the same combined
            // Female-body + Male-genital controls as Futanari without writing X
            // into the native Person/body lifecycle state.
            if (IsActiveAltFutaPerson(person))
                return "X";

            return GetBodyProfile(person);
        }

        private string GetAppearanceCatalogSex(AppearanceEntry entry)
        {
            if (entry == null)
                return "?";

            return entry.isAltFuta ? "X" : entry.sex;
        }

        private string GetCharacterCatalogSex(PersonEntry person)
        {
            if (person == null)
                return "?";

            if (IsActiveAltFutaPerson(person))
                return "X";

            if (GetBodyProfile(person) == "X")
                return "X";

            return person.sex;
        }

        private string GetBodyProfileLabel(string profile)
        {
            if (profile == "M")
                return "MALE";

            if (profile == "X")
                return "FUTANARI";

            return "FEMALE";
        }

        private string GetBodyPresetBrowseSex()
        {
            // BODY PRESETS mirror LOOKS: preset sex follows the currently
            // selected Character automatically. Cross-sex presets are exposed
            // only through the INCOMPATIBLE toggle; there is no manual
            // FEMALE/MALE/FUTANARI browse row.
            return GetBodyEditorProfile(GetSelectedPerson());
        }

        private void SetBodyPresetBrowseSex(string sex)
        {
            // Kept as a harmless compatibility stub for old serialized/plugin
            // state. v46 no longer provides a manual preset-sex selector.
            _bodyPresetBrowseSex = "";

            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;

            UpdateDerivedState();
            RebuildBodyEditorPage();
        }

        private void ToggleBodyPresetIncompatibleHud()
        {
            _showIncompatibleBodyPresets =
                !_showIncompatibleBodyPresets;

            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;

            UpdateDerivedState();
            RebuildBodyEditorPage();
        }

        private void SetSelectedBodyProfile(string profile)
        {
            PersonEntry person = GetSelectedPerson();

            if (person == null ||
                string.IsNullOrEmpty(person.uid))
            {
                return;
            }

            string ownedProfile = GetBodyEditorProfile(person);

            // v141: profile ownership comes only from the active Look adapters.
            // The BODY UI can refresh the current profile, but it cannot convert
            // an ordinary Female/Male into Futanari or downgrade a Futanari.
            if (profile != ownedProfile)
                return;

            if (_bodyProfileByPerson.Remove(person.uid))
                SaveBodyProfilesData();

            ClearActiveBodyPresetForPerson(
                person.uid
            );

            _bodyFineGroup = "";

            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;

            RebuildBodyMorphIndex();

            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;

            UpdateDerivedState();
            RebuildBodyEditorPage();
            RebuildLookCatalogPage();
        }

        private List<string> GetFineGroupNames(
            string profile)
        {
            List<string> names = new List<string>();

            if (profile == "M")
                names.Add("Chest");
            else
                names.Add("Breasts");

            names.Add("Waist & Abdomen");
            names.Add("Hips & Glutes");
            names.Add("Legs");
            names.Add("Arms");
            names.Add(
                profile == "F"
                ? "Vagina"
                : "Dick"
            );
            names.Add("Anus");

            return names;
        }

        private void RequestBodyPresetCatalogScan()
        {
            if (_bodyPresetScanRunning)
                return;

            StartCoroutine(
                ScanBodyPresetCatalogCoroutine()
            );
        }

        private void AnalyzeBodyPreset(
            string path,
            out int femaleCount,
            out int maleCount,
            out int futanariCount)
        {
            femaleCount = 0;
            maleCount = 0;
            futanariCount = 0;

            if (string.IsNullOrEmpty(path))
                return;

            string content = "";

            try
            {
                content =
                    SuperController.singleton
                        .ReadFileIntoString(path);
            }
            catch
            {
                return;
            }

            if (string.IsNullOrEmpty(content))
                return;

            int morphsAt =
                content.IndexOf(
                    "\"morphs\"",
                    StringComparison.OrdinalIgnoreCase
                );

            if (morphsAt < 0)
                return;

            int searchAt = morphsAt;

            for (int guard = 0;
                 guard < 1024 &&
                 searchAt < content.Length;
                 guard++)
            {
                int next;
                string name =
                    ExtractJsonStringValueAfterKey(
                        content,
                        "name",
                        searchAt,
                        out next
                    );

                if (string.IsNullOrEmpty(name) ||
                    next <= searchAt)
                {
                    break;
                }

                searchAt = next;

                string fineGroup;

                if (!string.IsNullOrEmpty(
                        ClassifyBodyMorph(
                            name, "", "F",
                            out fineGroup)))
                {
                    femaleCount++;
                }

                if (!string.IsNullOrEmpty(
                        ClassifyBodyMorph(
                            name, "", "M",
                            out fineGroup)))
                {
                    maleCount++;
                }

                if (!string.IsNullOrEmpty(
                        ClassifyBodyMorph(
                            name, "", "X",
                            out fineGroup)))
                {
                    futanariCount++;
                }
            }
        }

        private string DetectBodyPresetSex(string path)
        {
            if (string.IsNullOrEmpty(path))
                return "?";

            string presetLabel = GetPresetLabel(path);
            string probe =
                (presetLabel == null ? "" : presetLabel) +
                " " +
                path;

            string lower = probe.ToLowerInvariant().Replace('\\', '/');

            if (_nativeFutanariAdapter.IsNativeFutanariBodyPreset(
                    path,
                    presetLabel))
            {
                return "X";
            }

            // Reuse the same high-confidence character/gender metadata detection
            // already used by LOOKS for ordinary Female/Male presets.
            string detected = DetectAppearancePresetSex(path);

            if (detected == "F" || detected == "M" || detected == "X")
                return detected;

            // Last-resort path hints for presets stored in sex-specific folders.
            if (lower.Contains("genesis2female") ||
                lower.Contains("genesis 2 female") ||
                lower.Contains("female3") ||
                lower.Contains("/female/"))
            {
                return "F";
            }

            if (lower.Contains("genesis2male") ||
                lower.Contains("genesis 2 male") ||
                lower.Contains("male3") ||
                lower.Contains("/male/"))
            {
                return "M";
            }

            return "?";
        }

        private void AddBodyPresetEntry(
            string path,
            string source)
        {
            if (string.IsNullOrEmpty(path))
                return;

            path = NormalizePathSlashes(path);

            for (int i = 0; i < _bodyPresetEntries.Count; i++)
            {
                if (string.Equals(
                        _bodyPresetEntries[i].path,
                        path,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }
            }

            int f;
            int m;
            int x;

            AnalyzeBodyPreset(
                path,
                out f,
                out m,
                out x
            );

            if (f == 0 && m == 0 && x == 0)
                return;

            BodyPresetEntry entry =
                new BodyPresetEntry();

            entry.path = path;
            entry.label = GetPresetLabel(path);
            entry.thumbnailPath = GetSiblingJpgPath(path);
            entry.sex = DetectBodyPresetSex(path);
            entry.source = source;
            entry.femaleBodyMorphs = f;
            entry.maleBodyMorphs = m;
            entry.futanariBodyMorphs = x;

            _bodyPresetEntries.Add(entry);
        }

        private void ScanBodyPresetDirectoryRecursive(
            string root,
            string source,
            int depth)
        {
            if (string.IsNullOrEmpty(root) ||
                depth > 12)
            {
                return;
            }

            try
            {
                var files =
                    FileManagerSecure.GetFiles(
                        root,
                        "*.vap"
                    );

                foreach (string f in files)
                    AddBodyPresetEntry(f, source);
            }
            catch { }

            try
            {
                var dirs =
                    FileManagerSecure.GetDirectories(
                        root,
                        "*"
                    );

                foreach (string dir in dirs)
                {
                    ScanBodyPresetDirectoryRecursive(
                        dir,
                        source,
                        depth + 1
                    );
                }
            }
            catch { }
        }

        private void SortBodyPresetEntries()
        {
            _bodyPresetEntries.Sort(
                delegate(
                    BodyPresetEntry a,
                    BodyPresetEntry b)
                {
                    return string.Compare(
                        a.label,
                        b.label,
                        StringComparison.OrdinalIgnoreCase
                    );
                }
            );
        }

        private IEnumerator ScanBodyPresetCatalogCoroutine()
        {
            _bodyPresetScanRunning = true;
            _bodyPresetCatalogScanned = false;
            _bodyPresetEntries.Clear();

            if (_bodyPresetCatalogStatus != null)
            {
                _bodyPresetCatalogStatus.valNoCallback =
                    "Body presets: scanning local...";
            }

            ScanBodyPresetDirectoryRecursive(
                "Custom/Atom/Person/Morphs",
                "Local",
                0
            );

            SortBodyPresetEntries();
            RebuildBodyEditorPage();
            yield return null;

            if (_scanVarBodyPresets != null &&
                _scanVarBodyPresets.val)
            {
                List<string> vars =
                    new List<string>();

                CollectVarFilesRecursive(
                    "AddonPackages",
                    vars,
                    0
                );

                for (int i = 0; i < vars.Count; i++)
                {
                    string packageUid =
                        GetVarPackageUid(vars[i]);

                    if (!string.IsNullOrEmpty(packageUid))
                    {
                        ScanBodyPresetDirectoryRecursive(
                            packageUid +
                                ":/Custom/Atom/Person/Morphs",
                            packageUid,
                            0
                        );
                    }

                    if (i % 20 == 0)
                    {
                        if (_bodyPresetCatalogStatus != null)
                        {
                            _bodyPresetCatalogStatus.valNoCallback =
                                "Body presets: packages " +
                                (i + 1) + "/" +
                                vars.Count +
                                " | " +
                                _bodyPresetEntries.Count +
                                " relevant";
                        }

                        yield return null;
                    }
                }
            }

            SortBodyPresetEntries();

            _bodyPresetScanRunning = false;
            _bodyPresetCatalogScanned = true;

            if (_bodyPresetCatalogStatus != null)
            {
                _bodyPresetCatalogStatus.valNoCallback =
                    "Body presets: " +
                    _bodyPresetEntries.Count +
                    " relevant Morph preset(s)";
            }

            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;

            RebuildBodyEditorPage();
        }

        private bool IsBodyPresetCompatible(
            BodyPresetEntry entry,
            string profile)
        {
            if (entry == null || string.IsNullOrEmpty(profile))
                return false;

            // v44 incorrectly used femaleBodyMorphs/maleBodyMorphs/futanariBodyMorphs
            // as a sex test. Those counters only tell us that a preset contains
            // body-related morph names. Generic morphs classify for more than one
            // profile, which made the same preset appear under every sex.
            // Compatibility must use the preset's detected source sex instead.
            return string.Equals(
                entry.sex,
                profile,
                StringComparison.OrdinalIgnoreCase
            );
        }

        private BodyPresetEntry FindBodyPresetEntry(
            string path)
        {
            if (string.IsNullOrEmpty(path))
                return null;

            for (int i = 0;
                 i < _bodyPresetEntries.Count;
                 i++)
            {
                if (string.Equals(
                        _bodyPresetEntries[i].path,
                        path,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return _bodyPresetEntries[i];
                }
            }

            return null;
        }

        private List<BodyPresetEntry> GetFilteredBodyPresetEntries()
        {
            List<BodyPresetEntry> result =
                new List<BodyPresetEntry>();

            PersonEntry person = GetSelectedPerson();

            if (person == null)
                return result;

            string actualProfile = GetBodyEditorProfile(person);

            // Match LOOKS semantics exactly:
            //   INCOMPATIBLE off -> only presets for the selected Character profile
            //   INCOMPATIBLE on  -> compatible + cross-sex/unknown presets
            if (string.Equals(
                    _bodyPresetView,
                    "Recent",
                    StringComparison.OrdinalIgnoreCase))
            {
                for (int i = 0;
                     i < _recentBodyPresetPaths.Count;
                     i++)
                {
                    BodyPresetEntry entry =
                        FindBodyPresetEntry(
                            _recentBodyPresetPaths[i]
                        );

                    if (entry == null)
                        continue;

                    if (!_showIncompatibleBodyPresets &&
                        !IsBodyPresetCompatible(entry, actualProfile))
                    {
                        continue;
                    }

                    result.Add(entry);
                }

                return result;
            }

            for (int i = 0;
                 i < _bodyPresetEntries.Count;
                 i++)
            {
                BodyPresetEntry entry =
                    _bodyPresetEntries[i];

                if (string.Equals(
                        _bodyPresetView,
                        "Favorites",
                        StringComparison.OrdinalIgnoreCase) &&
                    !_favoriteBodyPresetPaths.Contains(entry.path))
                {
                    continue;
                }

                if (!_showIncompatibleBodyPresets &&
                    !IsBodyPresetCompatible(entry, actualProfile))
                {
                    continue;
                }

                result.Add(entry);
            }

            return result;
        }

        private string MakeBodyBaselineKey(string uid, string morphName)
        {
            return (uid == null ? "" : uid) +
                "\t" +
                (morphName == null ? "" : morphName);
        }

        private void LoadBodyBaselinesData()
        {
            if (_bodyBaselinesData == null)
                return;

            string raw =
                _bodyBaselinesData.val == null
                ? ""
                : _bodyBaselinesData.val;

            if (raw == _lastBodyBaselinesData)
                return;

            _lastBodyBaselinesData = raw;
            _bodyBaselineValues.Clear();

            string[] lines = raw.Split(
                new char[] { '\n' },
                StringSplitOptions.RemoveEmptyEntries
            );

            for (int i = 0; i < lines.Length; i++)
            {
                string[] parts = lines[i].Split(
                    new char[] { '\t' },
                    3
                );

                if (parts.Length != 3)
                    continue;

                float value;
                if (!float.TryParse(
                        parts[2],
                        System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture,
                        out value))
                {
                    continue;
                }

                _bodyBaselineValues[
                    MakeBodyBaselineKey(parts[0], parts[1])
                ] = value;
            }
        }

        private void SaveBodyBaselinesData()
        {
            if (_bodyBaselinesData == null)
                return;

            string raw = "";

            foreach (KeyValuePair<string, float> kv in _bodyBaselineValues)
            {
                int tab = kv.Key.IndexOf('\t');

                if (tab <= 0)
                    continue;

                string uid = kv.Key.Substring(0, tab)
                    .Replace("\r", " ")
                    .Replace("\n", " ");

                string morphName = kv.Key.Substring(tab + 1)
                    .Replace("\t", " ")
                    .Replace("\r", " ")
                    .Replace("\n", " ");

                raw +=
                    uid + "\t" +
                    morphName + "\t" +
                    kv.Value.ToString(
                        "R",
                        System.Globalization.CultureInfo.InvariantCulture
                    ) +
                    "\n";
            }

            _lastBodyBaselinesData = raw;
            _bodyBaselinesData.valNoCallback = raw;
        }

        private void ClearBodyBaselineForPerson(string uid)
        {
            if (string.IsNullOrEmpty(uid))
                return;

            string prefix = uid + "\t";
            List<string> remove = new List<string>();

            foreach (KeyValuePair<string, float> kv in _bodyBaselineValues)
            {
                if (kv.Key.StartsWith(
                        prefix,
                        StringComparison.Ordinal))
                {
                    remove.Add(kv.Key);
                }
            }

            if (remove.Count == 0)
                return;

            for (int i = 0; i < remove.Count; i++)
                _bodyBaselineValues.Remove(remove[i]);

            SaveBodyBaselinesData();
        }

        private string MakeFaceBaselineKey(string uid, string morphName)
        {
            return (uid == null ? "" : uid) +
                "\t" +
                (morphName == null ? "" : morphName);
        }

        private void LoadFaceBaselinesData()
        {
            if (_faceBaselinesData == null)
                return;

            string raw =
                _faceBaselinesData.val == null
                ? ""
                : _faceBaselinesData.val;

            if (raw == _lastFaceBaselinesData)
                return;

            _lastFaceBaselinesData = raw;
            _faceBaselineValues.Clear();

            string[] lines = raw.Split(
                new char[] { '\n' },
                StringSplitOptions.RemoveEmptyEntries
            );

            for (int i = 0; i < lines.Length; i++)
            {
                string[] parts = lines[i].Split(
                    new char[] { '\t' },
                    3
                );

                if (parts.Length != 3)
                    continue;

                float value;
                if (!float.TryParse(
                        parts[2],
                        System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture,
                        out value))
                {
                    continue;
                }

                _faceBaselineValues[
                    MakeFaceBaselineKey(parts[0], parts[1])
                ] = value;
            }
        }

        private void SaveFaceBaselinesData()
        {
            if (_faceBaselinesData == null)
                return;

            string raw = "";

            foreach (KeyValuePair<string, float> kv in _faceBaselineValues)
            {
                int tab = kv.Key.IndexOf('\t');

                if (tab <= 0)
                    continue;

                string uid = kv.Key.Substring(0, tab)
                    .Replace("\r", " ")
                    .Replace("\n", " ");

                string morphName = kv.Key.Substring(tab + 1)
                    .Replace("\t", " ")
                    .Replace("\r", " ")
                    .Replace("\n", " ");

                raw +=
                    uid + "\t" +
                    morphName + "\t" +
                    kv.Value.ToString(
                        "R",
                        System.Globalization.CultureInfo.InvariantCulture
                    ) +
                    "\n";
            }

            _lastFaceBaselinesData = raw;
            _faceBaselinesData.valNoCallback = raw;
        }

        private void ClearFaceBaselineForPerson(string uid)
        {
            if (string.IsNullOrEmpty(uid))
                return;

            string prefix = uid + "\t";
            List<string> remove = new List<string>();

            foreach (KeyValuePair<string, float> kv in _faceBaselineValues)
            {
                if (kv.Key.StartsWith(
                        prefix,
                        StringComparison.Ordinal))
                {
                    remove.Add(kv.Key);
                }
            }

            if (remove.Count == 0)
                return;

            for (int i = 0; i < remove.Count; i++)
                _faceBaselineValues.Remove(remove[i]);

            SaveFaceBaselinesData();
        }

        private DAZCharacterSelector GetCharacterSelectorForPerson(
            PersonEntry person)
        {
            if (person == null || person.atom == null)
                return null;

            try
            {
                JSONStorable geometry =
                    person.atom.GetStorableByID("geometry");

                DAZCharacterSelector selector =
                    geometry as DAZCharacterSelector;

                if (selector != null)
                    return selector;

                return person.atom
                    .GetComponentInChildren<DAZCharacterSelector>();
            }
            catch { }

            return null;
        }

        private GenerateDAZMorphsControlUI GetGenderMorphControlForPerson(
            PersonEntry person,
            string gender)
        {
            DAZCharacterSelector selector =
                GetCharacterSelectorForPerson(person);

            if (selector == null)
                return null;

            try
            {
                if (gender == "M")
                {
                    if (selector.morphsControlMaleUI != null)
                        return selector.morphsControlMaleUI;

                    if (selector.gender ==
                        DAZCharacterSelector.Gender.Male)
                    {
                        return selector.morphsControlUI;
                    }
                }
                else
                {
                    if (selector.morphsControlFemaleUI != null)
                        return selector.morphsControlFemaleUI;

                    if (selector.gender ==
                        DAZCharacterSelector.Gender.Female)
                    {
                        return selector.morphsControlUI;
                    }
                }
            }
            catch { }

            return null;
        }

        private GenerateDAZMorphsControlUI GetMorphControlForPerson(
            PersonEntry person)
        {
            // VaM maintains separate Male and Female morph banks even when the
            // current Person uses the opposite-gender morph toggle. A male-base
            // Futanari such as Lucie therefore must edit the Female bank for
            // FACE and ordinary BODY shaping rather than selector.morphsControlUI,
            // which follows the native Male base geometry.
            string profile = GetBodyEditorProfile(person);

            return GetGenderMorphControlForPerson(
                person,
                profile == "M" ? "M" : "F"
            );
        }

        private bool ContainsAny(
            string value,
            string[] needles)
        {
            if (string.IsNullOrEmpty(value))
                return false;

            for (int i = 0; i < needles.Length; i++)
            {
                if (value.IndexOf(
                        needles[i],
                        StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return true;
                }
            }

            return false;
        }

        private bool BodyNameContains(
            string value,
            params string[] needles)
        {
            return ContainsAny(value, needles);
        }

        private string ClassifyFineTuneGroup(
            string name,
            string region,
            string profile)
        {
            string n =
                name == null
                ? ""
                : name.ToLowerInvariant();

            string r =
                region == null
                ? ""
                : region.ToLowerInvariant();

            string combined = n + " / " + r;

            bool femaleBreast =
                BodyNameContains(
                    combined,
                    "breast", "areola", "nipple"
                );

            bool maleChest =
                BodyNameContains(
                    combined,
                    "pec", "pectoral", "chest"
                );

            bool maleGenitalAbbrev =
                n.StartsWith("frsk") ||
                n.StartsWith("gl_") ||
                n.StartsWith("gl-") ||
                n.StartsWith("sc_") ||
                n.StartsWith("sc-") ||
                n.StartsWith("sh_") ||
                n.StartsWith("sh-") ||
                n.StartsWith("pen_") ||
                n.StartsWith("pen-");

            bool maleGenital =
                maleGenitalAbbrev ||
                BodyNameContains(
                    combined,
                    "penis", "penile", "shaft", "glans",
                    "foreskin", "testicle", "testes",
                    "scrot", "male genital"
                );

            bool femaleGenital =
                BodyNameContains(
                    combined,
                    "vagina", "vag.", "vaginal",
                    "vulva", "labia", "clitoris",
                    "clit", "mons pubis", "female genital"
                );

            bool genericGenital =
                BodyNameContains(
                    combined,
                    "genital", "pubic"
                );

            bool analMorph =
                BodyNameContains(
                    combined,
                    "anus", "anal", "rectal", "rectum"
                );

            if (analMorph)
                return "Anus";

            // Profile compatibility:
            // F = female body + female genitals
            // M = male body + male genitals
            // X = female body + male genitals
            if (profile == "F" && maleGenital)
                return "";

            if (profile == "M" &&
                (femaleBreast || femaleGenital))
            {
                return "";
            }

            if (profile == "X" && femaleGenital)
                return "";

            // Female and Futanari use female torso/breast controls.
            // Male-only pectoral/chest local morphs are hidden from F/X.
            if ((profile == "F" || profile == "X") &&
                maleChest &&
                !femaleBreast)
            {
                return "";
            }

            if (femaleBreast)
            {
                if (profile == "M")
                    return "";

                return "Breasts";
            }

            if (maleChest)
            {
                return profile == "M"
                    ? "Chest"
                    : "";
            }

            if (maleGenital)
            {
                return (profile == "M" || profile == "X")
                    ? "Dick"
                    : "";
            }

            if (femaleGenital)
            {
                return profile == "F"
                    ? "Vagina"
                    : "";
            }

            if (genericGenital)
            {
                return profile == "F"
                    ? "Vagina"
                    : "Dick";
            }

            if (BodyNameContains(
                    combined,
                    "abd", "abdomen", "belly",
                    "stomach", "waist", "navel",
                    "tummy", "love handle",
                    "oblique", "lower back"))
            {
                return "Waist & Abdomen";
            }

            if (BodyNameContains(
                    combined,
                    "glute", "butt", "buttock",
                    "hip", "pelvis", "saddle"))
            {
                return "Hips & Glutes";
            }

            if (BodyNameContains(
                    combined,
                    "thigh", "calf", "shin",
                    "leg", "knee", "ankle"))
            {
                return "Legs";
            }

            if (BodyNameContains(
                    combined,
                    "bicep", "tricep", "forearm",
                    "upper arm", "lower arm",
                    "arm size", "arm definition"))
            {
                return "Arms";
            }

            if (BodyNameContains(
                    combined,
                    "upper back", "back definition",
                    "latissimus", "lats"))
            {
                return profile == "M"
                    ? "Chest"
                    : "Breasts";
            }

            return "";
        }

        private bool IsFaceExpressionMorph(string name, string region)
        {
            string n = name == null ? "" : name.ToLowerInvariant();
            string r = region == null ? "" : region.ToLowerInvariant();
            string combined = n + " / " + r;

            string[] expressionReject = new string[]
            {
                "expression", "viseme", "phoneme", "lip sync", "lipsync",
                "pose control", "pose controls", "pose/", "/pose",
                "blink", "wink", "eyes closed", "eye closed",
                "mouth open", "open mouth", "jaw open",
                "smile", "frown", "sneer", "grin", "grimace",
                "kiss", "pucker", "surprise", "surprised",
                "angry", "anger", "fear", "sad", "happy",
                "disgust", "laugh", "squint", "tongue",
                "speech", "talk", "phonetic"
            };

            if (ContainsAny(combined, expressionReject))
                return true;

            // Head movement controls sometimes live under a Head region but are not
            // anatomical face morphs.
            string[] movementReject = new string[]
            {
                "head bend", "head turn", "head twist", "head rotate",
                "head rotation", "head up", "head down", "head left",
                "head right", "eyes look", "eye look", "gaze"
            };

            return ContainsAny(combined, movementReject);
        }

        private string ClassifyFaceMorph(string name, string region)
        {
            string n = name == null ? "" : name.ToLowerInvariant();
            string r = region == null ? "" : region.ToLowerInvariant();
            string combined = n + " / " + r;

            if (IsFaceExpressionMorph(name, region))
                return "";

            // Explicitly reject non-face anatomy. This is intentionally broad because
            // many third-party morph packs use vague regions such as "Morphs".
            string[] bodyReject = new string[]
            {
                "bodybuilder", "body shape", "body size", "body height",
                "body weight", "body fat", "breast", "chest", "torso",
                "waist", "abdomen", "belly", "navel", "hip", "pelvis",
                "glute", "butt", "thigh", "calf", "shin", "leg",
                "shoulder", "bicep", "tricep", "forearm", "arm size",
                "hand", "finger", "foot", "toe", "genital", "penis",
                "vagina", "vulva", "labia", "clitoris", "anus", "testicle",
                "scrot", "neck"
            };

            if (ContainsAny(combined, bodyReject))
                return "";

            string[] faceMarkers = new string[]
            {
                "head", "face", "facial", "skull", "cranium",
                "forehead", "temple", "cheek", "cheekbone", "zygomatic",
                "eye", "eyelid", "brow", "eyebrow", "orbit", "canthus",
                "tear duct", "iris", "pupil", "nose", "nostril", "nasal",
                "mouth", "lip", "philtrum", "cupid", "nasolabial",
                "jaw", "chin", "mandible", "ear ", "ears"
            };

            if (!ContainsAny(combined, faceMarkers))
                return "";

            if (ContainsAny(combined, new string[]
                {
                    "eye", "eyelid", "upper lid", "lower lid",
                    "brow", "eyebrow", "orbit", "canthus", "tear duct",
                    "iris", "pupil"
                }))
            {
                return "Eyes";
            }

            if (ContainsAny(combined, new string[]
                {
                    "nose", "nostril", "nasal"
                }))
            {
                return "Nose";
            }

            if (ContainsAny(combined, new string[]
                {
                    "mouth", "lip", "philtrum", "cupid", "nasolabial"
                }))
            {
                return "Mouth";
            }

            if (ContainsAny(combined, new string[]
                {
                    "jaw", "chin", "mandible"
                }))
            {
                return "Jaw";
            }

            bool earMorph =
                n == "ear" ||
                n.StartsWith("ear ") ||
                n.Contains(" ear ") ||
                n.EndsWith(" ear") ||
                n.Contains("ears") ||
                r.Contains("ear");

            if (earMorph)
                return "Ears";

            // Global head/face identity and silhouette controls belong in Shape.
            // Use the morph NAME here rather than the generic Head region; otherwise
            // every uncategorized facial detail would be dumped into Shape.
            if (ContainsAny(n, new string[]
                {
                    "head", "face", "facial", "skull", "cranium",
                    "forehead", "cheek", "cheekbone", "zygomatic",
                    "temple", "young", "older", "old", "age",
                    "gaunt", "round", "square", "heart"
                }))
            {
                return "Shape";
            }

            // Any clearly facial morph that escaped the main anatomical buckets is
            // still useful and goes to Fine Tune instead of disappearing.
            return "Fine Tune";
        }

        private void RebuildFaceMorphIndex()
        {
            _faceMorphEntries.Clear();

            PersonEntry person = GetSelectedPerson();
            GenerateDAZMorphsControlUI morphControl =
                GetMorphControlForPerson(person);

            if (morphControl == null)
                return;

            try
            {
                List<string> names = morphControl.GetMorphDisplayNames();

                for (int i = 0; i < names.Count; i++)
                {
                    DAZMorph morph =
                        morphControl.GetMorphByDisplayName(names[i]);

                    if (morph == null)
                        continue;

                    string category =
                        ClassifyFaceMorph(names[i], morph.region);

                    if (string.IsNullOrEmpty(category))
                        continue;

                    FaceMorphEntry entry = new FaceMorphEntry();
                    entry.morph = morph;
                    entry.name = names[i];
                    entry.region = morph.region;
                    entry.category = category;
                    _faceMorphEntries.Add(entry);
                }
            }
            catch (Exception e)
            {
                SuperController.LogMessage(
                    "CharacterRouter: FACE morph scan failed: " + e
                );
            }

            _faceMorphEntries.Sort(
                delegate(FaceMorphEntry a, FaceMorphEntry b)
                {
                    return string.Compare(
                        a.name,
                        b.name,
                        StringComparison.OrdinalIgnoreCase
                    );
                }
            );
        }

        private void EnsureFaceBaselineForSelectedPerson()
        {
            PersonEntry person = GetSelectedPerson();

            if (person == null || string.IsNullOrEmpty(person.uid))
                return;

            if (_faceMorphEntries.Count == 0)
                RebuildFaceMorphIndex();

            bool changed = false;

            for (int i = 0; i < _faceMorphEntries.Count; i++)
            {
                FaceMorphEntry entry = _faceMorphEntries[i];

                if (entry == null || entry.morph == null)
                    continue;

                string key =
                    MakeFaceBaselineKey(person.uid, entry.name);

                if (_faceBaselineValues.ContainsKey(key))
                    continue;

                _faceBaselineValues[key] = entry.morph.morphValue;
                changed = true;
            }

            if (changed)
                SaveFaceBaselinesData();
        }

        private string NormalizeFaceMorphName(string value)
        {
            string simple = value == null ? "" : value.ToLowerInvariant();

            simple =
                simple.Replace("-", " ")
                      .Replace("_", " ")
                      .Replace(".", " ")
                      .Replace("/", " ")
                      .Replace("\\", " ");

            while (simple.IndexOf("  ", StringComparison.Ordinal) >= 0)
                simple = simple.Replace("  ", " ");

            return simple.Trim();
        }

        private bool IsFaceConceptTechnicalVariant(string simple)
        {
            if (string.IsNullOrEmpty(simple))
                return true;

            string padded = " " + simple + " ";

            if (ContainsAny(padded, new string[]
                {
                    " left ", " right ", " asym ", " asymmetric ",
                    " adjust ", " adjustment ", " offset ", " helper ",
                    " fix ", " control ", " ctrl ", " detail ",
                    " define ", " crease ", " smooth "
                }))
            {
                return true;
            }

            if (simple.EndsWith(" 2") ||
                simple.EndsWith(" 3") ||
                simple.EndsWith(" 4") ||
                simple.EndsWith(" ii") ||
                simple.EndsWith(" iii") ||
                simple.EndsWith(" iv"))
            {
                return true;
            }

            return false;
        }

        private int GetFaceConceptMatchScore(
            FaceMorphEntry entry,
            string[] aliases)
        {
            if (entry == null || aliases == null || aliases.Length == 0)
                return -100000;

            string simple = NormalizeFaceMorphName(entry.name);
            if (string.IsNullOrEmpty(simple))
                return -100000;

            int best = -100000;

            for (int i = 0; i < aliases.Length; i++)
            {
                string alias = NormalizeFaceMorphName(aliases[i]);
                if (string.IsNullOrEmpty(alias))
                    continue;

                int score = -100000;

                if (simple == alias)
                    score = 1000;
                else if (simple.StartsWith(alias + " ") ||
                         simple.EndsWith(" " + alias))
                    score = 720;
                else if (simple.IndexOf(alias, StringComparison.Ordinal) >= 0)
                    score = 560;

                if (score <= -100000)
                    continue;

                // Prefer the clean, generic morph for each concept.  Thus
                // "Eyes Height" wins over "Eyes Height Upper/Inner", and
                // "Nose Bridge Height" wins over "Nose Bridge Height 2".
                if (IsFaceConceptTechnicalVariant(simple) &&
                    simple != alias)
                {
                    score -= 500;
                }

                string[] positional = new string[]
                {
                    " upper", " lower", " inner", " outer", " bottom", " top"
                };

                for (int j = 0; j < positional.Length; j++)
                {
                    string marker = positional[j];
                    if (simple.IndexOf(marker, StringComparison.Ordinal) >= 0 &&
                        alias.IndexOf(marker, StringComparison.Ordinal) < 0)
                    {
                        score -= 260;
                    }
                }

                score -= Math.Max(0, simple.Length - alias.Length);

                if (score > best)
                    best = score;
            }

            return best;
        }

        private void AddBestFaceConcept(
            List<FaceMorphEntry> result,
            List<FaceMorphEntry> source,
            string[] aliases)
        {
            if (result == null || source == null || aliases == null)
                return;

            FaceMorphEntry bestEntry = null;
            int bestScore = 0;

            for (int i = 0; i < source.Count; i++)
            {
                FaceMorphEntry candidate = source[i];
                if (candidate == null)
                    continue;

                bool alreadyUsed = false;
                for (int r = 0; r < result.Count; r++)
                {
                    if (result[r] == candidate ||
                        (result[r] != null &&
                         string.Equals(
                             result[r].name,
                             candidate.name,
                             StringComparison.OrdinalIgnoreCase)))
                    {
                        alreadyUsed = true;
                        break;
                    }
                }

                if (alreadyUsed)
                    continue;

                int score = GetFaceConceptMatchScore(candidate, aliases);
                if (score > bestScore)
                {
                    bestScore = score;
                    bestEntry = candidate;
                }
            }

            if (bestEntry != null)
                result.Add(bestEntry);
        }

        private List<FaceMorphEntry> GetEssentialFaceMorphs(
            List<FaceMorphEntry> source,
            string subsection)
        {
            List<FaceMorphEntry> result =
                new List<FaceMorphEntry>();

            if (source == null || source.Count == 0)
                return result;

            // ESSENTIAL is deliberately concept-based rather than simply the
            // highest-scoring N names. One row = one useful visual concept.
            // Variant morphs remain available in ADVANCED.
            if (subsection == "Shape")
            {
                AddBestFaceConcept(result, source, new string[] { "Face Width" });
                AddBestFaceConcept(result, source, new string[] { "Face Height", "Face Length" });
                AddBestFaceConcept(result, source, new string[] { "Head Size", "Cranium Size" });
                AddBestFaceConcept(result, source, new string[] { "Forehead Height" });
                AddBestFaceConcept(result, source, new string[] { "Forehead Width" });
                AddBestFaceConcept(result, source, new string[] { "Cheek Bones Size", "Cheekbone Size", "Cheek Bones Width", "Cheekbone Width" });
                AddBestFaceConcept(result, source, new string[] { "Face Round", "Round Face" });
                AddBestFaceConcept(result, source, new string[] { "Face Square", "Square Face" });
            }
            else if (subsection == "Eyes")
            {
                AddBestFaceConcept(result, source, new string[] { "Eyes Size", "Eye Size" });
                AddBestFaceConcept(result, source, new string[] { "Eyes Width", "Eye Width" });
                AddBestFaceConcept(result, source, new string[] { "Eyes Height", "Eye Height" });
                AddBestFaceConcept(result, source, new string[] { "Eyes Spacing", "Eye Spacing", "Eyes Distance", "Eye Distance" });
                AddBestFaceConcept(result, source, new string[] { "Eyes Depth", "Eye Depth" });
                AddBestFaceConcept(result, source, new string[] { "Eyes Angle", "Eye Angle", "Eyes Tilt", "Eye Tilt", "Eyes Slant", "Eye Slant" });
                AddBestFaceConcept(result, source, new string[] { "Brow Height", "Eyebrow Height" });
                AddBestFaceConcept(result, source, new string[] { "Iris Size" });
            }
            else if (subsection == "Nose")
            {
                AddBestFaceConcept(result, source, new string[] { "Nose Size" });
                AddBestFaceConcept(result, source, new string[] { "Nose Width" });
                AddBestFaceConcept(result, source, new string[] { "Nose Length", "Nose Height" });
                AddBestFaceConcept(result, source, new string[] { "Nose Depth" });
                AddBestFaceConcept(result, source, new string[] { "Nose Bridge Width", "Bridge Width" });
                AddBestFaceConcept(result, source, new string[] { "Nose Bridge Height", "Bridge Height" });
                AddBestFaceConcept(result, source, new string[] { "Nose Bridge Depth", "Bridge Depth" });
                AddBestFaceConcept(result, source, new string[] { "Nose Tip Height", "Tip Height" });
                AddBestFaceConcept(result, source, new string[] { "Nostrils Width", "Nostril Width", "Nostrils Size", "Nostril Size", "NarrowNostrils", "WideNostrils" });
            }
            else if (subsection == "Mouth")
            {
                AddBestFaceConcept(result, source, new string[] { "Mouth Width" });
                AddBestFaceConcept(result, source, new string[] { "Mouth Size" });
                AddBestFaceConcept(result, source, new string[] { "Mouth Height" });
                AddBestFaceConcept(result, source, new string[] { "Lip Upper Size", "Upper Lip Size" });
                AddBestFaceConcept(result, source, new string[] { "Lip Lower Size", "Lower Lip Size" });
                AddBestFaceConcept(result, source, new string[] { "Lips Depth", "Lip Depth", "Lips Protrusion", "Lip Protrusion" });
                AddBestFaceConcept(result, source, new string[] { "Lips Thickness", "Lip Thickness", "Lips Thick" });
                AddBestFaceConcept(result, source, new string[] { "Lip Upper Thick", "Upper Lip Thick", "Upper Lip Fullness", "Lip Upper Full" });
                AddBestFaceConcept(result, source, new string[] { "Lip Lower Thick", "Lower Lip Thick", "Lower Lip Fullness", "Lips Bottom Full", "Lip Lower Full" });
                AddBestFaceConcept(result, source, new string[] { "Cupid Bow", "Cupid's Bow" });
            }
            else if (subsection == "Jaw")
            {
                AddBestFaceConcept(result, source, new string[] { "Jaw Width" });
                AddBestFaceConcept(result, source, new string[] { "Jaw Height" });
                AddBestFaceConcept(result, source, new string[] { "Jaw Depth" });
                AddBestFaceConcept(result, source, new string[] { "Jaw Angle" });
                AddBestFaceConcept(result, source, new string[] { "Chin Width" });
                AddBestFaceConcept(result, source, new string[] { "Chin Height" });
                AddBestFaceConcept(result, source, new string[] { "Chin Depth", "Chin Projection" });
                AddBestFaceConcept(result, source, new string[] { "Chin Round" });
                AddBestFaceConcept(result, source, new string[] { "Chin Square" });
            }
            else if (subsection == "Ears")
            {
                AddBestFaceConcept(result, source, new string[] { "Ears Size", "Ear Size" });
                AddBestFaceConcept(result, source, new string[] { "Ears Height", "Ear Height" });
                AddBestFaceConcept(result, source, new string[] { "Ears Width", "Ear Width" });
                AddBestFaceConcept(result, source, new string[] { "Ears Angle", "Ear Angle" });
                AddBestFaceConcept(result, source, new string[] { "Ears Depth", "Ear Depth" });
                AddBestFaceConcept(result, source, new string[] { "Earlobes Size", "Earlobe Size", "Ear Lobes Size" });
                AddBestFaceConcept(result, source, new string[] { "Earlobes Length", "Earlobe Length", "Ear Lobes Length" });
                AddBestFaceConcept(result, source, new string[] { "Earlobes Attached", "Earlobe Attached", "Ear Lobes Attached" });
            }
            else if (subsection == "Fine Tune")
            {
                // Curated cross-category refinements. These are deliberately
                // secondary controls: useful when polishing a face, but not
                // important enough to occupy the main anatomical tabs. Missing
                // concepts are simply skipped rather than filled with random
                // third-party morphs.
                AddBestFaceConcept(result, source, new string[]
                {
                    "Face Depth", "Facial Depth", "Head Depth"
                });
                AddBestFaceConcept(result, source, new string[]
                {
                    "Cheek Depth", "Cheeks Depth", "Cheek Fullness",
                    "Cheeks Fullness", "Cheek Hollow", "Cheeks Hollow"
                });
                AddBestFaceConcept(result, source, new string[]
                {
                    "Cheek Bones Height", "Cheekbone Height",
                    "Cheek Bones High", "Cheekbone High"
                });
                AddBestFaceConcept(result, source, new string[]
                {
                    "Temple Width", "Temples Width"
                });
                AddBestFaceConcept(result, source, new string[]
                {
                    "Temple Depth", "Temples Depth"
                });
                AddBestFaceConcept(result, source, new string[]
                {
                    "Philtrum Width", "Philtrum Size"
                });
                AddBestFaceConcept(result, source, new string[]
                {
                    "Philtrum Depth", "Philtrum Height", "Philtrum Length"
                });
                AddBestFaceConcept(result, source, new string[]
                {
                    "Nasolabial Depth", "Nasolabial Fold",
                    "Nasolabial Folds"
                });
                AddBestFaceConcept(result, source, new string[]
                {
                    "Eyelid Crease", "Eye Lid Crease", "Lid Crease"
                });
                AddBestFaceConcept(result, source, new string[]
                {
                    "Iris Placement", "Iris Position"
                });
            }

            return result;
        }

        private List<FaceMorphEntry> GetFaceMorphsForCurrentSubsection()
        {
            List<FaceMorphEntry> result = new List<FaceMorphEntry>();

            string subsection =
                _subsection != null ? _subsection.val : "Shape";

            for (int i = 0; i < _faceMorphEntries.Count; i++)
            {
                FaceMorphEntry entry = _faceMorphEntries[i];

                if (entry != null &&
                    string.Equals(
                        entry.category,
                        subsection,
                        StringComparison.OrdinalIgnoreCase))
                {
                    result.Add(entry);
                }
            }

            if (string.Equals(
                    _faceMode,
                    "Essential",
                    StringComparison.OrdinalIgnoreCase))
            {
                // Fine Tune is intentionally a cross-category curated view.
                // Most useful fine-detail morphs are classified under their
                // anatomical owner (Eyes/Mouth/Shape/etc.), so limiting the
                // source to category == Fine Tune can leave this tab nearly
                // empty. Essential Fine Tune therefore selects a few useful
                // refinements from the entire face index.
                List<FaceMorphEntry> essentialSource =
                    string.Equals(
                        subsection,
                        "Fine Tune",
                        StringComparison.OrdinalIgnoreCase)
                    ? _faceMorphEntries
                    : result;

                result =
                    GetEssentialFaceMorphs(
                        essentialSource,
                        subsection
                    );
            }

            return result;
        }

        private string ClassifyBodyMorph(
            string name,
            string region,
            string profile,
            out string fineGroup)
        {
            fineGroup = "";

            string n =
                name == null
                ? ""
                : name.ToLowerInvariant();

            string r =
                region == null
                ? ""
                : region.ToLowerInvariant();

            string combined = n + " / " + r;

            string[] reject = new string[]
            {
                "face", "head", "mouth", "lip", "eye", "brow",
                "nose", "ear", "jaw", "cheek", "teeth", "tongue",
                "expression", "viseme", "phoneme", "pose",
                "finger", "hand pose", "foot pose"
            };

            if (ContainsAny(combined, reject))
                return "";

            // Local anatomy gets first refusal. This prevents e.g.
            // Breast Height from being mistaken for Character Height.
            fineGroup =
                ClassifyFineTuneGroup(
                    name,
                    region,
                    profile
                );

            if (!string.IsNullOrEmpty(fineGroup))
                return "Fine Tune";

            // HEIGHT is deliberately strict. The v33 generic "height" rule
            // polluted this section with Breast Height, Chest Height, etc.
            bool isHeight =
                n == "height" ||
                n == "body height" ||
                n == "bodyheight" ||
                n == "stature" ||
                n.Contains("body scale") ||
                n.Contains("bodyscale") ||
                n.Contains("overall height") ||
                n.Contains("overall scale");

            if (isHeight)
                return "Height";

            // PROPORTIONS is about relationships/lengths/widths of major
            // body segments, not local surface/detail morphs.
            bool isProportion =
                n.Contains("shoulder width") ||
                n.Contains("shoulders width") ||
                n.Contains("shoulder size") ||
                n.Contains("ribcage width") ||
                n.Contains("rib cage width") ||
                n.Contains("torso length") ||
                n.Contains("body length") ||
                n.Contains("leg length") ||
                n.Contains("arm length") ||
                n.Contains("neck length") ||
                n.Contains("hip width") ||
                n.Contains("hips width") ||
                n.Contains("pelvis width") ||
                n.Contains("body width") ||
                n.Contains("torso width") ||
                n.Contains("proportion");

            if (isProportion)
                return "Proportions";

            // SHAPE is reserved for global body type / mass / muscularity.
            bool isShape =
                n.Contains("bodybuilder") ||
                n.Contains("fitness") ||
                n.Contains("emaciat") ||
                n == "thin" ||
                n.Contains("body thin") ||
                n.Contains("body slim") ||
                n.Contains("slim body") ||
                n.Contains("body weight") ||
                n == "weight" ||
                n.Contains("body fat") ||
                n.Contains("body bulk") ||
                n.Contains("athletic") ||
                n.Contains("curvy") ||
                n.Contains("volupt") ||
                n.Contains("muscularity") ||
                n.Contains("overall muscle") ||
                n.Contains("body shape");

            if (isShape)
                return "Shape";

            // A final Fine Tune pass may use body-region metadata, but only
            // when it maps to a known anatomical group for this profile.
            fineGroup =
                ClassifyFineTuneGroup(
                    "",
                    region,
                    profile
                );

            if (!string.IsNullOrEmpty(fineGroup))
                return "Fine Tune";

            return "";
        }

        private void AppendBodyMorphsFromControl(
            GenerateDAZMorphsControlUI morphControl,
            string bodyProfile,
            bool onlyMaleGenitalsForFutanari)
        {
            if (morphControl == null)
                return;

            try
            {
                List<string> names =
                    morphControl.GetMorphDisplayNames();

                for (int i = 0; i < names.Count; i++)
                {
                    DAZMorph morph =
                        morphControl.GetMorphByDisplayName(names[i]);

                    if (morph == null)
                        continue;

                    string fineGroup;
                    string category =
                        ClassifyBodyMorph(
                            names[i],
                            morph.region,
                            bodyProfile,
                            out fineGroup
                        );

                    if (string.IsNullOrEmpty(category))
                        continue;

                    // For a male-base Futanari the Female morph bank owns face/body
                    // shape, proportions, breasts, hips, etc. The Male bank is added
                    // only for penis/testes controls. This mirrors VaM's actual
                    // morphs vs morphsOtherGender split and prevents Male body-shape
                    // controls from leaking back into the Futanari editor.
                    if (onlyMaleGenitalsForFutanari &&
                        !(category == "Fine Tune" &&
                          fineGroup == "Dick"))
                    {
                        continue;
                    }

                    bool duplicate = false;

                    for (int j = 0; j < _bodyMorphEntries.Count; j++)
                    {
                        BodyMorphEntry existing =
                            _bodyMorphEntries[j];

                        if (existing != null &&
                            existing.morph == morph)
                        {
                            duplicate = true;
                            break;
                        }
                    }

                    if (duplicate)
                        continue;

                    BodyMorphEntry entry =
                        new BodyMorphEntry();
                    entry.morph = morph;
                    entry.name = names[i];
                    entry.region = morph.region;
                    entry.category = category;
                    entry.fineGroup = fineGroup;

                    _bodyMorphEntries.Add(entry);
                }
            }
            catch (Exception e)
            {
                SuperController.LogError(
                    "CharacterRouter: BODY morph bank scan failed: " + e
                );
            }
        }

        private void RebuildBodyMorphIndex()
        {
            _bodyMorphEntries.Clear();

            PersonEntry person = GetSelectedPerson();
            string bodyProfile = GetBodyEditorProfile(person);

            if (person == null)
                return;

            if (bodyProfile == "X")
            {
                // Futanari = Female morphology + Male genital controls.
                AppendBodyMorphsFromControl(
                    GetGenderMorphControlForPerson(person, "F"),
                    bodyProfile,
                    false
                );

                AppendBodyMorphsFromControl(
                    GetGenderMorphControlForPerson(person, "M"),
                    bodyProfile,
                    true
                );
            }
            else
            {
                AppendBodyMorphsFromControl(
                    GetGenderMorphControlForPerson(
                        person,
                        bodyProfile == "M" ? "M" : "F"
                    ),
                    bodyProfile,
                    false
                );
            }

            _bodyMorphEntries.Sort(
                delegate(BodyMorphEntry a, BodyMorphEntry b)
                {
                    return string.Compare(
                        a.name,
                        b.name,
                        StringComparison.OrdinalIgnoreCase
                    );
                }
            );
        }

        private void EnsureBodyBaselineForSelectedPerson()
        {
            PersonEntry person = GetSelectedPerson();

            if (person == null ||
                string.IsNullOrEmpty(person.uid))
            {
                return;
            }

            if (_bodyMorphEntries.Count == 0)
                RebuildBodyMorphIndex();

            bool changed = false;

            for (int i = 0; i < _bodyMorphEntries.Count; i++)
            {
                BodyMorphEntry entry = _bodyMorphEntries[i];

                if (entry == null || entry.morph == null)
                    continue;

                string key =
                    MakeBodyBaselineKey(
                        person.uid,
                        entry.name
                    );

                if (_bodyBaselineValues.ContainsKey(key))
                    continue;

                _bodyBaselineValues[key] =
                    entry.morph.morphValue;
                changed = true;
            }

            if (changed)
                SaveBodyBaselinesData();
        }

        private int GetEssentialBodyMorphScore(
            BodyMorphEntry entry,
            string profile,
            string fineGroup)
        {
            if (entry == null)
                return -100000;

            string n =
                entry.name == null
                ? ""
                : entry.name.ToLowerInvariant();

            string combined =
                n + " / " +
                (entry.region == null
                    ? ""
                    : entry.region.ToLowerInvariant());

            string simpleName =
                n.Replace("-", " ")
                 .Replace("_", " ")
                 .Replace(".", " ");

            while (simpleName.IndexOf("  ", StringComparison.Ordinal) >= 0)
                simpleName = simpleName.Replace("  ", " ");

            if (fineGroup == "Anus")
            {
                // The installed female anal pack uses technical names such as
                // ANUS-HORIZONTAL-ADJ, ANUS-VERTICAL-ADJ, ANUS-IN.OUT-ADJ.
                // They are useful controls despite "ADJ" in the name.
                if (BodyNameContains(
                        simpleName,
                        "rotation", "rotate", "angle"))
                {
                    return -500;
                }

                int anusScore = 0;

                if (BodyNameContains(
                        simpleName,
                        "outerarea relax",
                        "outer area relax",
                        "anus relax",
                        "anal relax"))
                {
                    anusScore += 100;
                }

                if (BodyNameContains(
                        simpleName,
                        "in out adj",
                        "in out smallarea",
                        "in out small area",
                        "anus open",
                        "anal open",
                        "anus gape",
                        "anal gape"))
                {
                    anusScore += 96;
                }

                if (BodyNameContains(
                        simpleName,
                        "horizontal adj",
                        "anus width",
                        "anal width"))
                {
                    anusScore += 92;
                }

                if (BodyNameContains(
                        simpleName,
                        "vertical adj",
                        "anus height",
                        "anal height"))
                {
                    anusScore += 90;
                }

                if (BodyNameContains(
                        simpleName,
                        "shape adj low",
                        "shape adjust low"))
                {
                    anusScore += 86;
                }

                if (BodyNameContains(
                        simpleName,
                        "shape adj top",
                        "shape adjust top"))
                {
                    anusScore += 84;
                }

                if (BodyNameContains(
                        simpleName,
                        "upper adj",
                        "upper adjust"))
                {
                    anusScore += 78;
                }

                if (BodyNameContains(
                        simpleName,
                        "size", "diameter", "depth",
                        "protrusion", "rim", "puffy"))
                {
                    anusScore += 72;
                }

                if (anusScore == 0 &&
                    entry.fineGroup == "Anus")
                {
                    anusScore = 20;
                }

                return anusScore;
            }

            // Strongly de-prioritize technical/detail morphs that overwhelm
            // a normal user but remain available in ADVANCED.
            string[] technical = new string[]
            {
                "rotation", "rotate", "move-", "move ", "offset",
                "adjust", "adj.", "back-adj", "front-adj",
                "crease", "smooth", "detail", "wrinkle",
                "shape1", "shape2", "shape3", "shape4",
                "shape 1", "shape 2", "shape 3", "shape 4",
                "upperless", "lesscurve",
                "position", "angle",
                "left", "right", "asym", "asymmetric"
            };

            if (ContainsAny(combined, technical))
                return -500;

            int score = 0;

            if (fineGroup == "Breasts" ||
                fineGroup == "Breasts & Chest")
            {
                if (BodyNameContains(n, "breast size", "breasts size", "breast volume"))
                    score += 100;
                if (BodyNameContains(n, "breast natural", "natural breasts", "natural breast"))
                    score += 95;
                if (BodyNameContains(n, "breast firmness", "firm breasts", "breast firm"))
                    score += 90;
                if (BodyNameContains(n, "breast sag", "sagging", "breast hang"))
                    score += 88;
                if (BodyNameContains(n, "cleavage", "breast spacing", "breast gap"))
                    score += 86;
                if (BodyNameContains(n, "breast width", "breast diameter"))
                    score += 82;
                if (BodyNameContains(n, "breast height"))
                    score += 80;
                if (BodyNameContains(n, "areola size"))
                    score += 78;
                if (BodyNameContains(n, "nipple size"))
                    score += 76;
                if (BodyNameContains(n, "nipple length", "nipple protrusion"))
                    score += 74;
                // Futanari uses the Female BODY set, so male pec/chest controls
                // are not promoted here.
            }
            else if (fineGroup == "Chest")
            {
                if (BodyNameContains(n, "pec size", "pectoral size", "chest size"))
                    score += 100;
                if (BodyNameContains(n, "pec definition", "chest definition"))
                    score += 90;
                if (BodyNameContains(n, "pec width", "chest width"))
                    score += 84;
                if (BodyNameContains(n, "pec height", "chest height"))
                    score += 80;
            }
            else if (fineGroup == "Waist & Abdomen")
            {
                if (BodyNameContains(n, "waist size", "waist width"))
                    score += 100;
                if (BodyNameContains(n, "abd definition", "abs definition"))
                    score += 96;
                if (BodyNameContains(n, "belly size", "stomach size", "abdomen size"))
                    score += 92;
                if (BodyNameContains(n, "belly shape"))
                    score += 88;
                if (BodyNameContains(n, "love handle"))
                    score += 82;
                if (BodyNameContains(n, "navel"))
                    score += 72;
            }
            else if (fineGroup == "Hips & Glutes")
            {
                if (BodyNameContains(n, "hip size", "hip width"))
                    score += 100;
                if (BodyNameContains(n, "glute size", "butt size", "buttock size"))
                    score += 98;
                if (BodyNameContains(n, "glute shape", "butt shape"))
                    score += 92;
                if (BodyNameContains(n, "pelvis"))
                    score += 80;
            }
            else if (fineGroup == "Legs")
            {
                if (BodyNameContains(n, "thigh size", "thigh thickness"))
                    score += 100;
                if (BodyNameContains(n, "calf size", "calf thickness"))
                    score += 94;
                if (BodyNameContains(n, "leg size", "leg thickness"))
                    score += 90;
                if (BodyNameContains(n, "knee"))
                    score += 72;
            }
            else if (fineGroup == "Arms")
            {
                if (BodyNameContains(n, "arm size", "upper arm size"))
                    score += 100;
                if (BodyNameContains(n, "bicep size", "biceps size"))
                    score += 96;
                if (BodyNameContains(n, "tricep size", "triceps size"))
                    score += 92;
                if (BodyNameContains(n, "forearm size"))
                    score += 88;
                if (BodyNameContains(n, "arm definition", "bicep definition"))
                    score += 82;
            }
            else if (
                fineGroup == "Vagina" ||
                fineGroup == "Dick")
            {
                if (profile == "M" || profile == "X")
                {
                    if (BodyNameContains(n, "penis length", "shaft length") ||
                        (n.StartsWith("sh_") && n.Contains("length")) ||
                        (n.StartsWith("sh-") && n.Contains("length")))
                    {
                        score += 100;
                    }

                    if (BodyNameContains(n, "penis girth", "shaft girth", "penis width") ||
                        (n.StartsWith("sh_") && n.Contains("width")) ||
                        (n.StartsWith("sh-") && n.Contains("width")))
                    {
                        score += 98;
                    }

                    if (BodyNameContains(n, "penis size"))
                        score += 96;

                    if (BodyNameContains(n, "glans size", "head size") ||
                        (n.StartsWith("gl_") && (n.Contains("length") || n.Contains("width"))) ||
                        (n.StartsWith("gl-") && (n.Contains("length") || n.Contains("width"))))
                    {
                        score += 90;
                    }

                    if (BodyNameContains(n, "testicle size", "testes size", "ball size"))
                        score += 86;

                    if (BodyNameContains(n, "scrotum size", "scrotal size") ||
                        (n.StartsWith("sc_") && n.Contains("width")) ||
                        (n.StartsWith("sc-") && n.Contains("width")))
                    {
                        score += 84;
                    }

                    if (BodyNameContains(n, "foreskin") ||
                        n.StartsWith("frsk"))
                    {
                        score += 78;
                    }
                }

                if (profile == "F")
                {
                    // User-facing "degree of opening" control should rank at the top.
                    if (BodyNameContains(
                            simpleName,
                            "vaginal opening",
                            "vagina opening",
                            "vagina open",
                            "vaginal open",
                            "vagina gape",
                            "vaginal gape",
                            "vulva open",
                            "vulva opening",
                            "vulva spread",
                            "vagina spread",
                            "vaginal spread"))
                    {
                        score += 110;
                    }

                    if (BodyNameContains(
                            simpleName,
                            "clitoris size",
                            "clit size"))
                    {
                        score += 100;
                    }

                    if (BodyNameContains(
                            simpleName,
                            "labia minora size"))
                    {
                        score += 98;
                    }

                    if (BodyNameContains(
                            simpleName,
                            "labia majora size"))
                    {
                        score += 96;
                    }

                    if (BodyNameContains(
                            simpleName,
                            "clitoris length",
                            "clit length",
                            "clitoris protrusion",
                            "clit protrusion"))
                    {
                        score += 94;
                    }

                    if (BodyNameContains(
                            simpleName,
                            "labia minora length",
                            "labia minora protrusion"))
                    {
                        score += 92;
                    }

                    if (BodyNameContains(
                            simpleName,
                            "vagina size",
                            "vaginal size",
                            "vagina width",
                            "vaginal width",
                            "vaginal opening",
                            "vagina opening",
                            "vagina open",
                            "vaginal open",
                            "vagina gape",
                            "vaginal gape",
                            "vulva open",
                            "vulva opening",
                            "vulva spread",
                            "vagina spread",
                            "vaginal spread"))
                    {
                        score += 90;
                    }

                    if (BodyNameContains(
                            simpleName,
                            "labia spread",
                            "labia separation",
                            "labia open"))
                    {
                        score += 88;
                    }

                    if (BodyNameContains(
                            simpleName,
                            "labia majora puffy",
                            "labia majora puff",
                            "labia puff"))
                    {
                        score += 86;
                    }

                    if (BodyNameContains(
                            simpleName,
                            "vagina depth",
                            "vaginal depth"))
                    {
                        score += 84;
                    }

                    if (BodyNameContains(
                            simpleName,
                            "mons pubis",
                            "mons size",
                            "pubic mound"))
                    {
                        score += 82;
                    }

                    if (BodyNameContains(
                            simpleName,
                            "clitoral hood",
                            "clit hood"))
                    {
                        score += 80;
                    }

                    // Broad but still anatomy-specific fallback. Many VaM packs use
                    // technical names such as CLIT-HOOD-IN.OUT, LABIA-OUTER-LENGTH,
                    // VAGINA-IN.OUT, VULVA-RELAX, etc.
                    if (score == 0 &&
                        BodyNameContains(
                            simpleName,
                            "labia",
                            "clitoris",
                            "clit",
                            "vagina",
                            "vaginal",
                            "vulva",
                            "mons",
                            "hood"))
                    {
                        if (BodyNameContains(
                                simpleName,
                                "size", "width", "length",
                                "depth", "open", "opening",
                                "gape", "spread", "puffy",
                                "shorter", "longer",
                                "in out", "in.out",
                                "relax", "tight",
                                "inner", "outer",
                                "up", "down"))
                        {
                            score += 55;
                        }
                        else
                        {
                            // Clear anatomy controls are still useful enough to
                            // compete for one of the 12 Essential slots.
                            score += 25;
                        }
                    }
                }
            }

            // Mild generic preference for user-facing "size/width/length/height"
            // morphs when no stronger rule matched.
            if (score == 0)
            {
                if (BodyNameContains(simpleName, "size"))
                    score += 25;
                if (BodyNameContains(simpleName, "width"))
                    score += 20;
                if (BodyNameContains(simpleName, "length"))
                    score += 20;
                if (BodyNameContains(simpleName, "height"))
                    score += 15;
            }

            return score;
        }

        private List<BodyMorphEntry> GetEssentialFineTuneMorphs(
            List<BodyMorphEntry> source,
            string profile,
            string fineGroup)
        {
            List<BodyMorphEntry> result =
                new List<BodyMorphEntry>();

            if (source == null || source.Count == 0)
                return result;

            List<BodyMorphEntry> ranked =
                new List<BodyMorphEntry>(source);

            ranked.Sort(
                delegate(BodyMorphEntry a, BodyMorphEntry b)
                {
                    int sa =
                        GetEssentialBodyMorphScore(
                            a,
                            profile,
                            fineGroup
                        );

                    int sb =
                        GetEssentialBodyMorphScore(
                            b,
                            profile,
                            fineGroup
                        );

                    if (sa != sb)
                        return sb.CompareTo(sa);

                    return string.Compare(
                        a.name,
                        b.name,
                        StringComparison.OrdinalIgnoreCase
                    );
                }
            );

            // Default UX target: one compact set, never dozens.
            // ANUS is intentionally tighter because most useful edits fit in 6-8 controls.
            int essentialMax =
                fineGroup == "Anus"
                ? 8
                : 12;

            for (int i = 0;
                 i < ranked.Count &&
                 result.Count < essentialMax;
                 i++)
            {
                int score =
                    GetEssentialBodyMorphScore(
                        ranked[i],
                        profile,
                        fineGroup
                    );

                if (score <= 0)
                    continue;

                result.Add(ranked[i]);
            }

            return result;
        }

        private List<BodyMorphEntry> GetBodyMorphsForCurrentSubsection()
        {
            List<BodyMorphEntry> result =
                new List<BodyMorphEntry>();

            string subsection =
                _subsection != null
                ? _subsection.val
                : "Shape";

            if (subsection == "Presets")
                return result;

            for (int i = 0; i < _bodyMorphEntries.Count; i++)
            {
                BodyMorphEntry entry = _bodyMorphEntries[i];

                if (entry == null ||
                    !string.Equals(
                        entry.category,
                        subsection,
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (string.Equals(
                        subsection,
                        "Fine Tune",
                        StringComparison.OrdinalIgnoreCase))
                {
                    if (!string.Equals(
                            entry.fineGroup,
                            _bodyFineGroup,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }
                }

                result.Add(entry);
            }

            if (string.Equals(
                    subsection,
                    "Fine Tune",
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    _bodyFineMode,
                    "Essential",
                    StringComparison.OrdinalIgnoreCase))
            {
                PersonEntry person = GetSelectedPerson();
                result =
                    GetEssentialFineTuneMorphs(
                        result,
                        GetBodyEditorProfile(person),
                        _bodyFineGroup
                    );
            }

            return result;
        }

        private bool StartNativeMorphPresetLoad(
            Atom person,
            string path,
            out string error)
        {
            error = "";

            if (person == null)
            {
                error = "No selected Person.";
                return false;
            }

            if (string.IsNullOrEmpty(path))
            {
                error = "Preset path is empty.";
                return false;
            }

            try
            {
                JSONStorable morphPresets =
                    person.GetStorableByID(
                        "MorphPresets"
                    );

                if (morphPresets == null)
                {
                    error =
                        "Selected Person has no MorphPresets storable.";
                    return false;
                }

                JSONStorableUrl presetBrowsePath =
                    morphPresets.GetUrlJSONParam(
                        "presetBrowsePath"
                    );

                if (presetBrowsePath == null)
                {
                    error =
                        "MorphPresets has no presetBrowsePath.";
                    return false;
                }

                JSONStorableBool loadPresetOnSelect =
                    morphPresets.GetBoolJSONParam(
                        "loadPresetOnSelect"
                    );

                bool previous = false;

                if (loadPresetOnSelect != null)
                {
                    previous =
                        loadPresetOnSelect.val;
                    loadPresetOnSelect.val = false;
                }

                try
                {
                    presetBrowsePath.val =
                        SuperController.singleton
                            .NormalizePath(path);

                    morphPresets.CallAction(
                        "LoadPreset"
                    );
                }
                finally
                {
                    if (loadPresetOnSelect != null)
                        loadPresetOnSelect.val = previous;
                }

                return true;
            }
            catch (Exception e)
            {
                error = e.Message;
                return false;
            }
        }

        private Dictionary<string, float> SnapshotMorphValuesFromControl(
            GenerateDAZMorphsControlUI control)
        {
            Dictionary<string, float> values =
                new Dictionary<string, float>(
                    StringComparer.OrdinalIgnoreCase
                );

            if (control == null)
                return values;

            try
            {
                List<string> names = control.GetMorphDisplayNames();

                for (int i = 0; i < names.Count; i++)
                {
                    DAZMorph morph =
                        control.GetMorphByDisplayName(names[i]);

                    if (morph != null)
                        values[names[i]] = morph.morphValue;
                }
            }
            catch { }

            return values;
        }

        private Dictionary<string, float> SnapshotAllMorphValues(
            PersonEntry person)
        {
            return SnapshotMorphValuesFromControl(
                GetMorphControlForPerson(person)
            );
        }

        private bool IsClearlyNonBodyPresetMorph(
            string name,
            string region)
        {
            string n =
                name == null
                ? ""
                : name.ToLowerInvariant();

            string r =
                region == null
                ? ""
                : region.ToLowerInvariant();

            string combined = n + " / " + r;

            string[] reject = new string[]
            {
                "face", "head", "mouth", "lip", "eye", "brow",
                "nose", "ear", "jaw", "cheek", "teeth", "tongue",
                "expression", "viseme", "phoneme",
                "pose", "finger", "hand pose", "foot pose"
            };

            return ContainsAny(combined, reject);
        }

        private bool IsMaleGenitalPresetMorph(
            string name,
            string region,
            string profile)
        {
            string fineGroup;

            string category =
                ClassifyBodyMorph(
                    name,
                    region,
                    profile,
                    out fineGroup
                );

            if (category == "Fine Tune" &&
                fineGroup == "Dick")
            {
                return true;
            }

            string n =
                name == null
                ? ""
                : name.ToLowerInvariant();

            string r =
                region == null
                ? ""
                : region.ToLowerInvariant();

            string combined = n + " / " + r;

            string[] genitalHints = new string[]
            {
                "penis", "penile", "dick", "cock",
                "glans", "foreskin", "shaft",
                "testicle", "testis", "testes",
                "scrotum", "scrotal"
            };

            return ContainsAny(combined, genitalHints);
        }

        private void IsolateBodyPresetOnMorphBank(
            GenerateDAZMorphsControlUI control,
            Dictionary<string, float> before,
            PersonEntry person,
            string profile,
            bool onlyMaleGenitals,
            ref bool baselineChanged)
        {
            if (control == null)
                return;

            Dictionary<string, float> desired =
                new Dictionary<string, float>(
                    StringComparer.OrdinalIgnoreCase
                );

            try
            {
                List<string> names =
                    control.GetMorphDisplayNames();

                for (int i = 0; i < names.Count; i++)
                {
                    DAZMorph morph =
                        control.GetMorphByDisplayName(
                            names[i]
                        );

                    if (morph == null)
                        continue;

                    float originalValue = 0f;
                    before.TryGetValue(
                        names[i],
                        out originalValue
                    );

                    // BODY preset isolation should be based on what the native
                    // Morph Preset actually changed, not only on our HUD
                    // classification. Many downloaded BODY presets are driven by
                    // custom full-body morphs whose names do not contain generic
                    // terms such as "body shape" and were therefore being
                    // immediately restored to their old value.
                    if (Mathf.Abs(
                            morph.morphValue -
                            originalValue) < 0.00001f)
                    {
                        continue;
                    }

                    bool allowed;

                    if (onlyMaleGenitals)
                    {
                        allowed =
                            IsMaleGenitalPresetMorph(
                                names[i],
                                morph.region,
                                profile
                            );
                    }
                    else
                    {
                        // Keep every changed morph unless metadata clearly says
                        // it belongs to Face/Head/expression/pose. This retains
                        // arbitrary author-named full-body morphs while preserving
                        // CharacterRouter's BODY-vs-FACE separation.
                        allowed =
                            !IsClearlyNonBodyPresetMorph(
                                names[i],
                                morph.region
                            );
                    }

                    if (!allowed)
                        continue;

                    desired[names[i]] =
                        morph.morphValue;

                    string baselineKey =
                        MakeBodyBaselineKey(
                            person.uid,
                            names[i]
                        );

                    if (!_bodyBaselineValues.ContainsKey(
                            baselineKey))
                    {
                        _bodyBaselineValues[
                            baselineKey
                        ] = originalValue;

                        baselineChanged = true;
                    }
                }

                // Undo the native Morph Preset globally, then put back only the
                // changed morphs allowed for this BODY bank.
                for (int i = 0; i < names.Count; i++)
                {
                    DAZMorph morph =
                        control.GetMorphByDisplayName(
                            names[i]
                        );

                    if (morph == null)
                        continue;

                    float originalValue = 0f;

                    before.TryGetValue(
                        names[i],
                        out originalValue
                    );

                    morph.morphValue =
                        originalValue;
                }

                foreach (KeyValuePair<string, float> kv
                         in desired)
                {
                    DAZMorph morph =
                        control.GetMorphByDisplayName(
                            kv.Key
                        );

                    if (morph != null)
                        morph.morphValue =
                            kv.Value;
                }
            }
            catch (Exception e)
            {
                SuperController.LogError(
                    "CharacterRouter v143: Body Preset isolation failed: " +
                    e
                );
            }
        }

        private void RestoreMorphBank(
            GenerateDAZMorphsControlUI control,
            Dictionary<string, float> before)
        {
            if (control == null)
                return;

            try
            {
                List<string> names = control.GetMorphDisplayNames();

                for (int i = 0; i < names.Count; i++)
                {
                    DAZMorph morph = control.GetMorphByDisplayName(names[i]);
                    if (morph == null)
                        continue;

                    float originalValue = 0f;
                    before.TryGetValue(names[i], out originalValue);
                    morph.morphValue = originalValue;
                }
            }
            catch (Exception e)
            {
                SuperController.LogError(
                    "CharacterRouter v141: opposite morph-bank restore failed: " + e
                );
            }
        }

