        private void SelectBodyPreset(
            BodyPresetEntry entry)
        {
            if (entry == null ||
                _bodyPresetApplyInProgress ||
                _lookApplyInProgress ||
                _controlledSpawnInProgress)
            {
                return;
            }

            StartCoroutine(
                ApplyBodyPresetCoroutine(entry)
            );
        }

        private IEnumerator ApplyBodyPresetCoroutine(
            BodyPresetEntry entry)
        {
            PersonEntry person = GetSelectedPerson();

            if (person == null ||
                person.atom == null ||
                entry == null)
            {
                yield break;
            }

            _bodyPresetApplyInProgress = true;

            RebuildBodyMorphIndex();
            EnsureBodyBaselineForSelectedPerson();

            string splitError;

            BodyPresetAdapter.Session splitSession =
                _bodyPresetAdapter.Begin(
                    person.atom,
                    person.uid,
                    out splitError
                );

            if (splitSession == null)
            {
                _bodyPresetApplyInProgress = false;

                if (_bodyStatusText != null)
                {
                    _bodyStatusText.text =
                        "BODY PRESETS — splitter failed: " +
                        splitError;
                }

                SuperController.LogError(
                    "CharacterRouter v146: BodyPresetAdapter.Begin failed: " +
                    splitError
                );

                yield break;
            }

            JSONStorableBool hidden =
                GetAtomHiddenStorable(person.atom);

            bool hiddenOld = false;
            bool hiddenChanged = false;

            if (hidden != null)
            {
                hiddenOld = hidden.val;
                hidden.val = true;
                hiddenChanged = true;
                yield return null;
            }

            if (_bodyStatusText != null)
            {
                _bodyStatusText.text =
                    "BODY PRESETS — loading " +
                    entry.label +
                    "...";
            }

            string error;

            bool started =
                StartNativeMorphPresetLoad(
                    person.atom,
                    entry.path,
                    out error
                );

            if (!started)
            {
                _bodyPresetAdapter.ClearActive(
                    person.atom,
                    person.uid
                );

                if (hiddenChanged && hidden != null)
                    hidden.val = hiddenOld;

                _bodyPresetApplyInProgress = false;

                if (_bodyStatusText != null)
                {
                    _bodyStatusText.text =
                        "BODY PRESETS — load failed: " +
                        error;
                }

                yield break;
            }

            yield return WaitForVaMLoadingToFinish(120f);
            yield return new WaitForSecondsRealtime(0.15f);
            yield return null;
            yield return new WaitForFixedUpdate();

            bool completed =
                _bodyPresetAdapter.Complete(
                    person.atom,
                    person.uid,
                    splitSession,
                    out splitError
                );

            if (hiddenChanged && hidden != null)
                hidden.val = hiddenOld;

            if (!completed)
            {
                _bodyPresetApplyInProgress = false;

                if (_bodyStatusText != null)
                {
                    _bodyStatusText.text =
                        "BODY PRESETS — split failed: " +
                        splitError;
                }

                SuperController.LogError(
                    "CharacterRouter v146: BodyPresetAdapter.Complete failed: " +
                    splitError
                );

                RebuildBodyMorphIndex();
                RebuildBodyEditorPage();
                yield break;
            }

            _activeBodyPresetByPerson[
                person.uid
            ] = entry.path;

            SaveActiveBodyPresetsData();
            RecordRecentBodyPreset(entry.path);

            yield return new WaitForFixedUpdate();

            _bodyPresetApplyInProgress = false;
            RebuildBodyMorphIndex();
            RebuildBodyEditorPage();
        }

        private void ResetBodySection()
        {
            PersonEntry person = GetSelectedPerson();
            if (person == null)
                return;

            _bodyPresetAdapter.ClearActive(
                person.atom,
                person.uid
            );

            EnsureBodyBaselineForSelectedPerson();

            string subsection =
                _subsection != null ? _subsection.val : "";

            List<BodyMorphEntry> resetEntries;

            if (string.Equals(
                    subsection,
                    "Fine Tune",
                    StringComparison.OrdinalIgnoreCase))
            {
                resetEntries =
                    GetBodyMorphsForCurrentSubsection();
            }
            else
            {
                resetEntries =
                    new List<BodyMorphEntry>();

                for (int i = 0; i < _bodyMorphEntries.Count; i++)
                {
                    BodyMorphEntry candidate = _bodyMorphEntries[i];

                    if (candidate != null &&
                        string.Equals(
                            candidate.category,
                            subsection,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        resetEntries.Add(candidate);
                    }
                }
            }

            for (int i = 0; i < resetEntries.Count; i++)
            {
                BodyMorphEntry entry = resetEntries[i];

                if (entry == null || entry.morph == null)
                    continue;

                float baseline;
                if (_bodyBaselineValues.TryGetValue(
                        MakeBodyBaselineKey(
                            person.uid,
                            entry.name
                        ),
                        out baseline))
                {
                    entry.morph.morphValue = baseline;
                }
            }

            ClearActiveBodyPresetForPerson(
                person.uid
            );

            RebuildBodyEditorPage();
        }

        private void ResetBodyAll()
        {
            PersonEntry person = GetSelectedPerson();
            if (person == null)
