        private void RefreshRoster(bool forceRebuild)
        {
            try
            {
                string oldSelected = _selectedCharacter != null ? _selectedCharacter.val : "";
                _persons.Clear();

                List<Atom> atoms = SuperController.singleton.GetAtoms();
                for (int i = 0; i < atoms.Count; i++)
                {
                    Atom atom = atoms[i];
                    if (atom == null || atom.type != "Person")
                        continue;

                    PersonEntry p = new PersonEntry();
                    p.atom = atom;
                    p.uid = atom.uid;
                    p.sex = DetectSex(atom);
                    _persons.Add(p);
                }

                _persons.Sort(delegate(PersonEntry a, PersonEntry b) {
                    if (_sortBySex != null && _sortBySex.val)
                    {
                        int sa = SexOrder(a.sex);
                        int sb = SexOrder(b.sex);
                        if (sa != sb) return sa.CompareTo(sb);
                    }
                    return string.Compare(a.uid, b.uid, StringComparison.OrdinalIgnoreCase);
                });

                PruneAliasesForMissingPersons();
                PruneActiveLooksForMissingPersons();
                PruneOriginalLooksForMissingPersons();
                EnsureFriendlyCharacterNames();

                List<string> choices = new List<string>();
                for (int i = 0; i < _persons.Count; i++)
                    choices.Add(_persons[i].uid);
                if (choices.Count == 0)
                    choices.Add("(none)");

                if (_selectedCharacter != null)
                {
                    _selectedCharacter.choices = choices;

                    if (!string.IsNullOrEmpty(oldSelected) && choices.Contains(oldSelected))
                        _selectedCharacter.valNoCallback = oldSelected;
                    else
                        _selectedCharacter.valNoCallback = choices[0];
                }

                string signature = GetRosterSignature();
                bool changed = signature != _lastRosterSignature;
                _lastRosterSignature = signature;

                if (_rosterStatus != null)
                    _rosterStatus.valNoCallback = "Roster: " + _persons.Count + " Person atom(s)";

                UpdateSubsectionChoices();
                UpdateDerivedState();
                SyncSelectedButtonName();

                if (forceRebuild || changed)
                    RebuildRosterButtons();
                else
                    UpdateButtonSelectionVisuals();
            }
            catch (Exception e)
            {
                SuperController.LogError("CharacterRouter v62 roster error: " + e);
            }
        }

        private string GetRosterSignature()
        {
            string s = "";
            for (int i = 0; i < _persons.Count; i++)
                s += _persons[i].uid + "|" + _persons[i].sex + ";";
            return s;
        }

        private int SexOrder(string sex)
        {
            if (sex == "F") return 0;
            if (sex == "M") return 1;
            return 2;
        }

        private string DetectSex(Atom atom)
        {
            if (atom == null) return "?";

            try
            {
                JSONStorable geometryStorable =
                    atom.GetStorableByID("geometry");

                // Native Futanari recognition is isolated. Ordinary Male/Female
                // Persons bypass the adapter and immediately follow VaM's native base.
                if (_nativeFutanariAdapter.IsNativeFutanariAtom(atom))
                    return "X";

                // Ordinary Female/Male detection follows VaM's active base geometry.
                DAZCharacterSelector selector =
                    geometryStorable as DAZCharacterSelector;

                if (selector != null)
                {
                    if (selector.gender ==
                        DAZCharacterSelector.Gender.Female)
                    {
                        return "F";
                    }

                    if (selector.gender ==
                        DAZCharacterSelector.Gender.Male)
                    {
                        return "M";
                    }
                }

                // Fallback for unusual/custom Person setups where geometry exists
                // but is not exposed as DAZCharacterSelector.
                if (geometryStorable != null)
                {
                    string[] names =
                        new string[]
                        {
                            "character", "Character",
                            "gender", "Gender"
                        };

                    for (int i = 0; i < names.Length; i++)
                    {
                        JSONStorableStringChooser c =
                            geometryStorable.GetStringChooserJSONParam(
                                names[i]
                            );
                        if (c != null && !string.IsNullOrEmpty(c.val))
                        {

                            // Check Female first because "Female" contains "male".
                            if (c.val.IndexOf(
                                    "Female",
                                    StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                return "F";
                            }

                            if (c.val.IndexOf(
                                    "Male",
                                    StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                return "M";
                            }
                        }

                        JSONStorableString st =
                            geometryStorable.GetStringJSONParam(
                                names[i]
                            );
                        if (st != null && !string.IsNullOrEmpty(st.val))
                        {

                            if (st.val.IndexOf(
                                    "Female",
                                    StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                return "F";
                            }

                            if (st.val.IndexOf(
                                    "Male",
                                    StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                return "M";
                            }
                        }
                    }
                }
            }
            catch (Exception e)
            {
                SuperController.LogMessage(
                    "CharacterRouter: gender detection fallback for " +
                    atom.uid + ": " + e.Message
                );
            }

            // Some named base characters do not expose a useful live gender through
            // geometry. If the atom is already owned by a known active Look, reuse the
            // catalog's structural sex classification before falling back to the UID.
            string activeUid = atom.uid == null ? "" : atom.uid;

            if (!string.IsNullOrEmpty(activeUid))
            {
                string activeLookPath;

                if (_activeLookByPerson.TryGetValue(
                        activeUid,
                        out activeLookPath))
                {
                    AppearanceEntry activeEntry =
                        FindAppearanceEntryByPath(
                            activeLookPath
                        );

                    if (activeEntry != null &&
                        (activeEntry.sex == "F" ||
                         activeEntry.sex == "M" ||
                         activeEntry.sex == "X"))
                    {
                        return activeEntry.sex;
                    }
                }
            }

            // Last-resort fallback for explicitly named atoms.
            string uid = activeUid;

            if (uid.IndexOf(
                    "Female",
                    StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "F";
            }

            if (uid.IndexOf(
                    "Male",
                    StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return "M";
            }

            return "?";
        }

        private PersonEntry GetSelectedPerson()
        {
            if (_selectedCharacter == null) return null;
            string uid = _selectedCharacter.val;

            for (int i = 0; i < _persons.Count; i++)
                if (_persons[i].uid == uid)
                    return _persons[i];

            return null;
        }

        private void UpdateSubsectionChoices()
        {
            if (_subsection == null) return;

            string section = _section != null ? _section.val : "Looks";
            string sex = "?";
            PersonEntry p = GetSelectedPerson();
            if (p != null) sex = GetCharacterCatalogSex(p);

            List<string> choices;

            if (section == "Looks")
                choices = new List<string> { "All", "Favorites", "Recent", "Scenes" };
            else if (section == "Face")
                choices = new List<string>
                {
                    "Shape", "Eyes", "Nose", "Mouth", "Jaw", "Ears", "Fine Tune"
                };
            else if (section == "Body")
                choices = new List<string>
                {
                    "Presets", "Shape", "Proportions", "Height", "Fine Tune"
                };
            else if (section == "Hair")
                choices = new List<string> { "All", "Favorites", "Scenes" };
            else if (section == "Wardrobe" && sex == "F")
                choices = new List<string> { "All", "Outfits", "Tops", "Bottoms", "Dresses", "Lingerie", "Underwear", "Shoes", "Accessories", "Favorites" };
            else if (section == "Wardrobe" && sex == "M")
                choices = new List<string> { "All", "Outfits", "Tops", "Bottoms", "Underwear", "Shoes", "Accessories", "Favorites" };
            else if (section == "Wardrobe")
                choices = new List<string> { "All", "Outfits", "Tops", "Bottoms", "Dresses", "Lingerie", "Underwear", "Shoes", "Accessories", "Favorites" };
            else if (section == "Details")
                choices = new List<string> { "All", "Skin", "Makeup", "Tattoos", "Piercings", "Nails", "Favorites" };
            else
                choices = new List<string> { "All" };

            string old = _subsection.val;
            _subsection.choices = choices;
            _subsection.valNoCallback = choices.Contains(old) ? old : choices[0];
        }

        private string Normalize(string value)
        {
            if (string.IsNullOrEmpty(value)) return "NONE";
            return value.Trim().ToUpperInvariant().Replace(" ", "_").Replace("-", "_");
        }

        private void UpdateDerivedState()
        {
            PersonEntry p = GetSelectedPerson();
            string uid = p != null ? p.uid : "";
            string sex = p != null ? GetCharacterCatalogSex(p) : "?";
            string compatibility;

            if (_showIncompatible != null && _showIncompatible.val)
                compatibility = "F,M,X,U";
            else if (sex == "F")
                compatibility = "F,U";
            else if (sex == "M")
                compatibility = "M,U";
            else if (sex == "X")
                compatibility = "X,U";
            else
                compatibility = "U";

            string section = Normalize(_section != null ? _section.val : "Looks");
            string subsection = Normalize(_subsection != null ? _subsection.val : "All");
            int page = _catalogPage != null ? Mathf.RoundToInt(_catalogPage.val) : 1;

            if (_selectedSex != null) _selectedSex.valNoCallback = "Selected sex: " + sex;
            if (_compatibilityFilter != null) _compatibilityFilter.valNoCallback = "Asset compatibility: " + compatibility;
            if (_selectedAtomUid != null) _selectedAtomUid.valNoCallback = "Selected Person UID: " + (string.IsNullOrEmpty(uid) ? "(none)" : uid);
            if (_sectionKey != null) _sectionKey.valNoCallback = "Section: " + section;

            if (_contextKey != null)
                _contextKey.valNoCallback = "Catalog context: " + Normalize(uid) + "|" + sex + "|" + section + "|" + subsection + "|P" + page + "|" + compatibility;
        }


        private void SubscribeSceneEvents()
        {
            try
            {
                SuperController.singleton.onAtomAddedHandlers += OnAtomAdded;
            }
            catch (Exception e)
            {
                SuperController.LogError("CharacterRouter: could not subscribe to atom-added event: " + e);
            }
        }

        private void UnsubscribeSceneEvents()
        {
            try
            {
                SuperController.singleton.onAtomAddedHandlers -= OnAtomAdded;
            }
            catch { }
        }

        private void OnAtomAdded(Atom atom)
        {
            if (atom == null || atom.type != "Person")
                return;

            // During our factory workflow the Person initially belongs to the temporary
            // SubScene and therefore has a transient UID such as CHAR_FACTORY/Person#2.
            // Do not expose that temporary state in the HUD and do not run fallback
            // relocation; the factory coroutine owns the whole transaction.
            if (_controlledSpawnInProgress)
                return;

            // A newly-created Atom may reuse a UID that belonged to a deleted Person.
            // Per-character state must belong to the atom instance, not just that reused UID.
            ClearPerPersonStateForFreshAtom(atom.uid);

            // Persons created outside CharacterRouter have no reliable creation Look.
            // Reset remains unavailable for them instead of guessing/snapshotting.

            // Refresh roster immediately so a Person created through VaM's native UI
            // appears without waiting for the periodic discovery pass.
            RefreshRoster(true);

            // Fallback compatibility for a Person created through VaM's native Add Atom UI.
            if (_autoRelocateNewPersons == null || !_autoRelocateNewPersons.val)
                return;

            int sequenceIndex = Mathf.Max(_spawnSequenceIndex, _persons.Count - 1);
            _spawnSequenceIndex = sequenceIndex + 1;

            StartCoroutine(RelocateNewPersonCoroutine(atom, sequenceIndex));
        }

        private bool IsCharacterCreationMode()
        {
            return _creationModeSex == "F" ||
                   _creationModeSex == "M" ||
                   _creationModeSex == "X";
        }

        private void BeginAddFemale()
        {
            BeginCharacterCreation("F");
        }

        private void BeginAddMale()
        {
            BeginCharacterCreation("M");
        }

        private void BeginAddFutanari()
        {
            BeginCharacterCreation("X");
        }

        private void BeginCharacterCreation(string sex)
        {
            if (_controlledSpawnInProgress || _lookApplyInProgress)
            {
                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback =
                        "Spawn: finish the current operation first.";
                return;
            }

            _creationModeSex =
                sex == "M"
                ? "M"
                : (sex == "X" ? "X" : "F");

            if (_section != null)
                _section.val = "Looks";

            UpdateSubsectionChoices();

            if (_subsection != null &&
                _subsection.choices != null &&
                _subsection.choices.Contains("All"))
            {
                _subsection.valNoCallback = "All";
            }

            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;

            UpdateDerivedState();
            UpdateButtonSelectionVisuals();
            ApplyLayout();
            RebuildLookCatalogPage();
        }

        private void CancelCharacterCreation()
        {
            if (!IsCharacterCreationMode())
                return;

            _creationModeSex = "";

            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;

            UpdateDerivedState();
            UpdateButtonSelectionVisuals();
            ApplyLayout();
            RebuildLookCatalogPage();
        }

        // Old saved bindings enter the female picker instead of spawning default VaM Person.
        private void AddCharacterSafely()
        {
            BeginAddFemale();
        }

        private string GetNextPersonUid()
        {
            List<string> uids = SuperController.singleton.GetAtomUIDs();

            if (!uids.Contains("Person"))
                return "Person";

            int index = 2;
            while (uids.Contains("Person#" + index))
                index++;

            return "Person#" + index;
        }

        private class CollisionState
        {
            public JSONStorableBool storable;
            public bool value;
        }

        private List<CollisionState> TemporarilyDisableExistingPersonCollisions()
        {
            List<CollisionState> states = new List<CollisionState>();

            if (_disableCollisionDuringSpawn == null || !_disableCollisionDuringSpawn.val)
                return states;

            List<Atom> atoms = SuperController.singleton.GetAtoms();
            for (int i = 0; i < atoms.Count; i++)
            {
                Atom a = atoms[i];
                if (a == null || a.type != "Person")
                    continue;

                JSONStorableBool collision = GetCollisionEnabledStorable(a);
                if (collision == null)
                    continue;

                CollisionState state = new CollisionState();
                state.storable = collision;
                state.value = collision.val;
                states.Add(state);

                collision.val = false;
            }

            return states;
        }

        private void RestoreCollisionStates(List<CollisionState> states)
        {
            if (states == null)
                return;

            for (int i = 0; i < states.Count; i++)
            {
                CollisionState state = states[i];
                if (state != null && state.storable != null)
                    state.storable.val = state.value;
            }
        }

        private string ResolveFactorySubScenePath()
        {
            string requested = _factorySubScenePath != null
                ? (_factorySubScenePath.val == null ? "" : _factorySubScenePath.val.Trim())
                : "";

            if (string.IsNullOrEmpty(requested))
                requested = "Custom/SubScene/Gleb/CHAR_FACTORY/DefaultPerson.json";

            requested = requested.Replace("\\", "/");

            if (string.Equals(requested, _lastFactoryPathInput, StringComparison.Ordinal) &&
                Time.realtimeSinceStartup < _nextFactoryPathCheckAt)
            {
                return _resolvedFactoryPath;
            }

            _lastFactoryPathInput = requested;
            _nextFactoryPathCheckAt = Time.realtimeSinceStartup + 1.0f;
            _resolvedFactoryPath = "";

            // VaM stores local SubScenes beneath Custom/SubScene/<Creator>/<Signature>/...
            // depending on creator metadata. Keep several compatible fallbacks so the
            // scene survives creator/path changes without manual editing.
            List<string> candidates = new List<string>();
            candidates.Add(requested);

            string creatorPath = "Custom/SubScene/Gleb/CHAR_FACTORY/DefaultPerson.json";
            string creatorPathPlural = "Custom/Subscenes/Gleb/CHAR_FACTORY/DefaultPerson.json";
            string noCreatorPath = "Custom/SubScene/CHAR_FACTORY/DefaultPerson.json";
            string noCreatorPathPlural = "Custom/Subscenes/CHAR_FACTORY/DefaultPerson.json";

            if (!candidates.Contains(creatorPath)) candidates.Add(creatorPath);
            if (!candidates.Contains(creatorPathPlural)) candidates.Add(creatorPathPlural);
            if (!candidates.Contains(noCreatorPath)) candidates.Add(noCreatorPath);
            if (!candidates.Contains(noCreatorPathPlural)) candidates.Add(noCreatorPathPlural);

            try
            {
                for (int i = 0; i < candidates.Count; i++)
                {
                    string candidate = candidates[i];
                    if (FileManagerSecure.FileExists(candidate))
                    {
                        _resolvedFactoryPath = candidate;

                        // Keep the UI synchronized with the actually found path.
                        if (_factorySubScenePath != null &&
                            !string.Equals(_factorySubScenePath.val, candidate, StringComparison.Ordinal))
                        {
                            _factorySubScenePath.valNoCallback = candidate;
                        }

                        return _resolvedFactoryPath;
                    }
                }
            }
            catch (Exception e)
            {
                SuperController.LogError("CharacterRouter: factory path check failed: " + e);
            }

            return "";
        }

        private List<Atom> SnapshotPersonAtoms()
        {
            List<Atom> result = new List<Atom>();
            List<Atom> atoms = SuperController.singleton.GetAtoms();

            for (int i = 0; i < atoms.Count; i++)
            {
                Atom a = atoms[i];
                if (a != null && a.type == "Person")
                    result.Add(a);
            }

            return result;
        }

        private Atom FindNewPersonSince(List<Atom> before)
        {
            List<Atom> atoms = SuperController.singleton.GetAtoms();

            for (int i = 0; i < atoms.Count; i++)
            {
                Atom a = atoms[i];
                if (a == null || a.type != "Person")
                    continue;

                if (before == null || !before.Contains(a))
                    return a;
            }

            return null;
        }

        private int CountCustomUnityAssetAtomsForPerson(Atom person)
        {
            if (person == null || string.IsNullOrEmpty(person.uid) ||
                SuperController.singleton == null)
                return 0;

            string prefix = person.uid + "#";
            int count = 0;

            try
            {
                List<Atom> atoms = SuperController.singleton.GetAtoms();
                if (atoms == null)
                    return 0;

                for (int i = 0; i < atoms.Count; i++)
                {
                    Atom atom = atoms[i];
                    if (atom == null || atom.type != "CustomUnityAsset" ||
                        string.IsNullOrEmpty(atom.uid))
                        continue;

                    if (atom.uid.StartsWith(prefix, StringComparison.Ordinal))
                        count++;
                }
            }
            catch
            {
                return 0;
            }

            return count;
        }

        // Stopper.CUAClothing creates separate scene atoms for Black Widow's
        // accessories. VaM does not consistently remove these atoms when the
        // owning Person disappears. A later Person can reuse the same UID and
        // RestoreFromLast then sees the old, already destroyed asset loaders.
        // Match both the owner's full UID and this Look's generated plugin UID;
        // never touch a CUA that the user added independently.
        private List<Atom> GetBlackWidowClothingCuaAtoms(string personUid)
        {
            List<Atom> result = new List<Atom>();
            if (string.IsNullOrEmpty(personUid) ||
                SuperController.singleton == null)
                return result;

            string prefix = personUid + "#DitzyDitz:BW_";
            List<Atom> atoms = SuperController.singleton.GetAtoms();
            if (atoms == null)
                return result;

            for (int i = 0; i < atoms.Count; i++)
            {
                Atom cua = atoms[i];
                if (cua != null && cua.type == "CustomUnityAsset" &&
                    !string.IsNullOrEmpty(cua.uid) &&
                    cua.uid.StartsWith(prefix, StringComparison.Ordinal) &&
                    cua.uid.IndexOf("_Stopper.CUAClothing",
                        StringComparison.OrdinalIgnoreCase) >= 0)
                    result.Add(cua);
            }

            return result;
        }

        private IEnumerator RemoveBlackWidowClothingCuaAtoms(string personUid)
        {
            // Wait until the owner's plugin is destroyed so it cannot recreate
            // the generated CUA while we remove it. Keep the Router's spawn lock
            // until the CUA atom list has settled.
            float deadline = Time.realtimeSinceStartup + 5f;
            while (SuperController.singleton != null &&
                   SuperController.singleton.GetAtomByUid(personUid) != null &&
                   Time.realtimeSinceStartup < deadline)
                yield return null;

            if (SuperController.singleton == null ||
                SuperController.singleton.GetAtomByUid(personUid) != null)
            {
                SuperController.LogError(
                    "CharacterRouter v240 REMOVE | stage=CUA_CLEANUP_BLOCKED" +
                    " | person=" + personUid + " | reason=person_still_present");
                yield break;
            }

            List<Atom> owned = GetBlackWidowClothingCuaAtoms(personUid);
            SuperController.LogMessage(
                "CharacterRouter v240 REMOVE | stage=CUA_CLEANUP_BEGIN" +
                " | person=" + personUid + " | count=" + owned.Count);

            for (int i = 0; i < owned.Count; i++)
            {
                Atom cua = owned[i];
                if (cua == null)
                    continue;

                string cuaUid = cua.uid;
                try
                {
                    SuperController.singleton.RemoveAtom(cua);
                    SuperController.LogMessage(
                        "CharacterRouter v240 REMOVE | stage=CUA_REMOVED" +
                        " | person=" + personUid + " | cua=" + cuaUid);
                }
                catch (Exception e)
                {
                    SuperController.LogError(
                        "CharacterRouter v240 REMOVE | stage=CUA_REMOVE_ERROR" +
                        " | person=" + personUid + " | cua=" + cuaUid +
                        " | detail=" + e);
                }
                // Atom and native Unity destruction can finish on later frames.
                yield return null;
            }

            yield return new WaitForEndOfFrame();
            yield return null;
            SuperController.LogMessage(
                "CharacterRouter v240 REMOVE | stage=CUA_CLEANUP_DONE" +
                " | person=" + personUid + " | remaining=" +
                GetBlackWidowClothingCuaAtoms(personUid).Count);
        }

        private IEnumerator DiagnoseBlackWidowHair(Atom person)
        {
            yield return new WaitForSecondsRealtime(4.0f);
            if (person == null || SuperController.singleton == null)
                yield break;

            string prefix = person.uid + "#DitzyDitz:BW_Hair#";
            int count = 0;
            MVRPluginManager[] managers =
                person.GetComponentsInChildren<MVRPluginManager>(true);
            int hairManagers = 0;
            for (int m = 0; managers != null && m < managers.Length; m++)
            {
                try
                {
                    JSONClass state = managers[m].GetJSON(true, true, true);
                    string id = state == null ? "" : state["id"].Value;
                    if (id.IndexOf("DitzyDitz:BW_Hair",
                            StringComparison.OrdinalIgnoreCase) < 0)
                        continue;
                    hairManagers++;
                    JSONArray stored = state["storables"].AsArray;
                    JSONNode client = null;
                    for (int s = 0; stored != null && s < stored.Count; s++)
                    {
                        if (stored[s] != null &&
                            stored[s]["id"].Value.IndexOf("_Stopper.CUAClothing",
                                StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            client = stored[s];
                            break;
                        }
                    }
                    SuperController.LogMessage(
                        "CharacterRouter v240 BW HAIR | stage=PLUGIN_STATE" +
                        " | person=" + person.uid + " | id=" + id +
                        " | asset=" + (client == null ? "" : client["assetName"].Value) +
                        " | url=" + (client == null ? "" : client["assetUrl"].Value));
                }
                catch (Exception e)
                {
                    SuperController.LogError(
                        "CharacterRouter v240 BW HAIR | stage=PLUGIN_ERROR" +
                        " | detail=" + e.Message);
                }
            }
            SuperController.LogMessage(
                "CharacterRouter v240 BW HAIR | stage=MANAGERS" +
                " | person=" + person.uid +
                " | managers=" + (managers == null ? 0 : managers.Length) +
                " | hair=" + hairManagers);
            List<Atom> atoms = SuperController.singleton.GetAtoms();
            for (int i = 0; atoms != null && i < atoms.Count; i++)
            {
                Atom cua = atoms[i];
                if (cua == null || cua.type != "CustomUnityAsset" ||
                    !cua.uid.StartsWith(prefix, StringComparison.Ordinal))
                    continue;

                count++;
                JSONStorable asset = cua.GetStorableByID("asset");
                JSONClass state = asset == null ? null :
                    asset.GetJSON(true, true, true);
                Renderer[] renderers =
                    cua.GetComponentsInChildren<Renderer>(true);
                int visible = 0;
                for (int j = 0; j < renderers.Length; j++)
                    if (renderers[j] != null && renderers[j].enabled &&
                        renderers[j].gameObject.activeInHierarchy)
                        visible++;

                SuperController.LogMessage(
                    "CharacterRouter v240 BW HAIR | stage=CUA_STATE" +
                    " | person=" + person.uid + " | cua=" + cua.uid +
                    " | asset=" + (state == null ? "" : state["assetName"].Value) +
                    " | url=" + (state == null ? "" : state["assetUrl"].Value) +
                    " | dll=" + (state == null ? "" : state["assetDllUrl"].Value) +
                    " | renderers=" + renderers.Length +
                    " | visibleRenderers=" + visible +
                    " | position=" + cua.transform.position);
            }
            SuperController.LogMessage(
                "CharacterRouter v240 BW HAIR | stage=DONE" +
                " | person=" + person.uid + " | cuaCount=" + count);
        }

        private IEnumerator WaitForVaMLoadingToFinish(float timeoutSeconds)
        {
            // browsePath can raise isLoading asynchronously; cross a frame boundary first.
            yield return new WaitForEndOfFrame();

            float deadline = Time.realtimeSinceStartup + timeoutSeconds;
            while (SuperController.singleton != null &&
                   SuperController.singleton.isLoading &&
                   Time.realtimeSinceStartup < deadline)
            {
                yield return null;
            }
        }

        private void SafeRemoveAtom(Atom atom)
        {
            if (atom == null || SuperController.singleton == null)
                return;

            try
            {
                SuperController.singleton.RemoveAtom(atom);
            }
            catch (Exception e)
            {
                SuperController.LogError("CharacterRouter: could not remove temporary factory atom: " + e);
            }
        }

        private Vector3 HorizontalNormalized(Vector3 v, Vector3 fallback)
        {
            v.y = 0f;
            if (v.sqrMagnitude < 0.0001f)
                v = fallback;

            v.Normalize();
            return v;
        }

        private bool IsFarEnoughFromPersons(
            Vector3 candidate,
            List<Atom> existingPersons,
            float minimumSpacing)
        {
            if (existingPersons == null)
                return true;

            float minSq = minimumSpacing * minimumSpacing;

            for (int i = 0; i < existingPersons.Count; i++)
            {
                Atom person = existingPersons[i];
                if (person == null || person.mainController == null)
                    continue;

                Vector3 p = person.mainController.transform.position;

                // A Person on a clearly different vertical level should not reserve
                // this floor's X/Z position.
                if (Mathf.Abs(p.y - candidate.y) > 1.6f)
                    continue;

                float dx = p.x - candidate.x;
                float dz = p.z - candidate.z;
                float horizontalSq = dx * dx + dz * dz;

                if (horizontalSq < minSq)
                    return false;
            }

            return true;
        }

        private bool IsApproximateStandingVolumeClear(Vector3 candidate)
        {
            // Person root/control in VaM sits above floor level. This capsule checks
            // the torso/head volume while deliberately staying clear of the floor.
            // Existing Person collisions are disabled before this function is used,
            // so hits here are normally environment/prop colliders.
            try
            {
                Vector3 lower = candidate + Vector3.up * 0.05f;
                Vector3 upper = candidate + Vector3.up * 1.05f;
                float radius = 0.28f;

                Collider[] hits = Physics.OverlapCapsule(
                    lower,
                    upper,
                    radius,
                    ~0,
                    QueryTriggerInteraction.Ignore
                );

                return hits == null || hits.Length == 0;
            }
            catch
            {
                // Dynamic placement must remain usable even in an unusual scene where
                // collider querying fails.
                return true;
            }
        }

        private bool TryFindDynamicSpawnPosition(
            Transform spawn,
            List<Atom> existingPersons,
            float minimumSpacing,
            float requestedRadius,
            bool requireSceneClearance,
            out Vector3 result)
        {
            result = spawn.position;

            Vector3 right = HorizontalNormalized(spawn.right, Vector3.right);
            Vector3 forward = HorizontalNormalized(spawn.forward, Vector3.forward);

            // First try the exact marker. If the current actor has moved away, the
            // central slot becomes reusable automatically.
            if (IsFarEnoughFromPersons(result, existingPersons, minimumSpacing) &&
                (!requireSceneClearance || IsApproximateStandingVolumeClear(result)))
            {
                return true;
            }

            float radialStep = Mathf.Max(0.65f, minimumSpacing);
            float searchRadius = Mathf.Max(requestedRadius, radialStep);

            // Guarantee enough search area for larger casts without making the user
            // manually enlarge a slider after every few actors.
            if (existingPersons != null)
            {
                float populationRadius =
                    radialStep * Mathf.Max(2f, Mathf.Sqrt(existingPersons.Count + 1f) * 2f);
                searchRadius = Mathf.Max(searchRadius, populationRadius);
            }

            const int samplesPerRing = 16;

            for (float radius = radialStep;
                 radius <= searchRadius + 0.001f;
                 radius += radialStep)
            {
                for (int i = 0; i < samplesPerRing; i++)
                {
                    float angle = (360f / samplesPerRing) * i * Mathf.Deg2Rad;
                    Vector3 direction =
                        right * Mathf.Cos(angle) +
                        forward * Mathf.Sin(angle);

                    Vector3 candidate = spawn.position + direction * radius;
                    candidate.y = spawn.position.y;

                    if (!IsFarEnoughFromPersons(
                            candidate,
                            existingPersons,
                            minimumSpacing))
                        continue;

                    if (requireSceneClearance &&
                        !IsApproximateStandingVolumeClear(candidate))
                        continue;

                    result = candidate;
                    return true;
                }
            }

            return false;
        }

        private Vector3 FindBestSpawnPosition(
            Transform spawn,
            List<Atom> existingPersons,
            out bool usedEnvironmentFallback)
        {
            usedEnvironmentFallback = false;

            float spacing =
                _spawnSpacing != null ? Mathf.Max(0.5f, _spawnSpacing.val) : 1.35f;

            float searchRadius =
                _spawnSearchRadius != null ? Mathf.Max(1f, _spawnSearchRadius.val) : 5f;

            bool dynamic =
                _dynamicFreeSpawn == null || _dynamicFreeSpawn.val;

            if (!dynamic)
            {
                int slotIndex = Mathf.Max(_spawnSequenceIndex, existingPersons != null ? existingPersons.Count : 0);
                float offset = GetSymmetricSpawnOffset(slotIndex) * spacing;
                return spawn.position + spawn.right * offset;
            }

            bool avoidColliders =
                _avoidSceneColliders == null || _avoidSceneColliders.val;

            Vector3 candidate;

            // Pass 1: free of other Persons AND approximately free of scene geometry.
            if (TryFindDynamicSpawnPosition(
                    spawn,
                    existingPersons,
                    spacing,
                    searchRadius,
                    avoidColliders,
                    out candidate))
            {
                return candidate;
            }

            // Some environments use large/odd colliders that can make every capsule
            // query look occupied. In that case, do not make Add Character unusable:
            // retry using Person spacing only.
            if (avoidColliders &&
                TryFindDynamicSpawnPosition(
                    spawn,
                    existingPersons,
                    spacing,
                    searchRadius,
                    false,
                    out candidate))
            {
                usedEnvironmentFallback = true;
                return candidate;
            }

            // Very defensive last resort: place beyond the configured search radius.
            usedEnvironmentFallback = true;
            Vector3 right = HorizontalNormalized(spawn.right, Vector3.right);
            return spawn.position + right * (searchRadius + spacing);
        }

        private string GetUniqueAtomUid(string baseUid)
        {
            if (string.IsNullOrEmpty(baseUid))
                baseUid = "Atom";

            List<string> uids = SuperController.singleton.GetAtomUIDs();

            if (uids == null || !uids.Contains(baseUid))
                return baseUid;

            int index = 2;
            string candidate = baseUid + "#" + index;

            while (uids.Contains(candidate))
            {
                index++;
                candidate = baseUid + "#" + index;
            }

            return candidate;
        }

        private bool InvokeNativeSubSceneUnparentAll(Atom factory)
        {
            if (factory == null)
                return false;

            try
            {
                JSONStorable subsceneStorable = factory.GetStorableByID("SubScene");
                if (subsceneStorable == null)
                    return false;

                // VaM 1.22 exposes this operation as a button on the SubScene panel.
                // Registered action labels can vary slightly between builds/resources,
                // so probe a small set of likely names through the public GetAction API.
                string[] candidates = new string[]
                {
                    "Un-parent All Atoms From This SubScene",
                    "Unparent All Atoms From This SubScene",
                    "Un-parent All Atoms",
                    "Unparent All Atoms",
                    "UnparentAllAtomsFromThisSubScene",
                    "UnparentAllAtoms"
                };

                for (int i = 0; i < candidates.Length; i++)
                {
                    JSONStorableAction action = subsceneStorable.GetAction(candidates[i]);
                    if (action != null && action.actionCallback != null)
                    {
                        action.actionCallback();
                        return true;
                    }
                }
            }
            catch (Exception e)
            {
                SuperController.LogError(
                    "CharacterRouter: native SubScene unparent action failed: " + e
                );
            }

            return false;
        }

        private IEnumerator WaitForSubSceneRestoreToSettle()
        {
            // isLoading may go false slightly before all atom/subscene restore work
            // has finished. AcidBubbles' VaM utilities commonly also wait for
            // freezeAnimation to clear before acting on freshly spawned atoms.
            while (SuperController.singleton != null &&
                   (SuperController.singleton.isLoading ||
                    SuperController.singleton.freezeAnimation))
            {
                yield return null;
            }

            // Cross several Update/physics boundaries so SubScene can finish restoring
            // parent membership and UID bookkeeping before we ask it to un-parent.
            for (int i = 0; i < 12; i++)
                yield return null;

            yield return new WaitForFixedUpdate();
            yield return new WaitForFixedUpdate();

            // A short real-time grace period makes this robust on slower/heavily-modded
            // installations without adding a noticeable delay to normal use.
            yield return new WaitForSecondsRealtime(0.35f);
        }

        private bool IsStillInsideFactory(Atom person, Atom factory)
        {
            if (person == null || factory == null)
                return false;

            string personUid = person.uid == null ? "" : person.uid;
            string factoryUid = factory.uid == null ? "" : factory.uid;

            if (string.IsNullOrEmpty(personUid) || string.IsNullOrEmpty(factoryUid))
                return false;

            return personUid.StartsWith(factoryUid + "/", StringComparison.Ordinal);
        }

        private IEnumerator WaitForPersonToDetachFromFactory(
            Atom person,
            Atom factory,
            float timeoutSeconds)
        {
            float deadline = Time.realtimeSinceStartup + timeoutSeconds;

            // VaM 1.22 may need several update/physics passes to normalize the atom UID
            // and SubScene ownership after ClearParentAtom().  Do not delete the factory
            // until the UID no longer carries the SubScene prefix.
            while (person != null &&
                   factory != null &&
                   IsStillInsideFactory(person, factory) &&
                   Time.realtimeSinceStartup < deadline)
            {
                yield return null;
            }
        }

        private int ClearFreshSpawnPersonPlugins(Atom person)
        {
            if (person == null)
                return 0;

            MVRPluginManager manager =
                person.GetStorableByID("PluginManager")
                    as MVRPluginManager;

            if (manager == null)
                return 0;

            List<string> slots =
                new List<string>();

            try
            {
                JSONClass state =
                    manager.GetJSON(true, true, true);

                JSONClass plugins =
                    state == null
                    ? null
                    : state["plugins"].AsObject;

                if (plugins != null)
                {
                    foreach (string slot in plugins.Keys)
                        slots.Add(slot);
                }
            }
            catch (Exception e)
            {
                SuperController.LogMessage(
                    "CharacterRouter v130: could not enumerate fresh-spawn Person plugins: " +
                    e.Message
                );
                return 0;
            }

            int removed = 0;

            for (int i = 0; i < slots.Count; i++)
            {
                try
                {
                    manager.RemovePluginWithUID(
                        slots[i]
                    );
                    removed++;
                }
                catch (Exception e)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v130: could not remove inherited fresh-spawn plugin " +
                        slots[i] + ": " + e.Message
                    );
                }
            }

            return removed;
        }

        private List<DAZClothingItem> GetActiveSimulatedClothingItems(Atom person)
        {
            List<DAZClothingItem> result =
                new List<DAZClothingItem>();

            if (person == null)
                return result;

            try
            {
                DAZCharacterSelector selector =
                    person.GetStorableByID("geometry")
                        as DAZCharacterSelector;

                if (selector == null ||
                    selector.clothingItems == null)
                {
                    return result;
                }

                for (int i = 0; i < selector.clothingItems.Length; i++)
                {
                    DAZClothingItem item =
                        selector.clothingItems[i];

                    if (item == null || !item.active)
                        continue;

                    ClothSimControl sim =
                        item.GetComponentInChildren<ClothSimControl>();

                    if (sim != null)
                        result.Add(item);
                }
            }
            catch (Exception e)
            {
                SuperController.LogMessage(
                    "CharacterRouter v135: could not enumerate active simulated clothing: " +
                    e.Message
                );
            }

            return result;
        }

        private IEnumerator RebuildActiveSimulatedClothingAfterColliderReadiness(
            Atom person,
            string label)
        {
            if (person == null)
                yield break;

            DAZCharacterSelector selector = null;

            try
            {
                selector =
                    person.GetStorableByID("geometry")
                        as DAZCharacterSelector;
            }
            catch { }

            if (selector == null)
                yield break;

            List<DAZClothingItem> items =
                GetActiveSimulatedClothingItems(person);

            if (items.Count == 0)
                yield break;

            // Equivalent to the confirmed manual fix:
            // uncheck the active simulated clothing item(s), wait for destruction,
            // then check them again after collider plugins are already live.
            int disabled = 0;

            for (int i = 0; i < items.Count; i++)
            {
                DAZClothingItem item = items[i];
                if (item == null)
                    continue;

                try
                {
                    selector.SetActiveClothingItem(
                        item,
                        false
                    );
                    disabled++;
                }
                catch (Exception e)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v135: could not disable simulated clothing " +
                        (item.displayName ?? item.name) +
                        ": " + e.Message
                    );
                }
            }

            if (disabled == 0)
                yield break;

            yield return null;
            yield return new WaitForEndOfFrame();
            yield return new WaitForFixedUpdate();

            int restored = 0;

            for (int i = 0; i < items.Count; i++)
            {
                DAZClothingItem item = items[i];
                if (item == null)
                    continue;

                try
                {
                    selector.SetActiveClothingItem(
                        item,
                        true
                    );
                    restored++;
                }
                catch (Exception e)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v135: could not restore simulated clothing " +
                        (item.displayName ?? item.name) +
                        ": " + e.Message
                    );
                }
            }

            yield return new WaitForEndOfFrame();
            yield return new WaitForFixedUpdate();

            SuperController.LogMessage(
                "CharacterRouter v135: rebuilt " +
                restored +
                " active simulated clothing item(s) after collider readiness for " +
                (label ?? "") +
                "."
            );
        }

        private IEnumerator AddCharacterSafelyCoroutine(
            string initialLookPath,
            string requestedSex,
            string initialLookLabel,
            string initialLookKey)
        {
            _controlledSpawnInProgress = true;

            int diagnosticSpawnSerial = ++_sceneLookDiagnosticSpawnSerial;
            bool diagnosticPirateSceneLook =
                !string.IsNullOrEmpty(initialLookKey) &&
                (
                    initialLookKey.IndexOf(
                        "Damarmau.pirate_queen",
                        StringComparison.OrdinalIgnoreCase) >= 0 ||
                    initialLookKey.IndexOf(
                        "Pirate",
                        StringComparison.OrdinalIgnoreCase) >= 0
                );

            if (diagnosticPirateSceneLook)
            {
                _decalMakerAdapter.DiagnosticNote(
                    "SPAWN PIRATE BEGIN | requestedSex=" +
                    (requestedSex ?? "") +
                    " | label=" + (initialLookLabel ?? "") +
                    " | key=" + (initialLookKey ?? "") +
                    " | loadPath=" + (initialLookPath ?? "")
                );
            }

            bool diagnosticSceneLook =
                !string.IsNullOrEmpty(initialLookKey) &&
                initialLookKey.StartsWith(
                    "SCENELOOK|",
                    StringComparison.OrdinalIgnoreCase
                ) &&
                (
                    (!string.IsNullOrEmpty(initialLookLabel) &&
                     initialLookLabel.IndexOf("Nico", StringComparison.OrdinalIgnoreCase) >= 0) ||
                    initialLookKey.IndexOf("paledriver.Nico", StringComparison.OrdinalIgnoreCase) >= 0
                );

            if (diagnosticSceneLook)
            {
                AppendSceneLookDiagnostic(
                    "=== SPAWN #" + diagnosticSpawnSerial +
                    " BEGIN | requestedSex=" + (requestedSex ?? "") +
                    " | label=" + (initialLookLabel ?? "") +
                    " | key=" + (initialLookKey ?? "") +
                    " | loadPath=" + (initialLookPath ?? "") + " ==="
                );
            }

            Atom factory = null;
            Atom created = null;
            List<CollisionState> existingCollisionStates = null;
            JSONStorableBool createdCollision = null;
            bool createdCollisionOld = true;
            bool createdCollisionChanged = false;

            JSONStorableBool createdHidden = null;
            bool createdHiddenOld = false;
            bool createdHiddenChanged = false;

            string factoryPath = ResolveFactorySubScenePath();
            Transform spawn = GetSpawnPointTransform();

            if (string.IsNullOrEmpty(factoryPath))
            {
                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback =
                        "Spawn: factory file not found. Check Factory SubScene Path.";
                _controlledSpawnInProgress = false;
                yield break;
            }

            if (spawn == null)
            {
                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback =
                        "Spawn: CHAR_SPAWN marker not found/ready.";
                _controlledSpawnInProgress = false;
                yield break;
            }

            // Existing Person atoms are snapshotted by object reference so we can identify
            // exactly which Person the SubScene load created, regardless of the transient UID.
            List<Atom> beforePersons = SnapshotPersonAtoms();

            // Disable existing actor collisions before both the environment probe and
            // SubScene loading. This prevents the probe from treating actors as props and
            // prevents physics interaction while the new actor is materializing.
            existingCollisionStates = TemporarilyDisableExistingPersonCollisions();

            bool usedEnvironmentFallback = false;
            Vector3 targetPosition = FindBestSpawnPosition(
                spawn,
                beforePersons,
                out usedEnvironmentFallback
            );
            Quaternion targetRotation = spawn.rotation;

            string factoryUid = GetUniqueAtomUid("CHAR_FACTORY_TEMP");

            if (_spawnStatus != null)
                _spawnStatus.valNoCallback = "Spawn: creating temporary SubScene factory...";

            IEnumerator addFactory = null;
            try
            {
                addFactory = SuperController.singleton.AddAtomByType(
                    "SubScene",
                    factoryUid,
                    false,
                    false,
                    false
                );
            }
            catch (Exception e)
            {
                RestoreCollisionStates(existingCollisionStates);
                _controlledSpawnInProgress = false;

                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback = "Spawn: could not create factory SubScene.";

                SuperController.LogError("CharacterRouter: Add SubScene failed: " + e);
                yield break;
            }

            if (addFactory != null)
            {
                while (addFactory.MoveNext())
                    yield return addFactory.Current;
            }

            factory = SuperController.singleton.GetAtomByUid(factoryUid);

            int factoryReadyAttempts = 0;
            while (factory != null && factory.mainController == null && factoryReadyAttempts < 120)
            {
                factoryReadyAttempts++;
                yield return null;
            }

            if (factory == null || factory.mainController == null)
            {
                RestoreCollisionStates(existingCollisionStates);
                _controlledSpawnInProgress = false;

                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback = "Spawn: temporary SubScene was not created.";

                yield break;
            }

            // Build the factory directly at the final spawn position. This is the
            // transform path that was already proven reliable before remote staging
            // was introduced.
            factory.mainController.transform.position = targetPosition;
            factory.mainController.transform.rotation = targetRotation;

            if (_spawnStatus != null)
            {
                _spawnStatus.valNoCallback =
                    usedEnvironmentFallback
                    ? "Spawn: loading at nearest Person-safe fallback position..."
                    : "Spawn: loading DefaultPerson at dynamically selected free position...";
            }

            bool browseAssigned = false;
            try
            {
                JSONStorable subsceneStorable = factory.GetStorableByID("SubScene");
                if (subsceneStorable == null)
                    throw new Exception("Temporary atom has no SubScene storable.");

                JSONStorableUrl browsePath =
                    subsceneStorable.GetUrlJSONParam("browsePath");
                if (browsePath == null)
                    throw new Exception("SubScene storable has no browsePath.");

                browsePath.val =
                    SuperController.singleton.NormalizePath(factoryPath);
                browseAssigned = true;
            }
            catch (Exception e)
            {
                SuperController.LogError("CharacterRouter: factory SubScene load start failed: " + e);
            }

            if (!browseAssigned)
            {
                SafeRemoveAtom(factory);
                RestoreCollisionStates(existingCollisionStates);
                _controlledSpawnInProgress = false;

                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback = "Spawn: could not start factory SubScene load.";

                yield break;
            }

            yield return WaitForVaMLoadingToFinish(120f);

            created = FindNewPersonSince(beforePersons);

            if (created == null)
            {
                SafeRemoveAtom(factory);
                RestoreCollisionStates(existingCollisionStates);
                _controlledSpawnInProgress = false;

                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback =
                        "Spawn: factory loaded but no new Person was found.";

                yield break;
            }

            // The template was authored with local position/rotation = 0 relative to the
            // SubScene. Still force the root to the requested slot before unparenting so
            // a later template edit cannot silently shift the actor.
            int personReadyAttempts = 0;
            while (created != null &&
                   created.mainController == null &&
                   personReadyAttempts < 120)
            {
                personReadyAttempts++;
                yield return null;
            }

            if (created == null || created.mainController == null)
            {
                SafeRemoveAtom(factory);
                RestoreCollisionStates(existingCollisionStates);
                _controlledSpawnInProgress = false;

                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback =
                        "Spawn: loaded Person root was not ready.";

                yield break;
            }

            if (_disableCollisionDuringSpawn != null &&
                _disableCollisionDuringSpawn.val)
            {
                createdCollision = GetCollisionEnabledStorable(created);
                if (createdCollision != null)
                {
                    createdCollisionOld = createdCollision.val;
                    createdCollision.val = false;
                    createdCollisionChanged = true;
                }
            }

            // Keep the Person fully active while hiding it from the user.
            // AtomControl.On=false prevents Appearance loading reliably on VaM 1.22;
            // AtomControl.hidden is a separate native state and does not disable the atom.
            createdHidden = GetAtomHiddenStorable(created);

            if (createdHidden != null)
            {
                createdHiddenOld = createdHidden.val;
                createdHidden.val = true;
                createdHiddenChanged = true;
                yield return null;
            }

            if (string.IsNullOrEmpty(initialLookPath))
            {
                if (createdHiddenChanged && createdHidden != null)
                    createdHidden.val = createdHiddenOld;

                SafeRemoveAtom(factory);
                RestoreCollisionStates(existingCollisionStates);
                _controlledSpawnInProgress = false;
                yield break;
            }

            if (_spawnStatus != null)
                _spawnStatus.valNoCallback =
                    "Spawn: detaching Character before Appearance load...";

            // Do NOT apply Appearance while the Person is still inside the temporary
            // SubScene. Existing-character Look application was already proven reliable
            // only on a normal Person atom, so v31 deliberately waits until detach.

            // Do not spatially move the Person here. It was created at the final
            // target from the beginning; only visibility is suppressed.

            // IMPORTANT: v18 proved the native action exists ("UnparentAllAtoms"),
            // but calling it immediately after load was too early: VaM's SubScene restore
            // could still be finishing and would leave/reapply membership afterwards.
            // Wait until the restore pipeline is genuinely settled first.
            yield return WaitForSubSceneRestoreToSettle();

            bool nativeUnparentInvoked = InvokeNativeSubSceneUnparentAll(factory);

            if (nativeUnparentInvoked)
            {
                yield return WaitForPersonToDetachFromFactory(created, factory, 1.25f);

                // Retry once after another settle window. This mirrors the successful
                // manual test, where the button was pressed only after the SubScene had
                // been sitting fully loaded for a while.
                if (IsStillInsideFactory(created, factory))
                {
                    yield return WaitForSubSceneRestoreToSettle();
                    InvokeNativeSubSceneUnparentAll(factory);
                    yield return WaitForPersonToDetachFromFactory(created, factory, 2.0f);
                }
            }
            else
            {
                // Compatibility fallback only. Never delete the factory unless the
                // Person demonstrably leaves it.
                try
                {
                    created.ClearParentAtom();
                }
                catch (Exception e)
                {
                    SuperController.LogError(
                        "CharacterRouter: fallback ClearParentAtom failed: " + e
                    );
                }

                yield return WaitForPersonToDetachFromFactory(created, factory, 2.0f);
            }

            // Reassert the known-good final world transform after the parent/UID
            // transition. Because the factory itself was already at this position,
            // Person body controllers and root have never been separated spatially.
            if (created != null && created.mainController != null)
            {
                created.mainController.transform.position = targetPosition;
                created.mainController.transform.rotation = targetRotation;
            }

            bool detached = !IsStillInsideFactory(created, factory);

            if (detached)
            {
                // Only an actually empty factory is safe to remove.
                SafeRemoveAtom(factory);
                factory = null;
            }
            else
            {
                // Safety fallback: never delete the factory while the Person is still
                // owned by it.  The Person remains usable and visible; the container
                // can be cleaned up later once we automate VaM's native SubScene
                // "Un-parent All Atoms" behavior.
                // Keep the still-owned factory silently; Spawn Status reports the
                // retained-factory condition without flooding VaM's Message Log.
            }

            // CHAR_FACTORY is a construction template, not part of the Character.
            // On a brand-new hidden Person there cannot yet be user-owned plugins, so
            // remove every Person PluginManager slot inherited from the factory before
            // applying the chosen Look. Sweep twice to catch late restore callbacks.
            if (detached && created != null)
            {
                int removedFactoryPlugins =
                    ClearFreshSpawnPersonPlugins(created);

                yield return null;
                yield return new WaitForEndOfFrame();

                removedFactoryPlugins +=
                    ClearFreshSpawnPersonPlugins(created);

                if (removedFactoryPlugins > 0)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v130: removed " +
                        removedFactoryPlugins +
                        " inherited factory Person plugin slot(s) from " +
                        created.uid +
                        " before initial Look."
                    );
                }
            }

            bool initialLookLoaded = false;
            string lookError = "";

            if (detached)
            {
                // v146: a deleted Person may have owned transient BODY/genital
                // morphs under the same UID. ClearActive first drops any adapter
                // references that survived the old atom, then purges CR_BodySplit_*
                // from the freshly detached Person before its initial Appearance.
                _bodyPresetAdapter.ClearActive(
                    created,
                    created != null ? created.uid : ""
                );

                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback =
                        "Spawn: applying selected Appearance to detached Character...";

                // A freshly detached Person can expose AppearancePresets a few
                // frames before the rest of the Person restore pipeline is actually
                // ready to accept the first preset. This race is most visible on the
                // first Character created after opening an otherwise empty scene:
                // LoadPreset returns without throwing, but DefaultPerson remains.
                // Give the new Person a short settle window before the first load.
                yield return null;
                yield return new WaitForEndOfFrame();
                yield return new WaitForFixedUpdate();
                yield return null;

                if (diagnosticSceneLook)
                    DumpSceneLookRuntimeState(
                        created, diagnosticSpawnSerial,
                        "BEFORE FIRST APPEARANCE LOAD", initialLookLabel
                    );

                initialLookLoaded = ApplyAppearancePresetWithPath(
                    created,
                    initialLookPath,
                    out lookError
                );

                if (diagnosticPirateSceneLook)
                {
                    _decalMakerAdapter.DiagnosticNote(
                        "SPAWN PIRATE FIRST LoadPreset RETURNED | started=" +
                        initialLookLoaded +
                        " | error=" + (lookError ?? "") +
                        " | isLoading=" +
                        (SuperController.singleton != null &&
                         SuperController.singleton.isLoading)
                    );
                    StartCoroutine(
                        _decalMakerAdapter.ObserveVaMLoading(
                            created,
                            "SPAWN PIRATE FIRST LOAD",
                            1.20f
                        )
                    );
                }

                if (diagnosticSceneLook)
                {
                    AppendSceneLookDiagnostic(
                        "SPAWN #" + diagnosticSpawnSerial +
                        " FIRST LoadPreset returned started=" + initialLookLoaded +
                        " error=" + (lookError ?? "")
                    );
                    DumpSceneLookRuntimeState(
                        created, diagnosticSpawnSerial,
                        "IMMEDIATELY AFTER FIRST LoadPreset CALL", initialLookLabel
                    );
                }

                if (initialLookLoaded)
                {
                    yield return WaitForVaMLoadingToFinish(120f);
                    yield return new WaitForSecondsRealtime(0.35f);
                    yield return null;
                    yield return new WaitForFixedUpdate();

                    if (diagnosticSceneLook)
                        DumpSceneLookRuntimeState(
                            created, diagnosticSpawnSerial,
                            "AFTER FIRST LOAD SETTLE", initialLookLabel
                        );

                    // Fresh-spawn confirmation is useful for the normal VaM race where
                    // the first Appearance load returns successfully but the detached Person
                    // is not yet ready to retain the preset.  Testing showed
                    // that reloading the same Appearance while CUAClothingAlt has already
                    // created live CustomUnityAsset atoms can restart those asynchronous CUA
                    // loads mid-flight.  This was the material
                    // lifecycle difference behind repeated-spawn CUA failures.
                    //
                    // Therefore keep the confirmation pass for ordinary Looks and for
                    // the first CUA pass where no CUA atom exists yet, but never fire the second
                    // Appearance load while this Person already owns live CUA atoms.
                    int cuaAtomsBeforeConfirmation =
                        CountCustomUnityAssetAtomsForPerson(created);
                    // BW_Hair is a CUA backed clothing item. Its CUA atom can
                    // exist before the asset has actually loaded; an early
                    // second Appearance load resets the still-empty CUA. The
                    // first pass already applied Black Widow's clothing and
                    // geometry, so let its CUA plugins finish that pass.
                    bool blackWidowCua =
                        !string.IsNullOrEmpty(initialLookPath) &&
                        initialLookPath.StartsWith(
                            "DitzyDitz.Black_Widow_Character.",
                            StringComparison.OrdinalIgnoreCase) &&
                        !string.IsNullOrEmpty(initialLookLabel) &&
                        initialLookLabel.StartsWith("Black Widow",
                            StringComparison.OrdinalIgnoreCase);
                    bool skipConfirmationForActiveCua =
                        cuaAtomsBeforeConfirmation > 0 || blackWidowCua;

                    if (blackWidowCua)
                        SuperController.LogMessage(
                            "CharacterRouter v240 BW HAIR | stage=SKIP_CONFIRM_LOAD" +
                            " | person=" + created.uid +
                            " | cuaAtoms=" + cuaAtomsBeforeConfirmation);

                    if (diagnosticSceneLook)
                    {
                        AppendSceneLookDiagnostic(
                            "SPAWN #" + diagnosticSpawnSerial +
                            " CONFIRM DECISION | personCuaAtoms=" +
                            cuaAtomsBeforeConfirmation +
                            " | action=" +
                            (skipConfirmationForActiveCua ? "SKIP_ACTIVE_CUA" : "RUN")
                        );
                    }

                    if (!skipConfirmationForActiveCua)
                    {
                        string confirmLookError = "";
                        bool confirmLookStarted = ApplyAppearancePresetWithPath(
                            created,
                            initialLookPath,
                            out confirmLookError
                        );

                        if (diagnosticPirateSceneLook)
                        {
                            _decalMakerAdapter.DiagnosticNote(
                                "SPAWN PIRATE CONFIRM LoadPreset RETURNED | started=" +
                                confirmLookStarted +
                                " | error=" + (confirmLookError ?? "") +
                                " | isLoading=" +
                                (SuperController.singleton != null &&
                                 SuperController.singleton.isLoading)
                            );
                            StartCoroutine(
                                _decalMakerAdapter.ObserveVaMLoading(
                                    created,
                                    "SPAWN PIRATE CONFIRM LOAD",
                                    1.20f
                                )
                            );
                        }

                        if (diagnosticSceneLook)
                        {
                            AppendSceneLookDiagnostic(
                                "SPAWN #" + diagnosticSpawnSerial +
                                " CONFIRM LoadPreset returned started=" + confirmLookStarted +
                                " error=" + (confirmLookError ?? "")
                            );
                            DumpSceneLookRuntimeState(
                                created, diagnosticSpawnSerial,
                                "IMMEDIATELY AFTER CONFIRM LoadPreset CALL", initialLookLabel
                            );
                        }

                        if (confirmLookStarted)
                        {
                            yield return WaitForVaMLoadingToFinish(120f);
                            yield return new WaitForSecondsRealtime(0.35f);
                            yield return null;
                            yield return new WaitForFixedUpdate();

                            if (diagnosticSceneLook)
                                DumpSceneLookRuntimeState(
                                    created, diagnosticSpawnSerial,
                                    "AFTER CONFIRM LOAD SETTLE", initialLookLabel
                                );
                        }
                        else
                        {
                            // The first pass already started successfully, so a failed
                            // confirmation is diagnostic rather than fatal.
                            SuperController.LogMessage(
                                "CharacterRouter v112: fresh-spawn Appearance confirmation " +
                                "could not start for " + initialLookPath + ": " + confirmLookError
                            );
                        }
                    }
                    else if (diagnosticSceneLook)
                    {
                        DumpSceneLookRuntimeState(
                            created, diagnosticSpawnSerial,
                            "CONFIRM SKIPPED BECAUSE CUA ALREADY ACTIVE", initialLookLabel
                        );
                    }
                }
                else
                {
                    SuperController.LogError(
                        "CharacterRouter: creation Look failed after detach for " +
                        initialLookPath + ": " + lookError
                    );
                }
            }

            AppearanceEntry initialAppliedEntry = null;

            // Scene appearance overlays are handled by their specialized adapter after
            // the final native Appearance pass.
            if (created != null && detached && initialLookLoaded)
            {
                if (!string.IsNullOrEmpty(initialLookKey))
                    initialAppliedEntry =
                        FindAppearanceEntryByPath(initialLookKey);

                if (initialAppliedEntry == null)
                    initialAppliedEntry =
                        FindSceneAppearanceEntryByTempPath(initialLookPath);

                AppearanceEntry initialSceneEntry =
                    initialAppliedEntry;

                if (initialSceneEntry != null && initialSceneEntry.isSceneLook)
                {
                    // Pass 1 creates/tracks any adapter-owned DecalMaker and restores the
                    // scene state. v121 diagnostics proved that a brand-new DecalMaker can
                    // already report the correct 2/2/2 JSON here while its renderer graph
                    // still fails to show those overlays.
                    yield return _decalMakerAdapter.ApplyFromScene(
                        created,
                        initialSceneEntry.scenePath,
                        initialSceneEntry.sceneAtomId,
                        initialSceneEntry.source
                    );

                    bool hasManagedSceneVisuals =
                        _decalMakerAdapter.HasManagedVisuals(created);

                    if (hasManagedSceneVisuals)
                    {
                        int cuaAtomsBeforeDecalParity =
                            CountCustomUnityAssetAtomsForPerson(created);

                        _decalMakerAdapter.DiagnosticNote(
                            "SPAWN DECAL PARITY BEGIN | person=" + created.uid +
                            " | cuaAtoms=" + cuaAtomsBeforeDecalParity +
                            " | isLoading=" +
                            (SuperController.singleton != null &&
                             SuperController.singleton.isLoading)
                        );

                        // Reproduce the lifecycle that already works for
                        // Lydia/Roxanne -> Pirate: keep the adapter-owned DecalMaker alive,
                        // load the native Appearance while that initialized instance exists,
                        // then clear and restore its frames again.
                        //
                        // Do not do this if Appearance has spawned live CUA atoms. Earlier
                        // spawn testing proved that reloading the same Appearance in that
                        // state can restart CUAClothingAlt loads and introduce a separate
                        // regression. Pirate currently reaches this path with zero CUA atoms.
                        if (cuaAtomsBeforeDecalParity == 0)
                        {
                            yield return null;
                            yield return new WaitForEndOfFrame();

                            string decalParityError = "";
                            bool decalParityStarted = ApplyAppearancePresetWithPath(
                                created,
                                initialLookPath,
                                out decalParityError
                            );

                            _decalMakerAdapter.DiagnosticNote(
                                "SPAWN DECAL PARITY LoadPreset RETURNED | person=" +
                                created.uid +
                                " | started=" + decalParityStarted +
                                " | error=" + (decalParityError ?? "") +
                                " | isLoading=" +
                                (SuperController.singleton != null &&
                                 SuperController.singleton.isLoading)
                            );

                            if (diagnosticPirateSceneLook)
                            {
                                StartCoroutine(
                                    _decalMakerAdapter.ObserveVaMLoading(
                                        created,
                                        "SPAWN PIRATE DECAL PARITY LOAD",
                                        1.20f
                                    )
                                );
                            }

                            if (decalParityStarted)
                            {
                                yield return WaitForVaMLoadingToFinish(120f);
                                yield return new WaitForSecondsRealtime(0.35f);
                                yield return null;
                                yield return new WaitForFixedUpdate();

                                _decalMakerAdapter.ClearVisualState(created);
                                yield return _decalMakerAdapter.ApplyFromScene(
                                    created,
                                    initialSceneEntry.scenePath,
                                    initialSceneEntry.sceneAtomId,
                                    initialSceneEntry.source
                                );

                                _decalMakerAdapter.DiagnosticNote(
                                    "SPAWN DECAL PARITY END | person=" + created.uid +
                                    " | restoredViaPersistentReuse=true"
                                );
                            }
                            else
                            {
                                _decalMakerAdapter.DiagnosticNote(
                                    "SPAWN DECAL PARITY ABORT | person=" + created.uid +
                                    " | reason=LoadPreset failed"
                                );
                            }
                        }
                        else
                        {
                            _decalMakerAdapter.DiagnosticNote(
                                "SPAWN DECAL PARITY SKIP | person=" + created.uid +
                                " | reason=ACTIVE_CUA | count=" +
                                cuaAtomsBeforeDecalParity
                            );
                        }
                    }

                    if (diagnosticPirateSceneLook)
                    {
                        StartCoroutine(
                            _decalMakerAdapter.ObserveManagedState(
                                created,
                                "SPAWN PIRATE POST-ADAPTER",
                                1.10f
                            )
                        );
                    }
                }
            }

            // v133+: restore model-specific Person plugins. A matching author-saved
            // Person Plugin Preset is preferred over scene inference.
            if (created != null &&
                detached &&
                initialLookLoaded &&
                initialAppliedEntry != null)
            {
                bool needsColliderRefresh =
                    !initialAppliedEntry.isSceneLook &&
                    _modelPluginAdapter.NeedsFreshSpawnAppearanceRefresh(
                        initialAppliedEntry.source,
                        initialAppliedEntry.label
                    );

                yield return _modelPluginAdapter.ApplyForLook(
                    created,
                    initialAppliedEntry.source,
                    initialAppliedEntry.label,
                    initialAppliedEntry.isSceneLook
                        ? initialAppliedEntry.scenePath
                        : "",
                    initialAppliedEntry.isSceneLook
                        ? initialAppliedEntry.sceneAtomId
                        : "",
                    _followCameraWithHead != null && !_followCameraWithHead.val,
                    true
                );

                // v135: Desmon Bank confirmed that reloading the Appearance is not
                // sufficient, while manually toggling the simulated shirt OFF -> ON fixes
                // the first spawn immediately. Therefore rebuild only active clothing items
                // that actually have ClothSimControl, and only for explicit author-saved
                // ColliderEditor + SupplementaryColliders/UYCol setups.
                if (needsColliderRefresh)
                {
                    yield return new WaitForEndOfFrame();
                    yield return new WaitForFixedUpdate();
                    yield return new WaitForFixedUpdate();

                    yield return RebuildActiveSimulatedClothingAfterColliderReadiness(
                        created,
                        initialAppliedEntry.label
                    );
                }
            }

            // v128: observer-only snapshot of qdaro runtime. This is deliberately
            // outside the appearance/decal lifecycle and performs no repairs.
            if (created != null && diagnosticPirateSceneLook)
            {
                StartCoroutine(
                    _qdaroProbe.Observe(
                        created,
                        "FRESH SPAWN FINAL",
                        _decalMakerAdapter.DiagnosticNote,
                        6.0f
                    )
                );
            }

            if (created != null && detached && initialLookLoaded)
                yield return StartCoroutine(ApplyHeadTrackingPolicy(created));

            if (created != null && detached && initialLookLoaded &&
                initialAppliedEntry != null)
                yield return _sceneMorphParityAdapter.ApplyForLook(
                    created, initialAppliedEntry.source,
                    initialAppliedEntry.path);

            if (created != null && detached && initialLookLoaded &&
                initialAppliedEntry != null)
                yield return _sceneCuaAccessoryAdapter.ApplyFromScene(
                    created, initialAppliedEntry.scenePath,
                    initialAppliedEntry.sceneAtomId,
                    initialAppliedEntry.source, initialAppliedEntry.label);

            if (created != null && detached && initialLookLoaded &&
                !string.IsNullOrEmpty(initialLookLabel) &&
                initialLookLabel.StartsWith("Black Widow",
                    StringComparison.OrdinalIgnoreCase))
                StartCoroutine(DiagnoseBlackWidowHair(created));

            // Unhide only after the final Appearance and any managed appearance
            // overlay adapter had a chance to materialize.
            if (createdHiddenChanged && createdHidden != null)
                createdHidden.val = createdHiddenOld;

            yield return new WaitForFixedUpdate();
            yield return new WaitForFixedUpdate();

            if (createdCollisionChanged && createdCollision != null)
                createdCollision.val = createdCollisionOld;

            RestoreCollisionStates(existingCollisionStates);

            // A newly spawned Person has collisions temporarily suppressed.
            // On 2B-Kaine the shoe follows the foot mesh, so finalize the foot
            // pose only after the normal collision state has been restored.
            if (created != null && detached && initialLookLoaded &&
                initialAppliedEntry != null &&
                (string.Equals(initialAppliedEntry.label, "2B-Kaine",
                    StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(initialAppliedEntry.label, "2B-SC6",
                    StringComparison.OrdinalIgnoreCase)) &&
                !string.IsNullOrEmpty(initialAppliedEntry.source) &&
                initialAppliedEntry.source.IndexOf(
                    "immyneedscake.Nier-2B-Compendium",
                    StringComparison.OrdinalIgnoreCase) >= 0)
            {
                yield return new WaitForFixedUpdate();
                yield return new WaitForFixedUpdate();
                _modelPluginAdapter.Finalize2BVariantFeetAfterSpawn(
                    created, initialAppliedEntry.label);
                yield return new WaitForFixedUpdate();
            }

            if (diagnosticSceneLook)
                DumpSceneLookRuntimeState(
                    created, diagnosticSpawnSerial,
                    "FINAL BEFORE ROUTER STATE SAVE", initialLookLabel
                );

            _spawnSequenceIndex++;

            string finalUid = created != null ? created.uid : "";

            // VaM commonly reuses Person#... names after deletion. The new atom must
            // never inherit alias/active-look/reset state from the deleted atom that
            // previously owned the same UID.
            ClearPerPersonStateForFreshAtom(finalUid);

            if (created != null &&
                !string.IsNullOrEmpty(finalUid) &&
                detached &&
                initialLookLoaded)
            {
                string stableLookKey =
                    string.IsNullOrEmpty(initialLookKey)
                    ? initialLookPath
                    : initialLookKey;

                if (!string.IsNullOrEmpty(initialLookKey) &&
                    initialLookKey.StartsWith(
                        "SCENELOOK|",
                        StringComparison.OrdinalIgnoreCase))
                {
                    _originalLookByPerson[finalUid] =
                        "LOOKKEY:" + initialLookKey;
                }
                else
                {
                    _originalLookByPerson[finalUid] =
                        "PATH:" + initialLookPath;
                }

                SaveOriginalLooksData();

                _activeLookByPerson[finalUid] =
                    stableLookKey;
                SaveActiveLooksData();

                AppearanceEntry spawnedAppearance =
                    FindAppearanceEntryByPath(stableLookKey);
                if (spawnedAppearance != null && spawnedAppearance.isAltFuta)
                {
                    yield return StartCoroutine(
                        SanitizeGeneratedAltFutaM2AfAfterLookCoroutine(
                            created,
                            "FRESH_SPAWN"
                        )
                    );
                }

                SetCharacterDisplayName(
                    finalUid,
                    initialLookLabel
                );

                // v141: native Futanari identity is adapter-owned, not a generic
                // serialized BODY-profile toggle. Clear any historical state.
                if (_bodyProfileByPerson.Remove(finalUid))
                    SaveBodyProfilesData();

                RecordRecentLook(
                    string.IsNullOrEmpty(initialLookKey)
                    ? initialLookPath
                    : initialLookKey
                );
            }

            if (diagnosticSceneLook)
            {
                AppendSceneLookDiagnostic(
                    "=== SPAWN #" + diagnosticSpawnSerial +
                    " END | uid=" + (finalUid ?? "") +
                    " | detached=" + detached +
                    " | initialLookLoaded=" + initialLookLoaded + " ===\n"
                );
            }

            if (!detached && createdHiddenChanged && createdHidden != null)
                createdHidden.val = createdHiddenOld;

            _creationModeSex = "";
            _controlledSpawnInProgress = false;

            RefreshRoster(true);
            if (_selectedCharacter != null &&
                _selectedCharacter.choices != null &&
                _selectedCharacter.choices.Contains(finalUid))
            {
                _selectedCharacter.val = finalUid;
            }

            if (_spawnStatus != null)
            {
                if (!detached)
                {
                    _spawnStatus.valNoCallback =
                        "Spawn: Character created, but SubScene unparent was incomplete.";
                }
                else if (!initialLookLoaded)
                {
                    _spawnStatus.valNoCallback =
                        "Spawn: Character created, but selected Look failed: " + lookError;
                }
                else
                {
                    _spawnStatus.valNoCallback =
                        "Spawn: added " + finalUid +
                        " with " + initialLookLabel + ".";
                }
            }
        }

        private void NormalizeRetainedFactories()
        {
            StartCoroutine(NormalizeRetainedFactoriesCoroutine());
        }

        private IEnumerator NormalizeRetainedFactoriesCoroutine()
        {
            List<Atom> atoms = SuperController.singleton.GetAtoms();
            List<Atom> factories = new List<Atom>();

            for (int i = 0; i < atoms.Count; i++)
            {
                Atom a = atoms[i];
                if (a == null || a.type != "SubScene" || string.IsNullOrEmpty(a.uid))
                    continue;

                if (a.uid.StartsWith("CHAR_FACTORY_TEMP", StringComparison.Ordinal))
                    factories.Add(a);
            }

            if (factories.Count == 0)
            {
                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback = "Spawn: no retained character factories found.";
                yield break;
            }

            if (_spawnStatus != null)
                _spawnStatus.valNoCallback =
                    "Spawn: normalizing " + factories.Count + " retained factory/factories...";

            for (int i = 0; i < factories.Count; i++)
            {
                Atom factory = factories[i];
                if (factory == null)
                    continue;

                yield return WaitForSubSceneRestoreToSettle();

                bool invoked = InvokeNativeSubSceneUnparentAll(factory);
                if (!invoked)
                    continue;

                // Let VaM rebuild its atom UID list after the native operation.
                yield return new WaitForSecondsRealtime(0.25f);
                yield return null;

                // If there are no longer any Person atoms whose UID begins with this
                // factory prefix, the container is empty and safe to remove.
                bool stillContainsPerson = false;
                List<Atom> current = SuperController.singleton.GetAtoms();

                for (int j = 0; j < current.Count; j++)
                {
                    Atom a = current[j];
                    if (a == null || a.type != "Person" || string.IsNullOrEmpty(a.uid))
                        continue;

                    if (a.uid.StartsWith(factory.uid + "/", StringComparison.Ordinal))
                    {
                        stillContainsPerson = true;
                        break;
                    }
                }

                if (!stillContainsPerson)
                    SafeRemoveAtom(factory);

                yield return null;
            }

            RefreshRoster(true);

            if (_spawnStatus != null)
                _spawnStatus.valNoCallback =
                    "Spawn: retained factory normalization finished.";
        }

        private void ResetSpawnSequence()
        {
            _spawnSequenceIndex = 0;
            UpdateSpawnStatus();
        }

        private void MoveSelectedPersonToSpawnPoint()
        {
            PersonEntry selected = GetSelectedPerson();
            if (selected == null || selected.atom == null)
            {
                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback = "Spawn: no selected Person";
                return;
            }

            StartCoroutine(RelocateNewPersonCoroutine(selected.atom, 0));
        }

        private Atom GetSpawnPointAtom()
        {
            if (_spawnPointUid == null || string.IsNullOrEmpty(_spawnPointUid.val))
                return null;

            try
            {
                return SuperController.singleton.GetAtomByUid(_spawnPointUid.val);
            }
            catch
            {
                return null;
            }
        }

        private Transform GetSpawnPointTransform()
        {
            Atom marker = GetSpawnPointAtom();
            if (marker == null)
                return null;

            if (marker.mainController != null)
                return marker.mainController.transform;

            return marker.transform;
        }

        private float GetSymmetricSpawnOffset(int index)
        {
            // 0, +1, -1, +2, -2, ... so the first Person uses the marker itself
            // and later Persons fan out around it rather than stacking.
            if (index <= 0)
                return 0f;

            int magnitude = (index + 1) / 2;
            int sign = (index % 2 == 1) ? 1 : -1;
            return magnitude * sign;
        }

        private JSONStorableBool GetAtomHiddenStorable(Atom atom)
        {
            if (atom == null)
                return null;

            try
            {
                JSONStorable atomControl =
                    atom.GetStorableByID("AtomControl");

                if (atomControl != null)
                {
                    JSONStorableBool hidden =
                        atomControl.GetBoolJSONParam("hidden");

                    if (hidden == null)
                        hidden = atomControl.GetBoolJSONParam("Hidden");

                    if (hidden != null)
                        return hidden;
                }
            }
            catch { }

            return null;
        }

        private JSONStorableBool GetCollisionEnabledStorable(Atom atom)
        {
            if (atom == null)
                return null;

            try
            {
                JSONStorable atomControl = atom.GetStorableByID("AtomControl");
                if (atomControl != null)
                    return atomControl.GetBoolJSONParam("collisionEnabled");
            }
            catch { }

            return null;
        }

        private IEnumerator RelocateNewPersonCoroutine(Atom atom, int sequenceIndex)
        {
            if (atom == null)
                yield break;

            JSONStorableBool collision = null;
            bool previousCollision = true;
            bool collisionTemporarilyDisabled = false;

            if (_disableCollisionDuringSpawn != null && _disableCollisionDuringSpawn.val)
            {
                collision = GetCollisionEnabledStorable(atom);
                if (collision != null)
                {
                    previousCollision = collision.val;
                    collision.val = false;
                    collisionTemporarilyDisabled = true;
                }
            }

            // Atom-added can fire before every Person controller is fully ready.
            int attempts = 0;
            while (atom != null && atom.mainController == null && attempts < 60)
            {
                attempts++;
                yield return null;
            }

            Transform spawn = GetSpawnPointTransform();
            if (atom == null || atom.mainController == null || spawn == null)
            {
                if (_spawnStatus != null)
                {
                    string uid = _spawnPointUid != null ? _spawnPointUid.val : "";
                    _spawnStatus.valNoCallback = "Spawn: marker not found/ready: " + uid;
                }

                if (collisionTemporarilyDisabled && collision != null)
                    collision.val = previousCollision;

                yield break;
            }

            float spacing = _spawnSpacing != null ? _spawnSpacing.val : 0.9f;
            float offset = GetSymmetricSpawnOffset(sequenceIndex) * spacing;

            Vector3 targetPosition = spawn.position + spawn.right * offset;
            Quaternion targetRotation = spawn.rotation;

            // Root/mainController movement keeps the Person's internal controller
            // relationships intact and avoids deleting/recreating the Person atom.
            atom.mainController.transform.position = targetPosition;
            atom.mainController.transform.rotation = targetRotation;

            // Let physics settle at the new non-overlapping position before restoring
            // collision. Two fixed steps is enough without a visible pause.
            yield return new WaitForFixedUpdate();
            yield return new WaitForFixedUpdate();

            if (collisionTemporarilyDisabled && collision != null)
                collision.val = previousCollision;

            if (_spawnStatus != null)
                _spawnStatus.valNoCallback = "Spawn: moved " + atom.uid + " to " + (_spawnPointUid != null ? _spawnPointUid.val : "marker");

            RefreshRoster(true);
        }

        private void UpdateSpawnStatus()
        {
            if (_spawnStatus == null)
                return;

            // Do not overwrite transactional progress/error text while the factory runs.
            if (_controlledSpawnInProgress)
                return;

            Atom marker = GetSpawnPointAtom();
            string uid = _spawnPointUid != null ? _spawnPointUid.val : "";
            string factoryPath = ResolveFactorySubScenePath();

            if (marker == null)
            {
                _spawnStatus.valNoCallback =
                    "Spawn: waiting for marker '" + uid + "'";
            }
            else if (string.IsNullOrEmpty(factoryPath))
            {
                _spawnStatus.valNoCallback =
                    "Spawn: factory file missing. Check Factory SubScene Path.";
            }
            else
            {
                _spawnStatus.valNoCallback =
                    "Spawn: CharacterFactory ready | " +
                    ((_dynamicFreeSpawn == null || _dynamicFreeSpawn.val)
                        ? "dynamic free placement ON"
                        : "linear placement") +
                    " | template OK";
            }
        }

        private void FindScreenDockBindings()
        {
            try
            {
                _screenDockStorable = null;
                _screenDockActivePage = null;
                _screenDockHudOpen = null;

                if (containingAtom == null) return;

                List<string> ids = containingAtom.GetStorableIDs();
                for (int i = 0; i < ids.Count; i++)
                {
                    JSONStorable s = containingAtom.GetStorableByID(ids[i]);
                    if (s == null || s == this) continue;

                    JSONStorableString activePage = s.GetStringJSONParam("Active Page");
                    JSONStorableBool hudOpen = s.GetBoolJSONParam("HUD Open");

                    if (activePage != null && hudOpen != null)
                    {
                        _screenDockStorable = s;
                        _screenDockActivePage = activePage;
                        _screenDockHudOpen = hudOpen;
                        return;
                    }
                }
            }
            catch (Exception e)
            {
                SuperController.LogError("CharacterRouter v6 ScreenDock binding error: " + e);
            }
        }

        private bool ShouldShowRoster()
        {
            // The roster is companion HUD content. If ScreenDock is not bound, fail closed
            // rather than leaving the roster permanently visible over a collapsed HUD.
            if (_screenDockActivePage == null || _screenDockHudOpen == null)
                return false;

            return _screenDockHudOpen.val && _screenDockActivePage.val == "CHARACTERS";
        }

        private void ReacquireCanvas()
        {
            DestroyRosterRoot();

            _multiMenuCanvas = null;

            if (containingAtom != null)
            {
                Canvas[] canvases = containingAtom.GetComponentsInChildren<Canvas>(true);
                for (int i = 0; i < canvases.Length; i++)
                {
                    if (canvases[i] != null && canvases[i].name.IndexOf("MultiMenu_Canvas", StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        _multiMenuCanvas = canvases[i];
                        break;
                    }
                }
            }

            if (_multiMenuCanvas == null)
            {
                GameObject go = GameObject.Find("MultiMenu_Canvas");
                if (go != null)
                    _multiMenuCanvas = go.GetComponent<Canvas>();
            }

            if (_multiMenuCanvas != null)
            {
                CaptureReferenceStyle();
                BuildAddCharacterRoot();
                BuildRosterRoot();
                BuildCharacterContextRoot();
                BuildSectionNavRoot();
                BuildLookCatalogRoot();
                BuildHairCatalogRoot();
                BuildFaceEditorRoot();
                BuildBodyEditorRoot();
                RebuildRosterButtons();
                RebuildSectionNavButtons();
                RebuildLookCatalogPage();
                RebuildHairCatalogPage();
                RebuildFaceEditorPage();
                RebuildBodyEditorPage();
            }
        }

        private void CaptureReferenceStyle()
        {
            try
            {
                Text[] texts = _multiMenuCanvas.GetComponentsInChildren<Text>(true);
                if (texts != null && texts.Length > 0)
                {
                    for (int i = 0; i < texts.Length; i++)
                    {
                        if (texts[i] != null && texts[i].font != null)
                        {
                            _referenceFont = texts[i].font;
                            _referenceFontSize = Mathf.Max(14, texts[i].fontSize);
                            _referenceTextColor = texts[i].color;
                            break;
                        }
                    }
                }

                Button[] buttons = _multiMenuCanvas.GetComponentsInChildren<Button>(true);
                if (buttons != null && buttons.Length > 0)
                {
                    for (int i = 0; i < buttons.Length; i++)
                    {
                        if (buttons[i] != null)
                        {
                            Image img = buttons[i].GetComponent<Image>();
                            if (img != null) _referenceButtonColor = img.color;
                            _referenceButtonColors = buttons[i].colors;
                            _haveReferenceButtonColors = true;
                            break;
                        }
                    }
                }
            }
            catch { }

            if (_referenceFont == null)
                _referenceFont = Resources.GetBuiltinResource<Font>("Arial.ttf");
        }

        private void BuildAddCharacterRoot()
        {
            if (_multiMenuCanvas == null)
                return;

            _addCharacterRoot = new GameObject("CharacterRouter_AddCharacterBar");
            _addCharacterRoot.transform.SetParent(_multiMenuCanvas.transform, false);

            _addCharacterRect = _addCharacterRoot.AddComponent<RectTransform>();
            _addCharacterRect.anchorMin = new Vector2(0.5f, 0.5f);
            _addCharacterRect.anchorMax = new Vector2(0.5f, 0.5f);
            _addCharacterRect.pivot = new Vector2(0.5f, 1f);

            _addCharacterPanelImage = _addCharacterRoot.AddComponent<Image>();
            _addCharacterPanelImage.color = new Color(
                _referenceButtonColor.r,
                _referenceButtonColor.g,
                _referenceButtonColor.b,
                0.35f
            );

            _addCharacterLayout = _addCharacterRoot.AddComponent<HorizontalLayoutGroup>();
            _addCharacterLayout.padding = new RectOffset(10, 10, 10, 10);
            _addCharacterLayout.spacing = 5f;
            _addCharacterLayout.childAlignment = TextAnchor.MiddleCenter;
            _addCharacterLayout.childControlWidth = true;
            _addCharacterLayout.childControlHeight = true;
            _addCharacterLayout.childForceExpandWidth = true;
            _addCharacterLayout.childForceExpandHeight = true;

            CreateFixedAddButton("+ ADD FEMALE", BeginAddFemale);
            CreateFixedAddButton("+ ADD MALE", BeginAddMale);
            CreateFixedAddButton("+ ADD FUTANARI", BeginAddFutanari);

            ApplyAddCharacterLayout();
        }

        private void CreateFixedAddButton(string label, UnityEngine.Events.UnityAction callback)
        {
            if (_addCharacterRoot == null)
                return;

            GameObject go = new GameObject("AddBar_" + label.Replace(" ", ""));
            go.transform.SetParent(_addCharacterRoot.transform, false);

            Image img = go.AddComponent<Image>();
            img.color = _referenceButtonColor;

            Button button = go.AddComponent<Button>();
            if (_haveReferenceButtonColors)
                button.colors = _referenceButtonColors;
            button.onClick.AddListener(callback);

            LayoutElement layout = go.AddComponent<LayoutElement>();
            layout.flexibleWidth = 1f;
            layout.flexibleHeight = 1f;
            layout.minWidth = 100f;
            layout.minHeight = 30f;

