            if (_sectionNavRoot == null)
                return;

            for (int i = _sectionNavRoot.transform.childCount - 1; i >= 0; i--)
                Destroy(_sectionNavRoot.transform.GetChild(i).gameObject);

            _sectionNavButtons.Clear();

            for (int i = 0; i < _sectionChoices.Count; i++)
                CreateSectionNavButton(_sectionChoices[i]);

