        private Color GetSelectedHudButtonColor()
        {
            Color c = _referenceButtonColor;
            c.r = Mathf.Clamp01(c.r * 0.75f);
            c.g = Mathf.Clamp01(c.g * 0.90f);
            c.b = Mathf.Clamp01(c.b * 1.15f);
            c.a = Mathf.Max(c.a, 0.95f);
            return c;
        }

        private void UpdateSectionNavSelectionVisuals()
        {
            string selectedSection = _section != null ? _section.val : "Looks";

            for (int i = 0; i < _sectionNavButtons.Count && i < _sectionChoices.Count; i++)
            {
                Button button = _sectionNavButtons[i];
                if (button == null)
                    continue;

                Image img = button.GetComponent<Image>();
                if (img == null)
                    continue;

                bool selected = string.Equals(
                    _sectionChoices[i],
                    selectedSection,
                    StringComparison.OrdinalIgnoreCase
                );

                img.color = selected ? GetSelectedHudButtonColor() : _referenceButtonColor;
            }
        }

        private float GetAddCharacterBarHeight()
        {
            float bh = _buttonHeight != null ? _buttonHeight.val : 50f;
            return bh + 20f;
        }

        private float GetRosterHeight()
        {
            if (_persons.Count <= 0)
                return 0f;

            int columns = Mathf.Clamp(
                Mathf.RoundToInt(_columns != null ? _columns.val : 3f),
                1,
                8
            );

            float bh = _buttonHeight != null ? _buttonHeight.val : 50f;
            float spacing = _buttonSpacing != null ? _buttonSpacing.val : 5f;
            int rows = Mathf.CeilToInt(_persons.Count / (float)columns);

            return 20f + rows * bh + Mathf.Max(0, rows - 1) * spacing;
        }

        private float GetCharacterContextHeight()
        {
            return HasSelectedPersonForRemoval() ? 44f : 0f;
        }

        private float GetStackGap()
        {
            return 5f;
        }

        private float GetRosterTopY()
        {
            float baseY = _panelY != null ? _panelY.val : -70f;
            return baseY - GetAddCharacterBarHeight() - GetStackGap();
        }

        private float GetContextTopY()
        {
            return GetRosterTopY() - GetRosterHeight() - (GetRosterHeight() > 0f ? GetStackGap() : 0f);
        }

        private float GetSectionNavTopY()
        {
            float y = GetContextTopY();
            float contextHeight = GetCharacterContextHeight();
            if (contextHeight > 0f)
                y -= contextHeight + GetStackGap();
            return y;
        }

        private float GetContentTopY()
        {
            float bh = _buttonHeight != null ? _buttonHeight.val : 50f;
            float navHeight = bh + 20f;
            return GetSectionNavTopY() - navHeight - GetStackGap();
        }

        private void ApplyAddCharacterLayout()
        {
            if (_addCharacterRect == null)
                return;

            float width = _panelWidth != null ? _panelWidth.val : 720f;
            float baseY = _panelY != null ? _panelY.val : -70f;
            _addCharacterRect.anchoredPosition = new Vector2(
                _panelX != null ? _panelX.val : 0f,
                baseY
            );
            _addCharacterRect.sizeDelta = new Vector2(width, GetAddCharacterBarHeight());
        }

        private void ApplyCharacterContextLayout()
        {
            if (_characterContextRect == null)
                return;

            float width = _panelWidth != null ? _panelWidth.val : 720f;
            float height = GetCharacterContextHeight();
            _characterContextRect.anchoredPosition = new Vector2(
                _panelX != null ? _panelX.val : 0f,
                GetContextTopY()
            );
            _characterContextRect.sizeDelta = new Vector2(width, Mathf.Max(1f, height));
        }

        private void UpdateCharacterContextVisuals()
        {
            PersonEntry selected = GetSelectedPerson();
            bool visible = !IsCharacterCreationMode() && selected != null;

            if (_characterContextRoot != null)
                _characterContextRoot.SetActive(visible && ShouldShowRoster());

            if (!visible)
                return;

            string name = GetDisplayName(selected);
            if (string.IsNullOrEmpty(name))
                name = selected.uid;

            if (_characterContextLabel != null)
                _characterContextLabel.text = "SELECTED CHARACTER: " + name.ToUpperInvariant();

            if (_characterContextRemoveText != null)
                _characterContextRemoveText.text = "REMOVE " + name.ToUpperInvariant();
        }

        private void ApplySectionNavLayout()
        {
            if (_sectionNavRect == null)
                return;

            float width = _panelWidth != null ? _panelWidth.val : 720f;
            float bh = _buttonHeight != null ? _buttonHeight.val : 50f;
            float navHeight = bh + 20f;

            _sectionNavRect.anchoredPosition = new Vector2(
                _panelX != null ? _panelX.val : 0f,
                GetSectionNavTopY()
            );
            _sectionNavRect.sizeDelta = new Vector2(width, navHeight);
        }

