        private GameObject CreateCatalogFilterBar(
            Transform parent,
            string objectName,
            Vector2 offsetMin,
            Vector2 offsetMax,
            out InputField searchInput,
            out InputField creatorInput,
            out InputField packageInput,
            out Button newButton,
            out Button sortButton,
            out Button clearButton,
            UnityEngine.Events.UnityAction<string> onSearch,
            UnityEngine.Events.UnityAction<string> onCreator,
            UnityEngine.Events.UnityAction<string> onPackage,
            UnityEngine.Events.UnityAction onNew,
            UnityEngine.Events.UnityAction onSort,
            UnityEngine.Events.UnityAction onClear)
        {
            GameObject root = new GameObject(objectName);
            root.transform.SetParent(parent, false);

            RectTransform rt = root.AddComponent<RectTransform>();
            rt.anchorMin = new Vector2(0f, 1f);
            rt.anchorMax = new Vector2(1f, 1f);
            rt.pivot = new Vector2(0.5f, 1f);
            rt.offsetMin = offsetMin;
            rt.offsetMax = offsetMax;

            HorizontalLayoutGroup layout = root.AddComponent<HorizontalLayoutGroup>();
            layout.spacing = 5f;
            layout.childAlignment = TextAnchor.MiddleCenter;
            layout.childControlWidth = true;
            layout.childControlHeight = true;
            layout.childForceExpandWidth = false;
            layout.childForceExpandHeight = true;

            searchInput = CreateCatalogFilterInput(root.transform, "Search", "Search...", 155f, onSearch);
            creatorInput = CreateCatalogFilterInput(root.transform, "Creator", "Creator...", 98f, onCreator);
            packageInput = CreateCatalogFilterInput(root.transform, "Package", "Package...", 112f, onPackage);
            newButton = CreateCatalogFilterButton(root.transform, "New", "NEW", 55f, onNew);
            sortButton = CreateCatalogFilterButton(root.transform, "Sort", "SORT: DEFAULT", 108f, onSort);
            clearButton = CreateCatalogFilterButton(root.transform, "Clear", "CLEAR", 62f, onClear);
            return root;
        }

        private InputField CreateCatalogFilterInput(
            Transform parent,
            string objectName,
            string placeholderText,
            float preferredWidth,
            UnityEngine.Events.UnityAction<string> onChanged)
        {
            GameObject go = new GameObject(objectName);
            go.transform.SetParent(parent, false);

            Image bg = go.AddComponent<Image>();
            bg.color = _referenceButtonColor;

            LayoutElement le = go.AddComponent<LayoutElement>();
            le.preferredWidth = preferredWidth;
            le.minWidth = Mathf.Min(80f, preferredWidth);
            le.flexibleWidth = objectName == "Search" ? 1f : 0f;

            GameObject textGo = new GameObject("Text");
            textGo.transform.SetParent(go.transform, false);
            RectTransform textRect = textGo.AddComponent<RectTransform>();
            textRect.anchorMin = Vector2.zero;
            textRect.anchorMax = Vector2.one;
            textRect.offsetMin = new Vector2(7f, 2f);
            textRect.offsetMax = new Vector2(-7f, -2f);

            Text text = textGo.AddComponent<Text>();
            text.font = _referenceFont;
            text.fontSize = Mathf.Max(12, _referenceFontSize - 8);
            text.color = _referenceTextColor;
            text.alignment = TextAnchor.MiddleLeft;
            text.supportRichText = false;
            text.raycastTarget = false;

            GameObject placeholderGo = new GameObject("Placeholder");
            placeholderGo.transform.SetParent(go.transform, false);
            RectTransform phRect = placeholderGo.AddComponent<RectTransform>();
            phRect.anchorMin = Vector2.zero;
            phRect.anchorMax = Vector2.one;
            phRect.offsetMin = new Vector2(7f, 2f);
            phRect.offsetMax = new Vector2(-7f, -2f);

            Text placeholder = placeholderGo.AddComponent<Text>();
            placeholder.font = _referenceFont;
            placeholder.fontSize = Mathf.Max(12, _referenceFontSize - 8);
            placeholder.color = new Color(_referenceTextColor.r, _referenceTextColor.g, _referenceTextColor.b, 0.55f);
            placeholder.alignment = TextAnchor.MiddleLeft;
            placeholder.text = placeholderText;
            placeholder.fontStyle = FontStyle.Italic;
            placeholder.raycastTarget = false;

            InputField input = go.AddComponent<InputField>();
            input.textComponent = text;
            input.placeholder = placeholder;
            input.lineType = InputField.LineType.SingleLine;
            input.characterLimit = 120;
            if (onChanged != null)
                input.onValueChanged.AddListener(onChanged);

            return input;
        }

