        private bool ContainsFilterText(string value, string filter)
        {
            if (string.IsNullOrEmpty(filter))
                return true;
            if (string.IsNullOrEmpty(value))
                return false;
            return value.IndexOf(filter.Trim(), StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private string GetCatalogPackage(string source)
        {
            return string.IsNullOrEmpty(source) ? "Local" : source;
        }

        private string GetCatalogCreator(string source, string path)
        {
            string package = GetCatalogPackage(source);
            if (!string.Equals(package, "Local", StringComparison.OrdinalIgnoreCase))
            {
                int dot = package.IndexOf('.');
                return dot > 0 ? package.Substring(0, dot) : package;
            }

            string p = NormalizePathSlashes(path);
            string[] roots = new string[]
            {
                "Custom/Atom/Person/Appearance/",
                "Custom/Atom/Person/Hair/",
                "Saves/scene/"
            };

            for (int i = 0; i < roots.Length; i++)
            {
                int at = p.IndexOf(roots[i], StringComparison.OrdinalIgnoreCase);
                if (at < 0) continue;
                string tail = p.Substring(at + roots[i].Length);
                int slash = tail.IndexOf('/');
                if (slash > 0)
                    return tail.Substring(0, slash);
            }
            return "Local";
        }

        private void RememberPackageModifiedTime(string packageUid, string varPath)
        {
            if (string.IsNullOrEmpty(packageUid) || string.IsNullOrEmpty(varPath))
                return;

            try
            {
                string physical = NormalizePathSlashes(varPath);
                if (FileManagerSecure.FileExists(physical))
                    _packageModifiedTicks[packageUid] = FileManagerSecure.FileLastWriteTime(physical).Ticks;
            }
            catch { }
        }

        private long GetCatalogModifiedTicks(string source, string path)
        {
            if (!string.IsNullOrEmpty(source) &&
                !string.Equals(source, "Local", StringComparison.OrdinalIgnoreCase))
            {
                long ticks;
                if (_packageModifiedTicks.TryGetValue(source, out ticks))
                    return ticks;

                try
                {
                    string varPath = "AddonPackages/" + source + ".var";
                    if (FileManagerSecure.FileExists(varPath))
                    {
                        ticks = FileManagerSecure.FileLastWriteTime(varPath).Ticks;
                        _packageModifiedTicks[source] = ticks;
                        return ticks;
                    }
                }
                catch { }
            }

            string p = NormalizePathSlashes(path);
            int packageSep = string.IsNullOrEmpty(p)
                ? -1
                : p.IndexOf(":/", StringComparison.Ordinal);

            // The mounted union scan can initially report a packaged file with
            // source=Local while the virtual path itself still carries the package UID.
            if (packageSep > 1)
            {
                string pathPackage = p.Substring(0, packageSep);
                if (pathPackage.IndexOf('.') >= 0 &&
                    !string.Equals(pathPackage, "SELF", StringComparison.OrdinalIgnoreCase))
                {
                    long ticks;
                    if (_packageModifiedTicks.TryGetValue(pathPackage, out ticks))
                        return ticks;
                    try
                    {
                        string varPath = "AddonPackages/" + pathPackage + ".var";
                        if (FileManagerSecure.FileExists(varPath))
                        {
                            ticks = FileManagerSecure.FileLastWriteTime(varPath).Ticks;
                            _packageModifiedTicks[pathPackage] = ticks;
                            return ticks;
                        }
                    }
                    catch { }
                }
            }

            if (!string.IsNullOrEmpty(p) && packageSep < 0)
            {
                try
                {
                    if (FileManagerSecure.FileExists(p))
                        return FileManagerSecure.FileLastWriteTime(p).Ticks;
                }
                catch { }
            }

            return 0L;
        }

        private void KeepNewestAppearanceEntries(List<AppearanceEntry> entries)
        {
            if (entries == null || !_lookNewOnly)
                return;

            entries.Sort(delegate(AppearanceEntry a, AppearanceEntry b)
            {
                long at = a == null ? 0L : GetCatalogModifiedTicks(a.source, a.isSceneLook ? a.scenePath : a.path);
                long bt = b == null ? 0L : GetCatalogModifiedTicks(b.source, b.isSceneLook ? b.scenePath : b.path);
                int c = bt.CompareTo(at);
                if (c != 0) return c;
                return CompareCatalogStrings(a == null ? "" : a.label, b == null ? "" : b.label);
            });

            string subsection = _subsection != null ? _subsection.val : "All";
            bool packageOverview =
                string.Equals(subsection, "Scenes", StringComparison.OrdinalIgnoreCase) &&
                _scenePackagesMode && string.IsNullOrEmpty(_sceneSelectedPackage);

            if (!packageOverview && entries.Count > NEWEST_CATALOG_LIMIT)
                entries.RemoveRange(NEWEST_CATALOG_LIMIT, entries.Count - NEWEST_CATALOG_LIMIT);
        }

        private void KeepNewestHairEntries(List<HairPresetEntry> entries)
        {
            if (entries == null || !_hairNewOnly)
                return;

            entries.Sort(delegate(HairPresetEntry a, HairPresetEntry b)
            {
                long at = a == null ? 0L : GetCatalogModifiedTicks(a.source, a.path);
                long bt = b == null ? 0L : GetCatalogModifiedTicks(b.source, b.path);
                int c = bt.CompareTo(at);
                if (c != 0) return c;
                return CompareCatalogStrings(a == null ? "" : a.label, b == null ? "" : b.label);
            });

            if (entries.Count > NEWEST_CATALOG_LIMIT)
                entries.RemoveRange(NEWEST_CATALOG_LIMIT, entries.Count - NEWEST_CATALOG_LIMIT);
        }

        private int CompareCatalogStrings(string a, string b)
        {
            return string.Compare(a ?? "", b ?? "", StringComparison.OrdinalIgnoreCase);
        }

        private void ApplyLookCatalogFiltersAndSort(List<AppearanceEntry> entries)
        {
            if (entries == null)
                return;

            for (int i = entries.Count - 1; i >= 0; i--)
            {
                AppearanceEntry e = entries[i];
                string creator = e == null ? "" : GetCatalogCreator(e.source, e.isSceneLook ? e.scenePath : e.path);
                string package = e == null ? "" : GetCatalogPackage(e.source);
                string searchable = e == null ? "" : (e.label + " " + e.path + " " + creator + " " + package);
                if (!ContainsFilterText(searchable, _lookSearchFilter) ||
                    !ContainsFilterText(creator, _lookCreatorFilter) ||
                    !ContainsFilterText(package, _lookPackageFilter))
                {
                    entries.RemoveAt(i);
                }
            }

            KeepNewestAppearanceEntries(entries);

            if (string.Equals(_lookSortMode, "Default", StringComparison.OrdinalIgnoreCase))
                return;

            entries.Sort(delegate(AppearanceEntry a, AppearanceEntry b)
            {
                if (string.Equals(_lookSortMode, "Name Z-A", StringComparison.OrdinalIgnoreCase))
                    return -CompareCatalogStrings(a == null ? "" : a.label, b == null ? "" : b.label);
                if (string.Equals(_lookSortMode, "Creator", StringComparison.OrdinalIgnoreCase))
                {
                    int c = CompareCatalogStrings(
                        a == null ? "" : GetCatalogCreator(a.source, a.isSceneLook ? a.scenePath : a.path),
                        b == null ? "" : GetCatalogCreator(b.source, b.isSceneLook ? b.scenePath : b.path));
                    if (c != 0) return c;
                }
                else if (string.Equals(_lookSortMode, "Package", StringComparison.OrdinalIgnoreCase))
                {
                    int c = CompareCatalogStrings(a == null ? "" : GetCatalogPackage(a.source), b == null ? "" : GetCatalogPackage(b.source));
                    if (c != 0) return c;
                }
                return CompareCatalogStrings(a == null ? "" : a.label, b == null ? "" : b.label);
            });
        }

        private void ApplyHairCatalogFiltersAndSort(List<HairPresetEntry> entries)
        {
            if (entries == null)
                return;

            for (int i = entries.Count - 1; i >= 0; i--)
            {
                HairPresetEntry e = entries[i];
                string creator = e == null ? "" : GetCatalogCreator(
                    e.source,
                    e.isSceneHair ? e.scenePath : e.path
                );
                string package = e == null ? "" : GetCatalogPackage(e.source);
                string searchable = e == null ? "" : (e.label + " " + e.path + " " + creator + " " + package);
                if (!ContainsFilterText(searchable, _hairSearchFilter) ||
                    !ContainsFilterText(creator, _hairCreatorFilter) ||
                    !ContainsFilterText(package, _hairPackageFilter))
                {
                    entries.RemoveAt(i);
                }
            }

            KeepNewestHairEntries(entries);

            if (string.Equals(_hairSortMode, "Default", StringComparison.OrdinalIgnoreCase))
                return;

            entries.Sort(delegate(HairPresetEntry a, HairPresetEntry b)
            {
                if (string.Equals(_hairSortMode, "Name Z-A", StringComparison.OrdinalIgnoreCase))
                    return -CompareCatalogStrings(a == null ? "" : a.label, b == null ? "" : b.label);
                if (string.Equals(_hairSortMode, "Creator", StringComparison.OrdinalIgnoreCase))
                {
                    int c = CompareCatalogStrings(
                        a == null ? "" : GetCatalogCreator(a.source, a.isSceneHair ? a.scenePath : a.path),
                        b == null ? "" : GetCatalogCreator(b.source, b.isSceneHair ? b.scenePath : b.path));
                    if (c != 0) return c;
                }
                else if (string.Equals(_hairSortMode, "Package", StringComparison.OrdinalIgnoreCase))
                {
                    int c = CompareCatalogStrings(a == null ? "" : GetCatalogPackage(a.source), b == null ? "" : GetCatalogPackage(b.source));
                    if (c != 0) return c;
                }
                return CompareCatalogStrings(a == null ? "" : a.label, b == null ? "" : b.label);
            });
        }

