        private void UpdateLookSubNavVisuals()
        {
            string subsection =
                _subsection != null ? _subsection.val : "All";

            for (int i = 0;
                 i < _lookSubNavButtons.Count &&
                 i < _lookSubNavNames.Count;
                 i++)
            {
                Button b = _lookSubNavButtons[i];
                if (b == null)
                    continue;

                Image img = b.GetComponent<Image>();
                if (img == null)
                    continue;

                bool active = string.Equals(
                    _lookSubNavNames[i],
                    subsection,
                    StringComparison.OrdinalIgnoreCase
                );

                img.color =
                    active
                    ? GetSelectedHudButtonColor()
                    : _referenceButtonColor;
            }

            if (_lookIncompatibleButton != null)
            {
                Image incompatibleImage =
                    _lookIncompatibleButton.GetComponent<Image>();

                if (incompatibleImage != null)
                {
                    incompatibleImage.color =
                        (_showIncompatible != null &&
                         _showIncompatible.val)
                        ? GetSelectedHudButtonColor()
                        : _referenceButtonColor;
                }

                Text[] incompatibleTexts =
                    _lookIncompatibleButton.GetComponentsInChildren<Text>();

                if (incompatibleTexts != null &&
                    incompatibleTexts.Length > 0)
                {
                    incompatibleTexts[0].text =
                        (_showIncompatible != null &&
                         _showIncompatible.val)
                        ? "INCOMPATIBLE ON"
                        : "INCOMPATIBLE";
                }
            }

            if (_lookResetButton != null)
            {
                Image resetImage =
                    _lookResetButton.GetComponent<Image>();

                if (resetImage != null)
                    resetImage.color = _referenceButtonColor;

                Text[] resetTexts =
                    _lookResetButton.GetComponentsInChildren<Text>();

                if (resetTexts != null && resetTexts.Length > 0)
                {
                    resetTexts[0].text =
                        IsCharacterCreationMode()
                        ? "CANCEL"
                        : "RESET";
                }
            }
        }

