        private void ApplyLookCatalogLayout()
        {
            if (_lookCatalogRect == null || _lookGrid == null)
                return;

            float width = _panelWidth != null ? _panelWidth.val : 720f;
            float y = GetContentTopY();

            float catalogHeight = 600f;

            _lookCatalogRect.anchoredPosition = new Vector2(
                _panelX != null ? _panelX.val : 0f,
                y
            );
            _lookCatalogRect.sizeDelta = new Vector2(width, catalogHeight);

            float usableWidth = Mathf.Max(200f, width - 20f);
            float cardWidth = (usableWidth - 18f) / 4f;
            float gridHeight = catalogHeight - 207f;
            float cardHeight = (gridHeight - 12f) / 3f;

            _lookGrid.cellSize = new Vector2(cardWidth, cardHeight);
        }

        private void ClearLookThumbnailResources()
        {
            for (int i = 0; i < _lookSprites.Count; i++)
            {
                if (_lookSprites[i] != null)
                    Destroy(_lookSprites[i]);
            }
            _lookSprites.Clear();

            for (int i = 0; i < _lookTextures.Count; i++)
            {
                if (_lookTextures[i] != null)
                    Destroy(_lookTextures[i]);
            }
            _lookTextures.Clear();
        }

        private string NormalizePathSlashes(string path)
        {
            return string.IsNullOrEmpty(path) ? "" : path.Replace("\\", "/");
        }

        private string GetPresetLabel(string path)
        {
            string p = NormalizePathSlashes(path);
            int slash = p.LastIndexOf('/');
            string name = slash >= 0 ? p.Substring(slash + 1) : p;

            if (name.EndsWith(".vap", StringComparison.OrdinalIgnoreCase))
                name = name.Substring(0, name.Length - 4);

            if (name.StartsWith("Preset_", StringComparison.OrdinalIgnoreCase))
                name = name.Substring(7);

            return string.IsNullOrEmpty(name) ? "(unnamed look)" : name;
        }

        private string GetSiblingJpgPath(string vapPath)
        {
            if (string.IsNullOrEmpty(vapPath))
                return "";

            string basePath = vapPath.EndsWith(".vap", StringComparison.OrdinalIgnoreCase)
                ? vapPath.Substring(0, vapPath.Length - 4)
                : vapPath;

            string jpg = basePath + ".jpg";

            try
            {
                if (FileManagerSecure.FileExists(jpg))
                    return jpg;
            }
            catch { }

            return "";
        }

        // Scene-contained Look extraction/filtering is adapted from the
        // MIT-licensed VaM Backstage extractor by cyberpunk2073 (2026).
        // See THIRD_PARTY_LICENSES.txt included with this package.
        private string GetSceneThumbnailPath(string scenePath)
        {
            if (string.IsNullOrEmpty(scenePath))
                return "";

            string p = NormalizePathSlashes(scenePath);
            string basePath = p.EndsWith(".json", StringComparison.OrdinalIgnoreCase)
                ? p.Substring(0, p.Length - 5)
                : p;

            string jpg = basePath + ".jpg";

            try
            {
                if (FileManagerSecure.FileExists(jpg))
                    return jpg;
            }
            catch { }

            return "";
        }

        private string GetSceneLabel(string scenePath)
        {
            string p = NormalizePathSlashes(scenePath);
            int slash = p.LastIndexOf('/');
            string name = slash >= 0 ? p.Substring(slash + 1) : p;

            if (name.EndsWith(".json", StringComparison.OrdinalIgnoreCase))
                name = name.Substring(0, name.Length - 5);

            return string.IsNullOrEmpty(name) ? "(scene look)" : name;
        }

        private string GetSceneLookKey(
            string scenePath,
            string atomId,
            string source)
        {
            return "SCENELOOK|" +
                (source == null ? "" : source) + "|" +
                NormalizePathSlashes(scenePath) + "|" +
                (atomId == null ? "" : atomId);
        }

        private string GetSceneHairKey(
            string region,
            string fingerprint)
        {
            // Fingerprint-based keys keep Favorites/active highlighting stable even
            // when the same scene hairstyle is reused in several installed scenes.
            return "SCENEHAIR|" +
                (region == null ? "Head" : region) + "|" +
                (fingerprint == null ? "" : fingerprint);
        }

        private string GetSceneHairTempPath(HairPresetEntry entry)
        {
            uint hash = StableSceneLookHash(
                entry == null ? "" : entry.path
            );

            return "Custom/Atom/Person/Hair/CharacterRouter_Extracted/" +
                "Preset_CharacterRouter_SceneHair_v160_" +
                hash.ToString("X8") + ".vap";
        }

        private bool IsCharacterRouterExtractedHairPath(string path)
        {
            if (string.IsNullOrEmpty(path))
                return false;

            string p = NormalizePathSlashes(path);
            return p.IndexOf(
                       "Custom/Atom/Person/Hair/CharacterRouter_Extracted",
                       StringComparison.OrdinalIgnoreCase) >= 0 ||
                   p.IndexOf(
                       "Preset_CharacterRouter_SceneHair_",
                       StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private uint StableSceneLookHash(string value)
        {
            unchecked
            {
                uint hash = 2166136261u;
                string text = value == null ? "" : value;

                for (int i = 0; i < text.Length; i++)
                {
                    hash ^= text[i];
                    hash *= 16777619u;
                }

                return hash;
            }
        }

        private string GetSceneLookTempPath(AppearanceEntry entry)
        {
            uint hash = StableSceneLookHash(
                entry == null ? "" : entry.path
            );

            // AppearancePresets only accepts files under its own store folder.
            // Keep extracted scene Looks in a dedicated subfolder of that store.
            return "Custom/Atom/Person/Appearance/CharacterRouter_Extracted/" +
                "Preset_CharacterRouter_SceneLook_" +
                hash.ToString("X8") + ".vap";
        }

        private bool IsCharacterRouterExtractedAppearancePath(string path)
        {
            if (string.IsNullOrEmpty(path))
                return false;

            string p = NormalizePathSlashes(path);

            if (p.IndexOf(
                    "Custom/Atom/Person/Appearance/CharacterRouter_Extracted",
                    StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return true;
            }

            int slash = p.LastIndexOf('/');
            string fileName = slash >= 0 ? p.Substring(slash + 1) : p;

            return fileName.StartsWith(
                       "Preset_CharacterRouter_SceneLook_",
                       StringComparison.OrdinalIgnoreCase) ||
                   fileName.StartsWith(
                       "CharacterRouter_SceneLook_",
                       StringComparison.OrdinalIgnoreCase);
        }

        private bool IsInternalSceneLookDisplayName(string value)
        {
            if (string.IsNullOrEmpty(value))
                return false;

            string v = value.Trim();
            return v.IndexOf(
                       "CharacterRouter_SceneLook_",
                       StringComparison.OrdinalIgnoreCase) >= 0 ||
                   v.IndexOf(
                       "Preset_CharacterRouter_SceneLook_",
                       StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private JSONNode ReadSceneJson(
            string scenePath,
            string source,
            bool rewriteSelfReferences,
            out string error)
        {
            error = "";

            if (string.IsNullOrEmpty(scenePath))
            {
                error = "Scene path is empty.";
                return null;
            }

            try
            {
                string content = FileManagerSecure.ReadAllText(scenePath);

                if (string.IsNullOrEmpty(content))
                {
                    error = "Scene file is empty or unreadable.";
                    return null;
                }

                if (rewriteSelfReferences &&
                    !string.IsNullOrEmpty(source) &&
                    !string.Equals(
                        source,
                        "Local",
                        StringComparison.OrdinalIgnoreCase))
                {
                    // Scene files inside a VAR commonly refer to assets as SELF:/...
                    // A temporary extracted Appearance lives outside that VAR, so those
                    // references must be made package-qualified before it is loaded.
                    content = content.Replace(
                        "SELF:/",
                        source + ":/"
                    );
                }

                JSONNode root = JSON.Parse(content);

                if (root == null)
                {
                    error = "Scene JSON could not be parsed.";
                    return null;
                }

                return root;
            }
            catch (Exception e)
            {
                error = e.Message;
                return null;
            }
        }

        private JSONNode FindScenePersonNode(
            JSONNode sceneRoot,
            string atomId)
        {
            if (sceneRoot == null)
                return null;

            JSONArray atoms = sceneRoot["atoms"].AsArray;
            if (atoms == null)
                return null;

            for (int i = 0; i < atoms.Count; i++)
            {
                JSONNode atom = atoms[i];
                if (atom == null)
                    continue;

                if (!string.Equals(
                        atom["type"].Value,
                        "Person",
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (string.Equals(
                        atom["id"].Value,
                        atomId,
                        StringComparison.Ordinal))
                {
                    return atom;
                }
            }

            return null;
        }

        private JSONNode FindSceneStorable(
            JSONNode personNode,
            string id)
        {
            if (personNode == null || string.IsNullOrEmpty(id))
                return null;

            JSONArray storables = personNode["storables"].AsArray;
            if (storables == null)
                return null;

            for (int i = 0; i < storables.Count; i++)
            {
                JSONNode storable = storables[i];
                if (storable == null)
                    continue;

                if (string.Equals(
                        storable["id"].Value,
                        id,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return storable;
                }
            }

            return null;
        }

        private bool HasActiveSceneCustomMorphForSex(
            JSONNode geometry,
            string sex)
        {
            if (geometry == null)
                return false;

            string pathToken = sex == "M"
                ? "/Custom/Atom/Person/Morphs/male/"
                : "/Custom/Atom/Person/Morphs/female/";

            string[] arrays = new string[] { "morphs", "morphsOtherGender" };

            for (int a = 0; a < arrays.Length; a++)
            {
                JSONArray morphs = geometry[arrays[a]].AsArray;
                if (morphs == null)
                    continue;

                for (int i = 0; i < morphs.Count; i++)
                {
                    JSONNode morph = morphs[i];
                    if (morph == null)
                        continue;

                    string uid = NormalizePathSlashes(morph["uid"].Value);
                    if (string.IsNullOrEmpty(uid) ||
                        uid.IndexOf(
                            pathToken,
                            StringComparison.OrdinalIgnoreCase) < 0)
                    {
                        continue;
                    }

                    float value = 0f;
                    if (!float.TryParse(
                            morph["value"].Value,
                            System.Globalization.NumberStyles.Float,
                            System.Globalization.CultureInfo.InvariantCulture,
                            out value))
                    {
                        continue;
                    }

                    // Ignore tiny residual values. A genuinely active custom body/face
                    // morph is much stronger sex evidence than a Hair/Clothing path.
                    if (Mathf.Abs(value) >= 0.05f)
                        return true;
                }
            }

            return false;
        }

        private string DetectScenePersonSex(
            JSONNode personNode,
            string scenePath,
            string source)
        {
            if (personNode == null)
                return "?";

            JSONNode geometry =
                FindSceneStorable(personNode, "geometry");

            string character = geometry == null
                ? ""
                : geometry["character"].Value;

            string atomId = personNode["id"].Value;
            string probe =
                (atomId == null ? "" : atomId) + " " +
                GetSceneLabel(scenePath) + " " +
                (source == null ? "" : source) + " " +
                (character == null ? "" : character);

            bool isAltFutaScene =
                _altFutaAdapter.IsAltFutaScenePerson(
                    personNode,
                    scenePath,
                    source
                );

            if (!isAltFutaScene &&
                _nativeFutanariAdapter.IsNativeFutanariScenePerson(
                    personNode,
                    scenePath,
                    source))
            {
                return "X";
            }

            // v94: an active custom morph stored in VaM's sex-specific morph
            // directory is stronger evidence than Hair/Clothing references.
            // This fixes scenes such as paledriver.Nico, whose female actor uses
            // a Male clothing accessory and was therefore previously classified '?'.
            bool hasActiveFemaleCustomMorph =
                HasActiveSceneCustomMorphForSex(geometry, "F");
            bool hasActiveMaleCustomMorph =
                HasActiveSceneCustomMorphForSex(geometry, "M");

            if (hasActiveFemaleCustomMorph && !hasActiveMaleCustomMorph)
                return "F";

            if (hasActiveMaleCustomMorph && !hasActiveFemaleCustomMorph)
                return "M";

            if (!string.IsNullOrEmpty(character))
            {
                if (character.IndexOf(
                        "Female",
                        StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return "F";
                }

                if (character.IndexOf(
                        "Male",
                        StringComparison.OrdinalIgnoreCase) >= 0 &&
                    character.IndexOf(
                        "Female",
                        StringComparison.OrdinalIgnoreCase) < 0)
                {
                    return "M";
                }
            }

            string serialized = personNode.ToString().Replace('\\', '/');

            bool hasFemalePaths =
                serialized.IndexOf(
                    "/Custom/Hair/Female/",
                    StringComparison.OrdinalIgnoreCase) >= 0 ||
                serialized.IndexOf(
                    "/Custom/Clothing/Female/",
                    StringComparison.OrdinalIgnoreCase) >= 0 ||
                serialized.IndexOf(
                    "/Custom/Atom/Person/Morphs/female/",
                    StringComparison.OrdinalIgnoreCase) >= 0;

            bool hasMalePaths =
                serialized.IndexOf(
                    "/Custom/Hair/Male/",
                    StringComparison.OrdinalIgnoreCase) >= 0 ||
                serialized.IndexOf(
                    "/Custom/Clothing/Male/",
                    StringComparison.OrdinalIgnoreCase) >= 0 ||
                serialized.IndexOf(
                    "/Custom/Atom/Person/Morphs/male/",
                    StringComparison.OrdinalIgnoreCase) >= 0;

            if (hasFemalePaths && !hasMalePaths)
                return "F";

            if (hasMalePaths && !hasFemalePaths)
                return "M";

            if (serialized.IndexOf(
                    "MVR_G2Female",
                    StringComparison.OrdinalIgnoreCase) >= 0 &&
                serialized.IndexOf(
                    "MVR_G2Male",
                    StringComparison.OrdinalIgnoreCase) < 0)
            {
                return "F";
            }

            if (serialized.IndexOf(
                    "MVR_G2Male",
                    StringComparison.OrdinalIgnoreCase) >= 0 &&
                serialized.IndexOf(
                    "MVR_G2Female",
                    StringComparison.OrdinalIgnoreCase) < 0)
            {
                return "M";
            }

            return "?";
        }

        private bool IsTransientSceneMorph(string uid)
        {
            if (string.IsNullOrEmpty(uid))
                return false;

            if (uid.IndexOf(
                    "Breast Impact",
                    StringComparison.OrdinalIgnoreCase) >= 0)
                return true;

            if (string.Equals(uid, "OpenXXL", StringComparison.OrdinalIgnoreCase))
                return true;

            if (uid.StartsWith("Mouth Open", StringComparison.OrdinalIgnoreCase) ||
                uid.StartsWith("Smile", StringComparison.OrdinalIgnoreCase) ||
                uid.StartsWith("Flirting", StringComparison.OrdinalIgnoreCase))
                return true;

            if (uid.IndexOf("Tongue In-Out", StringComparison.OrdinalIgnoreCase) >= 0 ||
                uid.IndexOf("Eyes Closed", StringComparison.OrdinalIgnoreCase) >= 0 ||
                uid.IndexOf("Shock", StringComparison.OrdinalIgnoreCase) >= 0 ||
                uid.IndexOf("Surprise", StringComparison.OrdinalIgnoreCase) >= 0 ||
                uid.IndexOf("Fear", StringComparison.OrdinalIgnoreCase) >= 0 ||
                uid.IndexOf("Pain", StringComparison.OrdinalIgnoreCase) >= 0 ||
                uid.IndexOf("Concentrate", StringComparison.OrdinalIgnoreCase) >= 0)
                return true;

            if ((uid.StartsWith("Left Fingers", StringComparison.OrdinalIgnoreCase) ||
                 uid.StartsWith("Right Fingers", StringComparison.OrdinalIgnoreCase)))
                return true;

            if (uid.StartsWith("Brow ", StringComparison.OrdinalIgnoreCase) &&
                (uid.IndexOf(" Up", StringComparison.OrdinalIgnoreCase) >= 0 ||
                 uid.IndexOf(" Down", StringComparison.OrdinalIgnoreCase) >= 0))
                return true;

            if (uid.StartsWith("Eyelids Top ", StringComparison.OrdinalIgnoreCase) ||
                uid.StartsWith("Eyelids Bottom ", StringComparison.OrdinalIgnoreCase))
                return true;

            return false;
        }

        private HashSet<string> GetActiveSceneClothingInternalIds(JSONNode personNode)
        {
            HashSet<string> result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (personNode == null)
                return result;

            JSONArray storables = personNode["storables"].AsArray;
            if (storables == null)
                return result;

            for (int i = 0; i < storables.Count; i++)
            {
                JSONNode storable = storables[i];
                if (storable == null ||
                    !string.Equals(
                        storable["id"].Value,
                        "geometry",
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                JSONArray clothing = storable["clothing"].AsArray;
                if (clothing == null)
                    break;

                for (int c = 0; c < clothing.Count; c++)
                {
                    JSONNode item = clothing[c];
                    if (item == null)
                        continue;

                    string enabled = item["enabled"].Value;
                    if (!string.IsNullOrEmpty(enabled) &&
                        string.Equals(
                            enabled,
                            "false",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    string internalId = item["internalId"].Value;
                    if (!string.IsNullOrEmpty(internalId))
                        result.Add(internalId.Trim());
                }

                break;
            }

            return result;
        }

        private bool IsActiveClothingPluginStorable(
            string id,
            HashSet<string> activeClothingInternalIds)
        {
            if (string.IsNullOrEmpty(id) ||
                activeClothingInternalIds == null ||
                activeClothingInternalIds.Count == 0)
            {
                return false;
            }

            int marker = id.IndexOf(
                ":plugin#",
                StringComparison.OrdinalIgnoreCase
            );

            if (marker <= 0)
                return false;

            string clothingInternalId = id.Substring(0, marker).Trim();
            return activeClothingInternalIds.Contains(clothingInternalId);
        }

        private bool ShouldSkipSceneAppearanceStorable(
            string id,
            HashSet<string> activeClothingInternalIds)
        {
            if (string.IsNullOrEmpty(id))
                return true;

            // Clothing plugins can be part of the appearance itself. CUA-backed hair,
            // jewelry and other clothing accessories often store their prefab/assetbundle
            // selection here. Keep those storables only when they belong to a clothing
            // item that is actually active in this scene Look. Atom/session plugins and
            // unrelated behavior plugins are still filtered out below.
            if (IsActiveClothingPluginStorable(id, activeClothingInternalIds))
                return false;

            string lower = id.ToLowerInvariant();

            if (lower == "headaudiosource")
                return true;

            return lower.Contains("control") ||
                   lower.Contains("trigger") ||
                   lower.Contains("plugin") ||
                   lower.Contains("preset") ||
                   lower.Contains("animation");
        }

