        private bool PatchSceneClothingPluginManagerToAshu(JSONClass storable)
        {
            if (storable == null || !IsClothingPluginManagerAshuAvailable())
                return false;

            JSONClass plugins = storable["plugins"].AsObject;
            if (plugins == null)
                return false;

            bool changed = false;
            List<string> keys = new List<string>();
            foreach (string key in plugins.Keys)
                keys.Add(key);

            for (int i = 0; i < keys.Count; i++)
            {
                string key = keys[i];
                string pluginPath = plugins[key].Value;
                if (string.IsNullOrEmpty(pluginPath))
                    continue;

                if (pluginPath.IndexOf(
                        "Stopper.ClothingPluginManager",
                        StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    plugins[key] = ClothingPluginManagerAshuPath;
                    changed = true;
                }
            }

            return changed;
        }

