        private string FindAssetUrlInJson(JSONNode node)
        {
            if (node == null)
                return "";

            JSONClass obj = node.AsObject;
            if (obj != null)
            {
                string direct = obj["assetUrl"].Value;
                if (!string.IsNullOrEmpty(direct))
                    return direct;

                foreach (string key in obj.Keys)
                {
                    string found = FindAssetUrlInJson(obj[key]);
                    if (!string.IsNullOrEmpty(found))
                        return found;
                }
            }

            JSONArray arr = node.AsArray;
            if (arr != null)
            {
                for (int i = 0; i < arr.Count; i++)
                {
                    string found = FindAssetUrlInJson(arr[i]);
                    if (!string.IsNullOrEmpty(found))
                        return found;
                }
            }

            return "";
        }

