        private string DescribeSceneClothingPluginStorable(JSONNode storable)
        {
            if (storable == null)
                return "";

            string id = storable["id"].Value;
            string description = id;
            JSONArray nested = storable["storables"].AsArray;

            if (nested != null)
            {
                for (int i = 0; i < nested.Count; i++)
                {
                    JSONNode child = nested[i];
                    if (child == null)
                        continue;

                    string childId = child["id"].Value;
                    string assetUrl = child["assetUrl"].Value;
                    if (!string.IsNullOrEmpty(childId))
                        description += " | child=" + childId;
                    if (!string.IsNullOrEmpty(assetUrl))
                        description += " | assetUrl=" + assetUrl;
                }
            }

            return description;
        }

