        private JSONClass BuildHairPresetFromScenePerson(
            JSONNode personNode,
            out string error)
        {
            error = "";

            if (personNode == null)
            {
                error = "Scene Person is missing.";
                return null;
            }

            JSONArray sourceStorables = personNode["storables"].AsArray;
            if (sourceStorables == null)
            {
                error = "Scene Person has no storables.";
                return null;
            }

            JSONNode sourceGeometry = FindSceneStorable(personNode, "geometry");
            if (sourceGeometry == null)
            {
                error = "Scene Person has no geometry storable.";
                return null;
            }

            JSONArray sourceHair = sourceGeometry["hair"].AsArray;
            if (sourceHair == null || sourceHair.Count == 0)
            {
                error = "Scene Person has no Hair state.";
                return null;
            }

            JSONArray hairCopy = CloneJsonArray(sourceHair);
            if (hairCopy == null)
            {
                error = "Could not clone scene Hair state.";
                return null;
            }

            HashSet<string> activePrefixes =
                new HashSet<string>(StringComparer.Ordinal);
            bool hasEnabledHair = false;

            for (int i = 0; i < sourceHair.Count; i++)
            {
                JSONNode item = sourceHair[i];
                if (item == null || !IsHairNodeEnabled(item))
                    continue;

                hasEnabledHair = true;
                string prefix = GetHairPrefixFromGeometryEntry(item);
                if (!string.IsNullOrEmpty(prefix))
                    activePrefixes.Add(prefix);
            }

            if (!hasEnabledHair)
            {
                error = "Scene Person has no enabled Hair components.";
                return null;
            }

            JSONArray outputStorables = new JSONArray();
            JSONClass geometry = new JSONClass();
            geometry["id"] = "geometry";
            geometry["hair"] = hairCopy;
            outputStorables.Add(geometry);

            // Preserve only dynamic state belonging to active Hair components.
            // Scene Persons contain many unrelated storables; importing them here
            // would turn a hairstyle into a partial Appearance preset.
            for (int i = 0; i < sourceStorables.Count; i++)
            {
                JSONNode st = sourceStorables[i];
                if (st == null)
                    continue;

                string id = st["id"].Value;
                if (string.IsNullOrEmpty(id) ||
                    string.Equals(id, "geometry", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(id, "HairPresets", StringComparison.OrdinalIgnoreCase) ||
                    !IsUsefulHairStateStorable(id))
                {
                    continue;
                }

                bool belongsToHair = false;
                foreach (string prefix in activePrefixes)
                {
                    if (id.StartsWith(prefix, StringComparison.Ordinal))
                    {
                        belongsToHair = true;
                        break;
                    }
                }

                if (!belongsToHair)
                    continue;

                JSONNode copy = JSON.Parse(st.ToString());
                if (copy != null)
                    outputStorables.Add(copy);
            }

            JSONClass preset = new JSONClass();
            preset["setUnlistedParamsToDefault"] = "true";
            preset["storables"] = outputStorables;
            return preset;
        }

        private string DetectSceneHairSex(
            JSONNode personNode,
            JSONClass preset,
            string scenePath,
            string source)
        {
            string sex = DetectHairPresetSexFromJson(preset);
            if (sex == "F" || sex == "M")
                return sex;

            JSONNode geometry = FindSceneStorable(personNode, "geometry");
            string character = geometry == null ? "" : geometry["character"].Value;
            if (!string.IsNullOrEmpty(character))
            {
                if (character.IndexOf("Female", StringComparison.OrdinalIgnoreCase) >= 0)
                    return "F";

                if (character.IndexOf("Male", StringComparison.OrdinalIgnoreCase) >= 0 &&
                    character.IndexOf("Female", StringComparison.OrdinalIgnoreCase) < 0)
                {
                    return "M";
                }
            }

            string sceneSex = DetectScenePersonSex(personNode, scenePath, source);
            return sceneSex == "F" || sceneSex == "M" ? sceneSex : "?";
        }

        private string GetSceneHairFingerprint(JSONClass preset, string region)
        {
            JSONClass regionPreset = BuildSceneHairRegionOnlyPresetJson(preset, region);
            if (regionPreset == null || !HairPresetHasEnabledGeometryItems(regionPreset))
                return "";

            // Scene files can retain disabled Hair entries from earlier edits. They
            // are not part of the visible hairstyle and must not manufacture duplicate
            // SCENES cards for the same active Hair layer. Keep visual-state storables,
            // but normalize geometry.hair to enabled items only before hashing.
            try
            {
                JSONArray storables = regionPreset["storables"].AsArray;
                if (storables != null)
                {
                    for (int i = 0; i < storables.Count; i++)
                    {
                        JSONNode st = storables[i];
                        if (st == null || st["id"].Value != "geometry")
                            continue;

                        JSONArray hair = st["hair"].AsArray;
                        if (hair == null)
                            break;

                        JSONArray enabledOnly = new JSONArray();
                        for (int h = 0; h < hair.Count; h++)
                        {
                            JSONNode item = hair[h];
                            if (item == null || !IsHairNodeEnabled(item))
                                continue;
                            JSONNode copy = JSON.Parse(item.ToString());
                            if (copy != null) enabledOnly.Add(copy);
                        }
                        st["hair"] = enabledOnly;
                        break;
                    }
                }
            }
            catch { }

            return StableSceneLookHash(regionPreset.ToString()).ToString("X8");
        }

        private bool HasSceneHairFingerprint(string region, string fingerprint)
        {
            if (string.IsNullOrEmpty(region) || string.IsNullOrEmpty(fingerprint))
                return false;

            return _sceneHairFingerprints.Contains(region + "|" + fingerprint);
        }

        private void AddSceneHairFromScene(string scenePath, string source)
        {
            if (string.IsNullOrEmpty(scenePath))
                return;

            scenePath = NormalizePathSlashes(scenePath);

            string readError;
            JSONNode root = ReadSceneJson(
                scenePath,
                source,
                true,
                out readError
            );

            if (root == null)
                return;

            JSONArray atoms = root["atoms"].AsArray;
            if (atoms == null)
                return;

            List<JSONNode> persons = new List<JSONNode>();
            for (int i = 0; i < atoms.Count; i++)
            {
                JSONNode atom = atoms[i];
                if (atom != null && string.Equals(
                        atom["type"].Value,
                        "Person",
                        StringComparison.OrdinalIgnoreCase))
                {
                    persons.Add(atom);
                }
            }

            if (persons.Count == 0)
                return;

            string thumb = GetSceneThumbnailPath(scenePath);

            for (int i = 0; i < persons.Count; i++)
            {
                JSONNode person = persons[i];
                string atomId = person["id"].Value;
                if (string.IsNullOrEmpty(atomId))
                    atomId = "Person" + (i + 1);

                string buildError;
                JSONClass preset = BuildHairPresetFromScenePerson(person, out buildError);
                if (preset == null)
                    continue;

                string label = GetScenePersonFriendlyLabel(
                    person,
                    scenePath,
                    source,
                    i,
                    persons.Count
                );

                string[] editableRegions = new string[] { "Head", "Facial", "Body", "Pubic" };
                for (int r = 0; r < editableRegions.Length; r++)
                {
                    string region = editableRegions[r];
                    JSONClass regionPreset = BuildSceneHairRegionOnlyPresetJson(preset, region);
                    if (regionPreset == null || !HairPresetHasEnabledGeometryItems(regionPreset))
                        continue;

                    string fingerprint = GetSceneHairFingerprint(preset, region);
                    if (string.IsNullOrEmpty(fingerprint) ||
                        HasSceneHairFingerprint(region, fingerprint))
                    {
                        continue;
                    }

                    string key = GetSceneHairKey(region, fingerprint);
                    HairPresetEntry entry = new HairPresetEntry();
                    entry.path = key;
                    entry.label = label;
                    entry.thumbnailPath = thumb;
                    entry.sex = DetectSceneHairSex(person, regionPreset, scenePath, source);
                    entry.region = region;
                    entry.source = source;
                    entry.isSceneHair = true;
                    entry.scenePath = scenePath;
                    entry.sceneAtomId = atomId;
                    entry.sceneHairFingerprint = fingerprint;

                    _hairPresetEntries.Add(entry);
                    _sceneHairFingerprints.Add(region + "|" + fingerprint);
                    _hairPresetRegionsByPath[key] =
                        new HashSet<string>(
                            new string[] { region },
                            StringComparer.OrdinalIgnoreCase
                        );
                }
            }
        }

        private void ScanSceneHairDirectoryRecursive(
            string root,
            string source,
            int depth)
        {
            if (string.IsNullOrEmpty(root) || depth > 12)
                return;

            try
            {
                var files = FileManagerSecure.GetFiles(root, "*.json");
                foreach (string f in files)
                    AddSceneHairFromScene(f, source);
            }
            catch { }

            try
            {
                var dirs = FileManagerSecure.GetDirectories(root, "*");
                foreach (string dir in dirs)
                    ScanSceneHairDirectoryRecursive(dir, source, depth + 1);
            }
            catch { }
        }

        private int CountSceneHairEntries()
        {
            int count = 0;
            for (int i = 0; i < _hairPresetEntries.Count; i++)
            {
                if (_hairPresetEntries[i] != null && _hairPresetEntries[i].isSceneHair)
                    count++;
            }
            return count;
        }

        private JSONClass BuildAppearancePresetFromScenePerson(
            JSONNode personNode,
            out string error)
        {
            error = "";

            if (personNode == null)
            {
                error = "Scene Person is missing.";
                return null;
            }

            JSONArray sourceStorables = personNode["storables"].AsArray;
            if (sourceStorables == null)
            {
                error = "Scene Person has no storables.";
                return null;
            }

            JSONArray outputStorables = new JSONArray();
            HashSet<string> activeClothingInternalIds =
                GetActiveSceneClothingInternalIds(personNode);
            bool diagnosticNico = IsNicoSceneLook(activeClothingInternalIds);
            List<string> preservedClothingPluginIds = new List<string>();

            for (int i = 0; i < sourceStorables.Count; i++)
            {
                JSONNode sourceStorable = sourceStorables[i];
                if (sourceStorable == null)
                    continue;

                string id = sourceStorable["id"].Value;
                bool isActiveClothingPlugin =
                    IsActiveClothingPluginStorable(
                        id,
                        activeClothingInternalIds
                    );

                if (ShouldSkipSceneAppearanceStorable(
                        id,
                        activeClothingInternalIds))
                {
                    continue;
                }

                if (isActiveClothingPlugin)
                    preservedClothingPluginIds.Add(
                        DescribeSceneClothingPluginStorable(sourceStorable)
                    );

                JSONNode clonedNode = JSON.Parse(sourceStorable.ToString());
                JSONClass storable = clonedNode == null
                    ? null
                    : clonedNode.AsObject;

                if (storable == null)
                    continue;

                if (isActiveClothingPlugin)
                {
                    string pluginBefore = GetPluginZeroPath(storable);
                    bool ashuAvailable = IsClothingPluginManagerAshuAvailable();
                    bool ashuPatched = PatchSceneClothingPluginManagerToAshu(storable);
                    string pluginAfter = GetPluginZeroPath(storable);

                    if (diagnosticNico)
                    {
                        AppendSceneLookDiagnostic(
                            "NICO EXTRACT PLUGIN | id=" + (id ?? "") +
                            " | ashuAvailable=" + ashuAvailable +
                            " | patched=" + ashuPatched +
                            " | before=" + (pluginBefore ?? "") +
                            " | after=" + (pluginAfter ?? "")
                        );
                    }
                }

                List<string> keysToRemove = new List<string>();
                foreach (string key in storable.Keys)
                {
                    string lowerKey = key.ToLowerInvariant();
                    if (lowerKey.Contains("position") ||
                        lowerKey.Contains("rotation"))
                    {
                        keysToRemove.Add(key);
                    }
                }

                for (int r = 0; r < keysToRemove.Count; r++)
                    storable.Remove(keysToRemove[r]);

                if (string.Equals(
                        id,
                        "geometry",
                        StringComparison.OrdinalIgnoreCase))
                {
                    JSONArray morphs = storable["morphs"].AsArray;
                    if (morphs != null)
                    {
                        JSONArray filteredMorphs = new JSONArray();

                        for (int m = 0; m < morphs.Count; m++)
                        {
                            JSONNode morph = morphs[m];
                            if (morph == null)
                                continue;

                            if (IsTransientSceneMorph(morph["uid"].Value))
                                continue;

                            JSONNode morphClone = JSON.Parse(morph.ToString());
                            if (morphClone != null)
                                filteredMorphs.Add(morphClone);
                        }

                        storable["morphs"] = filteredMorphs;
                    }
                }

                if (storable.Count > 1)
                    outputStorables.Add(storable);
            }

            if (outputStorables.Count == 0)
            {
                error = "No appearance storables could be extracted from scene Person.";
                return null;
            }

            if (diagnosticNico)
            {
                AppendSceneLookDiagnostic(
                    "NICO EXTRACT SUMMARY | AshuAvailable=" +
                    IsClothingPluginManagerAshuAvailable()
                );
                WriteSceneLookDiagnosticLog(
                    personNode["id"].Value,
                    activeClothingInternalIds,
                    preservedClothingPluginIds
                );
            }

            JSONClass preset = new JSONClass();
            preset["setUnlistedParamsToDefault"] = "true";
            preset["storables"] = outputStorables;
            return preset;
        }

        private bool EnsureSceneLookTempPreset(
            AppearanceEntry entry,
            out string tempPath,
            out string error)
        {
            tempPath = "";
            error = "";

            if (entry == null || !entry.isSceneLook)
            {
                error = "Catalog item is not a scene Look.";
                return false;
            }

            // v128: do not call SaveJSON repeatedly for the same deterministic
            // extracted Scene Look. Besides being unnecessary, VaM presents a
            // secure-write permission popup that can interrupt third-party clothing
            // plugin initialization. Existing v122 temp presets are reused verbatim.
            tempPath = GetSceneLookTempPath(entry);
            try
            {
                if (FileManagerSecure.FileExists(tempPath))
                {
                    _decalMakerAdapter.DiagnosticNote(
                        "SCENELOOK CACHE HIT | path=" + tempPath +
                        " | label=" + (entry.label ?? "")
                    );
                    return true;
                }
            }
            catch { }

            _decalMakerAdapter.DiagnosticNote(
                "SCENELOOK CACHE MISS | path=" + tempPath +
                " | label=" + (entry.label ?? "") +
                " | nextStep=SaveJSON_once"
            );

            string readError;
            JSONNode sceneRoot = ReadSceneJson(
                entry.scenePath,
                entry.source,
                true,
                out readError
            );

            if (sceneRoot == null)
            {
                error = "Could not read source scene: " + readError;
                return false;
            }

            JSONNode personNode = FindScenePersonNode(
                sceneRoot,
                entry.sceneAtomId
            );

            if (personNode == null)
            {
                error = "Person '" + entry.sceneAtomId + "' was not found in source scene.";
                return false;
            }

            string buildError;
            JSONClass preset = BuildAppearancePresetFromScenePerson(
                personNode,
                out buildError
            );

            if (preset == null)
            {
                error = "Could not extract scene appearance: " + buildError;
                return false;
            }

            try
            {
                // VaM's AppearancePresets storable rejects presetBrowsePath values
                // outside Custom/Atom/Person/Appearance/.  v55-v57 wrote the
                // extracted .vap to Custom/PluginData, which produced the exact
                // "not compatible with store folder path" error seen in VaM.
                FileManagerSecure.CreateDirectory(
                    "Custom/Atom/Person/Appearance/CharacterRouter_Extracted"
                );
                SaveJSON(preset, tempPath);
                if (
                    (!string.IsNullOrEmpty(entry.label) &&
                     entry.label.IndexOf("Nico", StringComparison.OrdinalIgnoreCase) >= 0) ||
                    (!string.IsNullOrEmpty(entry.source) &&
                     entry.source.IndexOf("paledriver.Nico", StringComparison.OrdinalIgnoreCase) >= 0)
                )
                {
                    AppendSceneLookDiagnostic(
                        "TEMP PRESET WRITTEN | label=" + (entry.label ?? "") +
                        " | source=" + (entry.source ?? "") +
                        " | path=" + tempPath +
                        " | AshuAvailable=" + IsClothingPluginManagerAshuAvailable()
                    );

                    JSONArray tempStorables = preset["storables"].AsArray;
                    if (tempStorables != null)
                    {
                        for (int ti = 0; ti < tempStorables.Count; ti++)
                        {
                            JSONNode ts = tempStorables[ti];
                            if (ts == null)
                                continue;

                            string tid = ts["id"].Value;
                            if (tid.IndexOf("Nico Hair:plugin#0", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                tid.IndexOf("Nico Necklace:plugin#0", StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                AppendSceneLookDiagnostic(
                                    "TEMP PRESET PLUGIN | id=" + tid +
                                    " | plugin#0=" + GetPluginZeroPath(ts) +
                                    " | assetUrl=" + FindAssetUrlInJson(ts)
                                );
                            }
                        }
                    }
                }
                return true;
            }
            catch (Exception e)
            {
                error = e.Message;
                tempPath = "";
                return false;
            }
        }

        private bool ResolveAppearanceLoadPath(
            AppearanceEntry entry,
            out string loadPath,
            out string error)
        {
            loadPath = "";
            error = "";

            if (entry == null)
            {
                error = "No Look selected.";
                return false;
            }

            if (!entry.isSceneLook)
            {
                loadPath = entry.path;
                return !string.IsNullOrEmpty(loadPath);
            }

            return EnsureSceneLookTempPreset(
                entry,
                out loadPath,
                out error
            );
        }

        private int CountSceneLookEntries()
        {
            int count = 0;
            for (int i = 0; i < _appearanceEntries.Count; i++)
            {
                if (_appearanceEntries[i] != null &&
                    _appearanceEntries[i].isSceneLook)
                {
                    count++;
                }
            }
            return count;
        }

        private bool HasAppearancePresetFromSource(string source)
        {
            if (string.IsNullOrEmpty(source))
                return false;

            for (int i = 0; i < _appearanceEntries.Count; i++)
            {
                AppearanceEntry entry = _appearanceEntries[i];
                if (entry == null || entry.isSceneLook)
                    continue;

                if (string.Equals(
                        entry.source,
                        source,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }

            return false;
        }

        private bool IsGenericScenePersonAtomId(string atomId)
        {
            if (string.IsNullOrEmpty(atomId))
                return true;

            string id = atomId.Trim();
            if (string.Equals(id, "Person", StringComparison.OrdinalIgnoreCase))
                return true;

            // VaM commonly names scene actors Person#2, Person2, Person_2, etc.
            if (id.StartsWith("Person", StringComparison.OrdinalIgnoreCase))
            {
                string rest = id.Substring(6).Trim();
                if (string.IsNullOrEmpty(rest))
                    return true;

                bool genericSuffix = true;
                for (int i = 0; i < rest.Length; i++)
                {
                    char ch = rest[i];
                    if (!char.IsDigit(ch) &&
                        ch != '#' && ch != '_' && ch != '-' && ch != ' ')
                    {
                        genericSuffix = false;
                        break;
                    }
                }

                if (genericSuffix)
                    return true;
            }

            return false;
        }

        private string CleanSceneCharacterName(string value)
        {
            if (string.IsNullOrEmpty(value))
                return "";

            string name = value.Replace('_', ' ').Trim();

            string[] suffixes = new string[]
            {
                " Full Body Morph", " Fullbody Morph", " Full Body",
                " Body Morph", " Head Morph", " Morph", " Body", " Head"
            };

            for (int i = 0; i < suffixes.Length; i++)
            {
                if (name.EndsWith(suffixes[i], StringComparison.OrdinalIgnoreCase) &&
                    name.Length > suffixes[i].Length + 1)
                {
                    name = name.Substring(0, name.Length - suffixes[i].Length).Trim();
                    break;
                }
            }

            return name;
        }

        private string GetStrongCustomMorphCharacterName(JSONNode personNode)
        {
            JSONNode geometry = FindSceneStorable(personNode, "geometry");
            if (geometry == null)
                return "";

            string bestName = "";
            float bestScore = 0f;

            string[] arrays = new string[] { "morphsOtherGender", "morphs" };

            for (int a = 0; a < arrays.Length; a++)
            {
                JSONArray morphs = geometry[arrays[a]].AsArray;
                if (morphs == null)
                    continue;

                for (int i = 0; i < morphs.Count; i++)
                {
                    JSONNode morph = morphs[i];
                    if (morph == null)
                        continue;

                    string uid = NormalizePathSlashes(morph["uid"].Value);
                    string name = morph["name"].Value;

                    // Only custom-file morphs are strong enough evidence for a
                    // character name. Built-in shaping/pose morphs are ignored.
                    if (string.IsNullOrEmpty(uid) ||
                        uid.IndexOf(
                            "/Custom/Atom/Person/Morphs/",
                            StringComparison.OrdinalIgnoreCase) < 0)
                    {
                        continue;
                    }

                    float value = 0f;
                    float.TryParse(
                        morph["value"].Value,
                        System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture,
                        out value
                    );

                    float score = Mathf.Abs(value);
                    if (score < 0.70f)
                        continue;

                    string cleaned = CleanSceneCharacterName(name);
                    if (string.IsNullOrEmpty(cleaned))
                        continue;

                    // Avoid selecting obvious utility/anatomy morphs as the actor name.
                    string lower = cleaned.ToLowerInvariant();
                    if (lower.Contains("lower hips") ||
                        lower.Contains("genital") ||
                        lower.Contains("foreskin") ||
                        lower.Contains("scrot") ||
                        lower.Contains("penis") ||
                        lower.Contains("vagina") ||
                        lower.Contains("breast") ||
                        lower.Contains("navel"))
                    {
                        continue;
                    }

                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestName = cleaned;
                    }
                }
            }

            return bestName;
        }

        private string GetScenePersonFriendlyLabel(
            JSONNode personNode,
            string scenePath,
            string source,
            int personIndex,
            int personCount)
        {
            string atomId = personNode == null ? "" : personNode["id"].Value;

            // A deliberately named Person atom is the best author-provided name.
            if (!IsGenericScenePersonAtomId(atomId))
                return atomId.Trim();

            // Scene-only Look packages very often carry a named custom character
            // morph even when the atom itself is just called "Person". Sara is a
            // verified example: its active custom morph is literally named "Sara".
            string morphName = GetStrongCustomMorphCharacterName(personNode);
            if (!string.IsNullOrEmpty(morphName))
                return morphName;

            string sceneLabel = GetSceneLabel(scenePath);

            // For a one-person scene, the scene/resource title is normally the best
            // human label and avoids useless "Scene — Person" names.
            if (personCount <= 1)
                return sceneLabel;

            // Multiple generic Persons need a stable disambiguator.
            return sceneLabel + " — Character " + (personIndex + 1);
        }

        private string GetSceneAppearanceFingerprint(JSONNode personNode)
        {
            string buildError;
            JSONClass preset = BuildAppearancePresetFromScenePerson(
                personNode,
                out buildError
            );

            if (preset == null)
                return "";

            return StableSceneLookHash(preset.ToString()).ToString("X8");
        }

        private bool HasSceneAppearanceFingerprint(string fingerprint)
        {
            if (string.IsNullOrEmpty(fingerprint))
                return false;

            for (int i = 0; i < _appearanceEntries.Count; i++)
            {
                AppearanceEntry entry = _appearanceEntries[i];
                if (entry == null || !entry.isSceneLook)
                    continue;

                if (string.Equals(
                        entry.sceneAppearanceFingerprint,
                        fingerprint,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }

            return false;
        }

        private void AddSceneCharactersFromScene(
            string scenePath,
            string source)
        {
            if (string.IsNullOrEmpty(scenePath))
                return;

            scenePath = NormalizePathSlashes(scenePath);

            // The unqualified Saves/scene view may expose mounted package files.
            // Package scenes are scanned explicitly with their package UID below;
            // do not add those a second time as "Local" scene Looks.
            if (string.Equals(
                    source,
                    "Local",
                    StringComparison.OrdinalIgnoreCase) &&
                scenePath.IndexOf(":/", StringComparison.Ordinal) >= 0)
            {
                return;
            }

            string readError;
            JSONNode root = ReadSceneJson(
                scenePath,
                source,
                false,
                out readError
            );

            if (root == null)
                return;

            JSONArray atoms = root["atoms"].AsArray;
            if (atoms == null)
                return;

            List<JSONNode> persons = new List<JSONNode>();

            for (int i = 0; i < atoms.Count; i++)
            {
                JSONNode atom = atoms[i];
                if (atom == null)
                    continue;

                if (string.Equals(
                        atom["type"].Value,
                        "Person",
                        StringComparison.OrdinalIgnoreCase))
                {
                    persons.Add(atom);
                }
            }

            if (persons.Count == 0)
                return;

            string sceneLabel = GetSceneLabel(scenePath);
            string thumb = GetSceneThumbnailPath(scenePath);

            for (int i = 0; i < persons.Count; i++)
            {
                JSONNode person = persons[i];
                string atomId = person["id"].Value;

                if (string.IsNullOrEmpty(atomId))
                    atomId = "Person" + (i + 1);

                string key = GetSceneLookKey(
                    scenePath,
                    atomId,
                    source
                );

                bool duplicate = false;
                for (int e = 0; e < _appearanceEntries.Count; e++)
                {
                    if (string.Equals(
                            _appearanceEntries[e].path,
                            key,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        duplicate = true;
                        break;
                    }
                }

                if (duplicate)
                    continue;

                string appearanceFingerprint =
                    GetSceneAppearanceFingerprint(person);

                // The same actor Look is often reused in many animation/demo scenes.
                // SCENES is a character catalog, not a scene catalog, so keep one
                // card for an exact appearance instead of one card per scene file.
                if (HasSceneAppearanceFingerprint(appearanceFingerprint))
                    continue;

                AppearanceEntry entry = new AppearanceEntry();
                entry.path = key;
                entry.label = GetScenePersonFriendlyLabel(
                    person,
                    scenePath,
                    source,
                    i,
                    persons.Count
                );
                entry.thumbnailPath = thumb;
                entry.isAltFuta =
                    _altFutaAdapter.IsAltFutaScenePerson(
                        person,
                        scenePath,
                        source
                    );
                entry.sex = DetectScenePersonSex(
                    person,
                    scenePath,
                    source
                );
                entry.source = source;
                entry.isSceneLook = true;
                entry.scenePath = scenePath;
                entry.sceneAtomId = atomId;
                entry.sceneAppearanceFingerprint = appearanceFingerprint;

                _appearanceEntries.Add(entry);
            }
        }

        private void ScanSceneDirectoryRecursive(
            string root,
            string source,
            int depth)
        {
            if (string.IsNullOrEmpty(root) || depth > 12)
                return;

            try
            {
                var files = FileManagerSecure.GetFiles(root, "*.json");
                foreach (string f in files)
                    AddSceneCharactersFromScene(f, source);
            }
            catch { }

            try
            {
                var dirs = FileManagerSecure.GetDirectories(root, "*");
                foreach (string dir in dirs)
                    ScanSceneDirectoryRecursive(dir, source, depth + 1);
            }
            catch { }
        }

        private string ExtractJsonStringValueAfterKey(
            string content,
            string key,
            int searchStart,
            out int nextSearchStart)
        {
            nextSearchStart = searchStart;

            if (string.IsNullOrEmpty(content) || string.IsNullOrEmpty(key))
                return "";

            string token = "\"" + key + "\"";
            int keyIndex = content.IndexOf(
                token,
                Mathf.Max(0, searchStart),
                StringComparison.OrdinalIgnoreCase
            );

            if (keyIndex < 0)
                return "";

            int colon = content.IndexOf(':', keyIndex + token.Length);
            if (colon < 0)
                return "";

            int quoteStart = content.IndexOf('"', colon + 1);
            if (quoteStart < 0)
                return "";

            int quoteEnd = quoteStart + 1;
            bool escaped = false;

            while (quoteEnd < content.Length)
            {
                char ch = content[quoteEnd];

                if (ch == '"' && !escaped)
                    break;

                if (ch == '\\' && !escaped)
                    escaped = true;
                else
                    escaped = false;

                quoteEnd++;
            }

            if (quoteEnd >= content.Length)
                return "";

            nextSearchStart = quoteEnd + 1;

            return content.Substring(
                quoteStart + 1,
                quoteEnd - quoteStart - 1
            );
        }

        private string DetectAppearanceGeometryAssetSex(string content)
        {
            if (string.IsNullOrEmpty(content))
                return "?";

            try
            {
                JSONNode root = JSON.Parse(content);
                JSONArray storables =
                    root == null
                    ? null
                    : root["storables"].AsArray;

                if (storables == null)
                    return "?";

                JSONNode geometry = null;

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode storable = storables[i];

                    if (storable != null &&
                        string.Equals(
                            storable["id"].Value,
                            "geometry",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        geometry = storable;
                        break;
                    }
                }

                if (geometry == null)
                    return "?";

                int femaleAssets = 0;
                int maleAssets = 0;

                string[] banks =
                    new string[] { "clothing", "hair" };

                for (int b = 0; b < banks.Length; b++)
                {
                    JSONArray items =
                        geometry[banks[b]].AsArray;

                    if (items == null)
                        continue;

                    for (int i = 0; i < items.Count; i++)
                    {
                        JSONNode item = items[i];
                        if (item == null)
                            continue;

                        string id =
                            item["id"].Value == null
                            ? ""
                            : item["id"].Value.Replace('\\', '/');

                        string probe =
                            "/" + id.TrimStart('/');

                        if (probe.IndexOf(
                                "/Custom/Clothing/Female/",
                                StringComparison.OrdinalIgnoreCase) >= 0 ||
                            probe.IndexOf(
                                "/Custom/Hair/Female/",
                                StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            femaleAssets++;
                        }

                        if (probe.IndexOf(
                                "/Custom/Clothing/Male/",
                                StringComparison.OrdinalIgnoreCase) >= 0 ||
                            probe.IndexOf(
                                "/Custom/Hair/Male/",
                                StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            maleAssets++;
                        }
                    }
                }

                if (femaleAssets > 0 && maleAssets == 0)
                    return "F";

                if (maleAssets > 0 && femaleAssets == 0)
                    return "M";
            }
            catch { }

            return "?";
        }

        private string DetectAppearancePresetSex(string path, string source = null)
        {
            if (string.IsNullOrEmpty(path))
                return "?";

            // VaM itself has only Female/Male base geometry, so Futanari Appearance
            // presets need an explicit catalog-level type. In practice these packs
            // overwhelmingly identify themselves in the preset/file name.
            string presetLabel =
                GetPresetLabel(path);

            // IMPORTANT: FileManagerSecure.GetFiles() can return a virtual preset
            // path without the package UID prefix.  The package UID is carried
            // separately in `source`, so include it in every filename/path probe.
            // This is required for older Hub packs such as
            // kemenate.Female_Looks.* where the .vap itself has no useful gender
            // metadata but the package UID is explicitly sex-specific.
            string nameProbe =
                (presetLabel == null ? "" : presetLabel) +
                " " +
                (source == null ? "" : source) +
                " " +
                path;

            bool isAltFuta =
                _altFutaAdapter.IsAltFutaAppearance(
                    path,
                    source,
                    presetLabel
                );

            if (!isAltFuta &&
                _nativeFutanariAdapter.IsNativeFutanariAppearance(
                    path,
                    source,
                    presetLabel))
            {
                return "X";
            }

            try
            {
                // For presets inside third-party VARs, use VaM's secure virtual
                // filesystem reader first. SuperController.ReadFileIntoString can
                // work for loose files yet fail/return empty on package virtual
                // paths, which left valid Looks such as Gara Mond classified [?].
                string content = "";

                try
                {
                    content = FileManagerSecure.ReadAllText(path);
                }
                catch { }

                if (string.IsNullOrEmpty(content))
                {
                    try
                    {
                        content = SuperController.singleton.ReadFileIntoString(path);
                    }
                    catch { }
                }

                if (!string.IsNullOrEmpty(content))
                {
                    bool foundFemale = false;
                    bool foundMale = false;

                    string[] keys =
                        new string[] { "character", "gender" };

                    for (int k = 0; k < keys.Length; k++)
                    {
                        int searchAt = 0;

                        for (int guard = 0;
                             guard < 96 &&
                             searchAt < content.Length;
                             guard++)
                        {
                            int next;
                            string value =
                                ExtractJsonStringValueAfterKey(
                                    content,
                                    keys[k],
                                    searchAt,
                                    out next
                                );

                            if (string.IsNullOrEmpty(value) ||
                                next <= searchAt)
                            {
                                break;
                            }

                            searchAt = next;

                            // Female must be checked first because it contains "male".
                            if (value.IndexOf(
                                    "Female",
                                    StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                foundFemale = true;
                            }
                            else if (value.IndexOf(
                                    "Male",
                                    StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                foundMale = true;
                            }
                        }
                    }

                    if (foundFemale && !foundMale)
                        return "F";

                    if (foundMale && !foundFemale)
                        return "M";

                    // Prefer direct geometry clothing/hair item IDs over arbitrary
                    // material/texture paths elsewhere in the preset. A Female item
                    // can legitimately reference a texture stored under a Male folder;
                    // treating that texture path as body-sex evidence made Arin [?].
                    string geometryAssetSex =
                        DetectAppearanceGeometryAssetSex(content);

                    if (geometryAssetSex == "F" ||
                        geometryAssetSex == "M")
                    {
                        return geometryAssetSex;
                    }

                    // Some valid Appearance presets use a named base character
                    // instead of a sex-bearing value in geometry.character.
                    // Example verified from the real kemenate Gara Mond package:
                    //     "character" : "Evey"
                    // so character/gender alone cannot classify it.  However the
                    // serialized preset contains many unambiguous sex-specific
                    // asset references (/Hair/Female/, /Clothing/Female/,
                    // /Morphs/female/) and no Male equivalents.  Use those paths
                    // as structural evidence before falling back to filename guesses.
                    string normalizedContent =
                        content.Replace('\\', '/');

                    bool hasFemaleAssetPaths =
                        normalizedContent.IndexOf(
                            "/Custom/Hair/Female/",
                            StringComparison.OrdinalIgnoreCase) >= 0 ||
                        normalizedContent.IndexOf(
                            "/Custom/Clothing/Female/",
                            StringComparison.OrdinalIgnoreCase) >= 0 ||
                        normalizedContent.IndexOf(
                            "/Custom/Atom/Person/Morphs/female/",
                            StringComparison.OrdinalIgnoreCase) >= 0;

                    bool hasMaleAssetPaths =
                        normalizedContent.IndexOf(
                            "/Custom/Hair/Male/",
                            StringComparison.OrdinalIgnoreCase) >= 0 ||
                        normalizedContent.IndexOf(
                            "/Custom/Clothing/Male/",
                            StringComparison.OrdinalIgnoreCase) >= 0 ||
                        normalizedContent.IndexOf(
                            "/Custom/Atom/Person/Morphs/male/",
                            StringComparison.OrdinalIgnoreCase) >= 0;

                    if (hasFemaleAssetPaths && !hasMaleAssetPaths)
                        return "F";

                    if (hasMaleAssetPaths && !hasFemaleAssetPaths)
                        return "M";

                    // Some older Appearance presets do not store a useful
                    // character/gender field. Their serialized geometry still
                    // commonly references the native Genesis 2 base explicitly.
                    bool hasFemaleGeometry =
                        content.IndexOf(
                            "MVR_G2Female",
                            StringComparison.OrdinalIgnoreCase) >= 0 ||
                        content.IndexOf(
                            "Genesis2Female",
                            StringComparison.OrdinalIgnoreCase) >= 0 ||
                        content.IndexOf(
                            "Genesis 2 Female",
                            StringComparison.OrdinalIgnoreCase) >= 0;

                    bool hasMaleGeometry =
                        content.IndexOf(
                            "MVR_G2Male",
                            StringComparison.OrdinalIgnoreCase) >= 0 ||
                        content.IndexOf(
                            "Genesis2Male",
                            StringComparison.OrdinalIgnoreCase) >= 0 ||
                        content.IndexOf(
                            "Genesis 2 Male",
                            StringComparison.OrdinalIgnoreCase) >= 0;

                    if (hasFemaleGeometry && !hasMaleGeometry)
                        return "F";

                    if (hasMaleGeometry && !hasFemaleGeometry)
                        return "M";
                }
            }
            catch { }

            // Package/path fallback. This is important for many older Hub Looks
            // whose .vap has no reliable gender metadata but whose package UID or
            // directory is explicitly sex-specific (for example Female_Looks).
            string pathProbe =
                nameProbe
                .Replace('\\', '/')
                .ToLowerInvariant();

            if (pathProbe.Contains("female") ||
                pathProbe.Contains("g2female") ||
                pathProbe.Contains("genesis2female") ||
                pathProbe.Contains("genesis 2 female") ||
                pathProbe.Contains("/female/"))
            {
                return "F";
            }

            // Female must be excluded before testing the substring "male".
            if ((pathProbe.Contains("male") ||
                 pathProbe.Contains("g2male") ||
                 pathProbe.Contains("genesis2male") ||
                 pathProbe.Contains("genesis 2 male") ||
                 pathProbe.Contains("/male/")) &&
                !pathProbe.Contains("female"))
            {
                return "M";
            }

            return "?";
        }

        private string ClassifyHairDescriptorExplicit(string value)
        {
            if (string.IsNullOrEmpty(value))
                return "";

            string p = value.Replace('\\', '/').ToLowerInvariant();

            // Genital / pubic Hair. Include common scrotum/testicle naming because
            // many male pubic-hair presets split lower-belly and scrotal hair into
            // separate Hair components.
            string[] pubic = new string[] {
                "pubic", "public natural", "lower belly", "groin", "crotch",
                "genital", "bikini", "bush", "landing strip", "happy trail",
                "natural wedge", "natural patch", "patch with stubble",
                "short base with stubble", "scrotum", "scrotal", "testicle",
                "testes", "ball hair", "balls hair", "ball fuzz", "balls fuzz",
                "sack hair", "nuts hair"
            };
            for (int i = 0; i < pubic.Length; i++)
                if (p.Contains(pubic[i])) return "Pubic";

            // Brows/lashes are Hair items too, but they are not part of the beard
            // layer. Keep them as an independent preserved region so choosing a
            // beard never removes or replaces the character's eyebrows.
            string[] brows = new string[] {
                "eyebrow", "brows", "brow hair", "eyelash", "eyelashes", "lashes"
            };
            for (int i = 0; i < brows.Length; i++)
                if (p.Contains(brows[i])) return "Brows";

            string[] facial = new string[] {
                "beard", "moustache", "mustache", "goatee", "sideburn",
                "facial hair", "stubble beard", "chin beard"
            };
            for (int i = 0; i < facial.Length; i++)
                if (p.Contains(facial[i])) return "Facial";

            string[] body = new string[] {
                "body hair", "chest hair", "torso hair", "belly hair",
                "abdomen hair", "abdominal hair", "armpit", "underarm",
                "arm hair", "leg hair", "back hair"
            };
            for (int i = 0; i < body.Length; i++)
                if (p.Contains(body[i])) return "Body";

            return "";
        }

        private string ClassifyHairDescriptor(string value)
        {
            string explicitRegion = ClassifyHairDescriptorExplicit(value);
            return string.IsNullOrEmpty(explicitRegion) ? "Head" : explicitRegion;
        }

        private string ClassifyHairNodeExplicit(JSONNode item)
        {
            if (item == null)
                return "";

            string descriptor =
                (item["internalId"].Value == null ? "" : item["internalId"].Value) + " " +
                (item["id"].Value == null ? "" : item["id"].Value) + " " +
                (item["displayName"].Value == null ? "" : item["displayName"].Value);
            return ClassifyHairDescriptorExplicit(descriptor);
        }

        private string ClassifyHairNode(JSONNode item)
        {
            string explicitRegion = ClassifyHairNodeExplicit(item);
            return string.IsNullOrEmpty(explicitRegion) ? "Head" : explicitRegion;
        }

        private HashSet<string> GetHairPresetRegions(string path)
        {
            HashSet<string> cached;
            if (!string.IsNullOrEmpty(path) &&
                _hairPresetRegionsByPath.TryGetValue(path, out cached))
            {
                return new HashSet<string>(cached, StringComparer.OrdinalIgnoreCase);
            }

            HashSet<string> result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (string.IsNullOrEmpty(path))
            {
                result.Add("Head");
                return result;
            }

            // Explicit Body/Pubic/Facial naming is authoritative. This keeps presets
            // such as Chris Redfield Body Hair out of Head even when a component has
            // a generic internal name.
            string explicitPathRegion = ClassifyHairDescriptorExplicit(path);
            // Body/Pubic package naming is authoritative because those presets often
            // contain generic component IDs that look like Head. Facial naming is
            // not exclusive: a mixed hairstyle+beard preset should belong to both
            // HEAD and FACIAL, so keep Facial as a seed and still inspect geometry.
            if (string.Equals(explicitPathRegion, "Body", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(explicitPathRegion, "Pubic", StringComparison.OrdinalIgnoreCase))
            {
                result.Add(explicitPathRegion);
                _hairPresetRegionsByPath[path] = new HashSet<string>(result, StringComparer.OrdinalIgnoreCase);
                return result;
            }
            if (string.Equals(explicitPathRegion, "Facial", StringComparison.OrdinalIgnoreCase))
                result.Add("Facial");
            if (string.Equals(explicitPathRegion, "Brows", StringComparison.OrdinalIgnoreCase))
                result.Add("Brows");

            try
            {
                string content = FileManagerSecure.ReadAllText(path);
                if (!string.IsNullOrEmpty(content))
                {
                    JSONClass preset = ParseHairPresetContentRobust(content);
                    JSONArray storables = preset == null ? null : preset["storables"].AsArray;
                    if (storables != null)
                    {
                        for (int i = 0; i < storables.Count; i++)
                        {
                            JSONNode st = storables[i];
                            if (st == null || st["id"].Value != "geometry")
                                continue;

                            JSONArray hair = st["hair"].AsArray;
                            if (hair == null)
                                break;

                            for (int h = 0; h < hair.Count; h++)
                            {
                                JSONNode item = hair[h];
                                if (item == null || !IsHairNodeEnabled(item))
                                {
                                    continue;
                                }

                                result.Add(ClassifyHairNode(item));
                            }
                            break;
                        }
                    }
                }
            }
            catch { }

            if (result.Count == 0)
                result.Add(ClassifyHairDescriptor(path));

            _hairPresetRegionsByPath[path] =
                new HashSet<string>(result, StringComparer.OrdinalIgnoreCase);
            return result;
        }

        private bool HairPresetHasRegion(HairPresetEntry entry, string region)
        {
            if (entry == null || string.IsNullOrEmpty(region))
                return false;

            if (entry.isRawHairItem && !string.IsNullOrEmpty(entry.region))
                return string.Equals(entry.region, region, StringComparison.OrdinalIgnoreCase);

            HashSet<string> regions = GetHairPresetRegions(entry.path);
            return regions.Contains(region);
        }

        private void RememberNonHeadHairComponents(string path)
        {
            if (string.IsNullOrEmpty(path))
                return;

            string explicitPathRegion = ClassifyHairDescriptorExplicit(path);

            try
            {
                string content = FileManagerSecure.ReadAllText(path);
                if (string.IsNullOrEmpty(content))
                    return;

                JSONClass preset = ParseHairPresetContentRobust(content);
                JSONArray storables = preset == null ? null : preset["storables"].AsArray;
                if (storables == null)
                    return;

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null || st["id"].Value != "geometry")
                        continue;

                    JSONArray hair = st["hair"].AsArray;
                    if (hair == null)
                        return;

                    for (int h = 0; h < hair.Count; h++)
                    {
                        JSONNode item = hair[h];
                        if (item == null || !IsHairNodeEnabled(item))
                        {
                            continue;
                        }

                        string region = ClassifyHairNodeExplicit(item);
                        if (string.IsNullOrEmpty(region) &&
                            (string.Equals(explicitPathRegion, "Body", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(explicitPathRegion, "Pubic", StringComparison.OrdinalIgnoreCase)))
                        {
                            region = explicitPathRegion;
                        }
                        else if (string.IsNullOrEmpty(region) &&
                                 (string.Equals(explicitPathRegion, "Facial", StringComparison.OrdinalIgnoreCase) ||
                                  string.Equals(explicitPathRegion, "Brows", StringComparison.OrdinalIgnoreCase)))
                        {
                            HashSet<string> presetRegions = GetHairPresetRegions(path);
                            if (!presetRegions.Contains("Head"))
                                region = explicitPathRegion;
                        }

                        if (string.IsNullOrEmpty(region) || region == "Head")
                            continue;

                        List<string> candidates = GetHairNodeCandidateNames(item);
                        for (int c = 0; c < candidates.Count; c++)
                        {
                            string key = NormalizeHairItemKey(candidates[c]);
                            if (string.IsNullOrEmpty(key) || key.Length < 5 ||
                                key == "hair" || key == "customhair" || key == "customhairitem")
                            {
                                continue;
                            }

                            _knownNonHeadHairComponentKeys.Add(key);
                            _knownHairComponentRegionByKey[key] = region;
                        }
                    }
                    return;
                }
            }
            catch { }
        }

        private string GetKnownHairNodeRegion(JSONNode item)
        {
            if (item == null || _knownHairComponentRegionByKey.Count == 0)
                return "";

            List<string> candidates = GetHairNodeCandidateNames(item);
            for (int i = 0; i < candidates.Count; i++)
            {
                string key = NormalizeHairItemKey(candidates[i]);
                string region;
                if (!string.IsNullOrEmpty(key) &&
                    _knownHairComponentRegionByKey.TryGetValue(key, out region))
                {
                    return region;
                }
            }
            return "";
        }

        private bool IsKnownNonHeadHairNode(JSONNode item)
        {
            return !string.IsNullOrEmpty(GetKnownHairNodeRegion(item));
        }

        private string ClassifyLiveHairNodeRegion(JSONNode item)
        {
            string region = ClassifyHairNodeExplicit(item);
            if (!string.IsNullOrEmpty(region))
                return region;

            region = GetKnownHairNodeRegion(item);
            if (!string.IsNullOrEmpty(region))
                return region;

            return "Head";
        }

        private string DetectHairPresetRegion(string path)
        {
            HashSet<string> regions = GetHairPresetRegions(path);
            // Keep Head as the primary card region for mixed hairstyle+beard presets.
            // v152 can still expose the same card in the Facial layer via the region set.
            if (regions.Contains("Head")) return "Head";
            if (regions.Contains("Pubic")) return "Pubic";
            if (regions.Contains("Body")) return "Body";
            if (regions.Contains("Facial")) return "Facial";
            if (regions.Contains("Brows")) return "Brows";
            return "Head";
        }

        private bool IsHeadHairName(string displayName)
        {
            return ClassifyHairDescriptor(displayName) == "Head";
        }

        // v154: return exact display names of the currently active live-bank items
        // belonging to one editable region. Prefer runtime geometry classification;
        // fall back to the visible bank name when old Hair items expose no useful ID.
        private List<string> GetAllActiveHairNames(PersonEntry person)
        {
            List<string> result = new List<string>();
            if (person == null || person.atom == null)
                return result;

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
                return result;

            string nativeSex = GetNativeHairSex(person);
            try
            {
                if (nativeSex == "M")
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair != null && hair.active && !string.IsNullOrEmpty(hair.displayName) &&
                            !result.Contains(hair.displayName))
                        {
                            result.Add(hair.displayName);
                        }
                    }
                }
                else
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair != null && hair.active && !string.IsNullOrEmpty(hair.displayName) &&
                            !result.Contains(hair.displayName))
                        {
                            result.Add(hair.displayName);
                        }
                    }
                }
            }
            catch { }

            return result;
        }

        private string GetRuntimeHairRegionForDisplayName(PersonEntry person, string displayName)
        {
            if (person == null || string.IsNullOrEmpty(person.uid) || string.IsNullOrEmpty(displayName))
                return "";

            Dictionary<string, string> map;
            if (!_runtimeHairRegionByPersonNameKey.TryGetValue(person.uid, out map) || map == null)
                return "";

            string key = NormalizeHairItemKey(displayName);
            if (string.IsNullOrEmpty(key))
                return "";

            string region;
            return map.TryGetValue(key, out region) ? region : "";
        }

        private void SetRuntimeHairRegionAliases(
            PersonEntry person,
            string region,
            List<string> liveNames)
        {
            if (person == null || string.IsNullOrEmpty(person.uid))
                return;

            string target = NormalizeEditableHairRegion(region);
            Dictionary<string, string> map;
            if (!_runtimeHairRegionByPersonNameKey.TryGetValue(person.uid, out map) || map == null)
            {
                map = new Dictionary<string, string>(StringComparer.Ordinal);
                _runtimeHairRegionByPersonNameKey[person.uid] = map;
            }

            // This map represents the CURRENT live layer, not history. Remove the
            // previous aliases for this target before recording its new exact names.
            List<string> remove = new List<string>();
            foreach (KeyValuePair<string, string> kv in map)
            {
                if (string.Equals(kv.Value, target, StringComparison.OrdinalIgnoreCase))
                    remove.Add(kv.Key);
            }
            for (int i = 0; i < remove.Count; i++)
                map.Remove(remove[i]);

            if (liveNames == null)
                return;

            for (int i = 0; i < liveNames.Count; i++)
            {
                string key = NormalizeHairItemKey(liveNames[i]);
                if (!string.IsNullOrEmpty(key))
                    map[key] = target;
            }
        }

        private List<string> GetActiveHairNamesForRegion(PersonEntry person, string requestedRegion)
        {
            List<string> result = new List<string>();
            if (person == null || person.atom == null)
                return result;

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
                return result;

            string nativeSex = GetNativeHairSex(person);
            string target = NormalizeEditableHairRegion(requestedRegion);

            try
            {
                JSONClass geometryState = selector.GetJSON(true, true, true);
                JSONArray liveHair = geometryState == null ? null : geometryState["hair"].AsArray;

                if (nativeSex == "M")
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair == null || !hair.active || string.IsNullOrEmpty(hair.displayName))
                            continue;

                        string region = GetRuntimeHairRegionForDisplayName(person, hair.displayName);
                        if (string.IsNullOrEmpty(region) && liveHair != null)
                        {
                            for (int i = 0; i < liveHair.Count; i++)
                            {
                                JSONNode node = liveHair[i];
                                if (node == null || !IsHairNodeEnabled(node))
                                    continue;
                                if (HairDisplayNameMatchesNode(hair.displayName, node))
                                {
                                    region = ClassifyLiveHairNodeRegion(node);
                                    break;
                                }
                            }
                        }

                        if (string.IsNullOrEmpty(region))
                            region = ClassifyHairDescriptor(hair.displayName);

                        if (string.Equals(region, target, StringComparison.OrdinalIgnoreCase) &&
                            !result.Contains(hair.displayName))
                        {
                            result.Add(hair.displayName);
                        }
                    }
                }
                else
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair == null || !hair.active || string.IsNullOrEmpty(hair.displayName))
                            continue;

                        string region = GetRuntimeHairRegionForDisplayName(person, hair.displayName);
                        if (string.IsNullOrEmpty(region) && liveHair != null)
                        {
                            for (int i = 0; i < liveHair.Count; i++)
                            {
                                JSONNode node = liveHair[i];
                                if (node == null || !IsHairNodeEnabled(node))
                                    continue;
                                if (HairDisplayNameMatchesNode(hair.displayName, node))
                                {
                                    region = ClassifyLiveHairNodeRegion(node);
                                    break;
                                }
                            }
                        }

                        if (string.IsNullOrEmpty(region))
                            region = ClassifyHairDescriptor(hair.displayName);

                        if (string.Equals(region, target, StringComparison.OrdinalIgnoreCase) &&
                            !result.Contains(hair.displayName))
                        {
                            result.Add(hair.displayName);
                        }
                    }
                }
            }
            catch { }

            return result;
        }

        private List<string> GetActiveHairNamesExceptRegion(PersonEntry person, string excludedRegion)
        {
            List<string> result = new List<string>();
            if (person == null || person.atom == null)
                return result;

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
                return result;

            string nativeSex = GetNativeHairSex(person);
            string target = NormalizeEditableHairRegion(excludedRegion);
            HashSet<string> geometryMatchedLiveNames =
                new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            try
            {
                JSONClass geometryState = selector.GetJSON(true, true, true);
                JSONArray liveHair = geometryState == null ? null : geometryState["hair"].AsArray;
                if (liveHair != null)
                {
                    for (int i = 0; i < liveHair.Count; i++)
                    {
                        JSONNode node = liveHair[i];
                        if (node == null || !IsHairNodeEnabled(node))
                            continue;

                        string nodeRegion = ClassifyLiveHairNodeRegion(node);

                        if (nativeSex == "M")
                        {
                            foreach (var hair in selector.maleHairItems)
                            {
                                if (hair == null || !hair.active ||
                                    string.IsNullOrEmpty(hair.displayName) ||
                                    !HairDisplayNameMatchesNode(hair.displayName, node))
                                {
                                    continue;
                                }

                                geometryMatchedLiveNames.Add(NormalizeHairItemKey(hair.displayName));
                                string region = GetRuntimeHairRegionForDisplayName(person, hair.displayName);
                                if (string.IsNullOrEmpty(region)) region = nodeRegion;
                                if (!string.Equals(region, target, StringComparison.OrdinalIgnoreCase) &&
                                    !result.Contains(hair.displayName))
                                {
                                    result.Add(hair.displayName);
                                }
                                break;
                            }
                        }
                        else
                        {
                            foreach (var hair in selector.femaleHairItems)
                            {
                                if (hair == null || !hair.active ||
                                    string.IsNullOrEmpty(hair.displayName) ||
                                    !HairDisplayNameMatchesNode(hair.displayName, node))
                                {
                                    continue;
                                }

                                geometryMatchedLiveNames.Add(NormalizeHairItemKey(hair.displayName));
                                string region = GetRuntimeHairRegionForDisplayName(person, hair.displayName);
                                if (string.IsNullOrEmpty(region)) region = nodeRegion;
                                if (!string.Equals(region, target, StringComparison.OrdinalIgnoreCase) &&
                                    !result.Contains(hair.displayName))
                                {
                                    result.Add(hair.displayName);
                                }
                                break;
                            }
                        }
                    }
                }

                // Fallback only for active items that could not be associated with
                // any geometry.hair node. Do not re-classify a geometry-matched target
                // item by its shorter live-bank displayName: Calvin's
                // "Natural Balls Extra Density" is the confirmed example where that
                // would incorrectly preserve the old INTIMATE item during replacement.
                if (nativeSex == "M")
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair == null || !hair.active || string.IsNullOrEmpty(hair.displayName))
                            continue;
                        string liveKey = NormalizeHairItemKey(hair.displayName);
                        if (geometryMatchedLiveNames.Contains(liveKey))
                            continue;
                        string region = GetRuntimeHairRegionForDisplayName(person, hair.displayName);
                        if (string.IsNullOrEmpty(region))
                            region = ClassifyHairDescriptor(hair.displayName);
                        if (!string.Equals(region, target, StringComparison.OrdinalIgnoreCase) &&
                            !result.Contains(hair.displayName))
                        {
                            result.Add(hair.displayName);
                        }
                    }
                }
                else
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair == null || !hair.active || string.IsNullOrEmpty(hair.displayName))
                            continue;
                        string liveKey = NormalizeHairItemKey(hair.displayName);
                        if (geometryMatchedLiveNames.Contains(liveKey))
                            continue;
                        string region = GetRuntimeHairRegionForDisplayName(person, hair.displayName);
                        if (string.IsNullOrEmpty(region))
                            region = ClassifyHairDescriptor(hair.displayName);
                        if (!string.Equals(region, target, StringComparison.OrdinalIgnoreCase) &&
                            !result.Contains(hair.displayName))
                        {
                            result.Add(hair.displayName);
                        }
                    }
                }
            }
            catch { }

            return result;
        }

        private List<string> GetActiveNonHeadHairNames(PersonEntry person)
        {
            return GetActiveHairNamesExceptRegion(person, "Head");
        }

        private void ReEnableNonHeadHairItems(PersonEntry person, List<string> names)
        {
            if (person == null || names == null || names.Count == 0)
                return;

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
                return;

            HashSet<string> wanted = new HashSet<string>(StringComparer.Ordinal);
            for (int i = 0; i < names.Count; i++)
                wanted.Add(NormalizeHairItemKey(names[i]));

            string nativeSex = GetNativeHairSex(person);
            try
            {
                if (nativeSex == "M")
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair != null && wanted.Contains(NormalizeHairItemKey(hair.displayName)))
                            selector.SetActiveHairItem(hair, true);
                    }
                }
                else
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair != null && wanted.Contains(NormalizeHairItemKey(hair.displayName)))
                            selector.SetActiveHairItem(hair, true);
                    }
                }
            }
            catch { }
        }

        private string HairDiagField(JSONNode node, string key)
        {
            if (node == null)
                return "";
            try
            {
                string value = node[key].Value;
                return value == null ? "" : value.Replace("\r", " ").Replace("\n", " ");
            }
            catch { }
            return "";
        }

        private string HairDiagJoin(List<string> values)
        {
            if (values == null || values.Count == 0)
                return "<none>";
            return string.Join(" | ", values.ToArray());
        }

        private void LogHairDiagnostic(PersonEntry person, string stage)
        {
            if (person == null || person.atom == null)
            {
                SuperController.LogMessage(
                    "CharacterRouter v150 HAIR DIAG | stage=" + stage + " | no Person"
                );
                return;
            }

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
            {
                SuperController.LogMessage(
                    "CharacterRouter v150 HAIR DIAG | stage=" + stage +
                    " | uid=" + person.uid + " | selector=null"
                );
                return;
            }

            string nativeSex = GetNativeHairSex(person);
            SuperController.LogMessage(
                "CharacterRouter v150 HAIR DIAG BEGIN | stage=" + stage +
                " | uid=" + person.uid + " | nativeSex=" + nativeSex
            );

            try
            {
                JSONClass geometryState = selector.GetJSON(true, true, true);
                JSONArray liveHair = geometryState == null ? null : geometryState["hair"].AsArray;
                if (liveHair == null)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v150 HAIR DIAG GEOMETRY | stage=" + stage + " | <no hair array>"
                    );
                }
                else
                {
                    for (int i = 0; i < liveHair.Count; i++)
                    {
                        JSONNode node = liveHair[i];
                        if (node == null)
                            continue;

                        string enabled = HairDiagField(node, "enabled");
                        string internalId = HairDiagField(node, "internalId");
                        string id = HairDiagField(node, "id");
                        string displayName = HairDiagField(node, "displayName");
                        string explicitRegion = ClassifyHairNodeExplicit(node);
                        bool knownNonHead = IsKnownNonHeadHairNode(node);
                        List<string> candidates = GetHairNodeCandidateNames(node);

                        SuperController.LogMessage(
                            "CharacterRouter v150 HAIR DIAG GEOMETRY | stage=" + stage +
                            " | index=" + i +
                            " | enabled=" + enabled +
                            " | explicitRegion=" + (string.IsNullOrEmpty(explicitRegion) ? "<none>" : explicitRegion) +
                            " | knownNonHead=" + knownNonHead +
                            " | internalId=" + internalId +
                            " | id=" + id +
                            " | displayName=" + displayName +
                            " | candidates=" + HairDiagJoin(candidates)
                        );
                    }
                }
            }
            catch (Exception e)
            {
                SuperController.LogMessage(
                    "CharacterRouter v150 HAIR DIAG GEOMETRY ERROR | stage=" + stage + " | " + e.Message
                );
            }

            try
            {
                if (nativeSex == "M")
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair == null || !hair.active)
                            continue;
                        SuperController.LogMessage(
                            "CharacterRouter v150 HAIR DIAG BANK | stage=" + stage +
                            " | active=" + hair.active +
                            " | instance=" + hair.GetInstanceID() +
                            " | displayName=" + (hair.displayName ?? "") +
                            " | explicitRegion=" + ClassifyHairDescriptorExplicit(hair.displayName)
                        );
                    }
                }
                else
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair == null || !hair.active)
                            continue;
                        SuperController.LogMessage(
                            "CharacterRouter v150 HAIR DIAG BANK | stage=" + stage +
                            " | active=" + hair.active +
                            " | instance=" + hair.GetInstanceID() +
                            " | displayName=" + (hair.displayName ?? "") +
                            " | explicitRegion=" + ClassifyHairDescriptorExplicit(hair.displayName)
                        );
                    }
                }
            }
            catch (Exception e)
            {
                SuperController.LogMessage(
                    "CharacterRouter v150 HAIR DIAG BANK ERROR | stage=" + stage + " | " + e.Message
                );
            }

            try
            {
                List<string> detectedNonHead = GetActiveNonHeadHairNames(person);
                SuperController.LogMessage(
                    "CharacterRouter v150 HAIR DIAG DETECTED NONHEAD | stage=" + stage +
                    " | " + HairDiagJoin(detectedNonHead)
                );
            }
            catch (Exception e)
            {
                SuperController.LogMessage(
                    "CharacterRouter v150 HAIR DIAG NONHEAD ERROR | stage=" + stage + " | " + e.Message
                );
            }

            SuperController.LogMessage(
                "CharacterRouter v150 HAIR DIAG END | stage=" + stage + " | uid=" + person.uid
            );
        }

        // v159: scene Hair must be classified from the scene node itself, not from
        // the global learned component map. A component can legitimately appear in
        // different saved presets/contexts; using contextual learned aliases here can
        // manufacture false BODY/INTIMATE cards (Chris Redfield head hair was the
        // confirmed case). Scene extraction therefore trusts only explicit node/path
        // descriptors and treats otherwise-unclassified items as Head.
        private string ClassifySceneHairNodeRegion(JSONNode item)
        {
            string region = ClassifyHairNodeExplicit(item);
            return string.IsNullOrEmpty(region) ? "Head" : region;
        }

        private JSONClass BuildSceneHairRegionOnlyPresetJson(JSONClass preset, string region)
        {
            if (preset == null)
                return null;

            string targetRegion = NormalizeEditableHairRegion(region);

            try
            {
                JSONClass result = CloneJsonClass(preset);
                if (result == null)
                    return null;

                JSONArray storables = result["storables"].AsArray;
                if (storables == null)
                    return result;

                HashSet<string> prefixes = new HashSet<string>(StringComparer.Ordinal);
                JSONArray filteredStorables = new JSONArray();

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null || st["id"].Value != "geometry")
                        continue;

                    JSONClass geometry = CloneJsonClass(st.AsObject);
                    if (geometry == null) continue;
                    JSONArray hair = st["hair"].AsArray;
                    JSONArray kept = new JSONArray();
                    if (hair != null)
                    {
                        for (int h = 0; h < hair.Count; h++)
                        {
                            JSONNode item = hair[h];
                            if (item == null || !IsHairNodeEnabled(item) ||
                                !string.Equals(
                                    ClassifySceneHairNodeRegion(item),
                                    targetRegion,
                                    StringComparison.OrdinalIgnoreCase))
                            {
                                continue;
                            }

                            JSONNode copy = JSON.Parse(item.ToString());
                            if (copy != null) kept.Add(copy);
                            string internalId = item["internalId"].Value;
                            if (!string.IsNullOrEmpty(internalId))
                                prefixes.Add(internalId);
                        }
                    }
                    geometry["hair"] = kept;
                    filteredStorables.Add(geometry);
                    break;
                }

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null) continue;
                    string id = st["id"].Value;
                    if (id == "geometry") continue;
                    bool keep = false;
                    foreach (string prefix in prefixes)
                    {
                        if (!string.IsNullOrEmpty(id) &&
                            id.StartsWith(prefix, StringComparison.Ordinal))
                        {
                            keep = true;
                            break;
                        }
                    }
                    if (keep)
                    {
                        JSONNode copy = JSON.Parse(st.ToString());
                        if (copy != null) filteredStorables.Add(copy);
                    }
                }

                result["storables"] = filteredStorables;
                return result;
            }
            catch { }

            return CloneJsonClass(preset);
        }


        // v175: a few valid Hair presets (NoStage3 Green Red is a confirmed
        // example) omit geometry.hair.internalId even though the owning .vam and
        // all Sim/Material storables use the normal Creator:Item prefix. Recover
        // that prefix cheaply from the exact .vam metadata when possible. This is
        // deliberately per-node and never scans AddonPackages recursively.
        private string GetEffectiveHairInternalId(JSONNode item)
        {
            if (item == null)
                return "";

            string internalId = item["internalId"].Value;
            if (!string.IsNullOrEmpty(internalId))
                return internalId.Trim();

            string id = item["id"].Value;
            if (string.IsNullOrEmpty(id))
                return "";

            try
            {
                string loadPath = id;
                try
                {
                    string normalized = FileManagerSecure.NormalizeLoadPath(id);
                    if (!string.IsNullOrEmpty(normalized))
                        loadPath = normalized;
                }
                catch { }

                string content = FileManagerSecure.ReadAllText(loadPath);
                if (!string.IsNullOrEmpty(content))
                {
                    JSONNode root = JSON.Parse(content);
                    if (root != null)
                    {
                        string uid = root["uid"].Value;
                        if (!string.IsNullOrEmpty(uid) && uid.IndexOf(':') > 0)
                            return uid.Trim();

                        string metaId = root["internalId"].Value;
                        if (!string.IsNullOrEmpty(metaId) && metaId.IndexOf(':') > 0)
                            return metaId.Trim();
                    }
                }
            }
            catch { }

            try
            {
                string path = id.Replace('\\', '/');
                if (!path.EndsWith(".vam", StringComparison.OrdinalIgnoreCase))
                    return "";

                int custom = path.IndexOf("/Custom/Hair/", StringComparison.OrdinalIgnoreCase);
                string tail;
                if (custom >= 0)
                    tail = path.Substring(custom + "/Custom/Hair/".Length);
                else if (path.StartsWith("Custom/Hair/", StringComparison.OrdinalIgnoreCase))
                    tail = path.Substring("Custom/Hair/".Length);
                else
                    return "";

                string[] parts = tail.Split('/');
                if (parts.Length < 3)
                    return "";

                int creatorIndex = 0;
                if (string.Equals(parts[0], "Female", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(parts[0], "Male", StringComparison.OrdinalIgnoreCase))
                {
                    creatorIndex = 1;
                }

                if (creatorIndex >= parts.Length - 1)
                    return "";

                string creator = parts[creatorIndex];
                string file = parts[parts.Length - 1];
                if (file.EndsWith(".vam", StringComparison.OrdinalIgnoreCase))
                    file = file.Substring(0, file.Length - 4);

                if (!string.IsNullOrEmpty(creator) && !string.IsNullOrEmpty(file))
                    return creator + ":" + file;
            }
            catch { }

            return "";
        }

        private bool IsHairFrameworkPlaceholderNode(JSONNode item)
        {
            if (item == null || !string.IsNullOrEmpty(item["internalId"].Value))
                return false;

            string id = item["id"].Value;
            if (string.IsNullOrEmpty(id))
                return false;

            string key = NormalizeHairItemKey(id);
            return key == "haircreator" || key == "simv2hair";
        }


        // v177: some old Hair Presets use the framework placeholder "Hair Creator"
        // in geometry.hair while the actual custom Hair item is represented by a
        // <Creator:Item>Creator storable plus matching Sim/ItemControl state.
        // PartyGirl PurplePink is the confirmed example. Recover only prefixes with
        // both Sim and ItemControl evidence, so unrelated creator/plugin storables are
        // never invented as Hair geometry.
        private JSONClass RecoverHairCreatorPlaceholderGeometry(JSONClass preset)
        {
            if (preset == null) return preset;
            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null) return preset;

                JSONClass geometry = null;
                JSONArray hair = null;
                bool hasCreatorPlaceholder = false;
                HashSet<string> existing = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                HashSet<string> storableIds = new HashSet<string>(StringComparer.Ordinal);

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null) continue;
                    string sid = st["id"].Value;
                    if (!string.IsNullOrEmpty(sid)) storableIds.Add(sid);
                    if (sid == "geometry")
                    {
                        geometry = st.AsObject;
                        hair = st["hair"].AsArray;
                    }
                }

                if (geometry == null || hair == null) return preset;

                for (int h = 0; h < hair.Count; h++)
                {
                    JSONNode item = hair[h];
                    if (item == null) continue;
                    if (IsHairFrameworkPlaceholderNode(item) &&
                        string.Equals(NormalizeHairItemKey(item["id"].Value), "haircreator", StringComparison.Ordinal))
                    {
                        hasCreatorPlaceholder = IsHairNodeEnabled(item);
                    }
                    string iid = GetEffectiveHairInternalId(item);
                    if (!string.IsNullOrEmpty(iid)) existing.Add(iid);
                }

                if (!hasCreatorPlaceholder) return preset;

                int added = 0;
                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null) continue;
                    string sid = st["id"].Value;
                    if (string.IsNullOrEmpty(sid) ||
                        !sid.EndsWith("Creator", StringComparison.OrdinalIgnoreCase) ||
                        sid.Length <= "Creator".Length)
                        continue;

                    string prefix = sid.Substring(0, sid.Length - "Creator".Length);
                    if (prefix.IndexOf(':') <= 0 || existing.Contains(prefix)) continue;
                    if (!storableIds.Contains(prefix + "Sim") ||
                        !storableIds.Contains(prefix + "ItemControl"))
                        continue;

                    JSONClass node = new JSONClass();
                    node["internalId"] = prefix;
                    node["id"] = prefix;
                    node["enabled"] = "true";
                    hair.Add(node);
                    existing.Add(prefix);
                    added++;
                }

                if (added > 0)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v183 FUTA HAIR RECOVERY | recovered " +
                        added + " Hair Creator component" + (added == 1 ? "" : "s") +
                        " from Creator/Sim/ItemControl storables."
                    );
                }
            }
            catch { }
            return preset;
        }

        private string StripLegacyHairStateSuffix(string storableId)
        {
            if (string.IsNullOrEmpty(storableId))
                return "";

            string[] suffixes = new string[] { "ItemControl", "Sim" };
            for (int i = 0; i < suffixes.Length; i++)
            {
                string suffix = suffixes[i];
                if (storableId.EndsWith(suffix, StringComparison.OrdinalIgnoreCase) &&
                    storableId.Length > suffix.Length)
                {
                    return storableId.Substring(0, storableId.Length - suffix.Length);
                }
            }
            return "";
        }

        // v175: some legacy Hair .vap files (Lumi is the confirmed example)
        // serialize only the disabled framework row "SimV2 Hair" in geometry.hair,
        // while the actual Hair item identity survives in per-item Sim/ItemControl
        // storables. Recover ONLY those explicit storable prefixes. This is a bounded
        // in-memory operation over the preset JSON; it does not scan packages.
        private JSONClass TryRecoverLegacyHairGeometryFromStorables(
            JSONClass preset,
            out string detail)
        {
            detail = "";
            if (preset == null)
                return null;

            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null)
                    return null;

                Dictionary<string, int> evidence =
                    new Dictionary<string, int>(StringComparer.Ordinal);

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null)
                        continue;

                    string id = st["id"].Value;
                    if (string.IsNullOrEmpty(id) || id == "geometry" || id == "HairPresets")
                        continue;

                    string prefix = StripLegacyHairStateSuffix(id);
                    if (string.IsNullOrEmpty(prefix) || prefix.IndexOf(':') <= 0)
                        continue;

                    int count = 0;
                    evidence.TryGetValue(prefix, out count);
                    evidence[prefix] = count + 1;
                }

                List<string> recoveredPrefixes = new List<string>();
                foreach (KeyValuePair<string, int> kv in evidence)
                {
                    // Two independent state storables (normally Sim + ItemControl)
                    // make a strong Hair-item signal and avoid inventing geometry
                    // from unrelated plugin/preset storables.
                    if (kv.Value >= 2)
                        recoveredPrefixes.Add(kv.Key);
                }

                if (recoveredPrefixes.Count == 0)
                    return null;

                JSONClass result = CloneJsonClass(preset);
                if (result == null)
                    return null;

                JSONArray resultStorables = result["storables"].AsArray;
                if (resultStorables == null)
                    return null;

                JSONClass geometry = null;
                for (int i = 0; i < resultStorables.Count; i++)
                {
                    JSONNode st = resultStorables[i];
                    if (st != null && st["id"].Value == "geometry")
                    {
                        geometry = st.AsObject;
                        break;
                    }
                }
                if (geometry == null)
                    return null;

                JSONArray hair = geometry["hair"].AsArray;
                if (hair == null)
                {
                    hair = new JSONArray();
                    geometry["hair"] = hair;
                }

                int added = 0;
                for (int i = 0; i < recoveredPrefixes.Count; i++)
                {
                    string prefix = recoveredPrefixes[i];
                    bool alreadyPresent = false;
                    for (int h = 0; h < hair.Count; h++)
                    {
                        JSONNode existing = hair[h];
                        if (existing == null)
                            continue;
                        string existingId = GetEffectiveHairInternalId(existing);
                        if (string.Equals(existingId, prefix, StringComparison.OrdinalIgnoreCase))
                        {
                            alreadyPresent = true;
                            break;
                        }
                    }
                    if (alreadyPresent)
                        continue;

                    JSONClass node = new JSONClass();
                    node["internalId"] = prefix;
                    node["id"] = prefix;
                    node["enabled"] = "true";
                    hair.Add(node);
                    added++;
                }

                if (added == 0)
                    return null;

                detail = "Recovered " + added +
                    " legacy Hair component" + (added == 1 ? "" : "s") +
                    " from preset Sim/ItemControl storables.";
                return result;
            }
            catch { }

            return null;
        }

        private bool HasEnabledRealHairNode(JSONClass preset)
        {
            if (preset == null)
                return false;
            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null)
                    return false;
                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null || st["id"].Value != "geometry")
                        continue;
                    JSONArray hair = st["hair"].AsArray;
                    if (hair == null)
                        return false;
                    for (int h = 0; h < hair.Count; h++)
                    {
                        JSONNode item = hair[h];
                        if (item != null && !IsHairFrameworkPlaceholderNode(item) &&
                            IsHairNodeEnabled(item))
                        {
                            return true;
                        }
                    }
                    break;
                }
            }
            catch { }
            return false;
        }

        private JSONClass BuildHairRegionOnlyPresetJson(JSONClass preset, string region)
        {
            if (preset == null)
                return null;

            string targetRegion = NormalizeEditableHairRegion(region);

            try
            {
                JSONClass result = CloneJsonClass(preset);
                if (result == null)
                    return null;

                JSONArray storables = result["storables"].AsArray;
                if (storables == null)
                    return result;

                HashSet<string> prefixes = new HashSet<string>(StringComparer.Ordinal);
                JSONArray filteredStorables = new JSONArray();

                // First pass: keep only geometry entries for the selected logical layer.
                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null || st["id"].Value != "geometry")
                        continue;

                    JSONClass geometry = CloneJsonClass(st.AsObject);
                    if (geometry == null) continue;
                    JSONArray hair = st["hair"].AsArray;
                    JSONArray kept = new JSONArray();
                    if (hair != null)
                    {
                        for (int h = 0; h < hair.Count; h++)
                        {
                            JSONNode item = hair[h];
                            if (item == null ||
                                IsHairFrameworkPlaceholderNode(item) ||
                                !string.Equals(ClassifyLiveHairNodeRegion(item), targetRegion, StringComparison.OrdinalIgnoreCase))
                            {
                                continue;
                            }

                            string internalId = GetEffectiveHairInternalId(item);
                            JSONNode copy = JSON.Parse(item.ToString());
                            if (copy != null)
                            {
                                if (string.IsNullOrEmpty(copy["internalId"].Value) &&
                                    !string.IsNullOrEmpty(internalId))
                                {
                                    copy["internalId"] = internalId;
                                }
                                kept.Add(copy);
                            }
                            if (!string.IsNullOrEmpty(internalId))
                                prefixes.Add(internalId);
                        }
                    }
                    geometry["hair"] = kept;
                    filteredStorables.Add(geometry);
                    break;
                }

                // Second pass: keep only per-item state belonging to that layer.
                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null) continue;
                    string id = st["id"].Value;
                    if (id == "geometry") continue;
                    bool keep = false;
                    foreach (string prefix in prefixes)
                    {
                        if (!string.IsNullOrEmpty(id) && id.StartsWith(prefix, StringComparison.Ordinal))
                        {
                            keep = true;
                            break;
                        }
                    }
                    if (keep)
                    {
                        JSONNode copy = JSON.Parse(st.ToString());
                        if (copy != null) filteredStorables.Add(copy);
                    }
                }

                result["storables"] = filteredStorables;
                return result;
            }
            catch { }
            return CloneJsonClass(preset);
        }

        private JSONClass BuildHeadOnlyHairPresetJson(JSONClass preset)
        {
            return BuildHairRegionOnlyPresetJson(preset, "Head");
        }

        private string DetectHairPresetSex(string path, string source)
        {
            string content = "";

            try
            {
                content = FileManagerSecure.ReadAllText(path);
            }
            catch { }

            string probe =
                ((content == null ? "" : content) + " " +
                 (path == null ? "" : path) + " " +
                 (source == null ? "" : source))
                .Replace('\\', '/')
                .ToLowerInvariant();

            bool hasFemale =
                probe.Contains("/custom/hair/female/") ||
                probe.Contains("/hair/female/") ||
                probe.Contains("g2female") ||
                probe.Contains("genesis2female") ||
                probe.Contains("genesis 2 female");

            bool hasMale =
                probe.Contains("/custom/hair/male/") ||
                probe.Contains("/hair/male/") ||
                probe.Contains("g2male") ||
                probe.Contains("genesis2male") ||
                probe.Contains("genesis 2 male");

            if (hasFemale && !hasMale)
                return "F";

            if (hasMale && !hasFemale)
                return "M";

            // Fallback to explicit package/path naming only when the preset itself
            // did not already identify a hair bank.
            if (!hasFemale && !hasMale)
            {
                if (probe.Contains("female") && !probe.Contains("male_only"))
                    return "F";

                if (probe.Contains("male") && !probe.Contains("female"))
                    return "M";
            }

            return "?";
        }

        private void AddHairPresetEntry(string path, string source)
        {
            if (string.IsNullOrEmpty(path))
                return;

            path = NormalizePathSlashes(path);

            // Native snapshots used only by RESET HAIR must never appear as
            // user-facing hairstyle cards.
            string lowerPath = path.ToLowerInvariant();
            if (lowerPath.Contains("characterrouter_hairreset_") ||
                IsCharacterRouterExtractedHairPath(path))
            {
                return;
            }

            for (int i = 0; i < _hairPresetEntries.Count; i++)
            {
                HairPresetEntry existing = _hairPresetEntries[i];
                if (existing == null ||
                    !string.Equals(
                        existing.path,
                        path,
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (existing.sex == "?")
                {
                    string upgraded = DetectHairPresetSex(path, source);
                    if (upgraded == "F" || upgraded == "M")
                        existing.sex = upgraded;
                }

                if (string.IsNullOrEmpty(existing.region))
                    existing.region = DetectHairPresetRegion(path);

                HashSet<string> existingRegions = GetHairPresetRegions(path);
                if (existingRegions.Contains("Facial") ||
                    existingRegions.Contains("Brows") ||
                    existingRegions.Contains("Body") ||
                    existingRegions.Contains("Pubic"))
                {
                    RememberNonHeadHairComponents(path);
                }

                if (string.IsNullOrEmpty(existing.source) ||
                    string.Equals(
                        existing.source,
                        "Local",
                        StringComparison.OrdinalIgnoreCase))
                {
                    if (!string.IsNullOrEmpty(source))
                        existing.source = source;
                }

                if (string.IsNullOrEmpty(existing.thumbnailPath))
                    existing.thumbnailPath = GetSiblingJpgPath(path);

                return;
            }

            HairPresetEntry entry = new HairPresetEntry();
            entry.path = path;
            entry.label = GetPresetLabel(path);
            entry.thumbnailPath = GetSiblingJpgPath(path);
            entry.sex = DetectHairPresetSex(path, source);
            entry.region = DetectHairPresetRegion(path);
            entry.source = source;
            HashSet<string> entryRegions = GetHairPresetRegions(path);
            if (entryRegions.Contains("Facial") ||
                entryRegions.Contains("Brows") ||
                entryRegions.Contains("Body") ||
                entryRegions.Contains("Pubic"))
            {
                RememberNonHeadHairComponents(path);
            }
            _hairPresetEntries.Add(entry);
        }

        private bool BytesContainAsciiToken(byte[] bytes, string token)
        {
            if (bytes == null || bytes.Length == 0 || string.IsNullOrEmpty(token))
                return false;

            string needle = token.ToLowerInvariant();
            if (needle.Length > bytes.Length)
                return false;

            for (int i = 0; i <= bytes.Length - needle.Length; i++)
            {
                bool match = true;
                for (int j = 0; j < needle.Length; j++)
                {
                    char c = (char)bytes[i + j];
                    if (char.ToLowerInvariant(c) != needle[j])
                    {
                        match = false;
                        break;
                    }
                }
                if (match)
                    return true;
            }
            return false;
        }

        private string ExtractAltFutaScalpHints(byte[] bytes)
        {
            if (bytes == null || bytes.Length == 0)
                return "";

            HashSet<string> found = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i <= bytes.Length - 5 && found.Count < 4; i++)
            {
                if (char.ToLowerInvariant((char)bytes[i]) != 's' ||
                    char.ToLowerInvariant((char)bytes[i + 1]) != 'c' ||
                    char.ToLowerInvariant((char)bytes[i + 2]) != 'a' ||
                    char.ToLowerInvariant((char)bytes[i + 3]) != 'l' ||
                    char.ToLowerInvariant((char)bytes[i + 4]) != 'p')
                    continue;

                int left = i;
                int right = i + 5;
                while (left > 0 && i - left < 36 && bytes[left - 1] >= 32 && bytes[left - 1] <= 126)
                    left--;
                while (right < bytes.Length && right - i < 72 && bytes[right] >= 32 && bytes[right] <= 126)
                    right++;

                try
                {
                    string hint = System.Text.Encoding.ASCII.GetString(bytes, left, right - left).Trim();
                    if (!string.IsNullOrEmpty(hint))
                        found.Add(hint.Replace("|", "/"));
                }
                catch { }
            }

            return found.Count == 0 ? "<none>" : string.Join(" ; ", new List<string>(found).ToArray());
        }

        private void LogAltFutaIntimateCandidateDiagnostic(
            string vamPath,
            string displayName,
            string uid,
            bool explicitFuta,
            bool metaCustomScalp,
            bool vajExists,
            bool vajReadOk,
            bool hasSkinWrap,
            bool hasCustomScalpWrap,
            bool vabExists,
            bool vabReadOk,
            string scalpHints,
            string reason)
        {
            if (string.IsNullOrEmpty(vamPath) ||
                !_altFutaIntimateCandidateDiagLogged.Add(vamPath))
                return;

            // v210: legacy per-candidate AltFuta scan logging suppressed.
        }

        private int GetAltFutaIntimateCompatibilityLevel(
            string vamPath,
            out string displayName)
        {
            displayName = "";
            if (string.IsNullOrEmpty(vamPath))
                return 0;

            try
            {
                string metaText = FileManagerSecure.ReadAllText(vamPath);
                if (string.IsNullOrEmpty(metaText))
                    return 0;

                JSONNode meta = JSON.Parse(metaText);
                if (meta == null)
                    return 0;

                string itemType = meta["itemType"].Value;
                if (!string.Equals(itemType, "HairFemale", StringComparison.OrdinalIgnoreCase))
                    return 0;

                string uid = meta["uid"].Value;
                displayName = meta["displayName"].Value;
                string creator = meta["creatorName"].Value;
                string tags = meta["tags"].Value;

                string probe = (
                    vamPath + " " + uid + " " + displayName + " " +
                    creator + " " + tags
                ).ToLowerInvariant();

                bool intimate =
                    probe.Contains("pubic") ||
                    probe.Contains("pubes") ||
                    probe.Contains("genital") ||
                    probe.Contains("intimate") ||
                    probe.Contains("mons pubis") ||
                    probe.Contains("mons_pubic");
                if (!intimate)
                    return 0;

                _altFutaIntimateDiagSeen++;

                string semanticProbe = (
                    vamPath + " " + uid + " " + displayName + " " + tags
                ).ToLowerInvariant();
                bool explicitAltFuta =
                    semanticProbe.Contains("altfuta") ||
                    semanticProbe.Contains("alt futa") ||
                    semanticProbe.Contains("alt_futa");
                bool explicitFuta = explicitAltFuta || semanticProbe.Contains("futa");
                bool metaCustomScalp =
                    semanticProbe.Contains("custom scalp") ||
                    semanticProbe.Contains("customscalp") ||
                    semanticProbe.Contains("skin wrap") ||
                    semanticProbe.Contains("skinwrap");

                string basePath = vamPath.EndsWith(".vam", StringComparison.OrdinalIgnoreCase)
                    ? vamPath.Substring(0, vamPath.Length - 4)
                    : vamPath;
                string vajPath = basePath + ".vaj";
                string vabPath = basePath + ".vab";

                bool vajExists = false;
                bool vajReadOk = false;
                bool hasSkinWrap = false;
                bool hasCustomScalpWrap = false;
                try { vajExists = FileManagerSecure.FileExists(vajPath); } catch { }
                try
                {
                    // v190 diagnostic: do not trust FileExists alone for package sibling
                    // files. Read directly as well, because VAR virtual paths can be
                    // readable even when an existence probe is inconsistent.
                    string vajText = FileManagerSecure.ReadAllText(vajPath);
                    if (!string.IsNullOrEmpty(vajText))
                    {
                        vajReadOk = true;
                        JSONNode vaj = JSON.Parse(vajText);
                        if (vaj != null)
                        {
                            JSONArray components = vaj["components"].AsArray;
                            if (components != null)
                            {
                                for (int i = 0; i < components.Count; i++)
                                {
                                    JSONNode component = components[i];
                                    if (component != null &&
                                        string.Equals(component["type"].Value, "DAZSkinWrap", StringComparison.OrdinalIgnoreCase))
                                    {
                                        hasSkinWrap = true;
                                        break;
                                    }
                                }
                            }

                            JSONArray storables = vaj["storables"].AsArray;
                            if (storables != null)
                            {
                                for (int i = 0; i < storables.Count; i++)
                                {
                                    JSONNode st = storables[i];
                                    string sid = st == null ? "" : st["id"].Value;
                                    if (!string.IsNullOrEmpty(sid) &&
                                        sid.EndsWith("CustomScalpWrapControl", StringComparison.OrdinalIgnoreCase))
                                    {
                                        hasCustomScalpWrap = true;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
                catch { }

                bool vabExists = false;
                bool vabReadOk = false;
                bool femalePubicAltScalp = false;
                string scalpHints = "<none>";
                try { vabExists = FileManagerSecure.FileExists(vabPath); } catch { }
                try
                {
                    byte[] bytes = FileManagerSecure.ReadAllBytes(vabPath);
                    if (bytes != null && bytes.Length > 0)
                    {
                        vabReadOk = true;
                        femalePubicAltScalp =
                            BytesContainAsciiToken(bytes, "scalp_F_pubic") ||
                            BytesContainAsciiToken(bytes, "scalp_f_pubic");
                        scalpHints = ExtractAltFutaScalpHints(bytes);
                    }
                }
                catch { }

                // v190: only an explicit AltFuta authoring signal is strong enough
                // for the default catalog. Diagnostics from v189 proved that the
                // female-pubic scalp/custom-wrap signatures are also used by many
                // ordinary Female pubic hairs, so geometry structure alone cannot
                // distinguish AltFuta-safe assets from generic Female intimate hair.
                // Plain "Futa" naming is also insufficient (e.g. PantyRegionScalp).
                if (explicitAltFuta)
                {
                    _altFutaIntimateDiagAccepted++;
                    return 3;
                }

                // Keep every other intimate HairFemale discoverable through
                // INCOMPATIBLE, but never promote it to the normal AltFuta catalog
                // merely because it has DAZSkinWrap/CustomScalpWrap or scalp_F_pubic.
                if (explicitFuta || metaCustomScalp || hasSkinWrap || hasCustomScalpWrap || femalePubicAltScalp)
                {
                    string reason;
                    if (explicitFuta)
                        reason = "futa-label-not-proof-of-altfuta";
                    else if (femalePubicAltScalp)
                        reason = "female-pubic-scalp-not-proof-of-altfuta";
                    else if (metaCustomScalp && !vajReadOk)
                        reason = "metadata-custom-scalp-but-vaj-unreadable";
                    else
                        reason = "generic-female-custom-scalp";

                    LogAltFutaIntimateCandidateDiagnostic(
                        vamPath, displayName, uid, explicitFuta, metaCustomScalp,
                        vajExists, vajReadOk, hasSkinWrap, hasCustomScalpWrap,
                        vabExists, vabReadOk, scalpHints, reason
                    );
                }

                return 0;
            }
            catch (Exception ex)
            {
                if (_altFutaIntimateCandidateDiagLogged.Add("ERR|" + vamPath))
                {
                    SuperController.LogMessage(
                        "CharacterRouter v190 ALTFUTA INTIMATE CANDIDATE ERROR | path=" +
                        vamPath + " | " + ex.Message
                    );
                }
                return 0;
            }
        }

