        private JSONClass DiagnosticVector3(Vector3 value)
        {
            JSONClass result = new JSONClass();
            result["x"] = DiagnosticFloat(value.x);
            result["y"] = DiagnosticFloat(value.y);
            result["z"] = DiagnosticFloat(value.z);
            return result;
        }

        private IEnumerator ExportAltFutaBodyMeshDiagnostic(PersonEntry person)
        {
            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null || selector.selectedCharacter == null || selector.selectedCharacter.skin == null)
            {
                string msg = "Could not find selectedCharacter.skin on the selected AltFuta Person.";
                UpdateHairHudStatus("HAIR — GPU body mesh export failed");
                SuperController.LogError("CharacterRouter v229 ALTFUTA BODY GPU EXPORT ERROR | " + msg);
                yield break;
            }

            DAZSkinV2 skin = selector.selectedCharacter.skin;
            if (skin.dazMesh == null || skin.dazMesh.baseVertices == null ||
                skin.rawSkinnedVerts == null || skin.rawVertsBuffer == null)
            {
                string msg = "DAZSkinV2 baseVertices/rawSkinnedVerts/rawVertsBuffer are not available.";
                UpdateHairHudStatus("HAIR — GPU body mesh export failed");
                SuperController.LogError("CharacterRouter v229 ALTFUTA BODY GPU EXPORT ERROR | " + msg);
                yield break;
            }

            // v225: rawSkinnedVerts is a CPU-side cache and, with GPU skinning, can contain
            // a mixture of current and stale coordinates. Read the live raw skin buffer once
            // directly from the GPU instead. This is a one-shot diagnostic, so the synchronous
            // GetData stall is acceptable and avoids System.Reflection entirely.
            yield return new WaitForEndOfFrame();

            Vector3[] baseVertices = skin.dazMesh.baseVertices;
            Vector3[] cachedVertices = skin.rawSkinnedVerts;
            Vector3[] gpuVertices = null;
            bool success = false;
            string error = "";
            int exported = 0;
            int mismatchCount = 0;
            float mismatchMax = 0f;

            try
            {
                int gpuCount = skin.rawVertsBuffer.count;
                if (gpuCount <= 0)
                    throw new Exception("rawVertsBuffer.count is zero.");

                gpuVertices = new Vector3[gpuCount];
                skin.rawVertsBuffer.GetData(gpuVertices);

                JSONClass root = new JSONClass();
                root["characterRouterVersion"] = "219";
                root["personUid"] = person != null ? (person.uid ?? "") : "";
                root["selectorGender"] = selector.gender.ToString();
                root["requestedVertexCount"] = AltFutaDiagnosticBodyVertexIndices.Length.ToString();
                root["baseVertexCount"] = baseVertices.Length.ToString();
                root["cachedRawSkinnedVertexCount"] = cachedVertices.Length.ToString();
                root["gpuRawVertexCount"] = gpuVertices.Length.ToString();
                root["skinLocalPosition"] = DiagnosticVector3(skin.transform.localPosition);
                root["skinLocalScale"] = DiagnosticVector3(skin.transform.localScale);

                JSONArray vertices = new JSONArray();
                for (int i = 0; i < AltFutaDiagnosticBodyVertexIndices.Length; i++)
                {
                    int index = AltFutaDiagnosticBodyVertexIndices[i];
                    if (index < 0 || index >= baseVertices.Length ||
                        index >= cachedVertices.Length || index >= gpuVertices.Length)
                        continue;

                    Vector3 cached = cachedVertices[index];
                    Vector3 gpu = gpuVertices[index];
                    float cacheDelta = (cached - gpu).magnitude;
                    if (cacheDelta > 0.00001f)
                    {
                        mismatchCount++;
                        if (cacheDelta > mismatchMax)
                            mismatchMax = cacheDelta;
                    }

                    JSONClass node = new JSONClass();
                    node["i"] = index.ToString();
                    node["base"] = DiagnosticVector3(baseVertices[index]);
                    node["cachedRawLocal"] = DiagnosticVector3(cached);
                    node["gpuRawLocal"] = DiagnosticVector3(gpu);
                    node["gpuRawWorld"] = DiagnosticVector3(skin.transform.TransformPoint(gpu));
                    node["cachedVsGpuDistance"] = DiagnosticFloat(cacheDelta);
                    vertices.Add(node);
                    exported++;
                }
                root["cachedVsGpuMismatchCount"] = mismatchCount.ToString();
                root["cachedVsGpuMismatchMax"] = DiagnosticFloat(mismatchMax);
                root["vertices"] = vertices;

                FileManagerSecure.CreateDirectory(AltFutaBodyMeshDiagnosticOutputDirectory);
                SaveJSON(root, AltFutaBodyMeshDiagnosticOutputPath);
                string verify = FileManagerSecure.ReadAllText(AltFutaBodyMeshDiagnosticOutputPath);
                if (string.IsNullOrEmpty(verify))
                    throw new Exception("Saved JSON could not be read back.");

                success = true;
            }
            catch (Exception e)
            {
                error = e.Message;
            }

            if (success)
            {
                UpdateHairHudStatus("HAIR — exported AltFuta GPU body mesh JSON");
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA BODY GPU EXPORT | success=True" +
                    " | requested=898 | exported=" + exported +
                    " | baseVertexCount=" + baseVertices.Length +
                    " | cachedRawVertexCount=" + cachedVertices.Length +
                    " | gpuRawVertexCount=" + (gpuVertices != null ? gpuVertices.Length : 0) +
                    " | cachedVsGpuMismatchCount=" + mismatchCount +
                    " | cachedVsGpuMismatchMax=" + DiagnosticFloat(mismatchMax) +
                    " | path=" + AltFutaBodyMeshDiagnosticOutputPath
                );
            }
            else
            {
                UpdateHairHudStatus("HAIR — GPU body mesh export failed: " + error);
                SuperController.LogError(
                    "CharacterRouter v229 ALTFUTA BODY GPU EXPORT ERROR | " + error
                );
            }
        }

        private JSONArray DiagnosticVector3Array(Vector3[] values)
        {
            JSONArray result = new JSONArray();
            if (values == null)
                return result;

            for (int i = 0; i < values.Length; i++)
                result.Add(DiagnosticVector3(values[i]));
            return result;
        }

        private JSONClass DiagnosticTransform(Transform t)
        {
            JSONClass result = new JSONClass();
            if (t == null)
                return result;

            result["localPosition"] = DiagnosticVector3(t.localPosition);
            result["position"] = DiagnosticVector3(t.position);
            result["localEulerAngles"] = DiagnosticVector3(t.localEulerAngles);
            result["eulerAngles"] = DiagnosticVector3(t.eulerAngles);
            result["localScale"] = DiagnosticVector3(t.localScale);
            return result;
        }

        private void AddLiveScalpHairNode(
            JSONArray destination,
            Component hairComponent,
            string displayName,
            string bank,
            PersonEntry person)
        {
            if (destination == null || hairComponent == null)
                return;

            JSONClass hairNode = new JSONClass();
            hairNode["displayName"] = displayName ?? "";
            hairNode["bank"] = bank ?? "";
            hairNode["gameObjectName"] = hairComponent.gameObject != null ? hairComponent.gameObject.name : "";
            hairNode["activeInHierarchy"] = hairComponent.gameObject != null && hairComponent.gameObject.activeInHierarchy
                ? "true" : "false";
            hairNode["transform"] = DiagnosticTransform(hairComponent.transform);

            string routerRegion = GetRuntimeHairRegionForDisplayName(person, displayName);
            if (string.IsNullOrEmpty(routerRegion))
                routerRegion = ClassifyHairDescriptor(displayName);
            hairNode["routerRegion"] = routerRegion ?? "";

            Renderer[] allRenderers = null;
            try { allRenderers = hairComponent.GetComponentsInChildren<Renderer>(true); }
            catch { allRenderers = null; }
            int rendererCount = allRenderers == null ? 0 : allRenderers.Length;
            hairNode["rendererCount"] = rendererCount.ToString();
            if (allRenderers != null)
            {
                JSONArray rendererNodes = new JSONArray();
                for (int r = 0; r < allRenderers.Length; r++)
                {
                    Renderer renderer = allRenderers[r];
                    if (renderer == null)
                        continue;
                    JSONClass rn = new JSONClass();
                    rn["name"] = renderer.name ?? "";
                    rn["gameObjectName"] = renderer.gameObject != null ? renderer.gameObject.name : "";
                    rn["enabled"] = renderer.enabled ? "true" : "false";
                    rn["activeInHierarchy"] = renderer.gameObject != null && renderer.gameObject.activeInHierarchy
                        ? "true" : "false";
                    rn["boundsCenter"] = DiagnosticVector3(renderer.bounds.center);
                    rn["boundsSize"] = DiagnosticVector3(renderer.bounds.size);
                    rendererNodes.Add(rn);
                }
                hairNode["renderers"] = rendererNodes;
            }

            DAZSkinWrap[] wraps = null;
            try { wraps = hairComponent.GetComponentsInChildren<DAZSkinWrap>(true); }
            catch { wraps = null; }
            hairNode["skinWrapCount"] = (wraps == null ? 0 : wraps.Length).ToString();
            if (wraps != null)
            {
                JSONArray wrapNodes = new JSONArray();
                for (int w = 0; w < wraps.Length; w++)
                {
                    DAZSkinWrap wrap = wraps[w];
                    if (wrap == null)
                        continue;
                    JSONClass wn = new JSONClass();
                    wn["name"] = wrap.name ?? "";
                    wn["gameObjectName"] = wrap.gameObject != null ? wrap.gameObject.name : "";
                    wn["activeInHierarchy"] = wrap.gameObject != null && wrap.gameObject.activeInHierarchy
                        ? "true" : "false";
                    wn["transform"] = DiagnosticTransform(wrap.transform);
                    wrapNodes.Add(wn);
                }
                hairNode["skinWraps"] = wrapNodes;
            }

            DAZMesh[] meshes = null;
            try { meshes = hairComponent.GetComponentsInChildren<DAZMesh>(true); }
            catch { meshes = null; }
            hairNode["dazMeshCount"] = (meshes == null ? 0 : meshes.Length).ToString();
            JSONArray meshNodes = new JSONArray();
            if (meshes != null)
            {
                for (int m = 0; m < meshes.Length; m++)
                {
                    DAZMesh mesh = meshes[m];
                    if (mesh == null)
                        continue;

                    JSONClass mn = new JSONClass();
                    mn["name"] = mesh.name ?? "";
                    mn["gameObjectName"] = mesh.gameObject != null ? mesh.gameObject.name : "";
                    mn["activeInHierarchy"] = mesh.gameObject != null && mesh.gameObject.activeInHierarchy
                        ? "true" : "false";
                    mn["transform"] = DiagnosticTransform(mesh.transform);

                    try
                    {
                        Vector3[] baseVerts = mesh.baseVertices;
                        mn["baseVertexCount"] = (baseVerts == null ? 0 : baseVerts.Length).ToString();
                        if (baseVerts != null && baseVerts.Length <= 5000)
                            mn["baseVertices"] = DiagnosticVector3Array(baseVerts);
                    }
                    catch (Exception e)
                    {
                        mn["baseVerticesError"] = e.Message;
                    }

                    try
                    {
                        if (mesh.uvMappedMesh != null)
                        {
                            Vector3[] uvVerts = mesh.uvMappedMesh.vertices;
                            mn["uvMappedVertexCount"] = (uvVerts == null ? 0 : uvVerts.Length).ToString();
                            if (uvVerts != null && uvVerts.Length <= 5000)
                                mn["uvMappedVertices"] = DiagnosticVector3Array(uvVerts);
                        }
                        else
                        {
                            mn["uvMappedVertexCount"] = "0";
                        }
                    }
                    catch (Exception e)
                    {
                        mn["uvMappedVerticesError"] = e.Message;
                    }

                    try
                    {
                        MeshFilter mf = mesh.GetComponent<MeshFilter>();
                        if (mf != null && mf.sharedMesh != null)
                        {
                            Vector3[] mfVerts = mf.sharedMesh.vertices;
                            mn["meshFilterSharedVertexCount"] = (mfVerts == null ? 0 : mfVerts.Length).ToString();
                            if (mfVerts != null && mfVerts.Length <= 5000)
                                mn["meshFilterSharedVertices"] = DiagnosticVector3Array(mfVerts);
                        }
                    }
                    catch (Exception e)
                    {
                        mn["meshFilterError"] = e.Message;
                    }

                    try
                    {
                        SkinnedMeshRenderer smr = mesh.GetComponent<SkinnedMeshRenderer>();
                        if (smr != null && smr.sharedMesh != null)
                        {
                            Vector3[] sharedVerts = smr.sharedMesh.vertices;
                            mn["skinnedSharedVertexCount"] =
                                (sharedVerts == null ? 0 : sharedVerts.Length).ToString();
                            if (sharedVerts != null && sharedVerts.Length <= 5000)
                                mn["skinnedSharedVertices"] = DiagnosticVector3Array(sharedVerts);

                            Mesh baked = new Mesh();
                            try
                            {
                                smr.BakeMesh(baked);
                                Vector3[] bakedVerts = baked.vertices;
                                mn["skinnedBakedVertexCount"] =
                                    (bakedVerts == null ? 0 : bakedVerts.Length).ToString();
                                if (bakedVerts != null && bakedVerts.Length <= 5000)
                                    mn["skinnedBakedVertices"] = DiagnosticVector3Array(bakedVerts);
                            }
                            finally
                            {
                                UnityEngine.Object.Destroy(baked);
                            }
                        }
                    }
                    catch (Exception e)
                    {
                        mn["skinnedMeshRendererError"] = e.Message;
                    }

                    meshNodes.Add(mn);
                }
            }
            hairNode["meshes"] = meshNodes;
            destination.Add(hairNode);
        }

        private string DiagnosticTransformPath(Transform t, Transform stop)
        {
            if (t == null)
                return "";

            string path = t.name ?? "";
            Transform current = t.parent;
            int guard = 0;
            while (current != null && current != stop && guard < 64)
            {
                path = (current.name ?? "") + "/" + path;
                current = current.parent;
                guard++;
            }
            if (current == stop && stop != null)
                path = (stop.name ?? "") + "/" + path;
            return path;
        }

        private void AddHairBankSummary(
            JSONArray destination,
            Component hairComponent,
            string displayName,
            string bank,
            bool active,
            Transform atomRoot)
        {
            if (destination == null || hairComponent == null)
                return;

            JSONClass node = new JSONClass();
            node["displayName"] = displayName ?? "";
            node["bank"] = bank ?? "";
            node["instanceId"] = hairComponent.GetInstanceID().ToString();
            node["active"] = active ? "true" : "false";
            node["gameObjectName"] = hairComponent.gameObject != null ? hairComponent.gameObject.name : "";
            node["activeInHierarchy"] = hairComponent.gameObject != null && hairComponent.gameObject.activeInHierarchy
                ? "true" : "false";
            node["path"] = DiagnosticTransformPath(hairComponent.transform, atomRoot);

            int rendererCount = 0;
            int enabledRendererCount = 0;
            try
            {
                Renderer[] renderers = hairComponent.GetComponentsInChildren<Renderer>(true);
                rendererCount = renderers == null ? 0 : renderers.Length;
                if (renderers != null)
                {
                    for (int r = 0; r < renderers.Length; r++)
                    {
                        Renderer renderer = renderers[r];
                        if (renderer != null && renderer.enabled && renderer.gameObject.activeInHierarchy)
                            enabledRendererCount++;
                    }
                }
            }
            catch { }
            node["rendererCount"] = rendererCount.ToString();
            node["enabledRendererCount"] = enabledRendererCount.ToString();

            JSONArray meshSummary = new JSONArray();
            try
            {
                DAZMesh[] meshes = hairComponent.GetComponentsInChildren<DAZMesh>(true);
                if (meshes != null)
                {
                    for (int m = 0; m < meshes.Length; m++)
                    {
                        DAZMesh mesh = meshes[m];
                        if (mesh == null)
                            continue;
                        JSONClass mn = new JSONClass();
                        mn["name"] = mesh.name ?? "";
                        mn["path"] = DiagnosticTransformPath(mesh.transform, atomRoot);
                        mn["activeInHierarchy"] = mesh.gameObject != null && mesh.gameObject.activeInHierarchy
                            ? "true" : "false";
                        try
                        {
                            Vector3[] bv = mesh.baseVertices;
                            mn["baseVertexCount"] = (bv == null ? 0 : bv.Length).ToString();
                        }
                        catch { mn["baseVertexCount"] = "ERR"; }
                        try
                        {
                            Vector3[] uv = mesh.uvMappedMesh == null ? null : mesh.uvMappedMesh.vertices;
                            mn["uvMappedVertexCount"] = (uv == null ? 0 : uv.Length).ToString();
                        }
                        catch { mn["uvMappedVertexCount"] = "ERR"; }
                        meshSummary.Add(mn);
                    }
                }
            }
            catch { }
            node["meshes"] = meshSummary;
            destination.Add(node);
        }

        private void AddAtomDazMeshProbe(JSONClass root, PersonEntry person)
        {
            if (root == null || person == null || person.atom == null || person.atom.gameObject == null)
                return;

            JSONArray summaries = new JSONArray();
            JSONArray candidates = new JSONArray();
            int total = 0;
            int candidateCount = 0;
            Transform atomRoot = person.atom.gameObject.transform;

            try
            {
                DAZMesh[] meshes = person.atom.gameObject.GetComponentsInChildren<DAZMesh>(true);
                total = meshes == null ? 0 : meshes.Length;
                if (meshes != null)
                {
                    for (int i = 0; i < meshes.Length; i++)
                    {
                        DAZMesh mesh = meshes[i];
                        if (mesh == null)
                            continue;

                        int baseCount = 0;
                        int uvCount = 0;
                        Vector3[] baseVerts = null;
                        Vector3[] uvVerts = null;
                        try { baseVerts = mesh.baseVertices; baseCount = baseVerts == null ? 0 : baseVerts.Length; }
                        catch { }
                        try
                        {
                            uvVerts = mesh.uvMappedMesh == null ? null : mesh.uvMappedMesh.vertices;
                            uvCount = uvVerts == null ? 0 : uvVerts.Length;
                        }
                        catch { }

                        JSONClass summary = new JSONClass();
                        summary["name"] = mesh.name ?? "";
                        summary["path"] = DiagnosticTransformPath(mesh.transform, atomRoot);
                        summary["activeInHierarchy"] = mesh.gameObject != null && mesh.gameObject.activeInHierarchy
                            ? "true" : "false";
                        summary["instanceId"] = mesh.GetInstanceID().ToString();
                        summary["baseVertexCount"] = baseCount.ToString();
                        summary["uvMappedVertexCount"] = uvCount.ToString();
                        summaries.Add(summary);

                        // The generated M2AF asset uses the known scalp_F_pubic topology:
                        // 913 base vertices / 1001 UV-mapped vertices. Capture any object
                        // exposing either signature even if the owning Hair bank item is
                        // inactive or not registered as active by DAZCharacterSelector.
                        if (baseCount == 913 || uvCount == 1001)
                        {
                            candidateCount++;
                            JSONClass candidate = new JSONClass();
                            candidate["name"] = mesh.name ?? "";
                            candidate["path"] = DiagnosticTransformPath(mesh.transform, atomRoot);
                            candidate["activeInHierarchy"] = mesh.gameObject != null && mesh.gameObject.activeInHierarchy
                                ? "true" : "false";
                            candidate["instanceId"] = mesh.GetInstanceID().ToString();
                            candidate["transform"] = DiagnosticTransform(mesh.transform);
                            candidate["baseVertexCount"] = baseCount.ToString();
                            candidate["uvMappedVertexCount"] = uvCount.ToString();
                            if (baseVerts != null && baseVerts.Length <= 5000)
                                candidate["baseVertices"] = DiagnosticVector3Array(baseVerts);
                            if (uvVerts != null && uvVerts.Length <= 5000)
                                candidate["uvMappedVertices"] = DiagnosticVector3Array(uvVerts);
                            candidates.Add(candidate);
                        }
                    }
                }
            }
            catch (Exception e)
            {
                root["atomDazMeshScanError"] = e.Message;
            }

            root["atomDazMeshCount"] = total.ToString();
            root["scalpSignatureCandidateCount"] = candidateCount.ToString();
            root["atomDazMeshes"] = summaries;
            root["scalpSignatureCandidates"] = candidates;
        }

        private IEnumerator ExportAltFutaLiveScalpDiagnostic(PersonEntry person)
        {
            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
            {
                string msg = "Could not find DAZCharacterSelector on the selected AltFuta Person.";
                UpdateHairHudStatus("HAIR — M2AF bank probe failed");
                SuperController.LogError("CharacterRouter v229 ALTFUTA M2AF BANK PROBE ERROR | " + msg);
                yield break;
            }

            // v218 removes the ambiguity from v217: the diagnostic itself loads the
            // exact generated UV control asset before sampling the bank. v217 proved
            // that a manual pre-load was not represented in the exported active list
            // (only Scalp mid base + nika1 were captured), so this probe records both
            // the forced apply result and every Female/Male bank item.
            string forcedPath =
                "Gleb.CharacterRouter.229:/Custom/Hair/Female/Gleb/CharacterRouter/" +
                "AltFutaConverted/Base Extra 02 M2AF/Base Extra 02 M2AF.vam";
            bool forcedApplyOk = false;
            string forcedApplyDetail = "";
            string forcedLoadError = "";

            HairPresetEntry forcedEntry = FindHairPresetEntryByPath(forcedPath);
            if (forcedEntry == null)
            {
                forcedLoadError = "Generated UV catalog entry was not found: " + forcedPath;
            }
            else
            {
                string loadError;
                JSONClass preset = LoadHairPresetJson(forcedEntry.path, forcedEntry.source, out loadError);
                if (preset == null)
                {
                    forcedLoadError = "Could not build generated UV preset: " + loadError;
                }
                else
                {
                    yield return StartCoroutine(
                        ApplyHairPresetRegionJsonDirect(
                            person,
                            preset,
                            "F",
                            forcedEntry.label,
                            "Pubic",
                            false,
                            delegate(bool result, string msg)
                            {
                                forcedApplyOk = result;
                                forcedApplyDetail = msg;
                            }
                        )
                    );
                }
            }

            // Give the live bank and dynamic Hair objects several frames to settle.
            yield return null;
            yield return null;
            yield return null;
            yield return null;
            yield return null;
            yield return new WaitForEndOfFrame();

            bool success = false;
            string error = "";
            int activeHairCount = 0;
            int femaleBankCount = 0;
            int maleBankCount = 0;
            int fullCaptureCount = 0;
            int generatedNameMatches = 0;
            int generatedActiveMatches = 0;

            try
            {
                JSONClass root = new JSONClass();
                root["characterRouterVersion"] = "219";
                root["personUid"] = person != null ? (person.uid ?? "") : "";
                root["selectorGender"] = selector.gender.ToString();
                root["purpose"] = "Force-load generated Base Extra 02 M2AF UV control, then export full Hair banks + live geometry + 913/1001 scalp signatures.";
                root["forcedPath"] = forcedPath;
                root["forcedEntryFound"] = forcedEntry != null ? "true" : "false";
                root["forcedApplyOk"] = forcedApplyOk ? "true" : "false";
                root["forcedApplyDetail"] = forcedApplyDetail ?? "";
                root["forcedLoadError"] = forcedLoadError ?? "";

                // Capture the exact geometry.hair state that DAZCharacterSelector reports.
                try
                {
                    JSONClass liveGeometry = selector.GetJSON(true, true, true);
                    JSONArray liveHair = liveGeometry == null ? null : liveGeometry["hair"].AsArray;
                    root["selectorGeometryHairCount"] = (liveHair == null ? 0 : liveHair.Count).ToString();
                    if (liveHair != null)
                    {
                        JSONNode clone = JSON.Parse("{\"hair\":" + liveHair.ToString() + "}");
                        if (clone != null)
                            root["selectorGeometryHair"] = clone["hair"];
                    }
                }
                catch (Exception e)
                {
                    root["selectorGeometryError"] = e.Message;
                }

                JSONArray bankItems = new JSONArray();
                JSONArray fullHairs = new JSONArray();
                Transform atomRoot = person != null && person.atom != null && person.atom.gameObject != null
                    ? person.atom.gameObject.transform : null;

                try
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair == null)
                            continue;
                        femaleBankCount++;
                        if (hair.active)
                            activeHairCount++;

                        AddHairBankSummary(bankItems, hair, hair.displayName, "Female", hair.active, atomRoot);

                        string key = NormalizeHairItemKey(hair.displayName);
                        bool generatedName = key.IndexOf("baseextra02m2af", StringComparison.Ordinal) >= 0;
                        if (generatedName)
                        {
                            generatedNameMatches++;
                            if (hair.active) generatedActiveMatches++;
                        }

                        if (hair.active || generatedName)
                        {
                            AddLiveScalpHairNode(fullHairs, hair, hair.displayName, "Female", person);
                            fullCaptureCount++;
                        }
                    }
                }
                catch (Exception e)
                {
                    root["femaleHairScanError"] = e.Message;
                }

                try
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair == null)
                            continue;
                        maleBankCount++;
                        if (hair.active)
                            activeHairCount++;

                        AddHairBankSummary(bankItems, hair, hair.displayName, "Male", hair.active, atomRoot);

                        string key = NormalizeHairItemKey(hair.displayName);
                        bool generatedName = key.IndexOf("baseextra02m2af", StringComparison.Ordinal) >= 0;
                        if (generatedName)
                        {
                            generatedNameMatches++;
                            if (hair.active) generatedActiveMatches++;
                        }

                        if (hair.active || generatedName)
                        {
                            AddLiveScalpHairNode(fullHairs, hair, hair.displayName, "Male", person);
                            fullCaptureCount++;
                        }
                    }
                }
                catch (Exception e)
                {
                    root["maleHairScanError"] = e.Message;
                }

                root["activeHairCount"] = activeHairCount.ToString();
                root["femaleBankCount"] = femaleBankCount.ToString();
                root["maleBankCount"] = maleBankCount.ToString();
                root["generatedNameMatches"] = generatedNameMatches.ToString();
                root["generatedActiveMatches"] = generatedActiveMatches.ToString();
                root["fullCaptureCount"] = fullCaptureCount.ToString();
                root["hairBankItems"] = bankItems;
                root["fullHairs"] = fullHairs;

                AddAtomDazMeshProbe(root, person);

                FileManagerSecure.CreateDirectory(AltFutaLiveScalpDiagnosticOutputDirectory);
                SaveJSON(root, AltFutaLiveScalpDiagnosticOutputPath);
                string verify = FileManagerSecure.ReadAllText(AltFutaLiveScalpDiagnosticOutputPath);
                if (string.IsNullOrEmpty(verify))
                    throw new Exception("Saved JSON could not be read back.");

                success = true;
            }
            catch (Exception e)
            {
                error = e.Message;
            }

            if (success)
            {
                UpdateHairHudStatus("HAIR — exported forced M2AF bank probe JSON");
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA M2AF BANK PROBE | success=True" +
                    " | forcedApplyOk=" + forcedApplyOk +
                    " | femaleBank=" + femaleBankCount +
                    " | maleBank=" + maleBankCount +
                    " | active=" + activeHairCount +
                    " | generatedMatches=" + generatedNameMatches +
                    " | generatedActive=" + generatedActiveMatches +
                    " | fullCapture=" + fullCaptureCount +
                    " | path=" + AltFutaLiveScalpDiagnosticOutputPath
                );
            }
            else
            {
                UpdateHairHudStatus("HAIR — M2AF bank probe failed: " + error);
                SuperController.LogError(
                    "CharacterRouter v229 ALTFUTA M2AF BANK PROBE ERROR | " + error
                );
            }
        }

        private void AddAltFutaRawHairItem(
            string path,
            string source,
            int compatibilityLevel,
            string displayName)
        {
            if (string.IsNullOrEmpty(path) || compatibilityLevel <= 0)
                return;

            string normalized = NormalizePathSlashes(path);
            for (int i = 0; i < _hairPresetEntries.Count; i++)
            {
                HairPresetEntry existing = _hairPresetEntries[i];
                if (existing != null &&
                    string.Equals(existing.path, normalized, StringComparison.OrdinalIgnoreCase))
                {
                    if (compatibilityLevel > existing.altFutaIntimateCompatibility)
                        existing.altFutaIntimateCompatibility = compatibilityLevel;
                    existing.isAltFutaIntimate = true;
                    return;
                }
            }

            string vajPath = normalized.EndsWith(".vam", StringComparison.OrdinalIgnoreCase)
                ? normalized.Substring(0, normalized.Length - 4) + ".vaj"
                : normalized + ".vaj";
            try
            {
                if (!FileManagerSecure.FileExists(vajPath))
                    return;
            }
            catch { return; }

            HairPresetEntry entry = new HairPresetEntry();
            entry.path = normalized;
            entry.label = !string.IsNullOrEmpty(displayName)
                ? displayName
                : GetPresetLabel(normalized);

            string rawThumb = normalized.EndsWith(".vam", StringComparison.OrdinalIgnoreCase)
                ? normalized.Substring(0, normalized.Length - 4) + ".jpg"
                : "";
            try
            {
                entry.thumbnailPath = !string.IsNullOrEmpty(rawThumb) &&
                    FileManagerSecure.FileExists(rawThumb)
                    ? rawThumb
                    : "";
            }
            catch { entry.thumbnailPath = ""; }

            entry.sex = "F";
            entry.region = "Pubic";
            entry.source = source;
            entry.isRawHairItem = true;
            entry.isAltFutaIntimate = true;
            entry.altFutaIntimateCompatibility = compatibilityLevel;
            _hairPresetEntries.Add(entry);

            HashSet<string> regions = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            regions.Add("Pubic");
            _hairPresetRegionsByPath[normalized] = regions;
        }

        private void AddAltFutaExperimentalMaleIntimateItem(
            string sourcePath,
            string scaffoldPath,
            string label)
        {
            if (string.IsNullOrEmpty(sourcePath) || string.IsNullOrEmpty(scaffoldPath))
                return;

            sourcePath = NormalizePathSlashes(sourcePath);
            scaffoldPath = NormalizePathSlashes(scaffoldPath);

            try
            {
                if (!FileManagerSecure.FileExists(sourcePath) ||
                    !FileManagerSecure.FileExists(scaffoldPath))
                {
                    return;
                }
            }
            catch
            {
                return;
            }

            for (int i = 0; i < _hairPresetEntries.Count; i++)
            {
                HairPresetEntry existing = _hairPresetEntries[i];
                if (existing != null &&
                    existing.isExperimentalAltFutaMaleRetarget &&
                    string.Equals(existing.path, sourcePath, StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }
            }

            HairPresetEntry entry = new HairPresetEntry();
            entry.path = sourcePath;
            entry.label = string.IsNullOrEmpty(label) ? GetPresetLabel(sourcePath) : label;
            string rawThumb = sourcePath.EndsWith(".vam", StringComparison.OrdinalIgnoreCase)
                ? sourcePath.Substring(0, sourcePath.Length - 4) + ".jpg"
                : "";
            try
            {
                entry.thumbnailPath = !string.IsNullOrEmpty(rawThumb) &&
                    FileManagerSecure.FileExists(rawThumb)
                    ? rawThumb
                    : "";
            }
            catch { entry.thumbnailPath = ""; }

            int packageSeparator = sourcePath.IndexOf(":/", StringComparison.Ordinal);
            entry.source = packageSeparator > 0
                ? sourcePath.Substring(0, packageSeparator)
                : "Experimental";
            entry.sex = "F";
            entry.region = "Pubic";
            entry.isRawHairItem = true;
            entry.isAltFutaIntimate = true;
            entry.isExperimentalAltFutaMaleRetarget = true;
            entry.altFutaMaleRetargetScaffoldPath = scaffoldPath;
            entry.altFutaIntimateCompatibility = 4;
            _hairPresetEntries.Add(entry);

            HashSet<string> regions = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            regions.Add("Pubic");
            _hairPresetRegionsByPath[sourcePath] = regions;
        }

