        private void ScanAltFutaCompatibleRawHairDirectoryRecursive(
            string root,
            string source,
            int depth)
        {
            if (string.IsNullOrEmpty(root) || depth > 12)
                return;

            try
            {
                var files = FileManagerSecure.GetFiles(root, "*.vam");
                foreach (string file in files)
                {
                    if (string.IsNullOrEmpty(file))
                        continue;

                    // v194: CharacterRouter-generated converted test assets are added
                    // explicitly as presets. Do not also promote their raw .vam files.
                    string normalizedGeneratedPath = file.Replace('\\', '/');
                    if (normalizedGeneratedPath.IndexOf(
                            "/Gleb/CharacterRouter/AltFutaConverted/",
                            StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        continue;
                    }

                    string displayName;
                    int level = GetAltFutaIntimateCompatibilityLevel(file, out displayName);
                    if (level > 0)
                        AddAltFutaRawHairItem(file, source, level, displayName);
                }
            }
            catch { }

            try
            {
                var dirs = FileManagerSecure.GetDirectories(root, "*");
                foreach (string dir in dirs)
                    ScanAltFutaCompatibleRawHairDirectoryRecursive(dir, source, depth + 1);
            }
            catch { }
        }

        private void AddAltFutaCompatibleRawHairItems(string packageUid)
        {
            if (string.IsNullOrEmpty(packageUid))
                return;

            // v190: universal scanner with conservative promotion. Search every installed package,
            // but promote only explicitly AltFuta-authored HairFemale intimate assets.
            // Generic Female custom-scalp pubic assets remain INCOMPATIBLE.
            // Ordinary Male pubic assets also remain INCOMPATIBLE.
            ScanAltFutaCompatibleRawHairDirectoryRecursive(
                packageUid + ":/Custom/Hair/Female",
                packageUid,
                0
            );
        }

        private void ScanHairPresetDirectoryRecursive(
            string root,
            string source,
            int depth)
        {
            if (string.IsNullOrEmpty(root) || depth > 12)
                return;

            try
            {
                var files = FileManagerSecure.GetFiles(root, "*.vap");
                foreach (string file in files)
                    AddHairPresetEntry(file, source);
            }
            catch { }

            try
            {
                var dirs = FileManagerSecure.GetDirectories(root, "*");
                foreach (string dir in dirs)
                    ScanHairPresetDirectoryRecursive(
                        dir,
                        source,
                        depth + 1
                    );
            }
            catch { }
        }

        private void SortHairPresetEntries()
        {
            _hairPresetEntries.Sort(delegate(
                HairPresetEntry a,
                HairPresetEntry b)
            {
                if (a == null && b == null) return 0;
                if (a == null) return 1;
                if (b == null) return -1;
                if (a.isAltFutaIntimate && b.isAltFutaIntimate &&
                    a.altFutaIntimateCompatibility != b.altFutaIntimateCompatibility)
                {
                    return b.altFutaIntimateCompatibility.CompareTo(a.altFutaIntimateCompatibility);
                }
                return string.Compare(
                    a.label,
                    b.label,
                    StringComparison.OrdinalIgnoreCase
                );
            });
        }

        private void RequestHairPresetCatalogScan()
        {
            if (_hairPresetScanRunning)
                return;

            StartCoroutine(ScanHairPresetCatalogCoroutine());
        }

        private IEnumerator ScanHairPresetCatalogCoroutine()
        {
            _hairPresetScanRunning = true;
            _hairPresetCatalogScanned = false;
            _hairPresetEntries.Clear();
            _knownNonHeadHairComponentKeys.Clear();
            _knownHairComponentRegionByKey.Clear();
            _hairPresetRegionsByPath.Clear();
            _sceneHairFingerprints.Clear();
            _altFutaIntimateCandidateDiagLogged.Clear();
            _altFutaIntimateDiagSeen = 0;
            _altFutaIntimateDiagAccepted = 0;

            if (_hairPresetCatalogStatus != null)
                _hairPresetCatalogStatus.valNoCallback =
                    "Hair: scanning local presets...";

            UpdateHairHudStatus("HAIR — scanning local presets...");

            ScanHairPresetDirectoryRecursive(
                "Custom/Atom/Person/Hair",
                "Local",
                0
            );
            // v190: local/unpacked explicit/confirmed AltFuta assets are eligible too.
            ScanAltFutaCompatibleRawHairDirectoryRecursive(
                "Custom/Hair/Female",
                "Local",
                0
            );

            SortHairPresetEntries();
            RebuildHairCatalogPage();
            yield return null;

            bool scanVarHair = _scanVarHairPresets != null &&
                _scanVarHairPresets.val;
            bool scanSceneHair = _scanSceneCharacters != null &&
                _scanSceneCharacters.val;

            if (scanVarHair || scanSceneHair)
            {
                List<string> vars = new List<string>();
                CollectVarFilesRecursive("AddonPackages", vars, 0);

                for (int i = 0; i < vars.Count; i++)
                {
                    string packageUid = GetVarPackageUid(vars[i]);
                    RememberPackageModifiedTime(packageUid, vars[i]);
                    if (!string.IsNullOrEmpty(packageUid))
                    {
                        _nativeFutanariHairAdapter.RegisterInstalledPackageUid(packageUid);
                        _altFutaHairAdapter.RegisterInstalledPackageUid(packageUid);
                        if (scanVarHair)
                        {
                            ScanHairPresetDirectoryRecursive(
                                packageUid + ":/Custom/Atom/Person/Hair",
                                packageUid,
                                0
                            );
                            AddAltFutaCompatibleRawHairItems(packageUid);
                        }

                        if (scanSceneHair)
                        {
                            ScanSceneHairDirectoryRecursive(
                                packageUid + ":/Saves/scene",
                                packageUid,
                                0
                            );
                        }
                    }

                    if ((i + 1) % 20 == 0)
                    {
                        if (_hairPresetCatalogStatus != null)
                        {
                            int sceneCount = CountSceneHairEntries();
                            int savedCount = _hairPresetEntries.Count - sceneCount;
                            _hairPresetCatalogStatus.valNoCallback =
                                "Hair: scanning VARs " +
                                (i + 1) + " / " + vars.Count +
                                " | presets " + savedCount +
                                " | scene hair " + sceneCount;
                        }

                        SortHairPresetEntries();
                        RebuildHairCatalogPage();
                        yield return null;
                    }
                }
            }

            AddAltFutaExperimentalMaleIntimateItems();

            SortHairPresetEntries();
            _hairPresetCatalogScanned = true;
            _hairPresetScanRunning = false;

            if (_hairPresetCatalogStatus != null)
            {
                int finalSceneCount = CountSceneHairEntries();
                int finalSavedCount = _hairPresetEntries.Count - finalSceneCount;
                _hairPresetCatalogStatus.valNoCallback =
                    "Hair: " + _hairPresetEntries.Count +
                    " total (" + finalSavedCount + " preset(s) + " +
                    finalSceneCount + " scene layer(s))";
            }

            // v210: legacy AltFuta scan summary logging suppressed.

            RebuildHairCatalogPage();
        }

        private string GetHairTargetSex(PersonEntry person)
        {
            if (person == null)
                return "?";

            // v179: Native Futanari uses a Female Hair base for the visually
            // female regions, but INTIMATE is intentionally sourced from the
            // native Male Hair bank.  This keeps head/body styling female while
            // exposing male pubic/scrotal presets for the male genital geometry.
            // AltFuta remains Female-based here by design; its male-genital Hair
            // path is a separate adapter concern and must not be mixed into the
            // confirmed NativeFutanariHairAdapter lifecycle.
            if (IsActiveNativeFutanariPerson(person))
            {
                string activeRegion = NormalizeEditableHairRegion(_hairRegion);
                if (string.Equals(activeRegion, "Pubic", StringComparison.OrdinalIgnoreCase))
                    return "M";
                return "F";
            }

            if (IsActiveAltFutaPerson(person))
            {
                // v184: AltFuta is a native Female Person. Male pubic custom-scalp
                // assets do not wrap correctly to Female geometry (v183 diagnostics
                // showed 20000-unit renderer bounds). Use native HairFemale AltFuta
                // assets for INTIMATE instead of cross-gender Male clones.
                return "F";
            }

            DAZCharacterSelector selector =
                GetCharacterSelectorForPerson(person);

            if (selector != null)
            {
                try
                {
                    if (selector.gender ==
                        DAZCharacterSelector.Gender.Female)
                    {
                        return "F";
                    }

                    if (selector.gender ==
                        DAZCharacterSelector.Gender.Male)
                    {
                        return "M";
                    }
                }
                catch { }
            }

            if (person.sex == "F" || person.sex == "M")
                return person.sex;

            return "?";
        }

        private string GetNativeHairSex(PersonEntry person)
        {
            DAZCharacterSelector selector =
                GetCharacterSelectorForPerson(person);

            if (selector == null)
                return "?";

            try
            {
                if (selector.gender == DAZCharacterSelector.Gender.Female)
                    return "F";

                if (selector.gender == DAZCharacterSelector.Gender.Male)
                    return "M";
            }
            catch { }

            return "?";
        }

        // Adapted from Stopper.CrossGenderHair (Stopper, CC BY).
        // VaM keeps Female and Male CustomHairItem objects in separate containers.
        // A native Male-base Futa therefore cannot load a Female Hair Preset merely
        // because we show that preset in the browser. Clone the opposite-bank
        // CustomHairItems into the native bank before asking HairPresets to load.
        // The operation is idempotent: existing displayNames are not cloned twice.
        // v141: removed obsolete pre-v100 cross-gender Hair helper. The confirmed
        // v115 exact-source clone + readiness-barrier path below is the only
        // cross-gender Hair implementation retained.

        private bool ValidateHairPresetAssetFiles(
            string path,
            out string error)
        {
            error = "";

            if (string.IsNullOrEmpty(path))
                return true;

            try
            {
                string content = FileManagerSecure.ReadAllText(path);
                if (string.IsNullOrEmpty(content))
                    return true;

                JSONNode root = JSON.Parse(content);
                if (root == null)
                    return true;

                JSONArray storables = root["storables"].AsArray;
                if (storables == null)
                    return true;

                JSONArray hairArray = null;
                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode storable = storables[i];
                    if (storable != null &&
                        string.Equals(
                            storable["id"].Value,
                            "geometry",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        hairArray = storable["hair"].AsArray;
                        break;
                    }
                }

                if (hairArray == null)
                    return true;

                string sourcePrefix = "";
                int packageSeparator = path.IndexOf(":/", StringComparison.Ordinal);
                if (packageSeparator > 0)
                    sourcePrefix = path.Substring(0, packageSeparator);

                List<string> missing = new List<string>();

                for (int i = 0; i < hairArray.Count; i++)
                {
                    JSONNode hair = hairArray[i];
                    if (hair == null)
                        continue;

                    string enabled = hair["enabled"].Value;
                    if (string.Equals(
                            enabled,
                            "false",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    string id = hair["id"].Value;
                    if (string.IsNullOrEmpty(id) ||
                        id.IndexOf(":/", StringComparison.Ordinal) < 0)
                    {
                        continue;
                    }

                    string resolved = id;
                    if (id.StartsWith(
                            "SELF:/",
                            StringComparison.OrdinalIgnoreCase) &&
                        !string.IsNullOrEmpty(sourcePrefix))
                    {
                        resolved = sourcePrefix + ":/" +
                            id.Substring("SELF:/".Length);
                    }

                    bool exists = true;
                    try
                    {
                        exists = FileManagerSecure.FileExists(resolved);
                    }
                    catch { }

                    if (!exists)
                    {
                        // FileManagerSecure.FileExists can report false for VaM's
                        // symbolic package refs such as Creator.Package.latest:/.
                        // VaM's native preset loader resolves those correctly, so
                        // do not block a preset on that advisory check alone.
                        if (resolved.IndexOf(".latest:/", StringComparison.OrdinalIgnoreCase) >= 0)
                            continue;

                        missing.Add(resolved);
                        if (missing.Count >= 4)
                            break;
                    }
                }

                if (missing.Count == 0)
                    return true;

                error = "Missing hair asset" +
                    (missing.Count == 1 ? ": " : "s: ") +
                    string.Join(" | ", missing.ToArray());
                return false;
            }
            catch
            {
                // Validation is a guardrail, not a reason to block presets whose
                // JSON shape is unusual. VaM's native loader remains authoritative.
                return true;
            }
        }

        private bool IsHairPresetCompatible(
            HairPresetEntry entry,
            string targetSex)
        {
            if (entry == null)
                return false;

            if (_showIncompatibleHairPresets)
                return true;

            if (targetSex != "F" && targetSex != "M")
                return false;

            return entry.sex == targetSex;
        }

        private List<HairPresetEntry> GetFilteredHairPresetEntries()
        {
            List<HairPresetEntry> result = new List<HairPresetEntry>();
            PersonEntry person = GetSelectedPerson();
            string targetSex = GetHairTargetSex(person);
            string subsection = _subsection != null
                ? _subsection.val
                : "All";
            string targetRegion = NormalizeEditableHairRegion(_hairRegion);

            // v228: project decision — AltFuta pubic Hair is disabled entirely for now.
            // Do not expose Female, Male, scene, incompatible, or generated Pubic Hair
            // cards for an active AltFuta. HEAD/FACIAL/BODY remain unchanged.
            if (person != null && IsActiveAltFutaPerson(person) &&
                string.Equals(targetRegion, "Pubic", StringComparison.OrdinalIgnoreCase))
            {
                return result;
            }

            bool scenesView = string.Equals(
                subsection,
                "Scenes",
                StringComparison.OrdinalIgnoreCase
            );

            for (int i = 0; i < _hairPresetEntries.Count; i++)
            {
                HairPresetEntry entry = _hairPresetEntries[i];
                if (!IsHairPresetCompatible(entry, targetSex))
                    continue;

                if (!HairPresetHasRegion(entry, targetRegion))
                    continue;

                // v197: the generated M2AF HairFemale item is meaningful only on
                // an active AltFuta. Do not expose this implementation asset in
                // ordinary Male/Female INCOMPATIBLE views, where clicking it can
                // only produce a no-enabled-components error.
                if (IsV196AltFutaM2AfEntry(entry) &&
                    (person == null || !IsActiveAltFutaPerson(person)))
                {
                    continue;
                }

                // v197: the raw source control is for the native Male bank only.
                // Keep it out of Female/AltFuta incompatible views so the user
                // cannot accidentally invoke the unretargeted HairMale item there.
                if (IsV197MaleBaseExtra02SourceProbe(entry) &&
                    (person == null || IsActiveAltFutaPerson(person) || targetSex != "M"))
                {
                    continue;
                }

                if (entry.isExperimentalAltFutaMaleRetarget)
                {
                    if (person == null ||
                        !IsActiveAltFutaPerson(person) ||
                        !string.Equals(targetRegion, "Pubic", StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }
                }

                // v190: AltFuta INTIMATE defaults only to explicitly AltFuta-authored HairFemale assets.
                // v189 proved that female-pubic custom-scalp structure alone produces false positives.
                // Generic Female pubic presets and
                // Male presets remain available only with INCOMPATIBLE ON.
                if (person != null && IsActiveAltFutaPerson(person) &&
                    string.Equals(targetRegion, "Pubic", StringComparison.OrdinalIgnoreCase) &&
                    !_showIncompatibleHairPresets && !entry.isAltFutaIntimate)
                {
                    continue;
                }

                // Scene-contained Hair is an explicit import source, mirroring
                // Looks -> SCENES. Do not flood normal HEAD/FACIAL browsing with
                // every hairstyle found in every installed scene. Favorites may
                // still contain either normal or scene-derived items.
                if (scenesView)
                {
                    if (!entry.isSceneHair)
                        continue;
                }
                else if (string.Equals(
                            subsection,
                            "All",
                            StringComparison.OrdinalIgnoreCase))
                {
                    if (entry.isSceneHair)
                        continue;
                }

                if (string.Equals(
                        subsection,
                        "Favorites",
                        StringComparison.OrdinalIgnoreCase) &&
                    !_favoriteHairPresetPaths.Contains(entry.path))
                {
                    continue;
                }

                result.Add(entry);
            }

            ApplyHairCatalogFiltersAndSort(result);
            return result;
        }

        private JSONStorableString GetPresetNameParam(JSONStorable presetStorable)
        {
            if (presetStorable == null)
                return null;

            JSONStorableString value =
                presetStorable.GetStringJSONParam("presetName");

            if (value == null)
                value = presetStorable.GetStringJSONParam("PresetName");

            return value;
        }

        private JSONClass CloneJsonClass(JSONClass source)
        {
            if (source == null)
                return null;

            try
            {
                JSONNode clone = JSON.Parse(source.ToString());
                return clone == null ? null : clone.AsObject;
            }
            catch { }

            return null;
        }

        private JSONArray CloneJsonArray(JSONArray source)
        {
            if (source == null)
                return null;

            try
            {
                JSONNode clone = JSON.Parse(source.ToString());
                return clone == null ? null : clone.AsArray;
            }
            catch { }

            return null;
        }

        private string GetHairPrefixFromGeometryEntry(JSONNode hair)
        {
            if (hair == null)
                return "";

            string internalId = hair["internalId"].Value;
            if (!string.IsNullOrEmpty(internalId))
                return internalId;

            string id = hair["id"].Value;
            if (string.IsNullOrEmpty(id))
                return "";

            // Built-in hair entries do not always expose internalId. Package paths
            // are not useful as storable prefixes, but plain built-in IDs can be.
            if (id.IndexOf(":/", StringComparison.Ordinal) < 0)
                return id;

            return "";
        }

        private bool IsUsefulHairStateStorable(string id)
        {
            if (string.IsNullOrEmpty(id))
                return false;

            // Per-item PresetManagerControl storables are metadata, not hairstyle
            // appearance. On cloned cross-gender hair they are also the exact
            // storables that throw the PresetManagerControl null references seen in
            // v67. ItemDeleter/Reloader are controls rather than appearance state.
            if (id.EndsWith("Preset", StringComparison.OrdinalIgnoreCase) ||
                id.EndsWith("ItemDeleter", StringComparison.OrdinalIgnoreCase) ||
                id.EndsWith("ItemReloader", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            return true;
        }

        private bool IsCrossGenderSafeHairStateStorable(string id)
        {
            if (!IsUsefulHairStateStorable(id))
                return false;

            // Cross-gender cloned hair items can safely accept simulation/control
            // state, but Material storables often contain package-relative texture
            // paths whose PresetManager context does not survive a direct restore.
            // Skipping them is deliberate: it favors a complete, stable hairstyle
            // with the hair asset's native materials over a partial load plus a red
            // error cascade. We can add package-aware material fidelity later.
            if (id.IndexOf("Material", StringComparison.OrdinalIgnoreCase) >= 0)
                return false;

            return true;
        }

        private string GetHairResetSnapshotName(string uid)
        {
            string safe = string.IsNullOrEmpty(uid) ? "Person" : uid;
            char[] invalid = new char[] { '/', '\\', ':', '*', '?', '"', '<', '>', '|', '\t', '\r', '\n' };
            for (int i = 0; i < invalid.Length; i++)
                safe = safe.Replace(invalid[i], '_');
            return "Preset_CharacterRouter_HairReset_" + safe;
        }

        private string GetHairResetSnapshotPath(string uid)
        {
            return "Custom/Atom/Person/Hair/" +
                GetHairResetSnapshotName(uid) + ".vap";
        }

        private JSONClass BuildCurrentHairPresetJson(PersonEntry person)
        {
            if (person == null || person.atom == null)
                return null;

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
                return null;

            try
            {
                JSONClass geometryState = selector.GetJSON(true, true, true);
                if (geometryState == null)
                    return null;

                JSONArray liveHair = geometryState["hair"].AsArray;
                if (liveHair == null)
                    liveHair = new JSONArray();

                JSONClass preset = new JSONClass();
                preset["setUnlistedParamsToDefault"] = "true";

                JSONArray storables = new JSONArray();
                JSONClass geometry = new JSONClass();
                geometry["id"] = "geometry";
                geometry["hair"] = CloneJsonArray(liveHair) ?? new JSONArray();
                storables.Add(geometry);

                List<string> activePrefixes = new List<string>();
                for (int i = 0; i < liveHair.Count; i++)
                {
                    JSONNode hair = liveHair[i];
                    if (hair == null)
                        continue;

                    string enabled = hair["enabled"].Value;
                    if (!string.Equals(enabled, "true", StringComparison.OrdinalIgnoreCase))
                        continue;

                    string prefix = GetHairPrefixFromGeometryEntry(hair);
                    if (!string.IsNullOrEmpty(prefix) && !activePrefixes.Contains(prefix))
                        activePrefixes.Add(prefix);
                }

                List<string> ids = person.atom.GetStorableIDs();
                if (ids != null)
                {
                    for (int i = 0; i < ids.Count; i++)
                    {
                        string id = ids[i];
                        if (string.IsNullOrEmpty(id) || id == "geometry" || id == "HairPresets")
                            continue;

                        bool belongsToHair = false;
                        for (int pfx = 0; pfx < activePrefixes.Count; pfx++)
                        {
                            if (id.StartsWith(activePrefixes[pfx], StringComparison.Ordinal))
                            {
                                belongsToHair = true;
                                break;
                            }
                        }

                        if (!belongsToHair || !IsUsefulHairStateStorable(id))
                            continue;

                        JSONStorable storable = person.atom.GetStorableByID(id);
                        if (storable == null)
                            continue;

                        JSONClass state = storable.GetJSON(true, true, true);
                        if (state == null || state.Count == 0)
                            continue;

                        JSONClass copied = CloneJsonClass(state);
                        if (copied == null)
                            continue;

                        if (!copied.HasKey("id"))
                            copied["id"] = id;

                        storables.Add(copied);
                    }
                }

                preset["storables"] = storables;
                return preset;
            }
            catch (Exception e)
            {
                SuperController.LogError(
                    "CharacterRouter v93: could not capture Hair snapshot for " +
                    person.uid + ": " + e.Message
                );
            }

            return null;
        }

        private bool EnsureOriginalHairSnapshot(PersonEntry person, out string warning)
        {
            warning = "";

            if (person == null || person.atom == null || string.IsNullOrEmpty(person.uid))
            {
                warning = "No selected Person.";
                return false;
            }

            string existingPath;
            if (_originalHairSnapshotByPerson.TryGetValue(person.uid, out existingPath) &&
                !string.IsNullOrEmpty(existingPath))
            {
                bool exists = false;
                try { exists = FileManagerSecure.FileExists(existingPath); }
                catch { }
                if (exists)
                    return true;

                _originalHairSnapshotByPerson.Remove(person.uid);
            }

            JSONClass snapshot = BuildCurrentHairPresetJson(person);
            if (snapshot == null)
            {
                warning = "Could not capture the current hairstyle.";
                return false;
            }

            string path = GetHairResetSnapshotPath(person.uid);
            try
            {
                SaveJSON(snapshot, path);

                // Verify the file is actually readable before promising RESET.
                string probe = FileManagerSecure.ReadAllText(path);
                if (string.IsNullOrEmpty(probe))
                {
                    warning = "Hair reset snapshot was not written.";
                    return false;
                }

                _originalHairSnapshotByPerson[person.uid] = path;
                _originalHairSnapshotJsonByPerson[person.uid] = snapshot;
                SaveOriginalHairSnapshotsData();
                return true;
            }
            catch (Exception e)
            {
                warning = "Hair snapshot failed: " + e.Message;
                return false;
            }
        }

        private string DetectHairPresetSexFromJson(JSONClass preset)
        {
            if (preset == null)
                return "?";

            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null)
                    return "?";

                int female = 0;
                int male = 0;

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null || st["id"].Value != "geometry")
                        continue;

                    JSONArray hair = st["hair"].AsArray;
                    if (hair == null)
                        break;

                    for (int h = 0; h < hair.Count; h++)
                    {
                        JSONNode item = hair[h];
                        if (item == null || !IsHairNodeEnabled(item))
                            continue;

                        string id = item["id"].Value;
                        if (string.IsNullOrEmpty(id))
                            continue;

                        string lower = id.ToLowerInvariant();
                        if (lower.Contains("/hair/female/")) female++;
                        if (lower.Contains("/hair/male/")) male++;
                    }

                    break;
                }

                if (female > male && female > 0) return "F";
                if (male > female && male > 0) return "M";
            }
            catch { }

            return "?";
        }

        private HairPresetEntry FindHairPresetEntryByPath(string path)
        {
            if (string.IsNullOrEmpty(path))
                return null;

            for (int i = 0; i < _hairPresetEntries.Count; i++)
            {
                HairPresetEntry entry = _hairPresetEntries[i];
                if (entry != null && string.Equals(
                        entry.path,
                        path,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return entry;
                }
            }

            return null;
        }

        private JSONClass LoadSceneHairPresetJson(HairPresetEntry entry, out string error)
        {
            error = "";
            if (entry == null || !entry.isSceneHair)
            {
                error = "Catalog item is not scene Hair.";
                return null;
            }

            string readError;
            JSONNode root = ReadSceneJson(
                entry.scenePath,
                entry.source,
                true,
                out readError
            );
            if (root == null)
            {
                error = "Could not read source scene: " + readError;
                return null;
            }

            JSONNode person = FindScenePersonNode(root, entry.sceneAtomId);
            if (person == null)
            {
                error = "Person '" + entry.sceneAtomId + "' was not found in source scene.";
                return null;
            }

            string buildError;
            JSONClass preset = BuildHairPresetFromScenePerson(person, out buildError);
            if (preset == null)
            {
                error = "Could not extract scene Hair: " + buildError;
                return null;
            }

            // v159: a SCENES card is already region-specific. Return only that
            // region so direct application and native fallback can never import
            // Head/Facial/Body/Pubic layers belonging to the same scene Person.
            JSONClass regionPreset = BuildSceneHairRegionOnlyPresetJson(preset, entry.region);
            if (regionPreset == null || !HairPresetHasEnabledGeometryItems(regionPreset))
            {
                error = "Scene Person no longer contains an enabled " +
                    GetHairRegionDisplayName(entry.region) + " Hair layer.";
                return null;
            }

            return regionPreset;
        }

        private bool EnsureSceneHairTempPreset(
            HairPresetEntry entry,
            out string tempPath,
            out string error)
        {
            tempPath = "";
            error = "";

            if (entry == null || !entry.isSceneHair)
            {
                error = "Catalog item is not scene Hair.";
                return false;
            }

            tempPath = GetSceneHairTempPath(entry);
            try
            {
                if (FileManagerSecure.FileExists(tempPath))
                    return true;
            }
            catch { }

            JSONClass preset = LoadSceneHairPresetJson(entry, out error);
            if (preset == null)
                return false;

            try
            {
                // v157: SaveJSON does not create the parent directory. Scene Look
                // extraction already did this explicitly, but the new v156 Hair
                // extraction path forgot to do so. Without this, native fallback
                // for scene Hair fails with DirectoryNotFoundException before VaM
                // gets a chance to load the extracted preset.
                FileManagerSecure.CreateDirectory(
                    "Custom/Atom/Person/Hair/CharacterRouter_Extracted"
                );
                SaveJSON(preset, tempPath);
                string probe = FileManagerSecure.ReadAllText(tempPath);
                if (string.IsNullOrEmpty(probe))
                {
                    error = "Extracted scene Hair preset was not written.";
                    return false;
                }
                return true;
            }
            catch (Exception e)
            {
                error = e.Message;
                return false;
            }
        }

        private bool GetNativeHairLoadPath(
            HairPresetEntry entry,
            out string loadPath,
            out string error)
        {
            loadPath = entry == null ? "" : entry.path;
            error = "";

            if (entry == null)
            {
                error = "Hair catalog entry is missing.";
                return false;
            }

            if (!entry.isSceneHair)
                return true;

            return EnsureSceneHairTempPreset(entry, out loadPath, out error);
        }

        // v165: VaM .vap files are JSON-like but SimpleJSON can partially
        // parse them and silently lose geometry.hair[].enabled flags. Reparse the
        // raw hair array and splice it back into the parsed preset. This preserves
        // explicit enabled=false values in complex presets instead of activating
        // every listed component.
        private JSONArray ExtractRawGeometryHairArray(string content)
        {
            if (string.IsNullOrEmpty(content)) return null;
            try
            {
                int geometryPos = -1;
                int scan = 0;
                while (scan < content.Length)
                {
                    int idPos = content.IndexOf("\"id\"", scan, StringComparison.Ordinal);
                    if (idPos < 0) break;
                    int nextId = content.IndexOf("\"id\"", idPos + 4, StringComparison.Ordinal);
                    int g = content.IndexOf("\"geometry\"", idPos, StringComparison.Ordinal);
                    if (g >= 0 && (nextId < 0 || g < nextId)) { geometryPos = g; break; }
                    scan = idPos + 4;
                }
                if (geometryPos < 0) return null;

                int hairKey = content.IndexOf("\"hair\"", geometryPos, StringComparison.Ordinal);
                if (hairKey < 0) return null;
                int colon = content.IndexOf(':', hairKey);
                if (colon < 0) return null;
                int start = content.IndexOf('[', colon);
                if (start < 0) return null;

                bool inString = false;
                bool escaped = false;
                int depth = 0;
                int end = -1;
                for (int i = start; i < content.Length; i++)
                {
                    char c = content[i];
                    if (inString)
                    {
                        if (escaped) escaped = false;
                        else if (c == '\\') escaped = true;
                        else if (c == '"') inString = false;
                        continue;
                    }
                    if (c == '"') { inString = true; continue; }
                    if (c == '[') depth++;
                    else if (c == ']')
                    {
                        depth--;
                        if (depth == 0) { end = i; break; }
                    }
                }
                if (end < start) return null;

                string arrayText = content.Substring(start, end - start + 1);
                JSONNode parsed = JSON.Parse("{\"hair\":" + arrayText + "}");
                return parsed == null ? null : parsed["hair"].AsArray;
            }
            catch { }
            return null;
        }

        private JSONClass ParseHairPresetContentRobust(string content)
        {
            if (string.IsNullOrEmpty(content)) return null;
            JSONNode root = JSON.Parse(content);
            JSONClass preset = root == null ? null : root.AsObject;
            if (preset == null) return null;
            try
            {
                JSONArray rawHair = ExtractRawGeometryHairArray(content);
                if (rawHair != null)
                {
                    JSONArray storables = preset["storables"].AsArray;
                    if (storables != null)
                    {
                        for (int i = 0; i < storables.Count; i++)
                        {
                            JSONNode st = storables[i];
                            if (st != null && st["id"].Value == "geometry")
                            {
                                JSONClass geometry = st.AsObject;
                                if (geometry != null)
                                    geometry["hair"] = rawHair;
                                break;
                            }
                        }
                    }
                }
            }
            catch { }
            return preset;
        }

        private JSONClass BuildRawHairItemPresetJson(HairPresetEntry entry, out string error)
        {
            error = "";
            if (entry == null || !entry.isRawHairItem || string.IsNullOrEmpty(entry.path))
            {
                error = "Catalog item is not a raw Hair item.";
                return null;
            }

            try
            {
                string vamText = FileManagerSecure.ReadAllText(entry.path);
                JSONNode vamNode = string.IsNullOrEmpty(vamText) ? null : JSON.Parse(vamText);
                string uid = vamNode == null ? "" : vamNode["uid"].Value;
                if (string.IsNullOrEmpty(uid))
                {
                    error = "Raw Hair metadata has no uid.";
                    return null;
                }

                string vajPath = entry.path.EndsWith(".vam", StringComparison.OrdinalIgnoreCase)
                    ? entry.path.Substring(0, entry.path.Length - 4) + ".vaj"
                    : entry.path + ".vaj";
                string vajText = FileManagerSecure.ReadAllText(vajPath);
                JSONNode vajNode = string.IsNullOrEmpty(vajText) ? null : JSON.Parse(vajText);
                JSONArray itemStorables = vajNode == null ? null : vajNode["storables"].AsArray;

                JSONClass preset = new JSONClass();
                preset["setUnlistedParamsToDefault"] = "true";
                JSONArray storables = new JSONArray();

                JSONClass geometry = new JSONClass();
                geometry["id"] = "geometry";
                JSONArray hair = new JSONArray();
                JSONClass hairNode = new JSONClass();
                hairNode["id"] = entry.path;
                hairNode["internalId"] = uid;
                hairNode["enabled"] = "true";
                hair.Add(hairNode);
                geometry["hair"] = hair;
                storables.Add(geometry);

                if (itemStorables != null)
                {
                    for (int i = 0; i < itemStorables.Count; i++)
                    {
                        JSONNode st = itemStorables[i];
                        if (st == null)
                            continue;
                        string sid = st["id"].Value;
                        // Raw .vaj files can contain embedded PresetManager, deleter
                        // or reloader controls. Replaying those as a synthetic .vap is
                        // what produces VaM's "Not all preset parameters set" error.
                        // Keep only actual appearance/simulation/wrap state.
                        if (!IsUsefulHairStateStorable(sid))
                            continue;

                        JSONNode clone = JSON.Parse(st.ToString());
                        if (clone != null)
                            storables.Add(clone);
                    }
                }

                preset["storables"] = storables;
                return preset;
            }
            catch (Exception e)
            {
                error = e.Message;
                return null;
            }
        }

        private JSONClass LoadHairPresetJson(string path, string source, out string error)
        {
            error = "";

            HairPresetEntry sceneEntry = FindHairPresetEntryByPath(path);
            if (sceneEntry != null && sceneEntry.isSceneHair)
                return LoadSceneHairPresetJson(sceneEntry, out error);
            if (sceneEntry != null && sceneEntry.isRawHairItem)
                return BuildRawHairItemPresetJson(sceneEntry, out error);

            try
            {
                string content = FileManagerSecure.ReadAllText(path);
                if (string.IsNullOrEmpty(content))
                {
                    error = "Preset file is empty or unreadable.";
                    return null;
                }

                // Direct cross-gender restore happens outside VaM's native
                // PresetManager context, so SELF:/ must be resolved explicitly.
                if (!string.IsNullOrEmpty(source) &&
                    !string.Equals(source, "Local", StringComparison.OrdinalIgnoreCase))
                {
                    content = content.Replace("SELF:/", source + ":/");
                }

                JSONClass jc = ParseHairPresetContentRobust(content);
                if (jc == null)
                {
                    error = "Preset JSON is invalid.";
                    return null;
                }

                jc = RecoverHairCreatorPlaceholderGeometry(jc);
                return jc;
            }
            catch (Exception e)
            {
                error = e.Message;
                return null;
            }
        }

        private string NormalizeHairItemKey(string value)
        {
            if (string.IsNullOrEmpty(value))
                return "";

            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            string lower = value.ToLowerInvariant();
            for (int i = 0; i < lower.Length; i++)
            {
                char c = lower[i];
                if (char.IsLetterOrDigit(c))
                    sb.Append(c);
            }
            return sb.ToString();
        }

        private string NormalizeHairTokenBag(string value)
        {
            if (string.IsNullOrEmpty(value))
                return "";

            List<string> tokens = new List<string>();
            System.Text.StringBuilder current = new System.Text.StringBuilder();
            string lower = value.ToLowerInvariant();

            for (int i = 0; i < lower.Length; i++)
            {
                char c = lower[i];
                if (char.IsLetterOrDigit(c))
                {
                    current.Append(c);
                }
                else if (current.Length > 0)
                {
                    tokens.Add(current.ToString());
                    current.Length = 0;
                }
            }

            if (current.Length > 0)
                tokens.Add(current.ToString());

            if (tokens.Count < 2)
                return "";

            tokens.Sort(StringComparer.Ordinal);
            return string.Join("|", tokens.ToArray());
        }

        // v153: older/legacy Hair presets do not always serialize an explicit
        // geometry.hair[].enabled field. VaM still treats a listed item as active
        // unless it is explicitly disabled. Requiring the literal string "true"
        // made stock presets such as MeshedVR VaM Taric appear empty.
        private bool IsHairNodeEnabled(JSONNode item)
        {
            if (item == null)
                return false;

            string enabled = item["enabled"].Value;
            if (string.IsNullOrEmpty(enabled))
            {
                return !string.IsNullOrEmpty(item["internalId"].Value) ||
                       !string.IsNullOrEmpty(item["id"].Value);
            }

            if (string.Equals(enabled, "false", StringComparison.OrdinalIgnoreCase) || enabled == "0")
                return false;
            if (string.Equals(enabled, "true", StringComparison.OrdinalIgnoreCase) || enabled == "1")
                return true;

            return !string.IsNullOrEmpty(item["internalId"].Value) ||
                   !string.IsNullOrEmpty(item["id"].Value);
        }

        // v153: VaM can expose the same CustomHairItem without the author's final
        // one-letter variant suffix. Example: preset "MBeard B 01 b" versus live
        // bank displayName "MBeard B 01". This is only used after exact, normalized
        // and token-bag matching have failed.
        private string NormalizeHairVariantAlias(string value)
        {
            if (string.IsNullOrEmpty(value))
                return "";

            List<string> tokens = new List<string>();
            System.Text.StringBuilder current = new System.Text.StringBuilder();
            string lower = value.ToLowerInvariant();
            for (int i = 0; i < lower.Length; i++)
            {
                char c = lower[i];
                if (char.IsLetterOrDigit(c))
                    current.Append(c);
                else if (current.Length > 0)
                {
                    tokens.Add(current.ToString());
                    current.Length = 0;
                }
            }
            if (current.Length > 0)
                tokens.Add(current.ToString());

            if (tokens.Count >= 3)
            {
                string last = tokens[tokens.Count - 1];
                if (last.Length == 1 && char.IsLetter(last[0]))
                    tokens.RemoveAt(tokens.Count - 1);
            }

            return string.Join("|", tokens.ToArray());
        }

        private List<string> GetHairNodeCandidateNames(JSONNode node)
        {
            List<string> result = new List<string>();
            if (node == null)
                return result;

            string internalId = node["internalId"].Value;
            if (!string.IsNullOrEmpty(internalId))
            {
                result.Add(internalId);
                int colon = internalId.IndexOf(':');
                if (colon >= 0 && colon + 1 < internalId.Length)
                    result.Add(internalId.Substring(colon + 1));
            }

            string id = node["id"].Value;
            if (!string.IsNullOrEmpty(id))
            {
                result.Add(id);
                string slashNormalized = id.Replace('\\', '/');
                int slash = slashNormalized.LastIndexOf('/');
                string file = slash >= 0 ? slashNormalized.Substring(slash + 1) : slashNormalized;
                if (file.EndsWith(".vam", StringComparison.OrdinalIgnoreCase))
                    file = file.Substring(0, file.Length - 4);
                if (!string.IsNullOrEmpty(file))
                    result.Add(file);

                // v165: older creators sometimes expose a live displayName from a
                // source folder rather than the .vam filename. Lasseur 2BUN is a
                // confirmed example (SOFI.vam -> "2BUN Corona"). Include only the
                // nearest meaningful parent folders as conservative aliases.
                string[] parts = slashNormalized.Split('/');
                int addedParents = 0;
                for (int p = parts.Length - 2; p >= 0 && addedParents < 3; p--)
                {
                    string part = parts[p];
                    if (string.IsNullOrEmpty(part) ||
                        string.Equals(part, "Custom", StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(part, "Hair", StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(part, "Female", StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(part, "Male", StringComparison.OrdinalIgnoreCase))
                        continue;
                    if (!result.Contains(part)) result.Add(part);
                    addedParents++;
                }
            }

            return result;
        }

        private string NormalizeHairLooseAlias(string value)
        {
            if (string.IsNullOrEmpty(value)) return "";
            List<string> tokens = new List<string>();
            System.Text.StringBuilder current = new System.Text.StringBuilder();
            string lower = value.ToLowerInvariant();
            for (int i = 0; i < lower.Length; i++)
            {
                char c = lower[i];
                if (char.IsLetterOrDigit(c)) current.Append(c);
                else if (current.Length > 0) { tokens.Add(current.ToString()); current.Length = 0; }
            }
            if (current.Length > 0) tokens.Add(current.ToString());
            HashSet<string> generic = new HashSet<string>(StringComparer.OrdinalIgnoreCase) {
                "look", "hair", "hairstyle", "style", "preset", "custom", "female", "male"
            };
            List<string> kept = new List<string>();
            for (int i = 0; i < tokens.Count; i++) if (!generic.Contains(tokens[i])) kept.Add(tokens[i]);
            if (kept.Count == 0) return "";
            kept.Sort(StringComparer.Ordinal);
            return string.Join("|", kept.ToArray());
        }

        private bool HairDisplayNameMatchesNode(string displayName, JSONNode node)
        {
            if (string.IsNullOrEmpty(displayName) || node == null)
                return false;

            string trimmedDisplay = displayName.Trim();
            List<string> candidates = GetHairNodeCandidateNames(node);

            // v73 used suffix matching on aggressively normalized names. That could
            // select the wrong raw item when a package contained similarly named
            // components. The stock VaM Hair test proves that the preset's exact
            // component names work, so v88 (same stable rule as v83) only accepts exact names (case-insensitive),
            // with normalized equality as a punctuation/spacing fallback.
            for (int i = 0; i < candidates.Count; i++)
            {
                string candidate = candidates[i];
                if (string.IsNullOrEmpty(candidate))
                    continue;

                if (string.Equals(
                        trimmedDisplay,
                        candidate.Trim(),
                        StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }

            string displayKey = NormalizeHairItemKey(trimmedDisplay);
            if (string.IsNullOrEmpty(displayKey))
                return false;

            for (int i = 0; i < candidates.Count; i++)
            {
                string key = NormalizeHairItemKey(candidates[i]);
                if (!string.IsNullOrEmpty(key) && displayKey == key)
                    return true;
            }

            // v151: VaM's live Hair bank can expose the same component with the
            // same words in a different order than geometry.hair. Calvin's pubic
            // component is the real-world example:
            //   geometry: "Balls Natural Extra Density"
            //   bank:     "Natural Balls Extra Density"
            // Treat a multi-token bag as a conservative final equality fallback.
            string displayTokenBag = NormalizeHairTokenBag(trimmedDisplay);
            if (!string.IsNullOrEmpty(displayTokenBag))
            {
                for (int i = 0; i < candidates.Count; i++)
                {
                    string candidateTokenBag = NormalizeHairTokenBag(candidates[i]);
                    if (!string.IsNullOrEmpty(candidateTokenBag) &&
                        displayTokenBag == candidateTokenBag)
                    {
                        return true;
                    }
                }
            }

            string displayVariantAlias = NormalizeHairVariantAlias(trimmedDisplay);
            if (!string.IsNullOrEmpty(displayVariantAlias))
            {
                for (int i = 0; i < candidates.Count; i++)
                {
                    string candidateVariantAlias = NormalizeHairVariantAlias(candidates[i]);
                    if (!string.IsNullOrEmpty(candidateVariantAlias) &&
                        displayVariantAlias == candidateVariantAlias)
                    {
                        return true;
                    }
                }
            }

            // v165: final exact-token alias for folder-derived live names.
            string displayLoose = NormalizeHairLooseAlias(trimmedDisplay);
            if (!string.IsNullOrEmpty(displayLoose))
            {
                for (int i = 0; i < candidates.Count; i++)
                {
                    string candidateLoose = NormalizeHairLooseAlias(candidates[i]);
                    if (!string.IsNullOrEmpty(candidateLoose) && displayLoose == candidateLoose)
                        return true;
                }
            }

            return false;
        }

        private bool CaptureOriginalActiveHairItems(PersonEntry person, out string warning)
        {
            warning = "";
            if (person == null || person.atom == null || string.IsNullOrEmpty(person.uid))
            {
                warning = "No selected Person.";
                return false;
            }

            if (_originalActiveHairItemsByPerson.ContainsKey(person.uid))
                return true;

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
            {
                warning = "Character selector unavailable.";
                return false;
            }

            string nativeSex = GetNativeHairSex(person);
            List<string> names = new List<string>();

            try
            {
                if (nativeSex == "M")
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair != null && hair.active && !string.IsNullOrEmpty(hair.displayName))
                            names.Add(hair.displayName);
                    }
                }
                else
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair != null && hair.active && !string.IsNullOrEmpty(hair.displayName))
                            names.Add(hair.displayName);
                    }
                }
            }
            catch (Exception e)
            {
                warning = "Could not capture current Hair items: " + e.Message;
                return false;
            }

            _originalActiveHairItemsByPerson[person.uid] = names;
            _originalActiveHairItemsByRegion[GetHairActiveKey(person.uid, "Head")] =
                GetActiveHairNamesForRegion(person, "Head");
            _originalActiveHairItemsByRegion[GetHairActiveKey(person.uid, "Facial")] =
                GetActiveHairNamesForRegion(person, "Facial");
            _originalActiveHairItemsByRegion[GetHairActiveKey(person.uid, "Body")] =
                GetActiveHairNamesForRegion(person, "Body");
            _originalActiveHairItemsByRegion[GetHairActiveKey(person.uid, "Pubic")] =
                GetActiveHairNamesForRegion(person, "Pubic");

            // Keep a live in-memory copy of the original Sim/Material state too.
            // Unlike the broken v65-v71 disk snapshots this is never handed to
            // HairPresets; it is replayed only after the original raw items are back.
            if (!_originalHairSnapshotJsonByPerson.ContainsKey(person.uid))
            {
                JSONClass state = BuildCurrentHairPresetJson(person);
                if (state != null)
                    _originalHairSnapshotJsonByPerson[person.uid] = state;
            }

            return true;
        }

        private bool RestoreActiveHairItems(PersonEntry person, List<string> wanted, out string error)
        {
            error = "";
            if (person == null || person.atom == null)
            {
                error = "No selected Person.";
                return false;
            }

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
            {
                error = "Character selector unavailable.";
                return false;
            }

            string nativeSex = GetNativeHairSex(person);
            HashSet<string> wantedKeys = new HashSet<string>(StringComparer.Ordinal);
            if (wanted != null)
            {
                for (int i = 0; i < wanted.Count; i++)
                    wantedKeys.Add(NormalizeHairItemKey(wanted[i]));
            }

            try
            {
                if (nativeSex == "M")
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair == null)
                            continue;
                        bool on = wantedKeys.Contains(NormalizeHairItemKey(hair.displayName));
                        selector.SetActiveHairItem(hair, on);
                    }
                }
                else
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair == null)
                            continue;
                        bool on = wantedKeys.Contains(NormalizeHairItemKey(hair.displayName));
                        selector.SetActiveHairItem(hair, on);
                    }
                }

                return true;
            }
            catch (Exception e)
            {
                error = e.Message;
                return false;
            }
        }

        // Hair item creation/destruction in VaM is not fully synchronous.
        // Turning old items off and new items on in the same frame can leave stale
        // GPU hair/scalp objects alive. v83 performs the switch in two phases.
        private IEnumerator SwitchActiveHairItemsCoroutine(
            PersonEntry person,
            List<string> wanted,
            HashSet<int> preferredInstanceIds,
            Action<bool, string> completed)
        {
            if (person == null || person.atom == null)
            {
                if (completed != null) completed(false, "No selected Person.");
                yield break;
            }

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
            {
                if (completed != null) completed(false, "Character selector unavailable.");
                yield break;
            }

            string nativeSex = GetNativeHairSex(person);
            HashSet<string> wantedKeys = new HashSet<string>(StringComparer.Ordinal);
            if (wanted != null)
            {
                for (int i = 0; i < wanted.Count; i++)
                    wantedKeys.Add(NormalizeHairItemKey(wanted[i]));
            }

            try
            {
                // Phase 1: remove every currently active item from the native bank.
                if (nativeSex == "M")
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair != null && hair.active)
                            selector.SetActiveHairItem(hair, false);
                    }
                }
                else
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair != null && hair.active)
                            selector.SetActiveHairItem(hair, false);
                    }
                }
            }
            catch (Exception e)
            {
                if (completed != null) completed(false, "Could not clear current Hair: " + e.Message);
                yield break;
            }

            // Let VaM tear down old hair/scalp objects before adding replacements.
            yield return null;
            yield return null;
            yield return null;

            try
            {
                // Phase 2: activate only the complete requested set.
                if (nativeSex == "M")
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair == null)
                            continue;
                        bool useThis =
                            (preferredInstanceIds != null && preferredInstanceIds.Contains(hair.GetInstanceID())) ||
                            wantedKeys.Contains(NormalizeHairItemKey(hair.displayName));
                        if (useThis)
                            selector.SetActiveHairItem(hair, true);
                    }
                }
                else
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair == null)
                            continue;
                        bool useThis =
                            (preferredInstanceIds != null && preferredInstanceIds.Contains(hair.GetInstanceID())) ||
                            wantedKeys.Contains(NormalizeHairItemKey(hair.displayName));
                        if (useThis)
                            selector.SetActiveHairItem(hair, true);
                    }
                }

            }
            catch (Exception e)
            {
                if (completed != null) completed(false, "Could not enable requested Hair: " + e.Message);
                yield break;
            }

            // Dynamic Sim/Material storables appear a little later than the item.
            yield return null;
            yield return null;
            yield return null;

            if (completed != null) completed(true, "");
        }

        private Dictionary<string, string> BuildHairInternalIdSourceMap(JSONClass preset)
        {
            Dictionary<string, string> result =
                new Dictionary<string, string>(StringComparer.Ordinal);

            if (preset == null)
                return result;

            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null)
                    return result;

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null || st["id"].Value != "geometry")
                        continue;

                    JSONArray hair = st["hair"].AsArray;
                    if (hair == null)
                        break;

                    for (int h = 0; h < hair.Count; h++)
                    {
                        JSONNode item = hair[h];
                        if (item == null || !IsHairNodeEnabled(item))
                            continue;

                        string internalId = GetEffectiveHairInternalId(item);
                        string id = item["id"].Value;
                        if (string.IsNullOrEmpty(internalId))
                            continue;

                        string source = "";
                        int sep = string.IsNullOrEmpty(id) ? -1 : id.IndexOf(":/", StringComparison.Ordinal);
                        if (sep > 0)
                            source = id.Substring(0, sep);

                        result[internalId] = source;
                    }
                    break;
                }
            }
            catch { }

            return result;
        }

        private string GetHairStorableSourcePrefix(
            string storableId,
            Dictionary<string, string> map)
        {
            if (string.IsNullOrEmpty(storableId) || map == null)
                return null;

            string best = null;
            int bestLength = -1;
            foreach (KeyValuePair<string, string> kv in map)
            {
                if (string.IsNullOrEmpty(kv.Key))
                    continue;
                if (storableId.StartsWith(kv.Key, StringComparison.Ordinal) &&
                    kv.Key.Length > bestLength)
                {
                    best = kv.Value;
                    bestLength = kv.Key.Length;
                }
            }
            return best;
        }

        // v91: map the internalId stored by the source Female preset to the
        // internalId of the actually active native-bank item after cross-gender
        // cloning.  Some clones preserve the original internalId (Roac:Flip), while
        // others lose the author prefix (NoStage3:Short Wavy -> :Short Wavy).
        // The v86 log proved that visual-state restoration must target the LIVE ID.
        private Dictionary<string, string> BuildCrossGenderHairInternalIdMap(
            PersonEntry person,
            JSONClass preset)
        {
            Dictionary<string, string> result =
                new Dictionary<string, string>(StringComparer.Ordinal);

            if (person == null || person.atom == null || preset == null)
                return result;

            try
            {
                List<KeyValuePair<string, string>> sourceItems =
                    new List<KeyValuePair<string, string>>();

                JSONArray storables = preset["storables"].AsArray;
                if (storables != null)
                {
                    for (int i = 0; i < storables.Count; i++)
                    {
                        JSONNode st = storables[i];
                        if (st == null || st["id"].Value != "geometry")
                            continue;

                        JSONArray hair = st["hair"].AsArray;
                        if (hair == null) break;

                        for (int h = 0; h < hair.Count; h++)
                        {
                            JSONNode item = hair[h];
                            if (item == null || !IsHairNodeEnabled(item))
                                continue;

                            string internalId = GetEffectiveHairInternalId(item);
                            string itemId = item["id"].Value;
                            if (!string.IsNullOrEmpty(internalId))
                                sourceItems.Add(new KeyValuePair<string, string>(internalId, itemId));
                        }
                        break;
                    }
                }

                DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
                JSONClass liveGeometry = selector == null ? null : selector.GetJSON(true, true, true);
                JSONArray liveHair = liveGeometry == null ? null : liveGeometry["hair"].AsArray;
                if (liveHair == null)
                    return result;

                List<KeyValuePair<string, string>> liveItems =
                    new List<KeyValuePair<string, string>>();
                for (int h = 0; h < liveHair.Count; h++)
                {
                    JSONNode item = liveHair[h];
                    if (item == null || !IsHairNodeEnabled(item))
                        continue;

                    string internalId = item["internalId"].Value;
                    string itemId = item["id"].Value;
                    if (!string.IsNullOrEmpty(internalId))
                        liveItems.Add(new KeyValuePair<string, string>(internalId, itemId));
                }

                HashSet<int> usedLive = new HashSet<int>();
                for (int sidx = 0; sidx < sourceItems.Count; sidx++)
                {
                    string srcInternal = sourceItems[sidx].Key;
                    string srcId = sourceItems[sidx].Value;
                    string srcLeaf = srcInternal;
                    int colon = srcLeaf.IndexOf(':');
                    if (colon >= 0 && colon + 1 < srcLeaf.Length)
                        srcLeaf = srcLeaf.Substring(colon + 1);
                    string srcLeafKey = NormalizeHairItemKey(srcLeaf);

                    string srcFile = srcId == null ? "" : srcId.Replace('\\', '/');
                    int slash = srcFile.LastIndexOf('/');
                    if (slash >= 0) srcFile = srcFile.Substring(slash + 1);
                    if (srcFile.EndsWith(".vam", StringComparison.OrdinalIgnoreCase))
                        srcFile = srcFile.Substring(0, srcFile.Length - 4);
                    string srcFileKey = NormalizeHairItemKey(srcFile);

                    int best = -1;
                    int bestScore = -1;
                    for (int lidx = 0; lidx < liveItems.Count; lidx++)
                    {
                        if (usedLive.Contains(lidx)) continue;

                        string liveInternal = liveItems[lidx].Key;
                        string liveId = liveItems[lidx].Value;
                        int score = 0;

                        if (string.Equals(srcInternal, liveInternal, StringComparison.OrdinalIgnoreCase))
                            score += 10000;

                        string liveLeaf = liveInternal;
                        int liveColon = liveLeaf.IndexOf(':');
                        if (liveColon >= 0 && liveColon + 1 < liveLeaf.Length)
                            liveLeaf = liveLeaf.Substring(liveColon + 1);
                        string liveLeafKey = NormalizeHairItemKey(liveLeaf);
                        if (!string.IsNullOrEmpty(srcLeafKey) && srcLeafKey == liveLeafKey)
                            score += 5000;

                        string liveFile = liveId == null ? "" : liveId.Replace('\\', '/');
                        int liveSlash = liveFile.LastIndexOf('/');
                        if (liveSlash >= 0) liveFile = liveFile.Substring(liveSlash + 1);
                        if (liveFile.EndsWith(".vam", StringComparison.OrdinalIgnoreCase))
                            liveFile = liveFile.Substring(0, liveFile.Length - 4);
                        string liveFileKey = NormalizeHairItemKey(liveFile);
                        if (!string.IsNullOrEmpty(srcFileKey) && srcFileKey == liveFileKey)
                            score += 3000;

                        if (score > bestScore)
                        {
                            bestScore = score;
                            best = lidx;
                        }
                    }

                    if (best >= 0 && bestScore >= 3000)
                    {
                        result[srcInternal] = liveItems[best].Key;
                        usedLive.Add(best);
                    }
                }

                // v175: duplicate-display-name Hair can leave one source internalId
                // unmapped even though its live clone exists (Lasseur 2BUN is the
                // confirmed case). Use dynamic Sim/ItemControl storable prefixes as
                // a conservative final identity hint, but only when the pairing is
                // one-to-one for the same creator. This cannot affect ordinary items
                // that already mapped by exact internalId/file name.
                try
                {
                    HashSet<string> mappedLive =
                        new HashSet<string>(result.Values, StringComparer.OrdinalIgnoreCase);
                    List<string> atomIds = person.atom.GetStorableIDs();
                    Dictionary<string, List<string>> livePrefixesByCreator =
                        new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);

                    if (atomIds != null)
                    {
                        for (int i = 0; i < atomIds.Count; i++)
                        {
                            string sid = atomIds[i];
                            string prefix = StripLegacyHairStateSuffix(sid);
                            if (string.IsNullOrEmpty(prefix) || prefix.IndexOf(':') <= 0)
                                continue;
                            if (mappedLive.Contains(prefix))
                                continue;

                            string creator = prefix.Substring(0, prefix.IndexOf(':'));
                            List<string> list;
                            if (!livePrefixesByCreator.TryGetValue(creator, out list))
                            {
                                list = new List<string>();
                                livePrefixesByCreator[creator] = list;
                            }
                            if (!list.Contains(prefix))
                                list.Add(prefix);
                        }
                    }

                    Dictionary<string, List<string>> unmappedByCreator =
                        new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
                    for (int i = 0; i < sourceItems.Count; i++)
                    {
                        string srcInternal = sourceItems[i].Key;
                        if (result.ContainsKey(srcInternal) || srcInternal.IndexOf(':') <= 0)
                            continue;
                        string creator = srcInternal.Substring(0, srcInternal.IndexOf(':'));
                        List<string> list;
                        if (!unmappedByCreator.TryGetValue(creator, out list))
                        {
                            list = new List<string>();
                            unmappedByCreator[creator] = list;
                        }
                        if (!list.Contains(srcInternal))
                            list.Add(srcInternal);
                    }

                    foreach (KeyValuePair<string, List<string>> kv in unmappedByCreator)
                    {
                        List<string> liveCandidates;
                        if (kv.Value.Count != 1 ||
                            !livePrefixesByCreator.TryGetValue(kv.Key, out liveCandidates) ||
                            liveCandidates.Count != 1)
                        {
                            continue;
                        }

                        result[kv.Value[0]] = liveCandidates[0];
                        mappedLive.Add(liveCandidates[0]);
                    }
                }
                catch { }
            }
            catch { }

            return result;
        }

        private string TranslateCrossGenderHairStorableId(
            string sourceStorableId,
            Dictionary<string, string> internalIdMap)
        {
            if (string.IsNullOrEmpty(sourceStorableId) || internalIdMap == null)
                return sourceStorableId;

            string bestSource = null;
            string bestLive = null;
            int bestLength = -1;

            foreach (KeyValuePair<string, string> kv in internalIdMap)
            {
                if (string.IsNullOrEmpty(kv.Key) || string.IsNullOrEmpty(kv.Value))
                    continue;
                if (sourceStorableId.StartsWith(kv.Key, StringComparison.Ordinal) &&
                    kv.Key.Length > bestLength)
                {
                    bestSource = kv.Key;
                    bestLive = kv.Value;
                    bestLength = kv.Key.Length;
                }
            }

            if (string.IsNullOrEmpty(bestSource) || bestLive == null)
                return sourceStorableId;

            return bestLive + sourceStorableId.Substring(bestSource.Length);
        }

        private JSONClass RewriteHairStateSelfPaths(JSONClass state, string sourcePrefix)
        {
            if (state == null)
                return null;

            try
            {
                string raw = state.ToString();
                if (raw.IndexOf("SELF:/", StringComparison.Ordinal) >= 0)
                {
                    raw = string.IsNullOrEmpty(sourcePrefix)
                        ? raw.Replace("SELF:/", "")
                        : raw.Replace("SELF:/", sourcePrefix + ":/");
                }
                JSONNode parsed = JSON.Parse(raw);
                return parsed == null ? null : parsed.AsObject;
            }
            catch { }
            return null;
        }

        // Restore the visual/simulation state stored by a Hair Preset after all
        // requested raw items exist. Per-item *Preset manager storables remain
        // skipped because they are not cross-gender safe. Material SELF:/ paths are
        // resolved against the package of the corresponding .vam hair item rather
        // than against the package that merely contains the Hair Preset.
        private void RestoreHairPresetItemStates(PersonEntry person, JSONClass preset)
        {
            if (person == null || person.atom == null || preset == null)
                return;

            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null)
                    return;

                Dictionary<string, string> sourceMap = BuildHairInternalIdSourceMap(preset);

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode node = storables[i];
                    if (node == null)
                        continue;

                    string id = node["id"].Value;
                    if (string.IsNullOrEmpty(id) || id == "geometry" || id == "HairPresets")
                        continue;

                    if (!IsUsefulHairStateStorable(id))
                        continue;

                    JSONStorable target = person.atom.GetStorableByID(id);
                    if (target == null)
                        continue;

                    JSONClass state = node.AsObject;
                    if (state == null)
                        continue;

                    string sourcePrefix = GetHairStorableSourcePrefix(id, sourceMap);
                    JSONClass rewritten = RewriteHairStateSelfPaths(state, sourcePrefix);
                    if (rewritten == null)
                        continue;

                    try
                    {
                        target.RestoreFromJSON(rewritten, true, true, null, false);
                    }
                    catch
                    {
                        // One optional/custom material control should never abort the
                        // whole hairstyle. Geometry has already been switched safely.
                    }
                }
            }
            catch { }
        }

        // v91 keeps the proven v82/v83 raw-item switch, but replays the two classes
        // of per-item state that actually affect the visible hairstyle: Sim and
        // Material.  We still NEVER restore per-item Preset managers, ItemControl,
        // CustomScalpWrap, geometry, or HairPresets itself.  Material asset paths
        // are repaired against the package that owns the corresponding .vam item.
        // This is intentionally much narrower than the broken v81 full-preset load.
        private JSONClass RewriteCrossGenderHairVisualStatePaths(
            JSONClass state,
            string sourcePrefix)
        {
            if (state == null)
                return null;

            try
            {
                string raw = state.ToString();

                if (!string.IsNullOrEmpty(sourcePrefix))
                {
                    // Hair packages commonly store textures as SELF:/... .  When
                    // restored directly on a cloned opposite-gender item there is
                    // no PresetManager package context, so make the package explicit.
                    raw = raw.Replace("SELF:/", sourcePrefix + ":/");

                    // Some older hair assets store package-local textures as bare
                    // Custom/... paths instead of SELF:/Custom/... .  Stock VaM can
                    // resolve these while loading the original item, but the cloned
                    // cross-gender item loses that implicit package context.  Prefix
                    // JSON string values that start with Custom/ only; already fully
                    // qualified Package:/Custom/... values are untouched.
                    raw = raw.Replace("\"Custom/", "\"" + sourcePrefix + ":/Custom/");
                }
                else
                {
                    // Local Custom/... assets need no package prefix. Do not strip
                    // arbitrary paths. SELF:/ cannot be resolved safely here, so
                    // leave it untouched rather than inventing a wrong location.
                }

                JSONNode parsed = JSON.Parse(raw);
                return parsed == null ? null : parsed.AsObject;
            }
            catch { }

            return null;
        }

        // v176: exact-clone Hair items do not always expose the same dynamic
        // storable prefix as the source geometry internalId.  This is common in
        // older/complex assets (Oeshii PartyGirl and Lasseur 2BUN are confirmed).
        // Build a conservative source-prefix -> live-prefix map from the dynamic
        // storables that actually exist on the Person.  We never scan packages and
        // never fuzzy-match arbitrary Hair items: a candidate must preserve the
        // exact state-storable suffix, and ambiguous candidates require a strong
        // prefix-name match.
        private Dictionary<string, string> BuildCrossGenderHairStorablePrefixMap(
            PersonEntry person,
            JSONClass preset,
            Dictionary<string, string> seedMap)
        {
            Dictionary<string, string> result =
                seedMap == null
                    ? new Dictionary<string, string>(StringComparer.Ordinal)
                    : new Dictionary<string, string>(seedMap, StringComparer.Ordinal);

            if (person == null || person.atom == null || preset == null)
                return result;

            try
            {
                Dictionary<string, string> sourceMap = BuildHairInternalIdSourceMap(preset);
                if (sourceMap == null || sourceMap.Count == 0)
                    return result;

                JSONArray storables = preset["storables"].AsArray;
                List<string> atomIds = person.atom.GetStorableIDs();
                if (storables == null || atomIds == null)
                    return result;

                foreach (KeyValuePair<string, string> kv in sourceMap)
                {
                    string sourceInternal = kv.Key;
                    if (string.IsNullOrEmpty(sourceInternal))
                        continue;

                    // Keep a seed mapping only when it can actually address at least
                    // one source state storable.  Otherwise continue with discovery.
                    string seeded;
                    bool seedWorks = false;
                    if (result.TryGetValue(sourceInternal, out seeded) &&
                        !string.IsNullOrEmpty(seeded))
                    {
                        for (int i = 0; i < storables.Count; i++)
                        {
                            JSONNode st = storables[i];
                            if (st == null) continue;
                            string sid = st["id"].Value;
                            if (string.IsNullOrEmpty(sid) ||
                                !sid.StartsWith(sourceInternal, StringComparison.Ordinal))
                                continue;
                            string tail = sid.Substring(sourceInternal.Length);
                            if (!string.IsNullOrEmpty(tail) &&
                                person.atom.GetStorableByID(seeded + tail) != null)
                            {
                                seedWorks = true;
                                break;
                            }
                        }
                    }
                    if (seedWorks)
                        continue;

                    string sourceLeaf = sourceInternal;
                    int colon = sourceLeaf.IndexOf(':');
                    string sourceCreator = "";
                    if (colon >= 0)
                    {
                        sourceCreator = sourceLeaf.Substring(0, colon);
                        if (colon + 1 < sourceLeaf.Length)
                            sourceLeaf = sourceLeaf.Substring(colon + 1);
                    }
                    string sourceLeafKey = NormalizeHairItemKey(sourceLeaf);
                    string sourceLeafTokens = NormalizeHairTokenBag(sourceLeaf);

                    Dictionary<string, int> prefixScores =
                        new Dictionary<string, int>(StringComparer.Ordinal);

                    for (int i = 0; i < storables.Count; i++)
                    {
                        JSONNode st = storables[i];
                        if (st == null) continue;
                        string sid = st["id"].Value;
                        if (string.IsNullOrEmpty(sid) ||
                            !sid.StartsWith(sourceInternal, StringComparison.Ordinal))
                            continue;

                        if (!IsUsefulHairStateStorable(sid))
                            continue;

                        string tail = sid.Substring(sourceInternal.Length);
                        if (string.IsNullOrEmpty(tail))
                            continue;

                        List<string> matching = new List<string>();
                        for (int a = 0; a < atomIds.Count; a++)
                        {
                            string candidateId = atomIds[a];
                            if (string.IsNullOrEmpty(candidateId) ||
                                !candidateId.EndsWith(tail, StringComparison.OrdinalIgnoreCase) ||
                                candidateId.Length <= tail.Length)
                                continue;
                            matching.Add(candidateId.Substring(0, candidateId.Length - tail.Length));
                        }

                        for (int m = 0; m < matching.Count; m++)
                        {
                            string candidatePrefix = matching[m];
                            int score = 0;

                            if (string.Equals(candidatePrefix, sourceInternal, StringComparison.OrdinalIgnoreCase))
                                score += 2000;

                            string candidateLeaf = candidatePrefix;
                            int ccolon = candidateLeaf.IndexOf(':');
                            string candidateCreator = "";
                            if (ccolon >= 0)
                            {
                                candidateCreator = candidateLeaf.Substring(0, ccolon);
                                if (ccolon + 1 < candidateLeaf.Length)
                                    candidateLeaf = candidateLeaf.Substring(ccolon + 1);
                            }

                            string candidateKey = NormalizeHairItemKey(candidateLeaf);
                            if (!string.IsNullOrEmpty(sourceLeafKey) && sourceLeafKey == candidateKey)
                                score += 1200;

                            string candidateTokens = NormalizeHairTokenBag(candidateLeaf);
                            if (!string.IsNullOrEmpty(sourceLeafTokens) &&
                                sourceLeafTokens == candidateTokens)
                                score += 900;

                            if (!string.IsNullOrEmpty(sourceCreator) &&
                                string.Equals(sourceCreator, candidateCreator, StringComparison.OrdinalIgnoreCase))
                                score += 250;

                            // A long/distinctive state suffix (especially a named
                            // Material) is itself strong evidence when only one live
                            // storable has it.  This resolves Lasseur:Head where the
                            // live prefix is not name-equivalent to "Head".
                            if (matching.Count == 1)
                            {
                                score += tail.IndexOf("Material", StringComparison.OrdinalIgnoreCase) >= 0
                                    ? 1000
                                    : (tail.Length >= 10 ? 600 : 150);
                            }

                            int old = 0;
                            prefixScores.TryGetValue(candidatePrefix, out old);
                            prefixScores[candidatePrefix] = old + score;
                        }
                    }

                    string bestPrefix = null;
                    int bestScore = 0;
                    bool tie = false;
                    foreach (KeyValuePair<string, int> score in prefixScores)
                    {
                        if (score.Value > bestScore)
                        {
                            bestScore = score.Value;
                            bestPrefix = score.Key;
                            tie = false;
                        }
                        else if (score.Value == bestScore && score.Value > 0)
                        {
                            tie = true;
                        }
                    }

                    if (!tie && !string.IsNullOrEmpty(bestPrefix) && bestScore >= 600)
                        result[sourceInternal] = bestPrefix;
                    else if (!seedWorks)
                        result.Remove(sourceInternal);
                }
            }
            catch { }

            return result;
        }

        private void LogLegacyHairPresetStorableIds(JSONClass preset, string stage)
        {
            if (preset == null) return;
            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null) return;
                int written = 0;
                for (int i = 0; i < storables.Count && written < 30; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null) continue;
                    string id = st["id"].Value;
                    if (string.IsNullOrEmpty(id)) id = "<empty>";
                    SuperController.LogMessage(
                        "CharacterRouter v183 FUTA HAIR LEGACY | stage=" + stage +
                        " | index=" + i + " | id=" + id
                    );
                    written++;
                }
            }
            catch { }
        }

        private void RestoreCrossGenderHairVisualState(PersonEntry person, JSONClass preset, string presetLabel)
        {
            if (person == null || person.atom == null || preset == null)
                return;

            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null)
                    return;

                Dictionary<string, string> sourceMap =
                    BuildHairInternalIdSourceMap(preset);
                Dictionary<string, string> liveInternalIdMap =
                    BuildCrossGenderHairInternalIdMap(person, preset);
                liveInternalIdMap = BuildCrossGenderHairStorablePrefixMap(
                    person, preset, liveInternalIdMap
                );

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode node = storables[i];
                    if (node == null)
                        continue;

                    string id = node["id"].Value;
                    if (string.IsNullOrEmpty(id) || id == "geometry" || id == "HairPresets")
                        continue;

                    bool isSim = id.EndsWith(
                        "Sim",
                        StringComparison.OrdinalIgnoreCase);
                    bool isMaterial = id.IndexOf(
                        "Material",
                        StringComparison.OrdinalIgnoreCase) >= 0;
                    bool isItemControl = id.EndsWith(
                        "ItemControl",
                        StringComparison.OrdinalIgnoreCase);

                    if (!isSim && !isMaterial && !isItemControl)
                        continue;

                    // Per-item preset/control storables are never replayed.
                    if (!IsUsefulHairStateStorable(id))
                        continue;

                    string targetId = id;
                    JSONStorable target = person.atom.GetStorableByID(targetId);
                    if (target == null)
                    {
                        targetId = TranslateCrossGenderHairStorableId(id, liveInternalIdMap);
                        if (!string.IsNullOrEmpty(targetId))
                            target = person.atom.GetStorableByID(targetId);
                    }
                    if (target == null)
                        continue;

                    JSONClass state = node.AsObject;
                    if (state == null)
                        continue;

                    string sourcePrefix =
                        GetHairStorableSourcePrefix(id, sourceMap);

                    // Package material state is only safe when we can identify the
                    // .vam package that owns this item's storable. Sim state remains
                    // safe without source information, exactly as in v82.
                    if (isMaterial && string.IsNullOrEmpty(sourcePrefix))
                        continue;

                    JSONClass rewritten = isMaterial
                        ? RewriteCrossGenderHairVisualStatePaths(state, sourcePrefix)
                        : CloneJsonClass(state);

                    if (rewritten == null)
                        continue;

                    try
                    {
                        target.RestoreFromJSON(rewritten, true, true, null, false);
                    }
                    catch
                    {
                        // A bad optional material/Sim block must never undo the raw
                        // item switch. RESET remains available via the stable baseline.
                    }
                }
            }
            catch { }
        }


        // v181 diagnostic: native Futanari and AltFuta cross-gender Hair diagnostics.
        // Hair.  Log the requested source components and the exact opposite-bank
        // candidates so cross-gender failures can be diagnosed from VaM's normal
        // Message Log without another speculative compatibility patch.
        private void LogNativeFutaHeadPresetDiagnostic(
            PersonEntry person,
            JSONClass preset,
            string desiredSex,
            string stage)
        {
            if (person == null || person.atom == null || preset == null ||
                (!IsActiveNativeFutanariPerson(person) && !IsActiveAltFutaPerson(person)))
                return;

            try
            {
                string nativeSex = GetNativeHairSex(person);
                SuperController.LogMessage(
                    "CharacterRouter v183 FUTA HAIR DIAG BEGIN | stage=" + stage +
                    " | uid=" + person.uid + " | type=" +
                    (IsActiveAltFutaPerson(person) ? "AltFuta" : "NativeFutanari") +
                    " | nativeSex=" + nativeSex + " | desiredSex=" + desiredSex
                );

                DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
                JSONArray storables = preset["storables"].AsArray;
                JSONArray desiredHair = null;
                if (storables != null)
                {
                    for (int i = 0; i < storables.Count; i++)
                    {
                        JSONNode st = storables[i];
                        if (st != null && st["id"].Value == "geometry")
                        {
                            desiredHair = st["hair"].AsArray;
                            break;
                        }
                    }
                }

                // Log EVERY geometry node, including nodes explicitly disabled by the
                // source preset. This distinguishes old-format "no enabled flag" Hair
                // from complex presets that deliberately carry inactive components.
                if (desiredHair != null)
                {
                    for (int i = 0; i < desiredHair.Count; i++)
                    {
                        JSONNode node = desiredHair[i];
                        if (node == null) continue;

                        string internalId = node["internalId"].Value;
                        string id = node["id"].Value;
                        string enabledRaw = node["enabled"].Value;
                        bool enabledEffective = IsHairNodeEnabled(node);
                        string classifiedRegion = ClassifyLiveHairNodeRegion(node);

                        SuperController.LogMessage(
                            "CharacterRouter v183 FUTA HAIR DIAG NODE | stage=" + stage +
                            " | index=" + i + " | enabledRaw=" +
                            (string.IsNullOrEmpty(enabledRaw) ? "<missing>" : enabledRaw) +
                            " | enabledEffective=" + enabledEffective +
                            " | region=" + classifiedRegion +
                            " | internalId=" + internalId + " | id=" + id
                        );

                        if (!enabledEffective)
                            continue;

                        List<string> exact = new List<string>();
                        List<string> near = new List<string>();

                        if (selector != null)
                        {
                            if (desiredSex == "F")
                            {
                                foreach (var hair in selector.femaleHairItems)
                                {
                                    if (hair == null || hair.name != "CustomHairItem" || string.IsNullOrEmpty(hair.displayName))
                                        continue;
                                    if (HairDisplayNameMatchesNode(hair.displayName, node))
                                    {
                                        exact.Add(hair.displayName + "#" + hair.GetInstanceID());
                                    }
                                    else
                                    {
                                        string dk = NormalizeHairItemKey(hair.displayName);
                                        List<string> candidates = GetHairNodeCandidateNames(node);
                                        for (int c = 0; c < candidates.Count; c++)
                                        {
                                            string ck = NormalizeHairItemKey(candidates[c]);
                                            if (!string.IsNullOrEmpty(dk) && !string.IsNullOrEmpty(ck) &&
                                                (dk.Contains(ck) || ck.Contains(dk)))
                                            {
                                                near.Add(hair.displayName + "#" + hair.GetInstanceID());
                                                break;
                                            }
                                        }
                                    }
                                }
                            }
                            else if (desiredSex == "M")
                            {
                                foreach (var hair in selector.maleHairItems)
                                {
                                    if (hair == null || hair.name != "CustomHairItem" || string.IsNullOrEmpty(hair.displayName))
                                        continue;
                                    if (HairDisplayNameMatchesNode(hair.displayName, node))
                                    {
                                        exact.Add(hair.displayName + "#" + hair.GetInstanceID());
                                    }
                                    else
                                    {
                                        string dk = NormalizeHairItemKey(hair.displayName);
                                        List<string> candidates = GetHairNodeCandidateNames(node);
                                        for (int c = 0; c < candidates.Count; c++)
                                        {
                                            string ck = NormalizeHairItemKey(candidates[c]);
                                            if (!string.IsNullOrEmpty(dk) && !string.IsNullOrEmpty(ck) &&
                                                (dk.Contains(ck) || ck.Contains(dk)))
                                            {
                                                near.Add(hair.displayName + "#" + hair.GetInstanceID());
                                                break;
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        if (near.Count > 8) near.RemoveRange(8, near.Count - 8);

                        bool sourceReadable = false;
                        string sourceReadError = "";
                        if (!string.IsNullOrEmpty(id))
                        {
                            try
                            {
                                string resolvedPath = ResolveInstalledHairSourcePath(id);
                                string sourceProbe = FileManagerSecure.ReadAllText(resolvedPath);
                                sourceReadable = !string.IsNullOrEmpty(sourceProbe);
                            }
                            catch (Exception readException)
                            {
                                sourceReadError = readException.Message;
                            }
                        }

                        SuperController.LogMessage(
                            "CharacterRouter v183 FUTA HAIR DIAG SOURCE | stage=" + stage +
                            " | index=" + i + " | internalId=" + internalId + " | id=" + id +
                            " | sourceReadable=" + sourceReadable +
                            (string.IsNullOrEmpty(sourceReadError) ? "" : " | sourceReadError=" + sourceReadError) +
                            " | exact=" + (exact.Count == 0 ? "<none>" : string.Join(" ; ", exact.ToArray())) +
                            " | near=" + (near.Count == 0 ? "<none>" : string.Join(" ; ", near.ToArray()))
                        );
                    }
                }

                // The key diagnostic missing from v163/v168: show which preset
                // storables carry visual state, which ones CharacterRouter deliberately
                // skips, and whether a corresponding live clone storable actually exists.
                Dictionary<string, string> sourceMap = BuildHairInternalIdSourceMap(preset);
                Dictionary<string, string> liveMap = BuildCrossGenderHairInternalIdMap(person, preset);

                foreach (KeyValuePair<string, string> kv in liveMap)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v183 FUTA HAIR DIAG MAP | stage=" + stage +
                        " | sourceInternalId=" + kv.Key + " | liveInternalId=" + kv.Value
                    );
                }

                if (storables != null)
                {
                    for (int i = 0; i < storables.Count; i++)
                    {
                        JSONNode st = storables[i];
                        if (st == null) continue;
                        string sid = st["id"].Value;
                        if (string.IsNullOrEmpty(sid) || sid == "geometry" || sid == "HairPresets")
                            continue;

                        bool isSim = sid.EndsWith("Sim", StringComparison.OrdinalIgnoreCase);
                        bool isMaterial = sid.IndexOf("Material", StringComparison.OrdinalIgnoreCase) >= 0;
                        bool useful = IsUsefulHairStateStorable(sid);
                        string sourcePrefix = GetHairStorableSourcePrefix(sid, sourceMap);
                        JSONStorable direct = person.atom.GetStorableByID(sid);
                        string translatedId = TranslateCrossGenderHairStorableId(sid, liveMap);
                        JSONStorable translated = string.IsNullOrEmpty(translatedId)
                            ? null
                            : person.atom.GetStorableByID(translatedId);
                        string kind = isMaterial ? "Material" : (isSim ? "Sim" : "Other");

                        SuperController.LogMessage(
                            "CharacterRouter v183 FUTA HAIR DIAG STORABLE | stage=" + stage +
                            " | id=" + sid + " | kind=" + kind +
                            " | useful=" + useful +
                            " | sourcePrefix=" + (string.IsNullOrEmpty(sourcePrefix) ? "<none>" : sourcePrefix) +
                            " | directTarget=" + (direct != null) +
                            " | translatedId=" + (string.IsNullOrEmpty(translatedId) ? "<none>" : translatedId) +
                            " | translatedTarget=" + (translated != null)
                        );
                    }
                }

                if (selector != null)
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair != null && hair.active)
                            SuperController.LogMessage(
                                "CharacterRouter v183 FUTA HAIR DIAG ACTIVE | stage=" + stage +
                                " | bank=M" + (nativeSex == "M" ? "(native)" : "(opposite)") +
                                " | displayName=" + hair.displayName +
                                " | instance=" + hair.GetInstanceID() +
                                " | runtimeRegion=" + GetRuntimeHairRegionForDisplayName(person, hair.displayName)
                            );
                    }

                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair != null && hair.active)
                            SuperController.LogMessage(
                                "CharacterRouter v183 FUTA HAIR DIAG ACTIVE | stage=" + stage +
                                " | bank=F" + (nativeSex == "F" ? "(native)" : "(opposite)") +
                                " | displayName=" + hair.displayName +
                                " | instance=" + hair.GetInstanceID() +
                                " | runtimeRegion=" + GetRuntimeHairRegionForDisplayName(person, hair.displayName)
                            );
                    }
                }

                // v181: AltFuta INTIMATE diagnostic. Compare each source Male Hair item
                // with the active Female-bank exact clone. This reveals whether the
                // problem is transform/container placement or mesh/skin-wrap geometry.
                if (IsActiveAltFutaPerson(person) && desiredSex == "M" && desiredHair != null && selector != null)
                {
                    for (int i = 0; i < desiredHair.Count; i++)
                    {
                        JSONNode node = desiredHair[i];
                        if (node == null || !IsHairNodeEnabled(node)) continue;

                        foreach (var sourceHair in selector.maleHairItems)
                        {
                            if (sourceHair == null || sourceHair.name != "CustomHairItem" ||
                                string.IsNullOrEmpty(sourceHair.displayName) ||
                                !HairDisplayNameMatchesNode(sourceHair.displayName, node))
                                continue;

                            try
                            {
                                Transform st = sourceHair.transform;
                                Renderer[] sr = sourceHair.GetComponentsInChildren<Renderer>(true);
                                string sBounds = "<none>";
                                string sRootBone = "<none>";
                                if (sr != null && sr.Length > 0)
                                {
                                    bool init = false;
                                    Bounds b = new Bounds();
                                    for (int r = 0; r < sr.Length; r++)
                                    {
                                        if (sr[r] == null) continue;
                                        if (!init) { b = sr[r].bounds; init = true; }
                                        else b.Encapsulate(sr[r].bounds);
                                        SkinnedMeshRenderer smr = sr[r] as SkinnedMeshRenderer;
                                        if (smr != null && smr.rootBone != null && sRootBone == "<none>")
                                            sRootBone = smr.rootBone.name;
                                    }
                                    if (init)
                                        sBounds = "center=" + b.center.ToString("F3") + ",size=" + b.size.ToString("F3");
                                }

                                SuperController.LogMessage(
                                    "CharacterRouter v183 ALTFUTA INTIMATE SOURCE | stage=" + stage +
                                    " | displayName=" + sourceHair.displayName +
                                    " | instance=" + sourceHair.GetInstanceID() +
                                    " | active=" + sourceHair.active +
                                    " | parent=" + (st.parent != null ? st.parent.name : "<none>") +
                                    " | localPos=" + st.localPosition.ToString("F4") +
                                    " | localRot=" + st.localEulerAngles.ToString("F2") +
                                    " | localScale=" + st.localScale.ToString("F4") +
                                    " | worldPos=" + st.position.ToString("F4") +
                                    " | rootBone=" + sRootBone +
                                    " | renderers=" + (sr != null ? sr.Length : 0) +
                                    " | bounds=" + sBounds
                                );
                            }
                            catch (Exception sourceDiagError)
                            {
                                SuperController.LogMessage(
                                    "CharacterRouter v183 ALTFUTA INTIMATE SOURCE ERROR | stage=" + stage +
                                    " | displayName=" + sourceHair.displayName + " | " + sourceDiagError.Message
                                );
                            }

                            foreach (var cloneHair in selector.femaleHairItems)
                            {
                                if (cloneHair == null || !cloneHair.active ||
                                    !string.Equals(cloneHair.displayName, sourceHair.displayName, StringComparison.OrdinalIgnoreCase))
                                    continue;
                                try
                                {
                                    Transform ct = cloneHair.transform;
                                    Renderer[] cr = cloneHair.GetComponentsInChildren<Renderer>(true);
                                    string cBounds = "<none>";
                                    string cRootBone = "<none>";
                                    if (cr != null && cr.Length > 0)
                                    {
                                        bool init = false;
                                        Bounds b = new Bounds();
                                        for (int r = 0; r < cr.Length; r++)
                                        {
                                            if (cr[r] == null) continue;
                                            if (!init) { b = cr[r].bounds; init = true; }
                                            else b.Encapsulate(cr[r].bounds);
                                            SkinnedMeshRenderer smr = cr[r] as SkinnedMeshRenderer;
                                            if (smr != null && smr.rootBone != null && cRootBone == "<none>")
                                                cRootBone = smr.rootBone.name;
                                        }
                                        if (init)
                                            cBounds = "center=" + b.center.ToString("F3") + ",size=" + b.size.ToString("F3");
                                    }
                                    SuperController.LogMessage(
                                        "CharacterRouter v183 ALTFUTA INTIMATE CLONE | stage=" + stage +
                                        " | displayName=" + cloneHair.displayName +
                                        " | instance=" + cloneHair.GetInstanceID() +
                                        " | active=" + cloneHair.active +
                                        " | parent=" + (ct.parent != null ? ct.parent.name : "<none>") +
                                        " | localPos=" + ct.localPosition.ToString("F4") +
                                        " | localRot=" + ct.localEulerAngles.ToString("F2") +
                                        " | localScale=" + ct.localScale.ToString("F4") +
                                        " | worldPos=" + ct.position.ToString("F4") +
                                        " | rootBone=" + cRootBone +
                                        " | renderers=" + (cr != null ? cr.Length : 0) +
                                        " | bounds=" + cBounds
                                    );
                                }
                                catch (Exception cloneDiagError)
                                {
                                    SuperController.LogMessage(
                                        "CharacterRouter v183 ALTFUTA INTIMATE CLONE ERROR | stage=" + stage +
                                        " | displayName=" + cloneHair.displayName + " | " + cloneDiagError.Message
                                    );
                                }
                            }
                            break;
                        }
                    }
                }

                SuperController.LogMessage(
                    "CharacterRouter v183 FUTA HAIR DIAG END | stage=" + stage + " | uid=" + person.uid
                );
            }
            catch (Exception e)
            {
                SuperController.LogMessage(
                    "CharacterRouter v183 FUTA HAIR DIAG ERROR | stage=" + stage + " | " + e.Message
                );
            }
        }

        // v164: package-local Hair variants are not always pre-registered in the
        // opposite-gender bank under the preset's internalId. Resolve .latest refs
        // to the installed package where possible and use the .vam's own metadata as
        // a conservative alias source before declaring the component unavailable.
        private string ResolveInstalledHairSourcePath(string path)
        {
            if (string.IsNullOrEmpty(path))
                return path;

            try
            {
                string adapterResolved = _nativeFutanariHairAdapter.ResolveInstalledSourcePath(path);
                if (!string.IsNullOrEmpty(adapterResolved) &&
                    !string.Equals(adapterResolved, path, StringComparison.Ordinal))
                    return adapterResolved;
            }
            catch { }

            try
            {
                int sep = path.IndexOf(":/", StringComparison.Ordinal);
                if (sep <= 0)
                    return path;

                string packageUid = path.Substring(0, sep);
                if (!packageUid.EndsWith(".latest", StringComparison.OrdinalIgnoreCase))
                    return path;

                string baseUid = packageUid.Substring(0, packageUid.Length - ".latest".Length);
                int version = FileManagerSecure.GetPackageVersion(baseUid);
                if (version > 0)
                    return baseUid + "." + version + path.Substring(sep);
            }
            catch { }

            return path;
        }

        private bool HairNameEquivalent(string a, string b)
        {
            if (string.IsNullOrEmpty(a) || string.IsNullOrEmpty(b))
                return false;

            if (string.Equals(a.Trim(), b.Trim(), StringComparison.OrdinalIgnoreCase))
                return true;

            string ak = NormalizeHairItemKey(a);
            string bk = NormalizeHairItemKey(b);
            if (!string.IsNullOrEmpty(ak) && ak == bk)
                return true;

            string at = NormalizeHairTokenBag(a);
            string bt = NormalizeHairTokenBag(b);
            if (!string.IsNullOrEmpty(at) && at == bt)
                return true;

            string av = NormalizeHairVariantAlias(a);
            string bv = NormalizeHairVariantAlias(b);
            return !string.IsNullOrEmpty(av) && av == bv;
        }

        private bool HairDisplayNameMatchesSourceVam(string displayName, JSONNode node)
        {
            if (string.IsNullOrEmpty(displayName) || node == null)
                return false;

            string path = ResolveInstalledHairSourcePath(node["id"].Value);
            if (string.IsNullOrEmpty(path))
                return false;

            try
            {
                string content = FileManagerSecure.ReadAllText(path);
                if (string.IsNullOrEmpty(content))
                    return false;

                JSONNode root = JSON.Parse(content);
                if (root == null)
                    return false;

                string[] keys = new string[] {
                    "displayName", "uid", "id", "name", "storeName", "itemName"
                };
                for (int i = 0; i < keys.Length; i++)
                {
                    string candidate = root[keys[i]].Value;
                    if (string.IsNullOrEmpty(candidate))
                        continue;

                    if (HairNameEquivalent(displayName, candidate))
                        return true;

                    int colon = candidate.IndexOf(':');
                    if (colon >= 0 && colon + 1 < candidate.Length &&
                        HairNameEquivalent(displayName, candidate.Substring(colon + 1)))
                    {
                        return true;
                    }
                }
            }
            catch { }

            return false;
        }

        private bool HairSourceBankContainsNode(
            DAZCharacterSelector selector,
            string desiredSex,
            JSONNode node)
        {
            if (selector == null || node == null)
                return false;

            if (desiredSex == "F")
            {
                foreach (var hair in selector.femaleHairItems)
                {
                    if (hair == null || hair.name != "CustomHairItem" ||
                        string.IsNullOrEmpty(hair.displayName))
                        continue;
                    if (HairDisplayNameMatchesNode(hair.displayName, node) ||
                        HairDisplayNameMatchesSourceVam(hair.displayName, node))
                        return true;
                }
            }
            else if (desiredSex == "M")
            {
                foreach (var hair in selector.maleHairItems)
                {
                    if (hair == null || hair.name != "CustomHairItem" ||
                        string.IsNullOrEmpty(hair.displayName))
                        continue;
                    if (HairDisplayNameMatchesNode(hair.displayName, node) ||
                        HairDisplayNameMatchesSourceVam(hair.displayName, node))
                        return true;
                }
            }

            return false;
        }

        // Native Futanari can retain an original Female-bank head style while new
        // Female items are cloned into its Male native bank. Clear only the target
        // region in the opposite bank before activating the replacement, preserving
        // Brows/Facial/Body/Pubic layers there.
        private void DeactivateOppositeBankHairRegion(PersonEntry person, string targetRegion)
        {
            if (person == null || person.atom == null)
                return;

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
                return;

            string nativeSex = GetNativeHairSex(person);
            string target = NormalizeEditableHairRegion(targetRegion);

            try
            {
                if (nativeSex == "M")
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair == null || !hair.active || string.IsNullOrEmpty(hair.displayName))
                            continue;
                        string region = GetRuntimeHairRegionForDisplayName(person, hair.displayName);
                        if (string.IsNullOrEmpty(region))
                            region = ClassifyHairDescriptor(hair.displayName);
                        if (string.Equals(region, target, StringComparison.OrdinalIgnoreCase))
                            selector.SetActiveHairItem(hair, false);
                    }
                }
                else if (nativeSex == "F")
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair == null || !hair.active || string.IsNullOrEmpty(hair.displayName))
                            continue;
                        string region = GetRuntimeHairRegionForDisplayName(person, hair.displayName);
                        if (string.IsNullOrEmpty(region))
                            region = ClassifyHairDescriptor(hair.displayName);
                        if (string.Equals(region, target, StringComparison.OrdinalIgnoreCase))
                            selector.SetActiveHairItem(hair, false);
                    }
                }
            }
            catch { }
        }

        private bool ResolvePresetHairDisplayNames(
            PersonEntry person,
            JSONClass preset,
            string desiredSex,
            out List<string> resolvedNames,
            out HashSet<int> preferredInstanceIds,
            out string error)
        {
            resolvedNames = new List<string>();
            preferredInstanceIds = new HashSet<int>();
            error = "";

            if (person == null || person.atom == null || preset == null)
            {
                error = "Invalid Person or Hair preset.";
                return false;
            }

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
            {
                error = "Character selector unavailable.";
                return false;
            }

            JSONArray storables = preset["storables"].AsArray;
            if (storables == null)
            {
                error = "Hair preset contains no storables.";
                return false;
            }

            JSONArray desiredHair = null;
            for (int i = 0; i < storables.Count; i++)
            {
                JSONNode st = storables[i];
                if (st != null && st["id"].Value == "geometry")
                {
                    desiredHair = st["hair"].AsArray;
                    break;
                }
            }

            if (desiredHair == null)
            {
                error = "Hair preset contains no geometry hair state.";
                return false;
            }

            string nativeSex = GetNativeHairSex(person);
            bool crossGender =
                (nativeSex == "M" || nativeSex == "F") &&
                (desiredSex == "M" || desiredSex == "F") &&
                nativeSex != desiredSex;

            List<string> missing = new List<string>();

            // v91 root-cause fix: the v88 log proved that Damar's preset requests
            // Roac.Flip_hair, but the native Male bank supplied a same-name converted
            // WeebU.Futa_Hair item. That converted item owns a bare Custom/... alpha
            // path and errors before visual-state restore even begins. Alley Female
            // showed the same shadowing pattern for NoStage3:Short Wavy.
            //
            // For cross-gender presets, clone the EXACT source opposite-bank items
            // referenced by the preset and remember their Unity instance IDs. The
            // switch routine will activate only these clones, never a same-name
            // pre-existing native item.
            if (crossGender)
            {
                // v166: specialized native-Futanari/opposite-bank work lives in its
                // own adapter. CharacterRouter only supplies the requested geometry.
                bool resolvedCrossGender;
                if (IsActiveAltFutaPerson(person))
                {
                    resolvedCrossGender = _altFutaHairAdapter.ResolveExactSourceClones(
                        person.uid, selector, desiredHair, nativeSex, desiredSex,
                        out resolvedNames, out preferredInstanceIds, out error
                    );
                }
                else
                {
                    resolvedCrossGender = _nativeFutanariHairAdapter.ResolveExactSourceClones(
                        person.uid, selector, desiredHair, nativeSex, desiredSex,
                        out resolvedNames, out preferredInstanceIds, out error
                    );
                }

                if (!resolvedCrossGender)
                    return false;
            }
            else
            {
                // Same-gender presets continue to use VaM's native bank unchanged.
                for (int i = 0; i < desiredHair.Count; i++)
                {
                    JSONNode node = desiredHair[i];
                    if (node == null || !IsHairNodeEnabled(node))
                        continue;

                    string match = "";
                    if (nativeSex == "M")
                    {
                        foreach (var hair in selector.maleHairItems)
                        {
                            if (hair != null && HairDisplayNameMatchesNode(hair.displayName, node))
                            {
                                match = hair.displayName;
                                break;
                            }
                        }
                    }
                    else
                    {
                        foreach (var hair in selector.femaleHairItems)
                        {
                            if (hair != null && HairDisplayNameMatchesNode(hair.displayName, node))
                            {
                                match = hair.displayName;
                                break;
                            }
                        }
                    }

                    if (string.IsNullOrEmpty(match))
                    {
                        string internalId = node["internalId"].Value;
                        string id = node["id"].Value;
                        missing.Add(!string.IsNullOrEmpty(internalId) ? internalId : id);
                    }
                    else if (!resolvedNames.Contains(match))
                    {
                        resolvedNames.Add(match);
                    }
                }
            }

            if (missing.Count > 0)
            {
                int count = Math.Min(missing.Count, 4);
                string[] shown = new string[count];
                for (int i = 0; i < count; i++) shown[i] = missing[i];
                error = "Unavailable Hair component" + (missing.Count == 1 ? ": " : "s: ") +
                    string.Join(" | ", shown);
                return false;
            }

            if (resolvedNames.Count == 0)
            {
                error = "Hair preset contains no enabled Hair components.";
                return false;
            }

            if (crossGender && preferredInstanceIds.Count == 0)
            {
                error = "Exact cross-gender Hair clones were not available after initialization.";
                return false;
            }

            return true;
        }

        // v115: cross-gender Hair visual-state storables are created asynchronously.
        // Wait until the exact requested clones are visibly alive and the Sim/Material
        // storables that RestoreCrossGenderHairVisualState() will target actually exist.
        // This replaces the old fixed three-frame guess with a bounded readiness barrier.
        private bool IsCrossGenderHairReadyForVisualRestore(
            PersonEntry person,
            JSONClass preset,
            HashSet<int> preferredInstanceIds)
        {
            if (person == null || person.atom == null || preset == null ||
                preferredInstanceIds == null || preferredInstanceIds.Count == 0)
            {
                return false;
            }

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector == null)
                return false;

            string nativeSex = GetNativeHairSex(person);
            HashSet<int> readyIds = new HashSet<int>();

            try
            {
                if (nativeSex == "M")
                {
                    foreach (var hair in selector.maleHairItems)
                    {
                        if (hair == null || !preferredInstanceIds.Contains(hair.GetInstanceID()))
                            continue;

                        bool hasLiveRenderer = false;
                        Renderer[] renderers = hair.GetComponentsInChildren<Renderer>(true);
                        if (renderers != null)
                        {
                            for (int i = 0; i < renderers.Length; i++)
                            {
                                Renderer renderer = renderers[i];
                                if (renderer != null && renderer.enabled && renderer.gameObject.activeInHierarchy)
                                {
                                    hasLiveRenderer = true;
                                    break;
                                }
                            }
                        }

                        if (hair.active && hair.gameObject.activeInHierarchy && hasLiveRenderer)
                            readyIds.Add(hair.GetInstanceID());
                    }
                }
                else
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair == null || !preferredInstanceIds.Contains(hair.GetInstanceID()))
                            continue;

                        bool hasLiveRenderer = false;
                        Renderer[] renderers = hair.GetComponentsInChildren<Renderer>(true);
                        if (renderers != null)
                        {
                            for (int i = 0; i < renderers.Length; i++)
                            {
                                Renderer renderer = renderers[i];
                                if (renderer != null && renderer.enabled && renderer.gameObject.activeInHierarchy)
                                {
                                    hasLiveRenderer = true;
                                    break;
                                }
                            }
                        }

                        if (hair.active && hair.gameObject.activeInHierarchy && hasLiveRenderer)
                            readyIds.Add(hair.GetInstanceID());
                    }
                }
            }
            catch
            {
                return false;
            }

            if (readyIds.Count != preferredInstanceIds.Count)
                return false;

            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null)
                    return true;

                Dictionary<string, string> sourceMap = BuildHairInternalIdSourceMap(preset);
                Dictionary<string, string> liveInternalIdMap =
                    BuildCrossGenderHairInternalIdMap(person, preset);

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode node = storables[i];
                    if (node == null)
                        continue;

                    string id = node["id"].Value;
                    if (string.IsNullOrEmpty(id) || id == "geometry" || id == "HairPresets")
                        continue;

                    bool isSim = id.EndsWith("Sim", StringComparison.OrdinalIgnoreCase);
                    bool isMaterial = id.IndexOf("Material", StringComparison.OrdinalIgnoreCase) >= 0;
                    if (!isSim && !isMaterial)
                        continue;
                    if (!IsUsefulHairStateStorable(id))
                        continue;

                    string sourcePrefix = GetHairStorableSourcePrefix(id, sourceMap);
                    if (isMaterial && string.IsNullOrEmpty(sourcePrefix))
                        continue;

                    JSONStorable target = person.atom.GetStorableByID(id);
                    if (target == null)
                    {
                        string targetId = TranslateCrossGenderHairStorableId(id, liveInternalIdMap);
                        if (!string.IsNullOrEmpty(targetId))
                            target = person.atom.GetStorableByID(targetId);
                    }

                    if (target == null)
                        return false;
                }
            }
            catch
            {
                return false;
            }

            return true;
        }

        private IEnumerator WaitForCrossGenderHairVisualReadiness(
            PersonEntry person,
            JSONClass preset,
            HashSet<int> preferredInstanceIds)
        {
            const float timeoutSeconds = 1.0f;
            const int stableFramesRequired = 2;

            float started = Time.realtimeSinceStartup;
            int stableFrames = 0;

            while (Time.realtimeSinceStartup - started < timeoutSeconds)
            {
                if (IsCrossGenderHairReadyForVisualRestore(person, preset, preferredInstanceIds))
                {
                    stableFrames++;
                    if (stableFrames >= stableFramesRequired)
                        yield break;
                }
                else
                {
                    stableFrames = 0;
                }

                yield return null;
            }
        }

        // v154 legacy fallback: a few stock/old Hair presets (VaM Taric is a
        // confirmed example) cannot be decomposed from their serialized geometry
        // because they use an older Hair preset representation. Let VaM load the
        // complete preset natively, then keep only the requested live region and
        // restore every previously active item outside that region.
        private IEnumerator ApplyLegacyHairPresetRegionViaNativeLoad(
            PersonEntry person,
            string path,
            string targetRegion,
            bool isolatedRegionPreset,
            Action<bool, string> completed)
        {
            List<string> beforeAll = GetAllActiveHairNames(person);
            List<string> preserved = GetActiveHairNamesExceptRegion(person, targetRegion);
            // Preserve the live Sim/Material state of the layers that the native
            // full-preset load is about to replace temporarily.
            JSONClass preservedState = BuildCurrentHairPresetJson(person);

            string nativeError;
            if (!ApplyHairPresetWithPath(person.atom, path, out nativeError))
            {
                if (completed != null)
                    completed(false, string.IsNullOrEmpty(nativeError) ? "Native Hair preset load failed." : nativeError);
                yield break;
            }

            // VaM creates/removes Hair items and their storables asynchronously.
            yield return null;
            yield return null;
            yield return null;
            yield return null;

            // v159: extracted SCENES fallback files contain only the selected
            // logical region. Their live-bank aliases therefore do not need to be
            // re-classified after VaM loads them: every active item produced by this
            // isolated preset belongs to the target layer. This fixes TKB:Pubic Heart
            // and similar scene aliases that cannot be matched by displayName.
            List<string> loadedRegion = isolatedRegionPreset
                ? GetAllActiveHairNames(person)
                : GetActiveHairNamesForRegion(person, targetRegion);

            // v231: some legacy same-sex HEAD presets load successfully in VaM but
            // expose their live bank item under an alias that our region classifier
            // cannot recognize. Chris Redfield is the confirmed case. When native
            // load succeeded yet HEAD classification found nothing, recover the
            // newly activated live Hair names by diffing against the exact pre-load
            // active set. Restrict this to non-isolated Head fallback so BODY/PUBIC/
            // FACIAL cannot accidentally be re-labelled as Head.
            if (loadedRegion.Count == 0 &&
                !isolatedRegionPreset &&
                string.Equals(targetRegion, "Head", StringComparison.OrdinalIgnoreCase))
            {
                List<string> afterAll = GetAllActiveHairNames(person);
                for (int i = 0; i < afterAll.Count; i++)
                {
                    string candidate = afterAll[i];
                    if (string.IsNullOrEmpty(candidate))
                        continue;

                    bool existedBefore = false;
                    for (int b = 0; b < beforeAll.Count; b++)
                    {
                        if (string.Equals(beforeAll[b], candidate, StringComparison.OrdinalIgnoreCase))
                        {
                            existedBefore = true;
                            break;
                        }
                    }

                    if (!existedBefore && !loadedRegion.Contains(candidate))
                        loadedRegion.Add(candidate);
                }

                if (loadedRegion.Count > 0)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v231 MALE HEAD LEGACY ALIAS RECOVERY | stage=LIVE_DIFF" +
                        " | recovered=" + string.Join(" ; ", loadedRegion.ToArray())
                    );
                }
            }

            if (loadedRegion.Count == 0)
            {
                // Native loading is destructive even when post-load classification
                // fails. Roll back the exact pre-load Hair set before reporting the
                // error so a failed INTIMATE/BODY card can never leave Facial/Head
                // changed as a side effect.
                bool rollbackOk = false;
                string rollbackError = "";
                yield return StartCoroutine(
                    SwitchActiveHairItemsCoroutine(
                        person,
                        beforeAll,
                        new HashSet<int>(),
                        delegate(bool result, string msg)
                        {
                            rollbackOk = result;
                            rollbackError = msg;
                        }
                    )
                );
                if (rollbackOk && preservedState != null)
                {
                    yield return null;
                    yield return null;
                    RestoreHairPresetItemStates(person, preservedState);
                }

                if (completed != null)
                {
                    string msg = "Native preset loaded, but no " + targetRegion +
                        " Hair layer could be identified.";
                    if (!rollbackOk && !string.IsNullOrEmpty(rollbackError))
                        msg += " Rollback failed: " + rollbackError;
                    completed(false, msg);
                }
                yield break;
            }

            List<string> wanted = new List<string>(loadedRegion);
            for (int i = 0; i < preserved.Count; i++)
            {
                if (!wanted.Contains(preserved[i]))
                    wanted.Add(preserved[i]);
            }

            bool switched = false;
            string switchError = "";
            yield return StartCoroutine(
                SwitchActiveHairItemsCoroutine(
                    person,
                    wanted,
                    new HashSet<int>(),
                    delegate(bool result, string msg)
                    {
                        switched = result;
                        switchError = msg;
                    }
                )
            );

            if (!switched)
            {
                bool rollbackOk = false;
                string rollbackError = "";
                yield return StartCoroutine(
                    SwitchActiveHairItemsCoroutine(
                        person,
                        beforeAll,
                        new HashSet<int>(),
                        delegate(bool result, string msg)
                        {
                            rollbackOk = result;
                            rollbackError = msg;
                        }
                    )
                );
                if (rollbackOk && preservedState != null)
                {
                    yield return null;
                    yield return null;
                    RestoreHairPresetItemStates(person, preservedState);
                }

                if (completed != null)
                {
                    string msg = string.IsNullOrEmpty(switchError)
                        ? "Could not isolate native Hair layer."
                        : switchError;
                    if (!rollbackOk && !string.IsNullOrEmpty(rollbackError))
                        msg += " Rollback failed: " + rollbackError;
                    completed(false, msg);
                }
                yield break;
            }

            // Reapply the visual state of the preserved non-target layers after
            // VaM has recreated their dynamic storables.
            if (preservedState != null)
            {
                yield return null;
                yield return null;
                RestoreHairPresetItemStates(person, preservedState);
            }

            // v160: loadedRegion is the exact live-bank identity of the new target
            // layer. Remember it before future replace/reset operations try to
            // classify these aliases from serialized geometry again.
            SetRuntimeHairRegionAliases(person, targetRegion, loadedRegion);

            if (completed != null)
                completed(true, "Applied legacy " + targetRegion + " Hair layer via native VaM loader.");
        }

        private bool PresetReferencesGeneratedAltFutaConvertedHair(JSONClass preset)
        {
            if (preset == null)
                return false;

            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null)
                    return false;

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null || st["id"].Value != "geometry")
                        continue;

                    JSONArray hair = st["hair"].AsArray;
                    if (hair == null)
                        return false;

                    for (int h = 0; h < hair.Count; h++)
                    {
                        JSONNode node = hair[h];
                        if (node == null || !IsHairNodeEnabled(node))
                            continue;

                        string id = node["id"].Value.Replace('\\', '/');
                        if (id.IndexOf(
                                "/Gleb/CharacterRouter/AltFutaConverted/",
                                StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            return true;
                        }
                    }
                    break;
                }
            }
            catch { }

            return false;
        }

        // v229: same-sex native Male HEAD presets with authored Sim state are
        // safer when loaded through VaM's own HairPresets loader. The generic direct
        // live-bank switch correctly activates geometry, but some simulated styles
        // can lose/partially replay their dynamic Sim state and produce stretched
        // strands/loops. Keep this detector intentionally narrow so ordinary static
        // same-bank Hair continues using the stable direct path.
        private bool HairPresetHasNativeSimState(JSONClass preset)
        {
            if (preset == null)
                return false;

            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null)
                    return false;

                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null)
                        continue;

                    string id = st["id"].Value;
                    if (string.IsNullOrEmpty(id))
                        continue;

                    if (id.EndsWith("Sim", StringComparison.OrdinalIgnoreCase) ||
                        id.IndexOf("SimV2", StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        return true;
                    }
                }
            }
            catch { }

            return false;
        }

        private IEnumerator ApplyHairPresetRegionJsonDirect(
            PersonEntry person,
            JSONClass preset,
            string desiredSex,
            string presetLabel,
            string targetRegion,
            bool crossGender,
            Action<bool, string> completed)
        {
            JSONClass sourcePreset = preset;

            // v175: bounded legacy recovery for presets such as Lumi that contain
            // only a disabled SimV2 Hair framework row in geometry.hair but still
            // retain their actual Hair identity in Sim/ItemControl storables.
            // Never run this when the preset already has a real enabled Hair node.
            if (crossGender &&
                string.Equals(targetRegion, "Head", StringComparison.OrdinalIgnoreCase) &&
                !HasEnabledRealHairNode(sourcePreset))
            {
                string recoveryDetail;
                JSONClass recovered = TryRecoverLegacyHairGeometryFromStorables(
                    sourcePreset,
                    out recoveryDetail
                );
                if (recovered != null)
                {
                    sourcePreset = recovered;
                    if (!string.IsNullOrEmpty(recoveryDetail))
                        SuperController.LogMessage(
                            "CharacterRouter v183 FUTA HAIR RECOVERY | " + recoveryDetail
                        );
                }
                else
                {
                    LogLegacyHairPresetStorableIds(sourcePreset, "RECOVERY_FAILED");
                }
            }

            // v195: CharacterRouter's generated Male->AltFuta HairFemale asset has
            // an intentionally neutral display/internal ID ("Base Extra 02") while
            // its catalog metadata marks it as Pubic. Generic node classification
            // therefore defaults it to Head and would filter the only geometry row
            // away. Keep this generated one-item preset intact; runtime aliases below
            // record it as Pubic immediately after the successful switch.
            bool isGeneratedAltFutaIntimate =
                IsActiveAltFutaPerson(person) &&
                string.Equals(targetRegion, "Pubic", StringComparison.OrdinalIgnoreCase) &&
                PresetReferencesGeneratedAltFutaConvertedHair(sourcePreset);

            JSONClass regionPreset = isGeneratedAltFutaIntimate
                ? sourcePreset
                : BuildHairRegionOnlyPresetJson(sourcePreset, targetRegion);
            if (regionPreset == null)
                regionPreset = sourcePreset;

            // v231: old/large Head presets can carry perfectly valid enabled Hair
            // nodes that the learned global region map classifies away. This was
            // already handled for cross-gender Lumi in v177; Chris Redfield proves
            // the same failure mode exists for same-sex Male HEAD as well. If the
            // normal Head filter becomes empty while the source still has real
            // enabled Hair, retry with explicit descriptors only. Unknown items
            // default to Head, which is the conservative behavior we want here.
            if (string.Equals(targetRegion, "Head", StringComparison.OrdinalIgnoreCase) &&
                !HairPresetHasEnabledGeometryItems(regionPreset) &&
                HasEnabledRealHairNode(sourcePreset))
            {
                JSONClass explicitHead = BuildSceneHairRegionOnlyPresetJson(sourcePreset, "Head");
                if (explicitHead != null && HairPresetHasEnabledGeometryItems(explicitHead))
                    regionPreset = explicitHead;
            }

            List<string> preserved = GetActiveHairNamesExceptRegion(person, targetRegion);
            bool futaHeadDiag = crossGender && (
                string.Equals(targetRegion, "Head", StringComparison.OrdinalIgnoreCase) ||
                (IsActiveAltFutaPerson(person) &&
                 string.Equals(targetRegion, "Pubic", StringComparison.OrdinalIgnoreCase) &&
                 string.Equals(desiredSex, "M", StringComparison.OrdinalIgnoreCase))
            ); // v183 diagnostic: Head cross-gender plus AltFuta INTIMATE (Pubic) cross-gender.
            if (futaHeadDiag)
                LogNativeFutaHeadPresetDiagnostic(person, regionPreset, desiredSex, "BEFORE_RESOLVE");

            List<string> resolved;
            HashSet<int> preferredInstanceIds;
            string resolveError;
            if (!ResolvePresetHairDisplayNames(
                    person,
                    regionPreset,
                    desiredSex,
                    out resolved,
                    out preferredInstanceIds,
                    out resolveError))
            {
                if (futaHeadDiag)
                    LogNativeFutaHeadPresetDiagnostic(person, regionPreset, desiredSex, "RESOLVE_FAILED");
                if (completed != null) completed(false, resolveError);
                yield break;
            }

            if (futaHeadDiag)
                LogNativeFutaHeadPresetDiagnostic(person, regionPreset, desiredSex, "RESOLVED");

            if (resolved.Count == 0)
            {
                if (completed != null)
                    completed(false, "Preset has no " + targetRegion + " Hair components.");
                yield break;
            }

            List<string> targetResolved = new List<string>(resolved);

            // v175: for cross-gender Hair, the target layer must be activated ONLY by
            // the exact-source clone instance IDs returned by NativeFutanariHairAdapter.
            // Do not keep target display names in the normal name-matching set: VaM may
            // already contain a converted/native item with the same displayName, and the
            // old OR condition in SwitchActiveHairItemsCoroutine would activate BOTH the
            // exact clone and that shadow item. That produced doubled geometry and could
            // let the wrong material/color win (A2 / Green Red are confirmed examples).
            // Preserved non-target layers still use display-name matching as before.
            if (crossGender)
                resolved.Clear();

            for (int i = 0; i < preserved.Count; i++)
            {
                if (!resolved.Contains(preserved[i]))
                    resolved.Add(preserved[i]);
            }

            if (crossGender)
            {
                // v164: a native Futa may still render its original Female-bank
                // Head item. Clear only the target region there so the newly cloned
                // native-bank style cannot overlay the old hairstyle.
                Func<string, string> resolveRuntimeRegion = delegate(string displayName)
                {
                    string region = GetRuntimeHairRegionForDisplayName(person, displayName);
                    if (string.IsNullOrEmpty(region))
                        region = ClassifyHairDescriptor(displayName);
                    return region;
                };

                if (IsActiveAltFutaPerson(person))
                {
                    _altFutaHairAdapter.DeactivateOppositeBankRegion(
                        GetCharacterSelectorForPerson(person),
                        GetNativeHairSex(person),
                        targetRegion,
                        resolveRuntimeRegion
                    );
                }
                else
                {
                    _nativeFutanariHairAdapter.DeactivateOppositeBankRegion(
                        GetCharacterSelectorForPerson(person),
                        GetNativeHairSex(person),
                        targetRegion,
                        resolveRuntimeRegion
                    );
                }
                yield return null;
                yield return null;
            }

            bool switched = false;
            string switchError = "";
            yield return StartCoroutine(
                SwitchActiveHairItemsCoroutine(
                    person,
                    resolved,
                    preferredInstanceIds,
                    delegate(bool result, string msg)
                    {
                        switched = result;
                        switchError = msg;
                    }
                )
            );

            if (!switched)
            {
                if (completed != null)
                    completed(false, string.IsNullOrEmpty(switchError) ? "Could not switch Hair items." : switchError);
                yield break;
            }

            if (futaHeadDiag)
                LogNativeFutaHeadPresetDiagnostic(person, regionPreset, desiredSex, "AFTER_SWITCH");

            SetRuntimeHairRegionAliases(person, targetRegion, targetResolved);

            if (crossGender)
            {
                yield return StartCoroutine(
                    WaitForCrossGenderHairVisualReadiness(
                        person,
                        regionPreset,
                        preferredInstanceIds
                    )
                );
                RestoreCrossGenderHairVisualState(person, regionPreset, presetLabel);
            }
            else
            {
                // Same-bank items need only a few frames for their dynamic storables.
                yield return null;
                yield return null;
                yield return null;
                RestoreHairPresetItemStates(person, regionPreset);
            }

            if (futaHeadDiag)
                LogNativeFutaHeadPresetDiagnostic(person, regionPreset, desiredSex, "AFTER_VISUAL_RESTORE");

            yield return null;
            yield return null;
            yield return null;

            if (completed != null)
            {
                completed(
                    true,
                    crossGender
                        ? "Applied exact source " + targetRegion + " Hair clones + visual state."
                        : "Applied " + targetRegion + " Hair layer."
                );
            }
        }

        private IEnumerator ApplyHairPresetJsonDirect(
            PersonEntry person,
            JSONClass preset,
            string desiredSex,
            string presetLabel,
            Action<bool, string> completed)
        {
            string nativeSex = GetNativeHairSex(person);
            bool crossGender =
                (nativeSex == "M" || nativeSex == "F") &&
                (desiredSex == "M" || desiredSex == "F") &&
                nativeSex != desiredSex;

            yield return StartCoroutine(
                ApplyHairPresetRegionJsonDirect(
                    person, preset, desiredSex, presetLabel,
                    "Head", crossGender, completed
                )
            );
        }

        private bool HairPresetHasEnabledGeometryItems(JSONClass preset)
        {
            if (preset == null)
                return false;
            try
            {
                JSONArray storables = preset["storables"].AsArray;
                if (storables == null)
                    return false;
                for (int i = 0; i < storables.Count; i++)
                {
                    JSONNode st = storables[i];
                    if (st == null || st["id"].Value != "geometry")
                        continue;
                    JSONArray hair = st["hair"].AsArray;
                    if (hair == null) return false;
                    for (int h = 0; h < hair.Count; h++)
                    {
                        JSONNode item = hair[h];
                        if (item != null && IsHairNodeEnabled(item))
                        {
                            return true;
                        }
                    }
                    return false;
                }
            }
            catch { }
            return false;
        }

        private void ResetSelectedCharacterHair()
        {
            if (_hairPresetApplyInProgress || _controlledSpawnInProgress)
                return;

            StartCoroutine(ResetSelectedCharacterHairCoroutine());
        }

        private IEnumerator ResetSelectedCharacterHairCoroutine()
        {
            _hairPresetApplyInProgress = true;

            PersonEntry selected = GetSelectedPerson();
            if (selected == null || selected.atom == null)
            {
                UpdateHairHudStatus("HAIR — no selected Person");
                _hairPresetApplyInProgress = false;
                yield break;
            }

            string targetRegion = NormalizeEditableHairRegion(_hairRegion);

            JSONClass originalState;
            if (!_originalHairSnapshotJsonByPerson.TryGetValue(selected.uid, out originalState) ||
                originalState == null)
            {
                UpdateHairHudStatus("HAIR — RESET unavailable until Hair is changed");
                _hairPresetApplyInProgress = false;
                yield break;
            }

            JSONClass originalRegion = BuildHairRegionOnlyPresetJson(originalState, targetRegion);
            List<string> resetWanted = GetActiveHairNamesExceptRegion(selected, targetRegion);
            HashSet<int> preferred = new HashSet<int>();

            // v154: reset from the exact live-bank names captured before the first
            // edit instead of re-resolving serialized geometry aliases.  This fixes
            // stock Calvin's geometry "MHawk 01" vs bank "Mohawk 01" mismatch.
            List<string> originalRegionNames;
            if (!_originalActiveHairItemsByRegion.TryGetValue(
                    GetHairActiveKey(selected.uid, targetRegion),
                    out originalRegionNames))
            {
                originalRegionNames = new List<string>();
                List<string> originalAll;
                if (_originalActiveHairItemsByPerson.TryGetValue(selected.uid, out originalAll))
                {
                    for (int i = 0; i < originalAll.Count; i++)
                    {
                        string name = originalAll[i];
                        if (string.Equals(
                                ClassifyHairDescriptor(name),
                                targetRegion,
                                StringComparison.OrdinalIgnoreCase))
                        {
                            originalRegionNames.Add(name);
                        }
                    }
                }
            }

            for (int i = 0; i < originalRegionNames.Count; i++)
            {
                if (!resetWanted.Contains(originalRegionNames[i]))
                    resetWanted.Add(originalRegionNames[i]);
            }

            bool switched = false;
            string switchError = "";
            yield return StartCoroutine(
                SwitchActiveHairItemsCoroutine(
                    selected,
                    resetWanted,
                    preferred,
                    delegate(bool result, string msg)
                    {
                        switched = result;
                        switchError = msg;
                    }
                )
            );

            if (!switched)
            {
                UpdateHairHudStatus("HAIR — reset failed: " + switchError);
                _hairPresetApplyInProgress = false;
                yield break;
            }

            // v160: Reset establishes the captured original items as the current
            // exact live aliases for this region, so a later edit can replace them
            // even when their displayName cannot be inferred from geometry.
            SetRuntimeHairRegionAliases(selected, targetRegion, originalRegionNames);

            if (originalRegion != null)
            {
                RestoreHairPresetItemStates(selected, originalRegion);
                yield return null;
            }

            // ExternalHairAdapter represents head hairstyles (Nico-style Clothing/CUA
            // hair), not beard/moustache layers. Only Head reset touches it.
            if (targetRegion == "Head")
            {
                DAZCharacterSelector resetExternalSelector =
                    GetCharacterSelectorForPerson(selected);
                bool restoredExternalHair = false;
                string restoredExternalDetail = "";
                bool restoredExternalOk = _externalHairAdapter.RestoreOriginal(
                    selected.atom,
                    resetExternalSelector,
                    selected.uid,
                    out restoredExternalHair,
                    out restoredExternalDetail
                );

                if (!restoredExternalOk && !string.IsNullOrEmpty(restoredExternalDetail))
                    SuperController.LogMessage("CharacterRouter v229: " + restoredExternalDetail);

                if (restoredExternalHair)
                {
                    yield return null;
                    yield return null;
                    yield return null;
                }

                _sceneCuaAccessoryAdapter.Set2BSceneHairVisible(
                    selected.atom, true);
            }

            string activeKey = GetHairActiveKey(selected.uid, targetRegion);
            if (_activeHairPresetByPerson.Remove(activeKey))
                SaveActiveHairPresetsData();

            UpdateHairHudStatus("HAIR — reset " + targetRegion.ToUpperInvariant());
            RebuildHairCatalogPage();
            _hairPresetApplyInProgress = false;
        }

        // v163 diagnostic build; v161 Remove behavior retained. Remove is intentionally different from Reset. Remove clears only
        // the currently selected editable Hair region while preserving every other
        // active region. The original layer is captured before the first removal so
        // RESET <region> can restore it later.
        private void RemoveSelectedCharacterHair()
        {
            if (_hairPresetApplyInProgress || _controlledSpawnInProgress)
                return;

            StartCoroutine(RemoveSelectedCharacterHairCoroutine());
        }

        private IEnumerator RemoveSelectedCharacterHairCoroutine()
        {
            _hairPresetApplyInProgress = true;

            PersonEntry selected = GetSelectedPerson();
            if (selected == null || selected.atom == null)
            {
                UpdateHairHudStatus("HAIR — no selected Person");
                _hairPresetApplyInProgress = false;
                yield break;
            }

            string targetRegion = NormalizeEditableHairRegion(_hairRegion);

            // Capture the untouched baseline before the first destructive edit.
            // If we cannot capture it, do not remove anything: a Remove button that
            // cannot be undone by RESET would be too risky for the constructor UI.
            string snapshotWarning;
            bool snapshotReady = CaptureOriginalActiveHairItems(selected, out snapshotWarning);
            if (!snapshotReady)
            {
                UpdateHairHudStatus(
                    "HAIR — remove blocked: " +
                    (string.IsNullOrEmpty(snapshotWarning)
                        ? "could not capture original Hair"
                        : snapshotWarning)
                );
                _hairPresetApplyInProgress = false;
                yield break;
            }

            DAZCharacterSelector externalHairSelector = GetCharacterSelectorForPerson(selected);
            bool externalHairDisabled = false;
            bool kaineHairHidden = false;
            string externalHairDetail = "";

            // Nico-style external Hair belongs to HEAD. Removing HEAD should make
            // the character genuinely bald, while RESET HEAD can restore it through
            // ExternalHairAdapter's captured original state.
            if (targetRegion == "Head")
            {
                bool externalHairOk = _externalHairAdapter.CaptureAndDisable(
                    selected.atom,
                    externalHairSelector,
                    selected.uid,
                    out externalHairDisabled,
                    out externalHairDetail
                );

                if (!externalHairOk && !string.IsNullOrEmpty(externalHairDetail))
                    SuperController.LogMessage("CharacterRouter v229: " + externalHairDetail);

                if (externalHairDisabled)
                {
                    yield return null;
                    yield return null;
                    yield return null;
                }

                kaineHairHidden = _sceneCuaAccessoryAdapter.Set2BSceneHairVisible(
                    selected.atom, false);
            }

            // The v160 runtime region map is authoritative for scene/native aliases.
            // Keeping everything except the target gives us a true per-region Remove
            // without touching beard/body/intimate/head layers owned by the others.
            List<string> wanted = GetActiveHairNamesExceptRegion(selected, targetRegion);
            HashSet<int> preferred = new HashSet<int>();

            bool switched = false;
            string switchError = "";
            yield return StartCoroutine(
                SwitchActiveHairItemsCoroutine(
                    selected,
                    wanted,
                    preferred,
                    delegate(bool result, string msg)
                    {
                        switched = result;
                        switchError = msg;
                    }
                )
            );

            if (!switched)
            {
                // If HEAD external Hair was already disabled but the internal-bank
                // switch failed, put the external original back to avoid a partial
                // destructive operation.
                if (targetRegion == "Head" && externalHairDisabled)
                {
                    bool restoredExternal = false;
                    string restoredExternalDetail = "";
                    _externalHairAdapter.RestoreOriginal(
                        selected.atom,
                        externalHairSelector,
                        selected.uid,
                        out restoredExternal,
                        out restoredExternalDetail
                    );
                }
                if (targetRegion == "Head" && kaineHairHidden)
                    _sceneCuaAccessoryAdapter.Set2BSceneHairVisible(
                        selected.atom, true);

                UpdateHairHudStatus(
                    "HAIR — remove failed: " +
                    (string.IsNullOrEmpty(switchError)
                        ? "Could not switch Hair items."
                        : switchError)
                );
                _hairPresetApplyInProgress = false;
                yield break;
            }

            // This region now intentionally owns no live items. Clearing its runtime
            // aliases is essential so the next preset does not inherit stale names.
            SetRuntimeHairRegionAliases(
                selected,
                targetRegion,
                new List<string>()
            );

            string activeKey = GetHairActiveKey(selected.uid, targetRegion);
            if (_activeHairPresetByPerson.Remove(activeKey))
                SaveActiveHairPresetsData();

            UpdateHairHudStatus(
                "HAIR — removed " + GetHairRegionDisplayName(targetRegion).ToUpperInvariant()
            );
            RebuildHairCatalogPage();
            _hairPresetApplyInProgress = false;
        }

        private bool ApplyHairPresetWithPath(Atom person, string path, out string error)
        {
            error = "";

            if (person == null)
            {
                error = "No selected Person.";
                return false;
            }

            if (string.IsNullOrEmpty(path))
            {
                error = "Hair preset path is empty.";
                return false;
            }

            try
            {
                JSONStorable hairPresets = person.GetStorableByID("HairPresets");
                if (hairPresets == null)
                {
                    error = "Selected Person has no HairPresets storable.";
                    return false;
                }

                JSONStorableUrl presetBrowsePath = hairPresets.GetUrlJSONParam("presetBrowsePath");
                if (presetBrowsePath == null)
                {
                    error = "HairPresets has no presetBrowsePath.";
                    return false;
                }

                JSONStorableBool loadPresetOnSelect = hairPresets.GetBoolJSONParam("loadPresetOnSelect");
                bool previous = false;
                if (loadPresetOnSelect != null)
                {
                    previous = loadPresetOnSelect.val;
                    loadPresetOnSelect.val = false;
                }

                try
                {
                    presetBrowsePath.val = SuperController.singleton.NormalizePath(path);
                    hairPresets.CallAction("LoadPreset");
                }
                finally
                {
                    if (loadPresetOnSelect != null)
                        loadPresetOnSelect.val = previous;
                }

                return true;
            }
            catch (Exception e)
            {
                error = e.Message;
                return false;
            }
        }

        private bool TryLoadRawHairRuntimeState(
            string vamPath,
            out string uid,
            out string displayName,
            out JSONArray storables,
            out string error)
        {
            uid = "";
            displayName = "";
            storables = null;
            error = "";

            if (string.IsNullOrEmpty(vamPath))
            {
                error = "Raw Hair path is empty.";
                return false;
            }

            try
            {
                string vamText = FileManagerSecure.ReadAllText(vamPath);
                JSONNode vamNode = string.IsNullOrEmpty(vamText) ? null : JSON.Parse(vamText);
                uid = vamNode == null ? "" : vamNode["uid"].Value;
                displayName = vamNode == null ? "" : vamNode["displayName"].Value;
                if (string.IsNullOrEmpty(uid))
                {
                    error = "Raw Hair metadata has no uid.";
                    return false;
                }

                string vajPath = vamPath.EndsWith(".vam", StringComparison.OrdinalIgnoreCase)
                    ? vamPath.Substring(0, vamPath.Length - 4) + ".vaj"
                    : vamPath + ".vaj";
                string vajText = FileManagerSecure.ReadAllText(vajPath);
                JSONNode vajNode = string.IsNullOrEmpty(vajText) ? null : JSON.Parse(vajText);
                storables = vajNode == null ? null : vajNode["storables"].AsArray;
                if (storables == null)
                {
                    error = "Raw Hair .vaj has no storables.";
                    return false;
                }

                return true;
            }
            catch (Exception e)
            {
                error = e.Message;
                return false;
            }
        }

        private bool RestoreExperimentalAltFutaMaleState(
            PersonEntry person,
            string sourcePath,
            string scaffoldPath,
            string presetLabel,
            out string detail)
        {
            detail = "";
            if (person == null || person.atom == null)
            {
                detail = "No selected Person.";
                return false;
            }

            string sourceUid;
            string sourceDisplayName;
            JSONArray sourceStorables;
            string sourceError;
            if (!TryLoadRawHairRuntimeState(
                    sourcePath,
                    out sourceUid,
                    out sourceDisplayName,
                    out sourceStorables,
                    out sourceError))
            {
                detail = "Could not read Male source state: " + sourceError;
                return false;
            }

            string scaffoldUid;
            string scaffoldDisplayName;
            JSONArray scaffoldStorables;
            string scaffoldError;
            if (!TryLoadRawHairRuntimeState(
                    scaffoldPath,
                    out scaffoldUid,
                    out scaffoldDisplayName,
                    out scaffoldStorables,
                    out scaffoldError))
            {
                detail = "Could not read AltFuta scaffold state: " + scaffoldError;
                return false;
            }

            Dictionary<string, JSONClass> sourceBySuffix =
                new Dictionary<string, JSONClass>(StringComparer.Ordinal);

            for (int i = 0; i < sourceStorables.Count; i++)
            {
                JSONNode st = sourceStorables[i];
                if (st == null)
                    continue;

                string sid = st["id"].Value;
                if (string.IsNullOrEmpty(sid) ||
                    !sid.StartsWith(sourceUid, StringComparison.Ordinal) ||
                    !IsUsefulHairStateStorable(sid))
                {
                    continue;
                }

                string suffix = sid.Substring(sourceUid.Length);
                if (string.IsNullOrEmpty(suffix))
                    continue;

                JSONClass state = st.AsObject;
                if (state != null)
                    sourceBySuffix[suffix] = state;
            }

            string sourcePrefix = "";
            int packageSeparator = sourcePath.IndexOf(":/", StringComparison.Ordinal);
            if (packageSeparator > 0)
                sourcePrefix = sourcePath.Substring(0, packageSeparator);

            SuperController.LogMessage(
                "CharacterRouter v191 ALTFUTA MALE INTIMATE TEST | preset=" +
                (string.IsNullOrEmpty(presetLabel) ? "<none>" : presetLabel) +
                " | source=" + (string.IsNullOrEmpty(sourceDisplayName) ? "<none>" : sourceDisplayName) +
                " | appliedOn=" + (string.IsNullOrEmpty(scaffoldDisplayName) ? "<none>" : scaffoldDisplayName)
            );

            int transferred = 0;
            List<string> transferredSuffixes = new List<string>();
            foreach (KeyValuePair<string, JSONClass> kv in sourceBySuffix)
            {
                string targetId = scaffoldUid + kv.Key;
                JSONStorable target = person.atom.GetStorableByID(targetId);
                if (target == null)
                    continue;

                JSONClass rewritten = RewriteHairStateSelfPaths(kv.Value, sourcePrefix);
                if (rewritten == null)
                    continue;

                rewritten["id"] = targetId;
                try
                {
                    target.RestoreFromJSON(rewritten, true, true, null, false);
                    transferred++;
                    transferredSuffixes.Add(kv.Key);
                }
                catch { }
            }

            bool resultVisible = false;
            int rendererCount = 0;
            string boundsInfo = "<none>";

            DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
            if (selector != null)
            {
                foreach (var hair in selector.femaleHairItems)
                {
                    if (hair == null || !hair.active ||
                        !string.Equals(hair.displayName, scaffoldDisplayName, StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    try
                    {
                        Renderer[] renderers = hair.GetComponentsInChildren<Renderer>(true);
                        if (renderers != null)
                        {
                            rendererCount = renderers.Length;
                            bool init = false;
                            Bounds bounds = new Bounds();
                            for (int r = 0; r < renderers.Length; r++)
                            {
                                Renderer renderer = renderers[r];
                                if (renderer == null)
                                    continue;
                                if (renderer.enabled && renderer.gameObject.activeInHierarchy)
                                    resultVisible = true;
                                if (!init)
                                {
                                    bounds = renderer.bounds;
                                    init = true;
                                }
                                else
                                {
                                    bounds.Encapsulate(renderer.bounds);
                                }
                            }
                            if (init)
                                boundsInfo = "center=" + bounds.center.ToString("F3") + ",size=" + bounds.size.ToString("F3");
                        }
                    }
                    catch { }

                    break;
                }
            }

            SuperController.LogMessage(
                "CharacterRouter v191 ALTFUTA MALE INTIMATE TEST | preset=" +
                (string.IsNullOrEmpty(presetLabel) ? "<none>" : presetLabel) +
                " | transferredStorables=" + transferred +
                " | suffixes=" + (transferredSuffixes.Count == 0 ? "<none>" : string.Join(",", transferredSuffixes.ToArray())) +
                " | resultVisible=" + resultVisible +
                " | rendererCount=" + rendererCount +
                " | bounds=" + boundsInfo
            );

            if (transferred <= 0)
            {
                detail = "Male->AltFuta retarget transferred 0 storables.";
                return false;
            }

            detail = "Applied AltFuta M->AF test preset " +
                (string.IsNullOrEmpty(presetLabel) ? "<none>" : presetLabel) +
                " on scaffold " +
                (string.IsNullOrEmpty(scaffoldDisplayName) ? "<none>" : scaffoldDisplayName) +
                " | transferred " + transferred + " storables";
            return true;
        }

        private IEnumerator ApplyExperimentalAltFutaMaleIntimatePreset(
            PersonEntry person,
            HairPresetEntry entry,
            Action<bool, string> completed)
        {
            if (person == null || entry == null)
            {
                if (completed != null)
                    completed(false, "Experimental AltFuta M->AF preset is invalid.");
                yield break;
            }

            if (!IsActiveAltFutaPerson(person))
            {
                if (completed != null)
                    completed(false, "Experimental M->AF presets are available only for AltFuta.");
                yield break;
            }

            if (string.IsNullOrEmpty(entry.altFutaMaleRetargetScaffoldPath))
            {
                if (completed != null)
                    completed(false, "Experimental M->AF preset has no scaffold path.");
                yield break;
            }

            HairPresetEntry scaffoldEntry = new HairPresetEntry();
            scaffoldEntry.path = entry.altFutaMaleRetargetScaffoldPath;
            scaffoldEntry.label = entry.label;
            scaffoldEntry.sex = "F";
            scaffoldEntry.region = "Pubic";
            scaffoldEntry.source = entry.source;
            scaffoldEntry.isRawHairItem = true;

            string scaffoldBuildError;
            JSONClass scaffoldPreset = BuildRawHairItemPresetJson(scaffoldEntry, out scaffoldBuildError);
            if (scaffoldPreset == null)
            {
                if (completed != null)
                    completed(false, "Could not build AltFuta scaffold preset: " + scaffoldBuildError);
                yield break;
            }

            bool applied = false;
            string appliedDetail = "";
            yield return StartCoroutine(
                ApplyHairPresetRegionJsonDirect(
                    person,
                    scaffoldPreset,
                    "F",
                    entry.label,
                    "Pubic",
                    false,
                    delegate(bool result, string msg)
                    {
                        applied = result;
                        appliedDetail = msg;
                    }
                )
            );

            if (!applied)
            {
                if (completed != null)
                    completed(false, "Scaffold apply failed: " + appliedDetail);
                yield break;
            }

            yield return null;
            yield return null;
            yield return null;

            string transferDetail;
            bool transferOk = RestoreExperimentalAltFutaMaleState(
                person,
                entry.path,
                entry.altFutaMaleRetargetScaffoldPath,
                entry.label,
                out transferDetail
            );

            if (completed != null)
                completed(transferOk, transferDetail);
        }

        private bool IsGeneratedAltFutaM2AfDisplayName(string displayName)
        {
            return !string.IsNullOrEmpty(displayName) &&
                displayName.Trim().StartsWith(
                    "Base Extra 02 M2AF",
                    StringComparison.OrdinalIgnoreCase
                );
        }

        // v196: the generated test HairFemale item must never become part of an
        // AltFuta Look merely because the package was registered / a Look was loaded.
        // Only the explicit INTIMATE card is allowed to activate it. This sanitizer
        // touches exactly our generated displayName and leaves every source-Look Hair
        // item unchanged. The active-bank dump also tells us whether the sparse hair
        // visible immediately after spawn actually came from our test asset.
        private IEnumerator SanitizeGeneratedAltFutaM2AfAfterLookCoroutine(
            Atom atom,
            string stage)
        {
            if (atom == null)
                yield break;

            for (int pass = 0; pass < 4; pass++)
            {
                DAZCharacterSelector selector = null;
                try
                {
                    JSONStorable geometry = atom.GetStorableByID("geometry");
                    selector = geometry as DAZCharacterSelector;
                    if (selector == null)
                        selector = atom.GetComponentInChildren<DAZCharacterSelector>();
                }
                catch { }

                if (selector == null)
                {
                    if (pass == 0)
                        SuperController.LogMessage(
                            "CharacterRouter v229 ALTFUTA STARTUP | stage=" + stage +
                            " | selector=<none>"
                        );
                    yield return null;
                    continue;
                }

                List<string> activeBefore = new List<string>();
                int disabledGenerated = 0;
                int disabledOriginalPubic = 0;
                bool clearOriginalPubic = string.Equals(
                    stage,
                    "FRESH_SPAWN",
                    StringComparison.OrdinalIgnoreCase
                );
                try
                {
                    foreach (var hair in selector.femaleHairItems)
                    {
                        if (hair == null || !hair.active)
                            continue;

                        string name = hair.displayName ?? "";
                        activeBefore.Add(name);

                        if (IsGeneratedAltFutaM2AfDisplayName(name))
                        {
                            selector.SetActiveHairItem(hair, false);
                            disabledGenerated++;
                            continue;
                        }

                        // v199: an AltFuta should enter the scene with an empty
                        // INTIMATE layer. Caroline's source Look activates Pubic 02;
                        // clear only explicitly pubic Hair on FRESH_SPAWN, preserving
                        // Scalp mid base / nika1 and every other Head/Face/Body item.
                        if (clearOriginalPubic &&
                            string.Equals(
                                ClassifyHairDescriptorExplicit(name),
                                "Pubic",
                                StringComparison.OrdinalIgnoreCase))
                        {
                            selector.SetActiveHairItem(hair, false);
                            disabledOriginalPubic++;
                        }
                    }
                }
                catch (Exception e)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v229 ALTFUTA STARTUP ERROR | stage=" + stage +
                        " | pass=" + pass + " | " + e.Message
                    );
                }

                if (pass == 0 || disabledGenerated > 0 || disabledOriginalPubic > 0)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v229 ALTFUTA STARTUP | stage=" + stage +
                        " | pass=" + pass +
                        " | activeFemaleBefore=" +
                        (activeBefore.Count == 0 ? "<none>" : string.Join(" ; ", activeBefore.ToArray())) +
                        " | disabledGenerated=" + disabledGenerated +
                        " | disabledOriginalPubic=" + disabledOriginalPubic
                    );
                }

                yield return null;
                yield return null;
            }
        }

