        private void LogV196AltFutaM2AfResult(PersonEntry person, HairPresetEntry entry)
        {
            if (person == null || person.atom == null || entry == null)
                return;

            try
            {
                DAZCharacterSelector selector = GetCharacterSelectorForPerson(person);
                if (selector == null)
                    return;

                bool found = false;
                foreach (var hair in selector.femaleHairItems)
                {
                    if (hair == null || !hair.active ||
                        !string.Equals(
                            hair.displayName,
                            "Base Extra 02 M2AF",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    found = true;
                    Renderer[] renderers = hair.GetComponentsInChildren<Renderer>(true);
                    bool visible = false;
                    bool init = false;
                    Bounds bounds = new Bounds();
                    int rendererCount = 0;

                    if (renderers != null)
                    {
                        rendererCount = renderers.Length;
                        for (int i = 0; i < renderers.Length; i++)
                        {
                            Renderer renderer = renderers[i];
                            if (renderer == null)
                                continue;

                            if (renderer.enabled && renderer.gameObject.activeInHierarchy)
                                visible = true;

                            if (!init)
                            {
                                bounds = renderer.bounds;
                                init = true;
                            }
                            else
                            {
                                bounds.Encapsulate(renderer.bounds);
                            }
                        }
                    }

                    SuperController.LogMessage(
                        "CharacterRouter v229 ALTFUTA M2AF | found=True" +
                        " | visible=" + visible +
                        " | rendererCount=" + rendererCount +
                        " | bounds=" + (init
                            ? "center=" + bounds.center.ToString("F3") + ",size=" + bounds.size.ToString("F3")
                            : "<none>")
                    );
                    break;
                }

                if (!found)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v229 ALTFUTA M2AF | found=False | active converted Hair item not found after click"
                    );
                }
            }
            catch (Exception e)
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA M2AF ERROR | " + e.Message
                );
            }
        }

        private void SelectHairPresetCard(HairPresetEntry entry)
        {
            if (entry == null || _hairPresetApplyInProgress || _controlledSpawnInProgress)
                return;

            StartCoroutine(ApplyHairPresetCoroutine(entry));
        }

        private IEnumerator ApplyHairPresetCoroutine(HairPresetEntry entry)
        {
            _hairPresetApplyInProgress = true;

            PersonEntry selected = GetSelectedPerson();
            if (selected == null || selected.atom == null)
            {
                UpdateHairHudStatus("HAIR — no selected Person");
                _hairPresetApplyInProgress = false;
                yield break;
            }

            string targetRegion = NormalizeEditableHairRegion(_hairRegion);

            if (IsAltFutaBodyMeshDiagnosticEntry(entry))
            {
                UpdateHairHudStatus("HAIR — exporting AltFuta body mesh diagnostic...");
                yield return StartCoroutine(ExportAltFutaBodyMeshDiagnostic(selected));
                _hairPresetApplyInProgress = false;
                RebuildHairCatalogPage();
                yield break;
            }

            if (IsAltFutaLiveScalpDiagnosticEntry(entry))
            {
                UpdateHairHudStatus("HAIR — exporting active AltFuta scalp diagnostic...");
                yield return StartCoroutine(ExportAltFutaLiveScalpDiagnostic(selected));
                _hairPresetApplyInProgress = false;
                RebuildHairCatalogPage();
                yield break;
            }

            if (!HairPresetHasRegion(entry, targetRegion))
            {
                UpdateHairHudStatus("HAIR — preset has no " + targetRegion + " layer");
                _hairPresetApplyInProgress = false;
                yield break;
            }

            string validationError;
            if (!entry.isSceneHair && !entry.isRawHairItem &&
                !ValidateHairPresetAssetFiles(entry.path, out validationError))
            {
                UpdateHairHudStatus("HAIR — load blocked: " + validationError);
                SuperController.LogMessage(
                    "CharacterRouter v229: Hair preset blocked before load for " + entry.path + ": " + validationError
                );
                _hairPresetApplyInProgress = false;
                yield break;
            }

            string snapshotWarning;
            bool snapshotReady = CaptureOriginalActiveHairItems(selected, out snapshotWarning);
            if (!snapshotReady && !string.IsNullOrEmpty(snapshotWarning))
                SuperController.LogMessage("CharacterRouter v229: " + snapshotWarning);

            DAZCharacterSelector externalHairSelector = GetCharacterSelectorForPerson(selected);
            bool externalHairDisabled = false;
            bool kaineHairHidden = false;
            string externalHairDetail = "";

            // ExternalHairAdapter is a head-hair compatibility layer. Beard/moustache
            // edits must never disable a Nico-style external hairstyle.
            if (targetRegion == "Head")
            {
                bool externalHairOk = _externalHairAdapter.CaptureAndDisable(
                    selected.atom,
                    externalHairSelector,
                    selected.uid,
                    out externalHairDisabled,
                    out externalHairDetail
                );

                if (!externalHairOk && !string.IsNullOrEmpty(externalHairDetail))
                    SuperController.LogMessage("CharacterRouter v229: " + externalHairDetail);

                if (externalHairDisabled)
                {
                    yield return null;
                    yield return null;
                    yield return null;
                }

                kaineHairHidden = _sceneCuaAccessoryAdapter.Set2BSceneHairVisible(
                    selected.atom, false);
            }

            string nativeSex = GetNativeHairSex(selected);
            bool isCrossGender =
                (entry.sex == "F" || entry.sex == "M") &&
                (nativeSex == "F" || nativeSex == "M") &&
                entry.sex != nativeSex;

            UpdateHairHudStatus(
                "HAIR — loading " + targetRegion.ToUpperInvariant() + " · " + entry.label + "..."
            );

            bool ok = false;
            string detail = "";

            if (IsV196AltFutaM2AfEntry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA M2AF | stage=CLICK" +
                    " | mode=UV_VERTEX_RETARGET" +
                    " | strands=131" +
                    " | medianRootShift=0.027089" +
                    " | maxRootShift=0.057576" +
                    " | asset=" + entry.path
                );
            }

            if (IsV204AltFutaStripPreserveEntry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA STRIP PRESERVE | stage=CLICK" +
                    " | mode=AFFINE_ROOT_PLANE_REGULARIZED_FEMALE_WRAP" +
                    " | strands=131 | rootsUnique=131 | geoRootsUnique=131" +
                    " | planeNormalWeight=4" +
                    " | snapMedian=0.004699" +
                    " | snapMax=0.010305" +
                    " | planeThicknessStd=0.002234" +
                    " | malePlaneThicknessStd=0.002741" +
                    " | femaleWrap=scalp_F_pubic | asset=" + entry.path
                );
            }

            if (IsV204AltFutaStripPreserveTightEntry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA STRIP PRESERVE TIGHT | stage=CLICK" +
                    " | mode=AFFINE_ROOT_PLANE_REGULARIZED_TIGHT_FEMALE_WRAP" +
                    " | strands=131 | rootsUnique=131 | geoRootsUnique=131" +
                    " | planeNormalWeight=32" +
                    " | snapMedian=0.005824" +
                    " | snapMax=0.015432" +
                    " | planeThicknessStd=0.002079" +
                    " | malePlaneThicknessStd=0.002741" +
                    " | femaleWrap=scalp_F_pubic | asset=" + entry.path
                );
            }

            if (IsV225AltFutaFinalBaseExtra02Entry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA FINAL BASE EXTRA 02 | stage=CLICK" +
                    " | mode=FEMALE_BIND_UINT4_FEMALE_OTHER_FLOATS_ASYMMETRIC_F1_F2_TO_MALE" +
                    " | f1Blend=0.19 | f2Blend=0.235 | maleVertices=1468 | maleUV=1593 | strands=131" +
                    " | mappedMaleUV=1593 | femaleDonorsUsed=490" +
                    " | mapMedian=0.017945 | mapP90=0.031947 | mapMax=0.074063" +
                    " | asset=" + entry.path
                );
            }

            if (IsV214AltFutaF0OnlyEntry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA SKINWRAP COMPONENT F0 | stage=CLICK" +
                    " | mode=FEMALE_BIND_UINT4_FEMALE_OTHER_FLOATS_MALE_F0" +
                    " | maleVertices=1468 | maleUV=1593 | strands=131" +
                    " | mappedMaleUV=1593 | femaleDonorsUsed=490" +
                    " | mapMedian=0.017945 | mapP90=0.031947 | mapMax=0.074063" +
                    " | asset=" + entry.path
                );
            }

            if (IsV214AltFutaF1OnlyEntry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA SKINWRAP COMPONENT F1 | stage=CLICK" +
                    " | mode=FEMALE_BIND_UINT4_FEMALE_OTHER_FLOATS_MALE_F1" +
