                    " | mode=RUNTIME_GUIDE_GEOMETRY_AFFINE_BLEND" +
                    " | strands=131 | segments=10 | blend=0.50" +
                    " | rootIndices=UNCHANGED_V196_FEMALE" +
                    " | rootOffsetMedian=0.003261" +
                    " | rootOffsetMax=0.018020" +
                    " | relativeStrandMaxError=0.000000004" +
                    " | femaleWrap=scalp_F_pubic | asset=" + entry.path
                );
            }

            if (IsV208AltFutaGuideOffset100Entry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA GUIDE OFFSET 100 | stage=CLICK" +
                    " | mode=RUNTIME_GUIDE_GEOMETRY_AFFINE_FULL" +
                    " | strands=131 | segments=10 | blend=1.00" +
                    " | rootIndices=UNCHANGED_V196_FEMALE" +
                    " | rootOffsetMedian=0.006522" +
                    " | rootOffsetMax=0.036039" +
                    " | relativeStrandMaxError=0.000000004" +
                    " | femaleWrap=scalp_F_pubic | asset=" + entry.path
                );
            }

            if (IsV207AltFutaCloudPreserveEntry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA CLOUD PRESERVE | stage=CLICK" +
                    " | mode=KNN_SHAPE_PRESERVING_ASSIGNMENT_FEMALE_WRAP" +
                    " | strands=131 | rootsUnique=131 | geoRootsUnique=131" +
                    " | lockedRoots=2 | knnEdges=518" +
                    " | snapMedian=0.005763" +
                    " | snapMax=0.015729" +
                    " | planeThicknessStd=0.002223" +
                    " | neighborErrorMedian=0.002305" +
                    " | neighborErrorMean=0.002958" +
                    " | femaleWrap=scalp_F_pubic | asset=" + entry.path
                );
            }

            if (IsV206AltFutaCenterlinePreserveEntry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA CENTERLINE PRESERVE | stage=CLICK" +
                    " | mode=SAFE_ROOT_POOL_CENTERLINE_SMOOTH_FEMALE_WRAP" +
                    " | strands=131 | rootsUnique=131 | geoRootsUnique=131" +
                    " | safeRootPool=168 | safeGeoPool=165" +
                    " | changedRoots=35 | newSafeRoots=8" +
                    " | snapMedian=0.003772 | snapMax=0.053574" +
                    " | meanShiftFromTight=0.002023" +
                    " | femaleWrap=scalp_F_pubic | asset=" + entry.path
                );
            }

            if (IsV206AltFutaEdgeCompressionEntry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA EDGE COMPRESSION | stage=CLICK" +
                    " | mode=SAFE_ROOT_POOL_EDGE_COMPRESS_FEMALE_WRAP" +
                    " | strands=131 | rootsUnique=131 | geoRootsUnique=131" +
                    " | safeRootPool=168 | safeGeoPool=165" +
                    " | changedRoots=32 | newSafeRoots=8" +
                    " | snapMedian=0.004255 | snapMax=0.053574" +
                    " | meanShiftFromTight=0.001790" +
                    " | femaleWrap=scalp_F_pubic | asset=" + entry.path
                );
            }

            if (IsV203AltFutaRegularizedSimilarityEntry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA REGULARIZED SIMILARITY | stage=CLICK" +
                    " | mode=GLOBAL_ROOT_SIMILARITY_FEMALE_WRAP" +
                    " | strands=131" +
                    " | rootsUnique=131" +
                    " | similarityScale=1.155615" +
                    " | snapMedian=0.006653" +
                    " | snapMax=0.029745" +
                    " | residualToUVTargetsMedian=0.007597" +
                    " | femaleWrap=scalp_F_pubic" +
                    " | asset=" + entry.path
                );
            }

            if (IsV203AltFutaRegularizedAffineEntry(entry))
            {
                SuperController.LogMessage(
                    "CharacterRouter v229 ALTFUTA REGULARIZED AFFINE | stage=CLICK" +
                    " | mode=GLOBAL_ROOT_AFFINE_FEMALE_WRAP" +
                    " | strands=131" +
                    " | rootsUnique=131" +
                    " | snapMedian=0.006338" +
                    " | snapMax=0.017589" +
                    " | residualToUVTargetsMedian=0.006522" +
                    " | femaleWrap=scalp_F_pubic" +
                    " | asset=" + entry.path
                );
            }

            // v153: Head and Facial remain isolated logical layers; legacy preset compatibility is handled by IsHairNodeEnabled().
            // Using VaM's full HairPresets loader for native Head would allow a mixed
            // hairstyle+beard preset to replace Facial too, defeating separation.
            if (entry.isExperimentalAltFutaMaleRetarget)
            {
                yield return StartCoroutine(
                    ApplyExperimentalAltFutaMaleIntimatePreset(
                        selected,
                        entry,
                        delegate(bool result, string msg)
                        {
                            ok = result;
                            detail = msg;
                        }
                    )
                );
            }
            else
            {
                string loadError;
                JSONClass preset = LoadHairPresetJson(entry.path, entry.source, out loadError);
                if (preset == null)
                {
                    UpdateHairHudStatus("HAIR — load failed: " + loadError);
                    _hairPresetApplyInProgress = false;
                    yield break;
                }

                bool directOk = false;
                string directDetail = "";
                JSONClass regionProbe = BuildHairRegionOnlyPresetJson(preset, targetRegion);

                // v196: a raw HairFemale .vam is NOT a HairPresets .vap. In v195 the
                // generic empty-region fallback treated our generated M2AF raw item as
                // a legacy preset and passed its .vam path to HairPresets.LoadPreset,
                // which produced VaM's "not compatible with store folder" /
                // "Not all preset parameters set" errors. The converted M2AF item
                // must always stay on the direct live-bank activation path.
                bool generatedAltFutaM2Af = IsV196AltFutaM2AfEntry(entry);
                bool altFutaRawIntimate =
                    entry != null &&
                    entry.isRawHairItem &&
                    entry.isAltFutaIntimate;
                bool useLegacyNativeFallback =
                    !generatedAltFutaM2Af &&
                    !altFutaRawIntimate &&
                    !HairPresetHasEnabledGeometryItems(regionProbe);

                // v230: ordinary Male -> Male HEAD Hair with authored Sim state still
                // prefers VaM's native HairPresets initialization path, but only when
                // the preset's enabled Hair component can already be resolved against
                // the live Male bank. This preserves the v229 fix for styles such as
                // Male Hair1 with Sim without hijacking legacy alias-mismatch presets
                // such as Chris Redfield. Those stay on the proven v155 route:
                // direct resolver -> "Unavailable Hair component" -> native alias fallback.
                bool maleHeadSimCandidate =
                    !isCrossGender &&
                    string.Equals(targetRegion, "Head", StringComparison.OrdinalIgnoreCase) &&
                    string.Equals(nativeSex, "M", StringComparison.OrdinalIgnoreCase) &&
                    string.Equals(entry.sex, "M", StringComparison.OrdinalIgnoreCase) &&
                    !entry.isRawHairItem &&
                    !entry.isSceneHair &&
                    HairPresetHasNativeSimState(preset);

                bool maleHeadSimPreflightOk = true;
                string maleHeadSimPreflightDetail = "";
                if (maleHeadSimCandidate)
                {
                    List<string> preflightResolvedNames;
                    HashSet<int> preflightInstanceIds;
                    maleHeadSimPreflightOk = ResolvePresetHairDisplayNames(
                        selected,
                        preset,
                        entry.sex,
                        out preflightResolvedNames,
                        out preflightInstanceIds,
                        out maleHeadSimPreflightDetail
                    );
                }

                bool preferNativeMaleHeadSimLoad =
                    maleHeadSimCandidate && maleHeadSimPreflightOk;

                if (preferNativeMaleHeadSimLoad)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v231 MALE HEAD NATIVE SIM PATH | stage=ROUTE" +
                        " | preset=" + entry.label +
                        " | asset=" + entry.path
                    );
                }
                else if (maleHeadSimCandidate)
                {
                    SuperController.LogMessage(
                        "CharacterRouter v231 MALE HEAD NATIVE SIM PATH | stage=SKIP_ALIAS" +
                        " | preset=" + entry.label +
                        " | detail=" + maleHeadSimPreflightDetail +
                        " | asset=" + entry.path
                    );
                }

                // v169: safe rollback of the v167/v168 native-HairPresets experiment.
                // Native Futanari cross-gender Hair is again applied through the isolated
                // exact-source adapter path, which was the stable behavior before v167.
                // The adapter remains a separate module; only the risky full opposite-bank
                // native preset load is disabled because it caused missing SimV2 Hair items
                // and broke RESET HEAD on native Futanari.
                if (isCrossGender)
                {
                    yield return StartCoroutine(
                        ApplyHairPresetRegionJsonDirect(
                            selected,
                            preset,
                            entry.sex,
                            entry.label,
                            targetRegion,
                            true,
                            delegate(bool result, string msg)
                            {
                                directOk = result;
                                directDetail = msg;
                            }
                        )
                    );
                }
                else if (preferNativeMaleHeadSimLoad)
                {
                    string nativeLoadPath;
                    string nativePathError;
                    if (!GetNativeHairLoadPath(entry, out nativeLoadPath, out nativePathError))
                    {
                        directOk = false;
                        directDetail = "Could not prepare native Male HEAD Sim load: " + nativePathError;
                    }
                    else
                    {
                        yield return StartCoroutine(
                            ApplyLegacyHairPresetRegionViaNativeLoad(
                                selected,
                                nativeLoadPath,
                                targetRegion,
                                false,
                                delegate(bool result, string msg)
                                {
                                    directOk = result;
                                    directDetail = msg;
                                }
                            )
                        );
                    }

                    SuperController.LogMessage(
                        "CharacterRouter v231 MALE HEAD NATIVE SIM PATH | stage=RESULT" +
                        " | ok=" + directOk +
                        " | preset=" + entry.label +
                        " | detail=" + (string.IsNullOrEmpty(directDetail) ? "<none>" : directDetail)
                    );

                    // If VaM refuses this particular native preset path, preserve the
                    // old behavior rather than turning the regression fix into a load
                    // failure. The fallback may still show the old visual issue, but
                    // the card remains usable and the log tells us exactly what happened.
                    if (!directOk)
                    {
                        string nativeFailureDetail = directDetail;
                        yield return StartCoroutine(
                            ApplyHairPresetRegionJsonDirect(
                                selected,
                                preset,
                                entry.sex,
                                entry.label,
                                targetRegion,
                                false,
                                delegate(bool result, string msg)
                                {
                                    directOk = result;
                                    directDetail = msg;
                                }
                            )
                        );
                        if (!string.IsNullOrEmpty(nativeFailureDetail))
                            directDetail = directDetail + " | Native Sim path failed: " + nativeFailureDetail;
                    }
                }
                else if (useLegacyNativeFallback)
                {
                    string nativeLoadPath;
                    string nativePathError;
                    if (!GetNativeHairLoadPath(entry, out nativeLoadPath, out nativePathError))
                    {
                        directOk = false;
                        directDetail = "Could not prepare native scene Hair fallback: " + nativePathError;
                    }
                    else
                    {
                        yield return StartCoroutine(
                            ApplyLegacyHairPresetRegionViaNativeLoad(
                                selected,
                                nativeLoadPath,
                                targetRegion,
                                entry.isSceneHair,
                                delegate(bool result, string msg)
                                {
                                    directOk = result;
                                    directDetail = msg;
                                }
                            )
                        );
                    }
                }
                else
                {
                    yield return StartCoroutine(
                        ApplyHairPresetRegionJsonDirect(
                            selected,
                            preset,
                            entry.sex,
                            entry.label,
                            targetRegion,
                            false,
                            delegate(bool result, string msg)
                            {
                                directOk = result;
                                directDetail = msg;
                            }
                        )
                    );
                }

                // v155: some native presets serialize a valid internalId that VaM later
                // exposes under a substantially different live-bank display name. Chris
                // Redfield is a confirmed example: the preset requests
                // "Ben-g Copper:Male hair Chris 03", while manual bank resolution cannot
                // identify a matching CustomHairItem. The direct resolver has made no
                // switch at this point, so for SAME-SEX presets it is safe to retry through
                // VaM's native HairPresets loader and then isolate the requested region
                // using the already-tested legacy fallback. Cross-gender presets are handled earlier by NativeFutanariHairAdapter and do not enter this same-sex retry.
                if (!directOk && !isCrossGender &&
                    !useLegacyNativeFallback &&
                    !string.IsNullOrEmpty(directDetail) &&
                    directDetail.StartsWith("Unavailable Hair component", StringComparison.OrdinalIgnoreCase))
                {
                    bool fallbackOk = false;
                    string fallbackDetail = "";
                    string nativeLoadPath;
                    string nativePathError;
                    if (!GetNativeHairLoadPath(entry, out nativeLoadPath, out nativePathError))
                    {
                        fallbackDetail = "Could not prepare native scene Hair fallback: " + nativePathError;
                    }
                    else
                    {
                        yield return StartCoroutine(
                            ApplyLegacyHairPresetRegionViaNativeLoad(
                                selected,
                                nativeLoadPath,
                                targetRegion,
                                entry.isSceneHair,
                                delegate(bool result, string msg)
                                {
                                    fallbackOk = result;
                                    fallbackDetail = msg;
                                }
                            )
                        );
                    }

                    if (fallbackOk)
                    {
                        directOk = true;
                        directDetail = "Applied " + targetRegion +
                            " Hair layer via native VaM fallback (live-bank alias mismatch).";
                    }
                    else if (!string.IsNullOrEmpty(fallbackDetail))
                    {
                        directDetail = directDetail + " | Native fallback: " + fallbackDetail;
                    }
                }

                ok = directOk;
                detail = directDetail;
            }

            if (!ok)
            {
                if (externalHairDisabled)
                {
                    bool restoredExternal = false;
                    string restoreExternalDetail = "";
                    _externalHairAdapter.RestoreOriginal(
                        selected.atom,
                        externalHairSelector,
                        selected.uid,
                        out restoredExternal,
                        out restoreExternalDetail
                    );
                }
                if (kaineHairHidden)
                    _sceneCuaAccessoryAdapter.Set2BSceneHairVisible(
                        selected.atom, true);

                UpdateHairHudStatus("HAIR — load failed: " + detail);
                SuperController.LogError(
                    "CharacterRouter v231: " + targetRegion + " Hair preset load failed for " +
                    entry.path + ": " + detail
                );
                _hairPresetApplyInProgress = false;
                yield break;
            }

            if (IsV196AltFutaM2AfEntry(entry))
                LogV196AltFutaM2AfResult(selected, entry);

            _activeHairPresetByPerson[GetHairActiveKey(selected.uid, targetRegion)] = entry.path;
            SaveActiveHairPresetsData();

            UpdateHairHudStatus(
                !string.IsNullOrEmpty(detail)
                    ? "HAIR — " + detail
                    : "HAIR — applied " + targetRegion.ToUpperInvariant() + " · " + entry.label
            );
            RebuildHairCatalogPage();
            _hairPresetApplyInProgress = false;
        }

        private void AddAppearanceEntry(string path, string source)
        {
            if (string.IsNullOrEmpty(path))
                return;

            path = NormalizePathSlashes(path);

            // Extracted scene Looks are implementation files used only as load
            // targets for VaM's AppearancePresets storable.  FileManagerSecure
            // may return descendant files even when scanning the parent Appearance
            // folder, so filtering only the directory name is not sufficient.
            if (IsCharacterRouterExtractedAppearancePath(path))
                return;

            // FileManagerSecure's "Custom/..." view is a mounted union: a packaged
            // preset can already appear during the first "local" scan.  At that
            // point we only know source="Local", so an old preset with weak/absent
            // gender metadata (Gara Mond is a real example) can be cached as [?].
            // The later explicit AddonPackages pass sees the SAME virtual path with
            // the real package UID (e.g. kemenate.Female_Looks.*).  Older versions
            // deduplicated by path and returned immediately, so the stronger package
            // metadata never got a chance to repair the entry.
            //
            // v53 treats an explicit package scan as an information upgrade rather
            // than a duplicate: re-run sex detection with the package UID and replace
            // an unknown classification when we can now resolve it.
            for (int i = 0; i < _appearanceEntries.Count; i++)
            {
                AppearanceEntry existing = _appearanceEntries[i];

                if (existing == null ||
                    !string.Equals(
                        existing.path,
                        path,
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                bool incomingHasPackageSource =
                    !string.IsNullOrEmpty(source) &&
                    !string.Equals(
                        source,
                        "Local",
                        StringComparison.OrdinalIgnoreCase);

                bool existingHasPackageSource =
                    !string.IsNullOrEmpty(existing.source) &&
                    !string.Equals(
                        existing.source,
                        "Local",
                        StringComparison.OrdinalIgnoreCase);

                if (incomingHasPackageSource && !existingHasPackageSource)
                    existing.source = source;

                bool incomingAltFuta =
                    _altFutaAdapter.IsAltFutaAppearance(
                        path,
                        source,
                        GetPresetLabel(path)
                    );

                if (incomingAltFuta)
                    existing.isAltFuta = true;

                if (existing.sex == "?" && incomingHasPackageSource)
                {
                    string upgradedSex =
                        DetectAppearancePresetSex(path, source);

                    if (upgradedSex == "F" ||
                        upgradedSex == "M" ||
                        upgradedSex == "X")
                    {
                        existing.sex = upgradedSex;
                    }
                }

                // Keep thumbnail/label repair harmless for union-scan entries.
                if (string.IsNullOrEmpty(existing.label))
                    existing.label = GetPresetLabel(path);

                if (string.IsNullOrEmpty(existing.thumbnailPath))
                    existing.thumbnailPath = GetSiblingJpgPath(path);

                return;
            }

            AppearanceEntry entry = new AppearanceEntry();
            entry.path = path;
            entry.label = GetPresetLabel(path);
            entry.thumbnailPath = GetSiblingJpgPath(path);
            entry.isAltFuta =
                _altFutaAdapter.IsAltFutaAppearance(
                    path,
                    source,
                    entry.label
                );
            entry.sex = DetectAppearancePresetSex(path, source);
            entry.source = source;

            _appearanceEntries.Add(entry);
        }

        private void ScanAppearanceDirectoryRecursive(
            string root,
            string source,
            int depth)
        {
            if (string.IsNullOrEmpty(root) || depth > 12)
                return;

            // Scene-Look extraction files are implementation details, not user
            // Appearance presets.  Keep them out of the normal Looks catalog.
            if (root.IndexOf(
                    "Custom/Atom/Person/Appearance/CharacterRouter_Extracted",
                    StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return;
            }

            try
            {
                var files = FileManagerSecure.GetFiles(root, "*.vap");
                foreach (string f in files)
                {
                    if (IsCharacterRouterExtractedAppearancePath(f))
                        continue;

                    AddAppearanceEntry(f, source);
                }
            }
            catch { }

            try
            {
                var dirs = FileManagerSecure.GetDirectories(root, "*");
                foreach (string dir in dirs)
                    ScanAppearanceDirectoryRecursive(dir, source, depth + 1);
            }
            catch { }
        }

        private void CollectVarFilesRecursive(
            string root,
            List<string> varFiles,
            int depth)
        {
            if (string.IsNullOrEmpty(root) || depth > 12)
                return;

            try
            {
                var files = FileManagerSecure.GetFiles(root, "*.var");
                foreach (string f in files)
                    varFiles.Add(NormalizePathSlashes(f));
            }
            catch { }

            try
            {
                var dirs = FileManagerSecure.GetDirectories(root, "*");
                foreach (string dir in dirs)
                    CollectVarFilesRecursive(dir, varFiles, depth + 1);
            }
            catch { }
        }

        private string GetVarPackageUid(string varPath)
        {
            string p = NormalizePathSlashes(varPath);
            int slash = p.LastIndexOf('/');
            string fileName = slash >= 0 ? p.Substring(slash + 1) : p;

            if (fileName.EndsWith(".var", StringComparison.OrdinalIgnoreCase))
                fileName = fileName.Substring(0, fileName.Length - 4);

            return fileName;
        }

        private void RequestAppearanceCatalogScan()
        {
            if (_appearanceScanRunning)
                return;

            StartCoroutine(ScanAppearanceCatalogCoroutine());
        }

        private IEnumerator ScanAppearanceCatalogCoroutine()
        {
            _appearanceScanRunning = true;
            _appearanceCatalogScanned = false;
            _appearanceEntries.Clear();

            if (_lookCatalogStatus != null)
                _lookCatalogStatus.valNoCallback = "Looks: scanning local presets...";

            UpdateLookHudStatus("LOOKS — scanning local presets...");

            ScanAppearanceDirectoryRecursive(
                "Custom/Atom/Person/Appearance",
                "Local",
                0
            );

            // Show local results immediately.
            SortAppearanceEntries();
            RebuildLookCatalogPage();
            yield return null;

            bool scanPackages =
                (_scanVarAppearancePresets != null &&
                 _scanVarAppearancePresets.val) ||
                (_scanSceneCharacters != null &&
                 _scanSceneCharacters.val);

            if (scanPackages)
            {
                List<string> vars = new List<string>();
                CollectVarFilesRecursive("AddonPackages", vars, 0);

                for (int i = 0; i < vars.Count; i++)
                {
                    string packageUid = GetVarPackageUid(vars[i]);
                    RememberPackageModifiedTime(packageUid, vars[i]);

                    if (!string.IsNullOrEmpty(packageUid))
                    {
                        if (_scanVarAppearancePresets != null &&
                            _scanVarAppearancePresets.val)
                        {
                            string appearanceRoot =
                                packageUid + ":/Custom/Atom/Person/Appearance";

                            ScanAppearanceDirectoryRecursive(
                                appearanceRoot,
                                packageUid,
                                0
                            );
                        }

                        // Scene characters are a fallback for packages that do not
                        // already provide a proper Appearance preset. This avoids
                        // duplicate cards for resources such as Lucie Futa that ship
                        // both a scene and a reusable .vap, while still surfacing
                        // scene-only Looks such as Sara Futa.
                        if (_scanSceneCharacters != null &&
                            _scanSceneCharacters.val &&
                            !HasAppearancePresetFromSource(packageUid))
                        {
                            string sceneRoot =
                                packageUid + ":/Saves/scene";

                            ScanSceneDirectoryRecursive(
                                sceneRoot,
                                packageUid,
                                0
                            );
                        }
                    }

                    if (i % 10 == 0)
                    {
                        int sceneCount = CountSceneLookEntries();
                        int presetCount = _appearanceEntries.Count - sceneCount;

                        string progress =
                            "LOOKS — packages " + (i + 1) + "/" + vars.Count +
                            " | presets " + presetCount +
                            " | scene looks " + sceneCount;

                        if (_lookCatalogStatus != null)
                            _lookCatalogStatus.valNoCallback = progress;

                        UpdateLookHudStatus(progress);
                        yield return null;
                    }
                }
            }

            SortAppearanceEntries();
            RepairSceneLookStateAfterCatalogScan();

            _appearanceScanRunning = false;
            _appearanceCatalogScanned = true;

            int finalSceneCount = CountSceneLookEntries();
            int finalPresetCount = _appearanceEntries.Count - finalSceneCount;

            string finalStatus =
                "Looks: " + _appearanceEntries.Count + " total (" +
                finalPresetCount + " preset(s) + " +
                finalSceneCount + " scene character(s))";

            if (_lookCatalogStatus != null)
                _lookCatalogStatus.valNoCallback = finalStatus;

            UpdateLookHudStatus(
                "LOOKS — " + _appearanceEntries.Count + " look(s)"
            );

            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;

            RebuildLookCatalogPage();
        }

        private void SortAppearanceEntries()
        {
            _appearanceEntries.Sort(delegate(AppearanceEntry a, AppearanceEntry b) {
                int byLabel = string.Compare(
                    a.label,
                    b.label,
                    StringComparison.OrdinalIgnoreCase
                );

                if (byLabel != 0)
                    return byLabel;

                return string.Compare(
                    a.path,
                    b.path,
                    StringComparison.OrdinalIgnoreCase
                );
            });
        }

        private string GetCurrentAppearanceTargetSex()
        {
            if (IsCharacterCreationMode())
                return _creationModeSex;

            PersonEntry selected =
                GetSelectedPerson();

            if (selected == null)
                return "?";

            return GetCharacterCatalogSex(selected);
        }

        private bool IsAppearanceEntryCompatible(
            AppearanceEntry entry,
            string selectedSex)
        {
            if (entry == null)
                return false;

            bool showAllSexes =
                _showIncompatible != null &&
                _showIncompatible.val;

            if (showAllSexes)
                return true;

            if (selectedSex == "?")
                return false;

            return GetAppearanceCatalogSex(entry) == selectedSex;
        }

        private AppearanceEntry FindAppearanceEntryByPath(string path)
        {
            if (string.IsNullOrEmpty(path))
                return null;

            for (int i = 0; i < _appearanceEntries.Count; i++)
            {
                if (string.Equals(
                    _appearanceEntries[i].path,
                    path,
                    StringComparison.OrdinalIgnoreCase))
                {
                    return _appearanceEntries[i];
                }
            }

            return null;
        }

        private AppearanceEntry FindSceneAppearanceEntryByTempPath(string tempPath)
        {
            if (string.IsNullOrEmpty(tempPath))
                return null;

            string normalized = NormalizePathSlashes(tempPath);

            for (int i = 0; i < _appearanceEntries.Count; i++)
            {
                AppearanceEntry entry = _appearanceEntries[i];
                if (entry == null || !entry.isSceneLook)
                    continue;

                string candidate = NormalizePathSlashes(
                    GetSceneLookTempPath(entry)
                );

                if (string.Equals(
                        candidate,
                        normalized,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return entry;
                }
            }

            return null;
        }

        private void RepairSceneLookStateAfterCatalogScan()
        {
            bool aliasesChanged = false;
            bool originalsChanged = false;
            bool activeChanged = false;
            Dictionary<string, string> activeRepairs =
                new Dictionary<string, string>();

            foreach (KeyValuePair<string, string> kv in _activeLookByPerson)
            {
                if (string.IsNullOrEmpty(kv.Key) ||
                    string.IsNullOrEmpty(kv.Value))
                {
                    continue;
                }

                AppearanceEntry entry = FindAppearanceEntryByPath(kv.Value);

                // v58/v59 reset logic could replace the stable SCENELOOK key with
                // the temporary extracted .vap path.  Those temp files are hidden
                // from the catalog in v60, so recover the scene entry by reproducing
                // its deterministic temp path/hash.
                if ((entry == null || !entry.isSceneLook) &&
                    IsCharacterRouterExtractedAppearancePath(kv.Value))
                {
                    entry = FindSceneAppearanceEntryByTempPath(kv.Value);
                    if (entry != null)
                    {
                        activeRepairs[kv.Key] = entry.path;
                        activeChanged = true;
                    }
                }

                if (entry == null || !entry.isSceneLook)
                    continue;

                string alias;
                if (_aliases.TryGetValue(kv.Key, out alias) &&
                    IsInternalSceneLookDisplayName(alias))
                {
                    _aliases[kv.Key] = entry.label;
                    aliasesChanged = true;
                }

                string snapshot;
                if (_originalLookByPerson.TryGetValue(kv.Key, out snapshot) &&
                    !string.IsNullOrEmpty(snapshot) &&
                    snapshot.StartsWith(
                        "PATH:",
                        StringComparison.OrdinalIgnoreCase))
                {
                    string oldPath = snapshot.Substring(5);
                    if (IsCharacterRouterExtractedAppearancePath(oldPath))
                    {
                        _originalLookByPerson[kv.Key] =
                            "LOOKKEY:" + entry.path;
                        originalsChanged = true;
                    }
                }
            }

            foreach (KeyValuePair<string, string> repair in activeRepairs)
                _activeLookByPerson[repair.Key] = repair.Value;

            if (activeChanged)
                SaveActiveLooksData();

            if (aliasesChanged)
                SaveAliasesData();

            if (originalsChanged)
                SaveOriginalLooksData();
        }

        private List<AppearanceEntry> GetFilteredAppearanceEntries()
        {
            List<AppearanceEntry> result = new List<AppearanceEntry>();

            string sex =
                GetCurrentAppearanceTargetSex();

            string subsection =
                _subsection != null ? _subsection.val : "All";

            bool scenesView = string.Equals(
                subsection,
                "Scenes",
                StringComparison.OrdinalIgnoreCase
            );

            if (string.Equals(
                    subsection,
                    "Recent",
                    StringComparison.OrdinalIgnoreCase))
            {
                for (int i = 0; i < _recentLookPaths.Count; i++)
                {
                    AppearanceEntry entry =
                        FindAppearanceEntryByPath(
                            _recentLookPaths[i]
                        );

                    if (entry != null &&
                        IsAppearanceEntryCompatible(entry, sex))
                    {
                        result.Add(entry);
                    }
                }

                ApplyLookCatalogFiltersAndSort(result);
                return result;
            }

            for (int i = 0; i < _appearanceEntries.Count; i++)
            {
                AppearanceEntry entry = _appearanceEntries[i];

                if (!IsAppearanceEntryCompatible(entry, sex))
                    continue;

                // Scene-contained Persons are an explicit import source.  Do not
                // flood the normal ALL catalog with every Person found in every
                // installed scene package.  They are shown only in SCENES (or if
                // the user explicitly favorited one).
                if (scenesView)
                {
                    if (!entry.isSceneLook)
                        continue;
                }
                else if (string.Equals(
                            subsection,
                            "All",
                            StringComparison.OrdinalIgnoreCase))
                {
                    if (entry.isSceneLook)
                        continue;
                }

                if (string.Equals(
                        subsection,
                        "Favorites",
                        StringComparison.OrdinalIgnoreCase))
                {
                    if (!_favoriteLookPaths.Contains(entry.path))
                        continue;
                }

                result.Add(entry);
            }

            ApplyLookCatalogFiltersAndSort(result);
            return result;
        }

        private List<ScenePackageGroup> BuildScenePackageGroups(List<AppearanceEntry> entries)
        {
            Dictionary<string, ScenePackageGroup> map =
                new Dictionary<string, ScenePackageGroup>(StringComparer.OrdinalIgnoreCase);

            if (entries != null)
            {
                for (int i = 0; i < entries.Count; i++)
                {
                    AppearanceEntry entry = entries[i];
                    if (entry == null || !entry.isSceneLook)
                        continue;

                    string source = GetCatalogPackage(entry.source);
                    string key = string.IsNullOrEmpty(source) ? "Local" : source;
                    ScenePackageGroup group;
                    if (!map.TryGetValue(key, out group))
                    {
                        group = new ScenePackageGroup();
                        group.source = key;
                        group.label = key;
                        group.creator = GetCatalogCreator(entry.source, entry.scenePath);
                        group.thumbnailPath = entry.thumbnailPath;
                        group.count = 0;
                        group.newestTicks = 0L;
                        map[key] = group;
                    }

                    group.count++;
                    long ticks = GetCatalogModifiedTicks(entry.source, entry.scenePath);
                    if (ticks > group.newestTicks)
                        group.newestTicks = ticks;
                    if (string.IsNullOrEmpty(group.thumbnailPath) && !string.IsNullOrEmpty(entry.thumbnailPath))
                        group.thumbnailPath = entry.thumbnailPath;
                }
            }

            List<ScenePackageGroup> groups = new List<ScenePackageGroup>(map.Values);
            groups.Sort(delegate(ScenePackageGroup a, ScenePackageGroup b)
            {
                if (_lookNewOnly)
                {
                    int t = (b == null ? 0L : b.newestTicks).CompareTo(a == null ? 0L : a.newestTicks);
                    if (t != 0) return t;
                }

                if (string.Equals(_lookSortMode, "Name Z-A", StringComparison.OrdinalIgnoreCase))
                    return -CompareCatalogStrings(a == null ? "" : a.label, b == null ? "" : b.label);

                if (string.Equals(_lookSortMode, "Creator", StringComparison.OrdinalIgnoreCase))
                {
                    int c = CompareCatalogStrings(a == null ? "" : a.creator, b == null ? "" : b.creator);
                    if (c != 0) return c;
                }

                return CompareCatalogStrings(a == null ? "" : a.label, b == null ? "" : b.label);
            });

            if (_lookNewOnly && groups.Count > NEWEST_CATALOG_LIMIT)
                groups.RemoveRange(NEWEST_CATALOG_LIMIT, groups.Count - NEWEST_CATALOG_LIMIT);

            return groups;
        }

        private List<AppearanceEntry> FilterSceneEntriesToSelectedPackage(List<AppearanceEntry> entries)
        {
            if (entries == null || string.IsNullOrEmpty(_sceneSelectedPackage))
                return entries ?? new List<AppearanceEntry>();

            List<AppearanceEntry> result = new List<AppearanceEntry>();
            for (int i = 0; i < entries.Count; i++)
            {
                AppearanceEntry entry = entries[i];
                if (entry == null) continue;
                string package = GetCatalogPackage(entry.source);
                if (string.Equals(package, _sceneSelectedPackage, StringComparison.OrdinalIgnoreCase))
                    result.Add(entry);
            }
            return result;
        }

        private int GetLookDisplayCount(List<AppearanceEntry> filtered)
        {
            string subsection = _subsection != null ? _subsection.val : "All";
            bool scenesView = string.Equals(subsection, "Scenes", StringComparison.OrdinalIgnoreCase);
            if (!scenesView || !_scenePackagesMode)
                return filtered == null ? 0 : filtered.Count;

            if (string.IsNullOrEmpty(_sceneSelectedPackage))
                return BuildScenePackageGroups(filtered).Count;

            return FilterSceneEntriesToSelectedPackage(filtered).Count;
        }

        private void GoToFirstLookPage()
        {
            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;
            RebuildLookCatalogPage();
        }

        private void GoToLastLookPage()
        {
            List<AppearanceEntry> filtered = GetFilteredAppearanceEntries();
            int displayCount = GetLookDisplayCount(filtered);
            int pageCount = Mathf.Max(1, Mathf.CeilToInt(displayCount / (float)LOOKS_PER_PAGE));
            if (_catalogPage != null)
                _catalogPage.valNoCallback = pageCount;
            RebuildLookCatalogPage();
        }

        private void ChangeLookPage(int delta)
        {
            List<AppearanceEntry> filtered = GetFilteredAppearanceEntries();
            int displayCount = GetLookDisplayCount(filtered);
            int pageCount = Mathf.Max(
                1,
                Mathf.CeilToInt(displayCount / (float)LOOKS_PER_PAGE)
            );

            int page = _catalogPage != null
                ? Mathf.RoundToInt(_catalogPage.val)
                : 1;

            page = Mathf.Clamp(page + delta, 1, pageCount);

            if (_catalogPage != null)
                _catalogPage.valNoCallback = page;

            UpdateDerivedState();
            RebuildLookCatalogPage();
        }

        private void UpdateLookHudStatus(string text)
        {
            if (_lookHudStatusText != null)
                _lookHudStatusText.text = text;
        }

        private Sprite LoadLookThumbnail(string path)
        {
            if (string.IsNullOrEmpty(path))
                return null;

            try
            {
                byte[] bytes = FileManagerSecure.ReadAllBytes(path);
                if (bytes == null || bytes.Length == 0)
                    return null;

                Texture2D texture = new Texture2D(2, 2, TextureFormat.RGBA32, false);
                if (!texture.LoadImage(bytes))
                {
                    Destroy(texture);
                    return null;
                }

                texture.wrapMode = TextureWrapMode.Clamp;

                Sprite sprite = Sprite.Create(
                    texture,
                    new Rect(0f, 0f, texture.width, texture.height),
                    new Vector2(0.5f, 0.5f),
                    100f
                );

                _lookTextures.Add(texture);
                _lookSprites.Add(sprite);
                return sprite;
            }
            catch
            {
                return null;
            }
        }

        private bool ApplyAppearancePresetWithPath(
            Atom person,
            string path,
            out string error)
        {
            error = "";

            if (person == null)
            {
                error = "No selected Person.";
                return false;
            }

            if (string.IsNullOrEmpty(path))
            {
                error = "Preset path is empty.";
                return false;
            }

            try
            {
                JSONStorable appearance =
                    person.GetStorableByID("AppearancePresets");

                if (appearance == null)
                {
                    error = "Selected Person has no AppearancePresets storable.";
                    return false;
                }

                JSONStorableUrl presetBrowsePath =
                    appearance.GetUrlJSONParam("presetBrowsePath");

                if (presetBrowsePath == null)
                {
                    error = "AppearancePresets has no presetBrowsePath.";
                    return false;
                }

                JSONStorableBool loadPresetOnSelect =
                    appearance.GetBoolJSONParam("loadPresetOnSelect");

                bool previousLoadPresetOnSelect = false;

                if (loadPresetOnSelect != null)
                {
                    previousLoadPresetOnSelect = loadPresetOnSelect.val;
                    loadPresetOnSelect.val = false;
                }

                try
                {
                    presetBrowsePath.val =
                        SuperController.singleton.NormalizePath(path);

                    appearance.CallAction("LoadPreset");
                }
                finally
                {
                    if (loadPresetOnSelect != null)
                        loadPresetOnSelect.val = previousLoadPresetOnSelect;
                }

                return true;
            }
            catch (Exception e)
            {
                error = e.Message;
                return false;
            }
        }

        private void SelectLookCard(AppearanceEntry entry)
        {
            if (entry == null ||
                _lookApplyInProgress ||
                _controlledSpawnInProgress)
            {
                return;
            }

            if (IsCharacterCreationMode())
            {
                bool exactSexMatch =
                    GetAppearanceCatalogSex(entry) == _creationModeSex;
                bool unknownAllowed =
                    entry.sex == "?" &&
                    _showIncompatible != null &&
                    _showIncompatible.val;

                if (!exactSexMatch && !unknownAllowed)
                {
                    UpdateLookHudStatus(
                        "LOOKS — selected Look is not compatible with creation sex"
                    );
                    return;
                }

                string loadPath;
                string resolveError;

                if (!ResolveAppearanceLoadPath(
                        entry,
                        out loadPath,
                        out resolveError))
                {
                    UpdateLookHudStatus(
                        "LOOKS — could not prepare Look: " + resolveError
                    );
                    SuperController.LogError(
                        "CharacterRouter: could not prepare Look " +
                        entry.path + ": " + resolveError
                    );
                    return;
                }

                string spawnLifecycleSex =
                    entry.isAltFuta
                    ? "F"
                    : _creationModeSex;

                StartCoroutine(
                    AddCharacterSafelyCoroutine(
                        loadPath,
                        spawnLifecycleSex,
                        entry.label,
                        entry.path
                    )
                );
            }
            else
            {
                StartCoroutine(ApplyLookCardCoroutine(entry));
            }
        }

        private bool IsPirateSceneLookEntry(AppearanceEntry entry)
        {
            if (entry == null || !entry.isSceneLook)
                return false;

            return
                (!string.IsNullOrEmpty(entry.source) &&
                 entry.source.IndexOf(
                     "Damarmau.pirate_queen",
                     StringComparison.OrdinalIgnoreCase) >= 0) ||
                (!string.IsNullOrEmpty(entry.scenePath) &&
                 entry.scenePath.IndexOf(
                     "Pirate",
                     StringComparison.OrdinalIgnoreCase) >= 0);
        }

        private string GetCurrentLookTransitionProfile(PersonEntry person)
        {
            if (person == null)
                return "?";

            if (IsActiveAltFutaPerson(person))
                return "ALTFUTA";

            if (IsActiveNativeFutanariPerson(person))
                return "NATIVE_FUTA";

            string liveSex = DetectSex(person.atom);
            if (liveSex == "M") return "M";
            if (liveSex == "F") return "F";

            if (person.sex == "M") return "M";
            if (person.sex == "F") return "F";
            return "?";
        }

        private IEnumerator ApplyLookCardCoroutine(AppearanceEntry entry)
        {
            _lookApplyInProgress = true;

            PersonEntry selected = GetSelectedPerson();

            if (selected == null || selected.atom == null)
            {
                if (_selectedLookPath != null)
                    _selectedLookPath.valNoCallback =
                        "Look error: no selected Person";

                UpdateLookHudStatus("LOOKS — no selected Person");
                _lookApplyInProgress = false;
                yield break;
            }

            string loadPath;
            string resolveError;

            if (!ResolveAppearanceLoadPath(
                    entry,
                    out loadPath,
                    out resolveError))
            {
                if (_selectedLookPath != null)
                    _selectedLookPath.valNoCallback =
                        "Look error: " + resolveError;

                UpdateLookHudStatus(
                    "LOOKS — could not prepare Look: " + resolveError
                );

                SuperController.LogError(
                    "CharacterRouter: could not prepare Look " +
                    entry.path + ": " + resolveError
                );

                _lookApplyInProgress = false;
                yield break;
            }

            if (_selectedLookPath != null)
                _selectedLookPath.valNoCallback =
                    "Loading: " + entry.path;

            bool diagnosticPirateLook = IsPirateSceneLookEntry(entry);
            _decalMakerAdapter.DiagnosticNote(
                "LOOK SWITCH BEGIN | person=" + selected.uid +
                " | targetLabel=" + (entry.label ?? "") +
                " | targetPath=" + (entry.path ?? "") +
                " | sceneLook=" + entry.isSceneLook +
                " | pirateTarget=" + diagnosticPirateLook +
                " | isLoading=" +
                (SuperController.singleton != null &&
                 SuperController.singleton.isLoading)
            );

            string previousLookProfile =
                GetCurrentLookTransitionProfile(selected);
            string targetLookProfile =
                _lookSexTransitionAdapter.TargetProfile(
                    entry.sex,
                    entry.isAltFuta
                );
            bool stabilizeLookBoundary =
                _lookSexTransitionAdapter.RequiresBoundaryStabilization(
                    previousLookProfile,
                    targetLookProfile
                );

            if (stabilizeLookBoundary)
            {
                string transitionPrepDetail;
                bool transitionPrepOk =
                    _lookSexTransitionAdapter.Prepare(
                        selected.atom,
                        previousLookProfile,
                        targetLookProfile,
                        out transitionPrepDetail
                    );

                SuperController.LogMessage(
                    "CharacterRouter v232 LOOK SEX TRANSITION" +
                    " | stage=PREPARE" +
                    " | person=" + selected.uid +
                    " | from=" + previousLookProfile +
                    " | to=" + targetLookProfile +
                    " | ok=" + transitionPrepOk +
                    " | detail=" + (transitionPrepDetail ?? "")
                );
            }

            // BODY v146 overlays are transient geometry tied to the previous
            // Look. Remove them before loading another Appearance.
            _bodyPresetAdapter.ClearActive(
                selected.atom,
                selected.uid
            );

            // Remove only model-plugin slots created for the previous Look.
            // User-added plugins remain untouched.
            _modelPluginAdapter.ClearManaged(selected.atom);
            _sceneCuaAccessoryAdapter.ClearManaged(selected.atom);

            // Keep adapter-owned DecalMaker alive across Look changes. Only clear its
            // current frames here; full teardown is reserved for Person removal.
            _decalMakerAdapter.ClearVisualState(selected.atom);

            string error;
            bool started = ApplyAppearancePresetWithPath(
                selected.atom,
                loadPath,
                out error
            );

            _decalMakerAdapter.DiagnosticNote(
                "LOOK LoadPreset RETURNED | person=" + selected.uid +
                " | started=" + started +
                " | error=" + (error ?? "") +
                " | isLoading=" +
                (SuperController.singleton != null &&
                 SuperController.singleton.isLoading)
            );
            if (diagnosticPirateLook)
            {
                StartCoroutine(
                    _decalMakerAdapter.ObserveVaMLoading(
                        selected.atom,
                        "LOOK RETURN PIRATE",
                        1.20f
                    )
                );
            }

            if (diagnosticPirateLook)
            {
                StartCoroutine(
                    _qdaroProbe.Observe(
                        selected.atom,
                        "LOOK RETURN NATIVE LOAD",
                        _decalMakerAdapter.DiagnosticNote,
                        6.0f
                    )
                );
            }

            if (!started)
            {
                if (_selectedLookPath != null)
                    _selectedLookPath.valNoCallback =
                        "Look error: " + error;

                UpdateLookHudStatus("LOOKS — load failed: " + error);
                SuperController.LogError(
                    "CharacterRouter: Look load failed for " +
                    entry.path + " via " + loadPath + ": " + error
                );

                _lookApplyInProgress = false;
                yield break;
            }

            // v232: when one live Person crosses a base/profile boundary, let VaM
            // finish rebuilding its geometry/morph banks, then confirm-load the same
            // target Appearance once more. This specifically prevents stale native-Futa
            // genital/cross-bank state from surviving into the next Male/Female/AltFuta
            // Look without affecting ordinary same-profile Look switches.
            if (stabilizeLookBoundary)
            {
                yield return StartCoroutine(WaitForVaMLoadingToFinish(4.0f));
                for (int settleFrame = 0; settleFrame < 4; settleFrame++)
                    yield return null;
                yield return new WaitForFixedUpdate();

                string confirmError;
                bool confirmStarted = ApplyAppearancePresetWithPath(
                    selected.atom,
                    loadPath,
                    out confirmError
                );

                SuperController.LogMessage(
                    "CharacterRouter v232 LOOK SEX TRANSITION" +
                    " | stage=CONFIRM_LOAD" +
                    " | person=" + selected.uid +
                    " | from=" + previousLookProfile +
                    " | to=" + targetLookProfile +
                    " | started=" + confirmStarted +
                    " | error=" + (confirmError ?? "")
                );

                if (confirmStarted)
                {
                    yield return StartCoroutine(WaitForVaMLoadingToFinish(4.0f));
                    for (int postConfirmFrame = 0; postConfirmFrame < 3; postConfirmFrame++)
                        yield return null;
                }
            }

            if (entry.isSceneLook)
            {
                yield return _decalMakerAdapter.ApplyFromScene(
                    selected.atom,
                    entry.scenePath,
                    entry.sceneAtomId,
                    entry.source
                );

                if (diagnosticPirateLook)
                {
                    StartCoroutine(
                        _decalMakerAdapter.ObserveManagedState(
                            selected.atom,
                            "LOOK RETURN PIRATE POST-ADAPTER",
                            1.10f
                        )
                    );
                }
            }

            yield return _modelPluginAdapter.ApplyForLook(
                selected.atom,
                entry.source,
                entry.label,
                entry.isSceneLook ? entry.scenePath : "",
                entry.isSceneLook ? entry.sceneAtomId : "",
                _followCameraWithHead != null && !_followCameraWithHead.val
            );
            yield return StartCoroutine(ApplyHeadTrackingPolicy(selected.atom));

            yield return _sceneMorphParityAdapter.ApplyForLook(
                selected.atom, entry.source, entry.path);

            yield return _sceneCuaAccessoryAdapter.ApplyFromScene(
                selected.atom, entry.scenePath,
                entry.sceneAtomId, entry.source, entry.label);

            _decalMakerAdapter.DiagnosticNote(
                "LOOK SWITCH END | person=" + selected.uid +
                " | targetLabel=" + (entry.label ?? "") +
                " | isLoading=" +
                (SuperController.singleton != null &&
                 SuperController.singleton.isLoading)
            );
            _decalMakerAdapter.FlushDiagnostic();

            _activeLookByPerson[selected.uid] = entry.path;
            SaveActiveLooksData();

            if (entry.isAltFuta)
            {
                yield return StartCoroutine(
                    SanitizeGeneratedAltFutaM2AfAfterLookCoroutine(
                        selected.atom,
                        "LOOK_APPLY"
                    )
                );
            }

            RecordRecentLook(entry.path);

            // v141: active Look + adapters are the sole sex/profile authority.
            // Never persist a generic X toggle that could leak into another Look.
            if (_bodyProfileByPerson.Remove(selected.uid))
                SaveBodyProfilesData();

            SetCharacterDisplayName(
                selected.uid,
                entry.label
            );
            ClearBodyBaselineForPerson(selected.uid);
            ClearFaceBaselineForPerson(selected.uid);
            ClearActiveBodyPresetForPerson(
                selected.uid
            );
            // A new Look establishes a new hairstyle baseline. The next Hair edit
            // will lazily snapshot that new state before changing it.
            ClearHairEditStateForPerson(selected.uid, true);
            RebuildRosterButtons();

            if (_selectedLookPath != null)
                _selectedLookPath.valNoCallback =
                    "Applied: " + entry.path;

            UpdateLookHudStatus(
                "LOOKS — applied " + entry.label +
                (entry.isSceneLook ? " (from scene)" : "")
            );
            RebuildLookCatalogPage();

            _lookApplyInProgress = false;
            yield break;
        }

        private void CreateLookCard(AppearanceEntry entry)
        {
            if (_lookGridRoot == null || entry == null)
                return;

            GameObject card = new GameObject("LookCard_" + entry.label);
            card.transform.SetParent(_lookGridRoot.transform, false);

            Image cardImage = card.AddComponent<Image>();

            PersonEntry selectedPerson = GetSelectedPerson();
            string activeLookPath = "";

            if (selectedPerson != null &&
                !string.IsNullOrEmpty(selectedPerson.uid))
            {
                _activeLookByPerson.TryGetValue(
                    selectedPerson.uid,
                    out activeLookPath
                );
            }

            bool isActiveLook =
                !string.IsNullOrEmpty(activeLookPath) &&
                string.Equals(
                    activeLookPath,
                    entry.path,
                    StringComparison.OrdinalIgnoreCase
                );

            cardImage.color =
                isActiveLook
                ? GetSelectedHudButtonColor()
                : _referenceButtonColor;

            Button button = card.AddComponent<Button>();
            if (_haveReferenceButtonColors)
                button.colors = _referenceButtonColors;

            AppearanceEntry captured = entry;
            button.onClick.AddListener(delegate {
                SelectLookCard(captured);
            });

            GameObject favoriteGo =
                new GameObject("FavoriteToggle");
            favoriteGo.transform.SetParent(card.transform, false);

            RectTransform favoriteRect =
                favoriteGo.AddComponent<RectTransform>();
            favoriteRect.anchorMin = new Vector2(0f, 0.78f);
            favoriteRect.anchorMax = new Vector2(0.25f, 1f);
            favoriteRect.offsetMin = new Vector2(3f, -1f);
            favoriteRect.offsetMax = new Vector2(-1f, -3f);

            Image favoriteImage =
                favoriteGo.AddComponent<Image>();
            favoriteImage.color =
                new Color(0.15f, 0.15f, 0.15f, 0.70f);

            Button favoriteButton =
                favoriteGo.AddComponent<Button>();
            if (_haveReferenceButtonColors)
                favoriteButton.colors = _referenceButtonColors;

            AppearanceEntry favoriteCaptured = entry;
            favoriteButton.onClick.AddListener(delegate {
                ToggleFavoriteLook(
                    favoriteCaptured.path
                );
            });

            GameObject favoriteTextGo =
                new GameObject("Label");
            favoriteTextGo.transform.SetParent(
                favoriteGo.transform,
                false
            );

            RectTransform favoriteTextRect =
                favoriteTextGo.AddComponent<RectTransform>();
            favoriteTextRect.anchorMin = Vector2.zero;
            favoriteTextRect.anchorMax = Vector2.one;
            favoriteTextRect.offsetMin = Vector2.zero;
            favoriteTextRect.offsetMax = Vector2.zero;

            Text favoriteText =
                favoriteTextGo.AddComponent<Text>();
            favoriteText.font = GetFavoriteSymbolFont();
            favoriteText.fontSize =
                Mathf.Max(15, _referenceFontSize - 5);
            favoriteText.color = _referenceTextColor;
            favoriteText.alignment =
                TextAnchor.MiddleCenter;
            favoriteText.raycastTarget = false;
            favoriteText.text =
                _favoriteLookPaths.Contains(entry.path)
                ? "★"
                : "☆";

            GameObject previewGo = new GameObject("Preview");
            previewGo.transform.SetParent(card.transform, false);
            RectTransform previewRect = previewGo.AddComponent<RectTransform>();
            previewRect.anchorMin = new Vector2(0f, 0.24f);
            previewRect.anchorMax = new Vector2(1f, 1f);
            previewRect.offsetMin = new Vector2(5f, 3f);
            previewRect.offsetMax = new Vector2(-5f, -5f);

            Image preview = previewGo.AddComponent<Image>();
            preview.color = new Color(0.15f, 0.15f, 0.15f, 0.75f);
            preview.preserveAspect = true;

            Sprite sprite = LoadLookThumbnail(entry.thumbnailPath);
            if (sprite != null)
            {
                preview.sprite = sprite;
                preview.color = Color.white;
            }

            GameObject labelGo = new GameObject("Label");
            labelGo.transform.SetParent(card.transform, false);
            RectTransform labelRect = labelGo.AddComponent<RectTransform>();
            labelRect.anchorMin = new Vector2(0f, 0f);
            labelRect.anchorMax = new Vector2(1f, 0.24f);
            labelRect.offsetMin = new Vector2(4f, 2f);
            labelRect.offsetMax = new Vector2(-4f, -2f);

            Text label = labelGo.AddComponent<Text>();
            label.font = _referenceFont;
            label.fontSize = Mathf.Max(12, _referenceFontSize - 8);
            label.color = _referenceTextColor;
            label.alignment = TextAnchor.MiddleCenter;
            label.resizeTextForBestFit = true;
            label.resizeTextMinSize = 9;
            label.resizeTextMaxSize = Mathf.Max(13, _referenceFontSize - 5);

            string sexSuffix =
                entry.isAltFuta ? "  [FUTA]" :
                entry.sex == "F" ? "  [F]" :
                entry.sex == "M" ? "  [M]" :
                entry.sex == "X" ? "  [FUTA]" :
                ((_showIncompatible != null && _showIncompatible.val)
                    ? "  [?]"
                    : "");

            string sourceSuffix = entry.isSceneLook ? "  [SCENE]" : "";
            label.text = entry.label + sexSuffix + sourceSuffix;

            // Preview and label are added after FavoriteToggle, so explicitly keep
            // the star control as the topmost sibling. Without this, Preview receives
            // the pointer event and the nested star button appears dead.
            favoriteGo.transform.SetAsLastSibling();
        }

        private void CreateScenePackageCard(ScenePackageGroup group)
        {
            if (_lookGridRoot == null || group == null)
                return;

            GameObject card = new GameObject("ScenePackage_" + group.label);
            card.transform.SetParent(_lookGridRoot.transform, false);

            Image cardImage = card.AddComponent<Image>();
            cardImage.color = _referenceButtonColor;

            Button button = card.AddComponent<Button>();
            if (_haveReferenceButtonColors)
                button.colors = _referenceButtonColors;

            ScenePackageGroup captured = group;
            button.onClick.AddListener(delegate {
                _scenePackagesMode = true;
                _sceneSelectedPackage = captured.source ?? "";
                if (_catalogPage != null)
                    _catalogPage.valNoCallback = 1f;
                RebuildLookCatalogPage();
            });

            GameObject previewGo = new GameObject("Preview");
            previewGo.transform.SetParent(card.transform, false);
            RectTransform previewRect = previewGo.AddComponent<RectTransform>();
            previewRect.anchorMin = new Vector2(0f, 0.28f);
            previewRect.anchorMax = new Vector2(1f, 1f);
            previewRect.offsetMin = new Vector2(5f, 3f);
            previewRect.offsetMax = new Vector2(-5f, -5f);

            Image preview = previewGo.AddComponent<Image>();
            preview.color = new Color(0.15f, 0.15f, 0.15f, 0.75f);
            preview.preserveAspect = true;

            Sprite sprite = LoadLookThumbnail(group.thumbnailPath);
            if (sprite != null)
            {
                preview.sprite = sprite;
                preview.color = Color.white;
            }

            GameObject labelGo = new GameObject("Label");
            labelGo.transform.SetParent(card.transform, false);
            RectTransform labelRect = labelGo.AddComponent<RectTransform>();
            labelRect.anchorMin = new Vector2(0f, 0f);
            labelRect.anchorMax = new Vector2(1f, 0.28f);
            labelRect.offsetMin = new Vector2(4f, 2f);
            labelRect.offsetMax = new Vector2(-4f, -2f);

            Text label = labelGo.AddComponent<Text>();
            label.font = _referenceFont;
            label.fontSize = Mathf.Max(12, _referenceFontSize - 8);
            label.color = _referenceTextColor;
            label.alignment = TextAnchor.MiddleCenter;
            label.resizeTextForBestFit = true;
            label.resizeTextMinSize = 9;
            label.resizeTextMaxSize = Mathf.Max(13, _referenceFontSize - 5);
            label.text = group.label + "\n" + group.count + " item" + (group.count == 1 ? "" : "s");
        }

        private void RebuildLookCatalogPage()
        {
            if (_lookGridRoot == null)
                return;

            ClearLookThumbnailResources();

            for (int i = _lookGridRoot.transform.childCount - 1; i >= 0; i--)
                Destroy(_lookGridRoot.transform.GetChild(i).gameObject);

            List<AppearanceEntry> filtered = GetFilteredAppearanceEntries();
            string subsection = _subsection != null ? _subsection.val : "All";
            bool scenesView = string.Equals(
                subsection,
                "Scenes",
                StringComparison.OrdinalIgnoreCase
            );

            List<ScenePackageGroup> packageGroups = null;
            List<AppearanceEntry> displayEntries = filtered;
            bool packageOverview = scenesView && _scenePackagesMode &&
                string.IsNullOrEmpty(_sceneSelectedPackage);

            if (scenesView && _scenePackagesMode)
            {
                if (packageOverview)
                    packageGroups = BuildScenePackageGroups(filtered);
                else
                    displayEntries = FilterSceneEntriesToSelectedPackage(filtered);
            }

            int displayCount = packageOverview
                ? (packageGroups == null ? 0 : packageGroups.Count)
                : (displayEntries == null ? 0 : displayEntries.Count);

            int pageCount = Mathf.Max(
                1,
                Mathf.CeilToInt(displayCount / (float)LOOKS_PER_PAGE)
            );

            int page = _catalogPage != null
                ? Mathf.RoundToInt(_catalogPage.val)
                : 1;

            page = Mathf.Clamp(page, 1, pageCount);

            if (_catalogPage != null)
                _catalogPage.valNoCallback = page;

            int start = (page - 1) * LOOKS_PER_PAGE;
            int end = Mathf.Min(start + LOOKS_PER_PAGE, displayCount);

            if (packageOverview)
            {
                for (int i = start; i < end; i++)
                    CreateScenePackageCard(packageGroups[i]);
            }
            else
            {
                for (int i = start; i < end; i++)
                    CreateLookCard(displayEntries[i]);
            }

            if (_lookPageText != null)
            {
                if (packageOverview)
                {
                    _lookPageText.text =
                        "SCENES · PACKAGES   " + page + " / " + pageCount +
                        "   (" + displayCount + ")";
                }
                else if (scenesView && _scenePackagesMode &&
                         !string.IsNullOrEmpty(_sceneSelectedPackage))
                {
                    _lookPageText.text =
                        "SCENES > " + _sceneSelectedPackage.ToUpperInvariant() +
                        "   " + page + " / " + pageCount +
                        "   (" + displayCount + ")";
                }
                else
                {
                    _lookPageText.text =
                        subsection.ToUpperInvariant() +
                        "   " + page + " / " + pageCount +
                        "   (" + displayCount + ")";
                }
            }

            UpdateLookSubNavVisuals();
            UpdateSceneViewControls();
            UpdateCatalogFilterButtonLabels();

            string newSuffix = _lookNewOnly ? " | NEWEST" : "";

            if (!_appearanceCatalogScanned && !_appearanceScanRunning)
                UpdateLookHudStatus("LOOKS — catalog not scanned");
            else if (_appearanceScanRunning)
                UpdateLookHudStatus(
                    "LOOKS — scanning... " + _appearanceEntries.Count + " found"
                );
            else if (packageOverview)
                UpdateLookHudStatus(
                    "SCENES — " + displayCount + " package(s)" + newSuffix
                );
            else if (scenesView && _scenePackagesMode &&
                     !string.IsNullOrEmpty(_sceneSelectedPackage))
                UpdateLookHudStatus(
                    "SCENES — " + _sceneSelectedPackage + " | " +
                    displayCount + " look(s)" + newSuffix
                );
            else if (IsCharacterCreationMode())
                UpdateLookHudStatus(
                    (_creationModeSex == "F"
                        ? "ADD FEMALE — "
                        : (_creationModeSex == "M"
                            ? "ADD MALE — "
                            : "ADD FUTANARI — ")) +
                    (scenesView
                        ? "CHOOSE PERSON FROM SCENE"
                        : "CHOOSE APPEARANCE") +
                    " | " +
                    displayCount +
                    " look(s)" +
                    newSuffix +
                    ((_showIncompatible != null &&
                      _showIncompatible.val)
                        ? " | INCOMPATIBLE ON"
                        : "")
                );
            else if (GetSelectedPerson() == null)
                UpdateLookHudStatus(
                    "LOOKS — choose ADD FEMALE, ADD MALE or ADD FUTANARI" + newSuffix
                );
            else
                UpdateLookHudStatus(
                    "LOOKS — " +
                    displayCount +
                    ((_showIncompatible != null &&
                      _showIncompatible.val)
                        ? " look(s) | INCOMPATIBLE ON"
                        : " compatible look(s)") +
                    newSuffix
                );

            UpdateLookModeVisuals();

            _lastRenderedLookPage = page;

            _lastRenderedLookSex =
                GetCurrentAppearanceTargetSex();
            _lastRenderedLookSubsection = subsection;
            _lastRenderedShowIncompatible =
                _showIncompatible != null && _showIncompatible.val;
        }

        private void UpdateLookModeVisuals()
        {
            bool creating = IsCharacterCreationMode();
            Color bannerColor = creating ? GetSelectedHudButtonColor() : _referenceButtonColor;
            bannerColor.a = Mathf.Max(bannerColor.a, creating ? 0.98f : 0.72f);

            if (_lookModeBannerImage != null)
                _lookModeBannerImage.color = bannerColor;

            string banner = "EDIT CHARACTER LOOK";
            if (creating)
            {
                banner = _creationModeSex == "M"
                    ? "NEW MALE CHARACTER — SELECT STARTING LOOK"
                    : (_creationModeSex == "X"
                        ? "NEW FUTANARI CHARACTER — SELECT STARTING LOOK"
                        : "NEW FEMALE CHARACTER — SELECT STARTING LOOK");
            }
            else
            {
                PersonEntry selected = GetSelectedPerson();
                if (selected != null)
                {
                    string name = GetDisplayName(selected);
                    if (!string.IsNullOrEmpty(name))
                        banner = "EDIT LOOK — " + name.ToUpperInvariant();
                }
            }

            if (_lookModeBannerText != null)
                _lookModeBannerText.text = banner;

            SetHudButtonLabel(
                _lookResetButton,
                creating ? "CANCEL ADD" : "RESET LOOK"
            );

            if (_lookCatalogPanelImage != null)
            {
                Color c = _referenceButtonColor;
                if (creating)
                {
                    c.r = Mathf.Clamp01(c.r * 0.88f);
                    c.g = Mathf.Clamp01(c.g * 0.96f);
                    c.b = Mathf.Clamp01(c.b * 1.08f);
                    c.a = 0.48f;
                }
                else
                {
                    c.a = 0.35f;
                }
                _lookCatalogPanelImage.color = c;
            }
        }

