        private bool EnsureHairCatalogRoot()
        {
            try
            {
                if (_multiMenuCanvas == null)
                    return false;

                bool needsBuild =
                    _hairCatalogRoot == null ||
                    _hairCatalogRect == null ||
                    _hairGridRoot == null ||
                    _hairGrid == null ||
                    _hairSubNavRoot == null;

                if (needsBuild)
                {
                    BuildHairCatalogRoot();
                }

                if (_hairCatalogRoot == null ||
                    _hairCatalogRect == null ||
                    _hairGridRoot == null ||
                    _hairGrid == null)
                {
                    SuperController.LogError(
                        "CharacterRouter v93: HAIR HUD root did not initialize."
                    );
                    return false;
                }

                // HAIR is a late-added content surface. Force its geometry and
                // draw order when entering the section so it cannot remain as a
                // zero-sized/behind-the-other-editors root after a canvas rebuild.
                ApplyHairCatalogLayout();
                _hairCatalogRoot.transform.SetAsLastSibling();
                return true;
            }
            catch (Exception e)
            {
                SuperController.LogError(
                    "CharacterRouter v93: could not build HAIR HUD: " + e
                );
                return false;
            }
        }

        private void ApplyHairCatalogLayout()
        {
            if (_hairCatalogRect == null || _hairGrid == null)
                return;

            float width = _panelWidth != null
                ? _panelWidth.val
                : 720f;
            float y = GetContentTopY();
            float catalogHeight = 560f;

            _hairCatalogRect.anchoredPosition = new Vector2(
                _panelX != null ? _panelX.val : 0f,
                y
            );
            _hairCatalogRect.sizeDelta =
                new Vector2(width, catalogHeight);

            float usableWidth = Mathf.Max(200f, width - 20f);
            float cardWidth = (usableWidth - 18f) / 4f;
            float gridHeight = catalogHeight - 176f;
            float cardHeight = (gridHeight - 12f) / 3f;

            _hairGrid.cellSize =
                new Vector2(cardWidth, cardHeight);
        }

        private void ClearHairThumbnailResources()
        {
            for (int i = 0; i < _hairSprites.Count; i++)
            {
                if (_hairSprites[i] != null)
                    Destroy(_hairSprites[i]);
            }
            _hairSprites.Clear();

            for (int i = 0; i < _hairTextures.Count; i++)
            {
                if (_hairTextures[i] != null)
                    Destroy(_hairTextures[i]);
            }
            _hairTextures.Clear();
        }

        private Sprite LoadHairThumbnail(string path)
        {
            if (string.IsNullOrEmpty(path))
                return null;

            try
            {
                byte[] bytes = FileManagerSecure.ReadAllBytes(path);
                if (bytes == null || bytes.Length == 0)
                    return null;

                Texture2D texture = new Texture2D(
                    2,
                    2,
                    TextureFormat.RGBA32,
                    false
                );

                if (!texture.LoadImage(bytes))
                {
                    Destroy(texture);
                    return null;
                }

                texture.wrapMode = TextureWrapMode.Clamp;

                Sprite sprite = Sprite.Create(
                    texture,
                    new Rect(0f, 0f, texture.width, texture.height),
                    new Vector2(0.5f, 0.5f),
                    100f
                );

                _hairTextures.Add(texture);
                _hairSprites.Add(sprite);
                return sprite;
            }
            catch
            {
                return null;
            }
        }

        private void GoToFirstHairPage()
        {
            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;
            RebuildHairCatalogPage();
        }

        private void GoToLastHairPage()
        {
            List<HairPresetEntry> filtered = GetFilteredHairPresetEntries();
            int pageCount = Mathf.Max(
                1,
                Mathf.CeilToInt(filtered.Count / (float)HAIR_PRESETS_PER_PAGE)
            );
            if (_catalogPage != null)
                _catalogPage.valNoCallback = pageCount;
            RebuildHairCatalogPage();
        }

        private void ChangeHairPage(int delta)
        {
            List<HairPresetEntry> filtered =
                GetFilteredHairPresetEntries();

            int pageCount = Mathf.Max(
                1,
                Mathf.CeilToInt(
                    filtered.Count / (float)HAIR_PRESETS_PER_PAGE
                )
            );

            int page = _catalogPage != null
                ? Mathf.RoundToInt(_catalogPage.val)
                : 1;

            page = Mathf.Clamp(page + delta, 1, pageCount);
            if (_catalogPage != null)
                _catalogPage.valNoCallback = page;

            RebuildHairCatalogPage();
        }

        private void UpdateHairHudStatus(string text)
        {
            if (_hairHudStatusText != null)
                _hairHudStatusText.text = text;
        }

        private void UpdateHairSubNavVisuals()
        {
            string subsection = _subsection != null
                ? _subsection.val
                : "All";

            for (int i = 0; i < _hairSubNavButtons.Count; i++)
            {
                Button b = _hairSubNavButtons[i];
                if (b == null)
                    continue;

                Image img = b.GetComponent<Image>();
                if (img == null)
                    continue;

                string name = i < _hairSubNavNames.Count ? _hairSubNavNames[i] : "";
                bool selected =
                    (string.Equals(name, "Head", StringComparison.OrdinalIgnoreCase) &&
                     string.Equals(NormalizeEditableHairRegion(_hairRegion), "Head", StringComparison.OrdinalIgnoreCase)) ||
                    (string.Equals(name, "Facial", StringComparison.OrdinalIgnoreCase) &&
                     string.Equals(NormalizeEditableHairRegion(_hairRegion), "Facial", StringComparison.OrdinalIgnoreCase)) ||
                    (string.Equals(name, "Body", StringComparison.OrdinalIgnoreCase) &&
                     string.Equals(NormalizeEditableHairRegion(_hairRegion), "Body", StringComparison.OrdinalIgnoreCase)) ||
                    (string.Equals(name, "Intimate", StringComparison.OrdinalIgnoreCase) &&
                     string.Equals(NormalizeEditableHairRegion(_hairRegion), "Pubic", StringComparison.OrdinalIgnoreCase)) ||
                    (string.Equals(name, "Favorites", StringComparison.OrdinalIgnoreCase) &&
                     string.Equals(subsection, "Favorites", StringComparison.OrdinalIgnoreCase)) ||
                    (string.Equals(name, "Scenes", StringComparison.OrdinalIgnoreCase) &&
                     string.Equals(subsection, "Scenes", StringComparison.OrdinalIgnoreCase));

                img.color = selected
                    ? GetSelectedHudButtonColor()
                    : _referenceButtonColor;

                if (string.Equals(name, "Favorites", StringComparison.OrdinalIgnoreCase))
                {
                    SetHudButtonLabel(
                        b,
                        string.Equals(subsection, "Favorites", StringComparison.OrdinalIgnoreCase)
                            ? "FAVORITES ON"
                            : "FAVORITES"
                    );
                }
                else if (string.Equals(name, "Scenes", StringComparison.OrdinalIgnoreCase))
                {
                    SetHudButtonLabel(
                        b,
                        string.Equals(subsection, "Scenes", StringComparison.OrdinalIgnoreCase)
                            ? "SCENES ON"
                            : "SCENES"
                    );
                }
            }

            if (_hairIncompatibleButton != null)
            {
                Image img = _hairIncompatibleButton.GetComponent<Image>();
                if (img != null)
                {
                    img.color = _showIncompatibleHairPresets
                        ? GetSelectedHudButtonColor()
                        : _referenceButtonColor;
                }

                SetHudButtonLabel(
                    _hairIncompatibleButton,
                    _showIncompatibleHairPresets
                        ? "INCOMPATIBLE ON"
                        : "INCOMPATIBLE"
                );
            }

            if (_hairResetButton != null)
            {
                PersonEntry selectedPerson = GetSelectedPerson();
                bool canReset = selectedPerson != null &&
                    !string.IsNullOrEmpty(selectedPerson.uid) &&
                    _originalHairSnapshotJsonByPerson.ContainsKey(selectedPerson.uid);

                _hairResetButton.interactable = canReset;

                Image img = _hairResetButton.GetComponent<Image>();
                if (img != null)
                    img.color = _referenceButtonColor;

                string resetRegion = NormalizeEditableHairRegion(_hairRegion);
                string resetLabel =
                    string.Equals(resetRegion, "Facial", StringComparison.OrdinalIgnoreCase) ? "RESET FACIAL" :
                    string.Equals(resetRegion, "Body", StringComparison.OrdinalIgnoreCase) ? "RESET BODY HAIR" :
                    string.Equals(resetRegion, "Pubic", StringComparison.OrdinalIgnoreCase) ? "RESET INTIMATE" :
                    "RESET HEAD";
                SetHudButtonLabel(_hairResetButton, resetLabel);
            }

            if (_hairRemoveButton != null)
            {
                PersonEntry selectedPerson = GetSelectedPerson();
                _hairRemoveButton.interactable =
                    selectedPerson != null && !string.IsNullOrEmpty(selectedPerson.uid);

                Image img = _hairRemoveButton.GetComponent<Image>();
                if (img != null)
                    img.color = _referenceButtonColor;

                string removeRegion = NormalizeEditableHairRegion(_hairRegion);
                string removeLabel =
                    string.Equals(removeRegion, "Facial", StringComparison.OrdinalIgnoreCase) ? "REMOVE FACIAL" :
                    string.Equals(removeRegion, "Body", StringComparison.OrdinalIgnoreCase) ? "REMOVE BODY" :
                    string.Equals(removeRegion, "Pubic", StringComparison.OrdinalIgnoreCase) ? "REMOVE INTIMATE" :
                    "REMOVE HEAD";
                SetHudButtonLabel(_hairRemoveButton, removeLabel);
            }
        }

        private Font GetFavoriteSymbolFont()
        {
            if (_favoriteSymbolFont != null)
                return _favoriteSymbolFont;

            try
            {
                _favoriteSymbolFont = Font.CreateDynamicFontFromOSFont(
                    "Segoe UI Symbol",
                    Mathf.Max(18, _referenceFontSize)
                );
            }
            catch { }

            if (_favoriteSymbolFont == null)
                _favoriteSymbolFont = _referenceFont;

            return _favoriteSymbolFont;
        }

        private void CreateHairPresetCard(HairPresetEntry entry)
        {
            if (_hairGridRoot == null || entry == null)
                return;

            GameObject card =
                new GameObject("HairCard_" + entry.label);
            card.transform.SetParent(_hairGridRoot.transform, false);

            Image cardImage = card.AddComponent<Image>();

            PersonEntry selected = GetSelectedPerson();
            string activePath = "";
            if (selected != null)
                _activeHairPresetByPerson.TryGetValue(
                    GetHairActiveKey(selected.uid, _hairRegion),
                    out activePath
                );

            bool active =
                !string.IsNullOrEmpty(activePath) &&
                string.Equals(
                    activePath,
                    entry.path,
                    StringComparison.OrdinalIgnoreCase
                );

            cardImage.color = active
                ? GetSelectedHudButtonColor()
                : _referenceButtonColor;

            Button button = card.AddComponent<Button>();
            if (_haveReferenceButtonColors)
                button.colors = _referenceButtonColors;

            HairPresetEntry captured = entry;
            button.onClick.AddListener(delegate {
                SelectHairPresetCard(captured);
            });

            GameObject favoriteGo =
                new GameObject("FavoriteToggle");
            favoriteGo.transform.SetParent(card.transform, false);

            RectTransform favoriteRect =
                favoriteGo.AddComponent<RectTransform>();
            favoriteRect.anchorMin = new Vector2(0f, 0.78f);
            favoriteRect.anchorMax = new Vector2(0.25f, 1f);
            favoriteRect.offsetMin = new Vector2(3f, -1f);
            favoriteRect.offsetMax = new Vector2(-1f, -3f);

            Image favoriteImage = favoriteGo.AddComponent<Image>();
            favoriteImage.color =
                new Color(0.15f, 0.15f, 0.15f, 0.70f);

            Button favoriteButton = favoriteGo.AddComponent<Button>();
            if (_haveReferenceButtonColors)
                favoriteButton.colors = _referenceButtonColors;

            HairPresetEntry favoriteCaptured = entry;
            favoriteButton.onClick.AddListener(delegate {
                ToggleFavoriteHairPreset(favoriteCaptured.path);
            });

            GameObject favoriteTextGo = new GameObject("Label");
            favoriteTextGo.transform.SetParent(
                favoriteGo.transform,
                false
            );
            RectTransform favoriteTextRect =
                favoriteTextGo.AddComponent<RectTransform>();
            favoriteTextRect.anchorMin = Vector2.zero;
            favoriteTextRect.anchorMax = Vector2.one;
            favoriteTextRect.offsetMin = Vector2.zero;
            favoriteTextRect.offsetMax = Vector2.zero;

            Text favoriteText = favoriteTextGo.AddComponent<Text>();
            favoriteText.font = GetFavoriteSymbolFont();
            favoriteText.fontSize =
                Mathf.Max(15, _referenceFontSize - 5);
            favoriteText.color = _referenceTextColor;
            favoriteText.alignment = TextAnchor.MiddleCenter;
            favoriteText.raycastTarget = false;
            favoriteText.text =
                _favoriteHairPresetPaths.Contains(entry.path)
                    ? "★"
                    : "☆";

            GameObject previewGo = new GameObject("Preview");
            previewGo.transform.SetParent(card.transform, false);
            RectTransform previewRect =
                previewGo.AddComponent<RectTransform>();
            previewRect.anchorMin = new Vector2(0f, 0.24f);
            previewRect.anchorMax = new Vector2(1f, 1f);
            previewRect.offsetMin = new Vector2(5f, 3f);
            previewRect.offsetMax = new Vector2(-5f, -5f);

            Image preview = previewGo.AddComponent<Image>();
            preview.color =
                new Color(0.15f, 0.15f, 0.15f, 0.75f);
            preview.preserveAspect = true;

            Sprite sprite = LoadHairThumbnail(entry.thumbnailPath);
            if (sprite != null)
            {
                preview.sprite = sprite;
                preview.color = Color.white;
            }

            GameObject labelGo = new GameObject("Label");
            labelGo.transform.SetParent(card.transform, false);
            RectTransform labelRect =
                labelGo.AddComponent<RectTransform>();
            labelRect.anchorMin = new Vector2(0f, 0f);
            labelRect.anchorMax = new Vector2(1f, 0.24f);
            labelRect.offsetMin = new Vector2(4f, 2f);
            labelRect.offsetMax = new Vector2(-4f, -2f);

            Text label = labelGo.AddComponent<Text>();
            label.font = _referenceFont;
            label.fontSize = Mathf.Max(12, _referenceFontSize - 8);
            label.color = _referenceTextColor;
            label.alignment = TextAnchor.MiddleCenter;
            label.resizeTextForBestFit = true;
            label.resizeTextMinSize = 9;
            label.resizeTextMaxSize =
                Mathf.Max(13, _referenceFontSize - 5);

            string sexSuffix =
                entry.sex == "F" ? "  [F]" :
                entry.sex == "M" ? "  [M]" :
                (_showIncompatibleHairPresets ? "  [?]" : "");

            label.text = entry.label + sexSuffix;
            favoriteGo.transform.SetAsLastSibling();
        }

        private void RebuildHairCatalogPage()
        {
            if (_hairGridRoot == null)
                return;

            ClearHairThumbnailResources();

            for (int i = _hairGridRoot.transform.childCount - 1;
                 i >= 0;
                 i--)
            {
                Destroy(
                    _hairGridRoot.transform.GetChild(i).gameObject
                );
            }

            List<HairPresetEntry> filtered =
                GetFilteredHairPresetEntries();

            int pageCount = Mathf.Max(
                1,
                Mathf.CeilToInt(
                    filtered.Count / (float)HAIR_PRESETS_PER_PAGE
                )
            );

            int page = _catalogPage != null
                ? Mathf.RoundToInt(_catalogPage.val)
                : 1;
            page = Mathf.Clamp(page, 1, pageCount);

            if (_catalogPage != null)
                _catalogPage.valNoCallback = page;

            int start = (page - 1) * HAIR_PRESETS_PER_PAGE;
            int end = Mathf.Min(
                start + HAIR_PRESETS_PER_PAGE,
                filtered.Count
            );

            for (int i = start; i < end; i++)
                CreateHairPresetCard(filtered[i]);

            string subsection = _subsection != null
                ? _subsection.val
                : "All";

            if (_hairPageText != null)
            {
                _hairPageText.text =
                    GetHairRegionDisplayName(_hairRegion) + " · " +
                    subsection.ToUpperInvariant() +
                    (_hairNewOnly ? " · NEW" : "") +
                    "   " + page + " / " + pageCount +
                    "   (" + filtered.Count + ")";
            }

            UpdateHairSubNavVisuals();
            UpdateCatalogFilterButtonLabels();

            PersonEntry person = GetSelectedPerson();
            string targetSex = GetHairTargetSex(person);
            string targetLabel =
                targetSex == "F" ? "FEMALE" :
                targetSex == "M" ? "MALE" :
                "UNKNOWN";
            if (person != null && IsActiveAltFutaPerson(person) &&
                string.Equals(NormalizeEditableHairRegion(_hairRegion), "Pubic", StringComparison.OrdinalIgnoreCase) &&
                !_showIncompatibleHairPresets)
            {
                targetLabel = "ALTFUTA";
            }

            if (!_hairPresetCatalogScanned &&
                !_hairPresetScanRunning)
            {
                UpdateHairHudStatus(
                    "HAIR — catalog not scanned"
                );
            }
            else if (_hairPresetScanRunning)
            {
                UpdateHairHudStatus(
                    "HAIR — scanning... " +
                    _hairPresetEntries.Count + " found"
                );
            }
            else
            {
                bool altFutaPubicDisabled =
                    person != null && IsActiveAltFutaPerson(person) &&
                    string.Equals(NormalizeEditableHairRegion(_hairRegion), "Pubic", StringComparison.OrdinalIgnoreCase);

                if (altFutaPubicDisabled)
                {
                    UpdateHairHudStatus(
                        "HAIR — INTIMATE | ALTFUTA | PUBIC HAIR DISABLED"
                    );
                }
                else
                {
                    string logicalSuffix =
                        person != null && person.sex == "X"
                            ? " | FUTANARI CHARACTER"
                            : "";

                    UpdateHairHudStatus(
                        "HAIR — " + GetHairRegionDisplayName(_hairRegion) +
                        " | " + targetLabel + " HAIR BASE" +
                        logicalSuffix +
                        " | " + filtered.Count +
                        (_showIncompatibleHairPresets
                            ? " preset(s) | INCOMPATIBLE ON"
                            : " compatible preset(s)") +
                        (_hairNewOnly ? " | NEWEST" : "")
                    );
                }
            }

            _lastRenderedHairPage = page;
            _lastRenderedHairUid =
                person != null ? person.uid : "";
            _lastRenderedHairSubsection = subsection;
            _lastRenderedHairTargetSex = targetSex;
            _lastRenderedHairShowIncompatible =
                _showIncompatibleHairPresets;
        }

        private void SetHudButtonLabel(Button button, string label)
        {
            if (button == null)
                return;

            Text text = button.GetComponentInChildren<Text>(true);
            if (text != null)
                text.text = label;
        }

