            }

            _bodyFineMode = mode;

            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;

            UpdateDerivedState();
            RebuildBodyEditorPage();
        }

        private void UpdateBodyFineModeVisuals()
        {
            for (int i = 0;
                 i < _bodyFineModeButtons.Count &&
                 i < _bodyFineModeNames.Count;
                 i++)
            {
                Button b = _bodyFineModeButtons[i];

                if (b == null)
                    continue;

                Image img = b.GetComponent<Image>();

                if (img == null)
