        private void RebuildBodyFineNav()
        {
            if (_bodyFineNavRoot == null)
                return;

            for (int i =
                     _bodyFineNavRoot.transform.childCount - 1;
                 i >= 0;
                 i--)
            {
                Destroy(
                    _bodyFineNavRoot.transform
                        .GetChild(i)
                        .gameObject
                );
            }

            _bodyFineNavButtons.Clear();
            _bodyFineNavNames.Clear();

            PersonEntry person = GetSelectedPerson();
            string profile = GetBodyEditorProfile(person);

            List<string> names =
                GetFineGroupNames(profile);

            for (int i = 0; i < names.Count; i++)
                _bodyFineNavNames.Add(names[i]);

            if (_bodyFineNavNames.Count > 0 &&
                !_bodyFineNavNames.Contains(_bodyFineGroup))
            {
                _bodyFineGroup = _bodyFineNavNames[0];
            }

            for (int i = 0;
                 i < _bodyFineNavNames.Count;
                 i++)
            {
                string captured =
                    _bodyFineNavNames[i];

                Button button =
                    CreateBodyAuxNavButton(
                        _bodyFineNavRoot.transform,
                        "BodyFine_" + captured,
                        captured.ToUpperInvariant(),
                        delegate
                        {
                            _bodyFineGroup = captured;

                            if (_catalogPage != null)
                                _catalogPage.valNoCallback = 1f;

                            UpdateDerivedState();
                            RebuildBodyEditorPage();
                        }
                    );

                _bodyFineNavButtons.Add(button);
            }
        }

