        private void CreateBodyPresetCard(
            Transform parent,
            BodyPresetEntry entry)
        {
            if (parent == null ||
                entry == null)
            {
                return;
            }

            GameObject card =
                new GameObject(
                    "BodyPresetCard_" +
                    entry.label
                );

            card.transform.SetParent(
                parent,
                false
            );

            Image cardImage =
                card.AddComponent<Image>();

            PersonEntry person =
                GetSelectedPerson();

            string activePath = "";

            if (person != null)
            {
                _activeBodyPresetByPerson.TryGetValue(
                    person.uid,
                    out activePath
                );
