        private void BuildBodyPresetGrid(
            List<BodyPresetEntry> filtered,
            int page)
        {
            if (_bodyRowsRoot == null)
                return;

            GameObject gridGo =
                new GameObject("BodyPresetGrid");

            gridGo.transform.SetParent(
                _bodyRowsRoot.transform,
                false
            );

            LayoutElement gridElement =
                gridGo.AddComponent<LayoutElement>();

            gridElement.preferredHeight = 690f;
            gridElement.minHeight = 650f;

            GridLayoutGroup grid =
                gridGo.AddComponent<GridLayoutGroup>();

            grid.startCorner =
                GridLayoutGroup.Corner.UpperLeft;
            grid.startAxis =
                GridLayoutGroup.Axis.Horizontal;
            grid.childAlignment =
                TextAnchor.UpperCenter;
            grid.constraint =
                GridLayoutGroup.Constraint.FixedColumnCount;
            grid.constraintCount = 4;
            grid.spacing =
                new Vector2(6f, 6f);

            float width =
                (_panelWidth != null
                    ? _panelWidth.val
                    : 720f) - 38f;

            float cellWidth =
                Mathf.Max(
                    120f,
                    (width - 18f) / 4f
                );

            grid.cellSize =
                new Vector2(
                    cellWidth,
                    215f
                );

            int start =
                (page - 1) *
                BODY_PRESETS_PER_PAGE;

            int end =
                Mathf.Min(
                    start +
                    BODY_PRESETS_PER_PAGE,
                    filtered.Count
                );

            for (int i = start;
                 i < end;
                 i++)
            {
                CreateBodyPresetCard(
                    gridGo.transform,
                    filtered[i]
                );
            }
        }

