        private void ApplyFaceEditorLayout()
        {
            if (_faceEditorRect == null)
                return;

            float width =
                _panelWidth != null
                ? _panelWidth.val
                : 720f;

            float faceTopGap = 56f;
            float y = GetContentTopY() - faceTopGap;

            _faceEditorRect.anchoredPosition =
                new Vector2(
                    _panelX != null ? _panelX.val : 0f,
                    y
                );

            _faceEditorRect.sizeDelta =
                new Vector2(width, 920f);
        }

        private void UpdateFaceSubNavVisuals()
        {
            string subsection =
                _subsection != null
                ? _subsection.val
                : "Shape";

            for (int i = 0;
                 i < _faceSubNavButtons.Count &&
                 i < _faceSubNavNames.Count;
                 i++)
            {
                Button b = _faceSubNavButtons[i];
                if (b == null)
                    continue;

                Image img = b.GetComponent<Image>();
                if (img == null)
                    continue;

                bool active =
                    string.Equals(
                        _faceSubNavNames[i],
                        subsection,
                        StringComparison.OrdinalIgnoreCase
                    );

                img.color =
                    active
                    ? GetSelectedHudButtonColor()
                    : _referenceButtonColor;
            }
        }

        private void SetFaceMode(string mode)
        {
            if (mode != "Essential" &&
                mode != "Advanced")
            {
                return;
            }

            _faceMode = mode;

            if (_catalogPage != null)
                _catalogPage.valNoCallback = 1f;

            UpdateFaceModeVisuals();
            UpdateDerivedState();
            RebuildFaceEditorPage();
        }

        private void UpdateFaceModeVisuals()
        {
            for (int i = 0;
                 i < _faceModeButtons.Count &&
                 i < _faceModeNames.Count;
                 i++)
            {
                Button b = _faceModeButtons[i];
                if (b == null)
                    continue;

                Image img = b.GetComponent<Image>();
                if (img == null)
                    continue;

                bool active =
                    string.Equals(
                        _faceModeNames[i],
                        _faceMode,
                        StringComparison.OrdinalIgnoreCase
                    );

                img.color =
                    active
                    ? GetSelectedHudButtonColor()
                    : _referenceButtonColor;
            }
        }

        private void ChangeFacePage(int delta)
        {
            int itemCount =
                GetFaceMorphsForCurrentSubsection().Count;

            int pageCount =
                Mathf.Max(
                    1,
                    Mathf.CeilToInt(
                        itemCount /
                        (float)FACE_MORPHS_PER_PAGE
                    )
                );

            int page =
                _catalogPage != null
                ? Mathf.RoundToInt(_catalogPage.val)
                : 1;

            page = Mathf.Clamp(
                page + delta,
                1,
                pageCount
            );

            if (_catalogPage != null)
                _catalogPage.valNoCallback = page;

            UpdateDerivedState();
            RebuildFaceEditorPage();
        }

        private void ResetFaceSection()
        {
            PersonEntry person = GetSelectedPerson();
            if (person == null)
                return;

            RebuildFaceMorphIndex();
            EnsureFaceBaselineForSelectedPerson();

            List<FaceMorphEntry> entries =
                GetFaceMorphsForCurrentSubsection();

            for (int i = 0; i < entries.Count; i++)
            {
                FaceMorphEntry entry = entries[i];
                if (entry == null || entry.morph == null)
                    continue;

                float baseline;
                if (_faceBaselineValues.TryGetValue(
                        MakeFaceBaselineKey(
                            person.uid,
                            entry.name
                        ),
                        out baseline))
                {
                    entry.morph.morphValue = baseline;
                }
            }

            RebuildFaceEditorPage();
        }

        private void ResetFaceAll()
        {
            PersonEntry person = GetSelectedPerson();
            if (person == null)
                return;

            RebuildFaceMorphIndex();
            EnsureFaceBaselineForSelectedPerson();

            for (int i = 0; i < _faceMorphEntries.Count; i++)
            {
                FaceMorphEntry entry = _faceMorphEntries[i];
                if (entry == null || entry.morph == null)
                    continue;

                float baseline;
                if (_faceBaselineValues.TryGetValue(
                        MakeFaceBaselineKey(
                            person.uid,
                            entry.name
                        ),
                        out baseline))
                {
                    entry.morph.morphValue = baseline;
                }
            }

            RebuildFaceEditorPage();
        }

        private void ResetSingleFaceMorph(
            FaceMorphEntry entry,
            Slider slider,
            Text valueText)
        {
            if (entry == null || entry.morph == null)
                return;

            PersonEntry person = GetSelectedPerson();
            if (person == null || string.IsNullOrEmpty(person.uid))
                return;

            EnsureFaceBaselineForSelectedPerson();

            float baseline;
            if (!_faceBaselineValues.TryGetValue(
                    MakeFaceBaselineKey(
                        person.uid,
                        entry.name
                    ),
                    out baseline))
            {
                return;
            }

            entry.morph.morphValue = baseline;

            if (slider != null)
                slider.value = baseline;

            if (valueText != null)
                valueText.text = baseline.ToString("0.000");
        }

        private void CreateFaceMorphSliderRow(
