                }
            );
        }

        private void RebuildFaceEditorPage()
        {
            if (_faceRowsRoot == null)
                return;

            for (int i =
                     _faceRowsRoot.transform.childCount - 1;
                 i >= 0;
                 i--)
            {
                Destroy(
                    _faceRowsRoot.transform
                        .GetChild(i)
                        .gameObject
                );
            }

            PersonEntry person = GetSelectedPerson();

            if (person == null)
            {
                if (_faceStatusText != null)
                    _faceStatusText.text =
                        "FACE — select a Character";

                if (_facePageText != null)
                    _facePageText.text = "1 / 1";

                return;
            }

            RebuildFaceMorphIndex();
            EnsureFaceBaselineForSelectedPerson();
            UpdateFaceSubNavVisuals();
            UpdateFaceModeVisuals();

            List<FaceMorphEntry> filtered =
                GetFaceMorphsForCurrentSubsection();

            int pageCount =
                Mathf.Max(
                    1,
                    Mathf.CeilToInt(
                        filtered.Count /
                        (float)FACE_MORPHS_PER_PAGE
                    )
                );

            int page =
                _catalogPage != null
                ? Mathf.RoundToInt(_catalogPage.val)
                : 1;

            page = Mathf.Clamp(page, 1, pageCount);

            if (_catalogPage != null)
                _catalogPage.valNoCallback = page;

            int start =
                (page - 1) * FACE_MORPHS_PER_PAGE;

            int end =
                Mathf.Min(
                    start + FACE_MORPHS_PER_PAGE,
                    filtered.Count
                );

            for (int i = start; i < end; i++)
                CreateFaceMorphSliderRow(filtered[i]);

            string subsection =
                _subsection != null
                ? _subsection.val
                : "Shape";

            string profile = GetBodyEditorProfile(person);

            if (_faceStatusText != null)
            {
                _faceStatusText.text =
                    "FACE — " +
                    subsection.ToUpperInvariant() +
                    " | " +
                    GetBodyProfileLabel(profile) +
                    " | " +
                    _faceMode.ToUpperInvariant() +
                    " | " +
                    filtered.Count +
                    " morph(s)";
            }

            if (_facePageText != null)
            {
                _facePageText.text =
                    page + " / " + pageCount;
            }

            _lastRenderedFacePage = page;
            _lastRenderedFaceUid = person.uid;
            _lastRenderedFaceSubsection = subsection;
            _lastRenderedFaceProfile = profile;
            _lastRenderedFaceMode = _faceMode;
        }

