                Mathf.Max(12, _referenceFontSize - 6);
            text.text = label;
        }

        private void ApplyBodyEditorLayout()
        {
            if (_bodyEditorRect == null)
                return;

            float width =
                _panelWidth != null
                ? _panelWidth.val
                : 720f;

            float bodyTopGap = 56f;
            float y = GetContentTopY() - bodyTopGap;

            _bodyEditorRect.anchoredPosition =
                new Vector2(
                    _panelX != null ? _panelX.val : 0f,
                    y
                );

            _bodyEditorRect.sizeDelta =
                new Vector2(width, 920f);
        }

        private void UpdateBodySubNavVisuals()
        {
            string subsection =
                _subsection != null
                ? _subsection.val
                : "Presets";

            for (int i = 0;
                 i < _bodySubNavButtons.Count &&
                 i < _bodySubNavNames.Count;
                 i++)
            {
                Button b = _bodySubNavButtons[i];
                if (b == null)
                    continue;

                Image img = b.GetComponent<Image>();
                if (img == null)
                    continue;

                bool active =
                    string.Equals(
                        _bodySubNavNames[i],
                        subsection,
                        StringComparison.OrdinalIgnoreCase
                    );

                img.color =
                    active
                    ? GetSelectedHudButtonColor()
                    : _referenceButtonColor;
            }
        }

        private void ChangeBodyPage(int delta)
        {
            string subsection =
                _subsection != null
                ? _subsection.val
                : "Presets";

            int itemCount;
            int itemsPerPage;

            if (string.Equals(
                    subsection,
                    "Presets",
                    StringComparison.OrdinalIgnoreCase))
            {
                itemCount =
                    GetFilteredBodyPresetEntries().Count;
                itemsPerPage =
                    BODY_PRESETS_PER_PAGE;
            }
            else
            {
                itemCount =
                    GetBodyMorphsForCurrentSubsection().Count;
                itemsPerPage =
                    BODY_MORPHS_PER_PAGE;
            }

            int pageCount =
                Mathf.Max(
                    1,
                    Mathf.CeilToInt(
                        itemCount /
                        (float)itemsPerPage
                    )
                );

            int page =
                _catalogPage != null
                ? Mathf.RoundToInt(_catalogPage.val)
                : 1;

            page =
                Mathf.Clamp(
                    page + delta,
                    1,
                    pageCount
                );

            if (_catalogPage != null)
                _catalogPage.valNoCallback = page;

            UpdateDerivedState();
            RebuildBodyEditorPage();
        }

        private void ResetSingleBodyMorph(
            BodyMorphEntry entry,
            Slider slider,
            Text valueText,
            bool invertHeightSemantic)
        {
            if (entry == null ||
                entry.morph == null)
            {
                return;
            }

            PersonEntry person = GetSelectedPerson();

            if (person == null ||
                string.IsNullOrEmpty(person.uid))
            {
                return;
            }

            EnsureBodyBaselineForSelectedPerson();

            float baseline;

            if (!_bodyBaselineValues.TryGetValue(
                    MakeBodyBaselineKey(
                        person.uid,
                        entry.name
                    ),
                    out baseline))
            {
                return;
            }

            entry.morph.morphValue = baseline;

            float uiValue =
                invertHeightSemantic
                ? -baseline
                : baseline;

            if (slider != null)
                slider.value = uiValue;

            if (valueText != null)
                valueText.text =
                    uiValue.ToString("0.000");
        }

        private void CreateBodyMorphSliderRow(
            BodyMorphEntry entry)
        {
            if (_bodyRowsRoot == null ||
                entry == null ||
                entry.morph == null)
