            nameGo.transform.SetParent(row.transform, false);

            LayoutElement nameLayout =
                nameGo.AddComponent<LayoutElement>();
            nameLayout.preferredWidth = 190f;
            nameLayout.minWidth = 135f;

            Text nameText =
                nameGo.AddComponent<Text>();
            nameText.font = _referenceFont;
            nameText.fontSize =
