            nameText.color = _referenceTextColor;
            nameText.alignment =
                TextAnchor.MiddleLeft;
            nameText.resizeTextForBestFit = true;
            nameText.resizeTextMinSize = 9;
            nameText.resizeTextMaxSize =
                Mathf.Max(13, _referenceFontSize - 5);
            nameText.text = entry.name;

            GameObject sliderGo =
                new GameObject("Slider");
            sliderGo.transform.SetParent(row.transform, false);

            LayoutElement sliderLayout =
                sliderGo.AddComponent<LayoutElement>();
            sliderLayout.flexibleWidth = 1f;
            sliderLayout.minWidth = 220f;

            Slider slider =
                sliderGo.AddComponent<Slider>();

            Image sliderBg =
                sliderGo.AddComponent<Image>();
            sliderBg.color =
                new Color(0.12f, 0.12f, 0.12f, 0.9f);
            slider.targetGraphic = sliderBg;

            GameObject fillArea =
                new GameObject("FillArea");
            fillArea.transform.SetParent(
                sliderGo.transform,
                false
            );

            RectTransform fillAreaRect =
                fillArea.AddComponent<RectTransform>();
            fillAreaRect.anchorMin =
                new Vector2(0f, 0.25f);
            fillAreaRect.anchorMax =
                new Vector2(1f, 0.75f);
            fillAreaRect.offsetMin =
                new Vector2(5f, 0f);
            fillAreaRect.offsetMax =
                new Vector2(-5f, 0f);

            GameObject fillGo =
                new GameObject("Fill");
            fillGo.transform.SetParent(
                fillArea.transform,
                false
            );

            RectTransform fillRect =
                fillGo.AddComponent<RectTransform>();
            fillRect.anchorMin = Vector2.zero;
            fillRect.anchorMax = Vector2.one;
            fillRect.offsetMin = Vector2.zero;
            fillRect.offsetMax = Vector2.zero;

            Image fillImage =
                fillGo.AddComponent<Image>();
            fillImage.color = _referenceTextColor;

            slider.fillRect = fillRect;

            GameObject handleArea =
                new GameObject("HandleArea");
            handleArea.transform.SetParent(
                sliderGo.transform,
                false
            );

            RectTransform handleAreaRect =
                handleArea.AddComponent<RectTransform>();
            handleAreaRect.anchorMin = Vector2.zero;
            handleAreaRect.anchorMax = Vector2.one;
            handleAreaRect.offsetMin =
                new Vector2(5f, 0f);
            handleAreaRect.offsetMax =
                new Vector2(-5f, 0f);

            GameObject handleGo =
                new GameObject("Handle");
            handleGo.transform.SetParent(
                handleArea.transform,
                false
            );

            RectTransform handleRect =
                handleGo.AddComponent<RectTransform>();
            handleRect.sizeDelta =
                new Vector2(14f, 0f);

            Image handleImage =
                handleGo.AddComponent<Image>();
            handleImage.color = _referenceTextColor;

            slider.handleRect = handleRect;

            float minValue = entry.morph.min;
            float maxValue = entry.morph.max;

            if (maxValue <= minValue)
            {
                minValue = -1f;
                maxValue = 1f;
            }

            bool invertHeightSemantic =
                _subsection != null &&
                string.Equals(
                    _subsection.val,
                    "Height",
                    StringComparison.OrdinalIgnoreCase
                );

            if (invertHeightSemantic)
            {
                slider.minValue = -maxValue;
                slider.maxValue = -minValue;
                slider.value = -entry.morph.morphValue;
            }
            else
            {
                slider.minValue = minValue;
                slider.maxValue = maxValue;
                slider.value = entry.morph.morphValue;
            }

            GameObject valueGo =
                new GameObject("Value");
            valueGo.transform.SetParent(row.transform, false);

            LayoutElement valueLayout =
                valueGo.AddComponent<LayoutElement>();
            valueLayout.preferredWidth = 70f;
            valueLayout.minWidth = 60f;

            Text valueText =
                valueGo.AddComponent<Text>();
            valueText.font = _referenceFont;
            valueText.fontSize =
                Mathf.Max(11, _referenceFontSize - 8);
            valueText.color = _referenceTextColor;
            valueText.alignment =
                TextAnchor.MiddleCenter;
            valueText.text =
                slider.value.ToString("0.000");

            BodyMorphEntry captured = entry;
            bool capturedInvertHeight =
                invertHeightSemantic;

            slider.onValueChanged.AddListener(
                delegate(float value)
                {
                    EnsureBodyBaselineForSelectedPerson();

                    if (captured != null &&
                        captured.morph != null)
                    {
                        captured.morph.morphValue =
                            capturedInvertHeight
                            ? -value
                            : value;
                    }

                    PersonEntry livePerson =
                        GetSelectedPerson();

                    if (livePerson != null &&
                        _activeBodyPresetByPerson.ContainsKey(
                            livePerson.uid))
                    {
                        ClearActiveBodyPresetForPerson(
                            livePerson.uid
                        );
                    }

                    if (valueText != null)
                        valueText.text = value.ToString("0.000");
                }
            );

            GameObject resetGo =
                new GameObject("Reset");
            resetGo.transform.SetParent(
                row.transform,
                false
            );

            LayoutElement resetLayout =
                resetGo.AddComponent<LayoutElement>();
            resetLayout.preferredWidth = 74f;
            resetLayout.minWidth = 66f;

            Image resetImage =
                resetGo.AddComponent<Image>();
            resetImage.color = _referenceButtonColor;

            Button resetButton =
                resetGo.AddComponent<Button>();

            if (_haveReferenceButtonColors)
                resetButton.colors =
                    _referenceButtonColors;

            GameObject resetTextGo =
                new GameObject("Label");
            resetTextGo.transform.SetParent(
                resetGo.transform,
                false
            );

            RectTransform resetTextRect =
                resetTextGo.AddComponent<RectTransform>();
            resetTextRect.anchorMin = Vector2.zero;
            resetTextRect.anchorMax = Vector2.one;
            resetTextRect.offsetMin =
                new Vector2(2f, 1f);
            resetTextRect.offsetMax =
                new Vector2(-2f, -1f);

            Text resetText =
                resetTextGo.AddComponent<Text>();
            resetText.font = _referenceFont;
            resetText.fontSize =
                Mathf.Max(10, _referenceFontSize - 9);
            resetText.color = _referenceTextColor;
            resetText.alignment =
                TextAnchor.MiddleCenter;
            resetText.resizeTextForBestFit = true;
            resetText.resizeTextMinSize = 8;
            resetText.resizeTextMaxSize =
                Mathf.Max(11, _referenceFontSize - 7);
            resetText.text = "RESET";

            resetButton.onClick.AddListener(
                delegate
                {
                    ResetSingleBodyMorph(
                        captured,
                        slider,
                        valueText,
                        capturedInvertHeight
                    );
                }
            );
        }

        private void RebuildBodyEditorPage()
        {
            if (_bodyRowsRoot == null)
                return;

            for (int i =
                     _bodyRowsRoot.transform.childCount - 1;
                 i >= 0;
                 i--)
            {
                Destroy(
                    _bodyRowsRoot.transform
                        .GetChild(i)
                        .gameObject
                );
            }

            PersonEntry person = GetSelectedPerson();

            if (person == null)
            {
                if (_bodyStatusText != null)
                    _bodyStatusText.text =
                        "BODY — select a Character";

                return;
            }

            RebuildBodyMorphIndex();
            EnsureBodyBaselineForSelectedPerson();

            string subsection =
                _subsection != null
                ? _subsection.val
                : "Presets";

            string bodyProfile =
                GetBodyEditorProfile(person);

            UpdateBodySubNavVisuals();
            RebuildBodyProfileNav();
            UpdateBodyProfileVisuals();

            bool fineTune =
                string.Equals(
                    subsection,
                    "Fine Tune",
                    StringComparison.OrdinalIgnoreCase
                );

            RebuildBodyFineNav();

            if (_bodyFineNavRoot != null)
                _bodyFineNavRoot.SetActive(fineTune);

            if (_bodyFineModeRoot != null)
                _bodyFineModeRoot.SetActive(fineTune);

            UpdateBodyFineModeVisuals();

            if (_bodyRowsRect != null)
            {
                _bodyRowsRect.offsetMax =
                    new Vector2(
                        -10f,
                        fineTune ? -200f : -124f
                    );
            }

            UpdateBodyFineNavVisuals();

            bool presetsMode =
                string.Equals(
                    subsection,
                    "Presets",
                    StringComparison.OrdinalIgnoreCase
                );

            if (_bodyPresetNavRoot != null)
                _bodyPresetNavRoot.SetActive(presetsMode);

            if (_bodyPresetSexRoot != null)
                _bodyPresetSexRoot.SetActive(false);

            if (presetsMode)
            {
                if (_bodyFineNavRoot != null)
                    _bodyFineNavRoot.SetActive(false);

                if (_bodyFineModeRoot != null)
                    _bodyFineModeRoot.SetActive(false);

                if (_bodyRowsRect != null)
                {
                    _bodyRowsRect.offsetMax =
                        new Vector2(
                            -10f,
                            -162f
                        );
                }

                UpdateBodyPresetNavVisuals();

                if (!_bodyPresetCatalogScanned &&
                    !_bodyPresetScanRunning)
                {
                    RequestBodyPresetCatalogScan();
                }

                List<BodyPresetEntry> filteredPresets =
                    GetFilteredBodyPresetEntries();

                int presetPageCount =
                    Mathf.Max(
                        1,
                        Mathf.CeilToInt(
                            filteredPresets.Count /
                            (float)BODY_PRESETS_PER_PAGE
                        )
                    );

                int presetPage =
                    _catalogPage != null
                    ? Mathf.RoundToInt(
                        _catalogPage.val
                    )
                    : 1;

                presetPage =
                    Mathf.Clamp(
                        presetPage,
                        1,
                        presetPageCount
                    );

                if (_catalogPage != null)
                {
                    _catalogPage.valNoCallback =
                        presetPage;
                }

                BuildBodyPresetGrid(
                    filteredPresets,
                    presetPage
                );

                if (_bodyStatusText != null)
                {
                    string browseProfile =
                        GetBodyPresetBrowseSex();

                    _bodyStatusText.text =
                        _bodyPresetScanRunning
                        ? "BODY PRESETS — scanning... " +
                          _bodyPresetEntries.Count +
                          " relevant"
                        : "BODY PRESETS — " +
                          GetBodyProfileLabel(
                              browseProfile
                          ) +
                          (_showIncompatibleBodyPresets
                              ? " | INCOMPATIBLE ON"
                              : " | COMPATIBLE") +
                          " | " +
                          _bodyPresetView.ToUpperInvariant() +
                          " | " +
                          filteredPresets.Count +
                          " preset(s)";
                }

                if (_bodyPageText != null)
                {
                    _bodyPageText.text =
                        presetPage +
                        " / " +
                        presetPageCount;
                }

                _lastRenderedBodyPage =
                    presetPage;
                _lastRenderedBodyUid =
                    person.uid;
                _lastRenderedBodySubsection =
                    subsection;
                _lastRenderedBodyProfile =
                    bodyProfile;
                _lastRenderedBodyFineGroup =
                    _bodyFineGroup;
                _lastRenderedBodyFineMode =
                    _bodyFineMode;
                _lastRenderedBodyPresetView =
                    _bodyPresetView;
                _lastRenderedBodyPresetBrowseSex =
                    GetBodyPresetBrowseSex();
                _lastRenderedBodyPresetShowIncompatible =
                    _showIncompatibleBodyPresets;

                return;
            }
            else
            {
                if (_bodyPresetNavRoot != null)
                    _bodyPresetNavRoot.SetActive(false);

                if (_bodyPresetSexRoot != null)
                    _bodyPresetSexRoot.SetActive(false);
            }

            List<BodyMorphEntry> filtered =
                GetBodyMorphsForCurrentSubsection();

            int pageCount =
                Mathf.Max(
                    1,
                    Mathf.CeilToInt(
                        filtered.Count /
                        (float)BODY_MORPHS_PER_PAGE
                    )
                );

            int page =
                _catalogPage != null
                ? Mathf.RoundToInt(_catalogPage.val)
                : 1;

            page = Mathf.Clamp(page, 1, pageCount);

            if (_catalogPage != null)
                _catalogPage.valNoCallback = page;

            int start =
                (page - 1) *
                BODY_MORPHS_PER_PAGE;

            int end =
                Mathf.Min(
                    start + BODY_MORPHS_PER_PAGE,
                    filtered.Count
                );

            for (int i = start; i < end; i++)
                CreateBodyMorphSliderRow(filtered[i]);

            if (_bodyStatusText != null)
            {
                string installedHint = "";

                if (fineTune &&
                    string.Equals(
                        _bodyFineMode,
                        "Advanced",
                        StringComparison.OrdinalIgnoreCase) &&
                    filtered.Count <= 2)
                {
                    installedHint =
                        " | installed Person exposes only " +
                        filtered.Count +
                        " compatible morph(s)";
                }

                _bodyStatusText.text =
                    "BODY — " +
                    subsection.ToUpperInvariant() +
                    (fineTune
                        ? " / " + _bodyFineGroup.ToUpperInvariant() +
                          " / " + _bodyFineMode.ToUpperInvariant()
                        : "") +
                    " | " +
                    GetBodyProfileLabel(bodyProfile) +
                    " | " +
                    filtered.Count +
                    " morph(s)" +
                    installedHint;
            }

            if (_bodyPageText != null)
            {
                _bodyPageText.text =
                    page + " / " + pageCount;
            }

            _lastRenderedBodyPage = page;
            _lastRenderedBodyUid = person.uid;
            _lastRenderedBodySubsection = subsection;
            _lastRenderedBodyProfile = bodyProfile;
            _lastRenderedBodyFineGroup = _bodyFineGroup;
            _lastRenderedBodyFineMode = _bodyFineMode;
            _lastRenderedBodyPresetView = _bodyPresetView;
            _lastRenderedBodyPresetBrowseSex = GetBodyPresetBrowseSex();
            _lastRenderedBodyPresetShowIncompatible = _showIncompatibleBodyPresets;
        }

        private void ApplyLayout()
        {
            if (_rosterRect == null || _grid == null)
                return;

            int columns = Mathf.Clamp(Mathf.RoundToInt(_columns != null ? _columns.val : 3f), 1, 8);
            float bw = _buttonWidth != null ? _buttonWidth.val : 220f;
            float bh = _buttonHeight != null ? _buttonHeight.val : 50f;
            float spacing = _buttonSpacing != null ? _buttonSpacing.val : 5f;
            float width = _panelWidth != null ? _panelWidth.val : 720f;

            int rows = _persons.Count > 0
                ? Mathf.CeilToInt(_persons.Count / (float)columns)
                : 0;
            float height = rows > 0
                ? 20f + rows * bh + Mathf.Max(0, rows - 1) * spacing
                : 0f;

            _rosterRect.anchoredPosition = new Vector2(
                _panelX != null ? _panelX.val : 0f,
                GetRosterTopY()
            );
            _rosterRect.sizeDelta = new Vector2(width, Mathf.Max(1f, height));

            _grid.constraintCount = columns;
            _grid.cellSize = new Vector2(bw, bh);
            _grid.spacing = new Vector2(spacing, spacing);

            if (_rosterRoot != null)
                _rosterRoot.SetActive(ShouldShowRoster() && _persons.Count > 0);

            ApplyAddCharacterLayout();
            ApplyCharacterContextLayout();
            ApplySectionNavLayout();
            ApplyLookCatalogLayout();
            ApplyHairCatalogLayout();
            ApplyFaceEditorLayout();
            ApplyBodyEditorLayout();
            _lastLayoutHash = GetLayoutHash();
        }

        private int GetLayoutHash()
        {
            int h = 17;
            h = h * 31 + Mathf.RoundToInt((_panelX != null ? _panelX.val : 0f) * 10f);
            h = h * 31 + Mathf.RoundToInt((_panelY != null ? _panelY.val : 0f) * 10f);
            h = h * 31 + Mathf.RoundToInt((_panelWidth != null ? _panelWidth.val : 720f) * 10f);
            h = h * 31 + Mathf.RoundToInt((_buttonWidth != null ? _buttonWidth.val : 220f) * 10f);
            h = h * 31 + Mathf.RoundToInt((_buttonHeight != null ? _buttonHeight.val : 50f) * 10f);
            h = h * 31 + Mathf.RoundToInt((_buttonSpacing != null ? _buttonSpacing.val : 5f) * 10f);
            h = h * 31 + Mathf.RoundToInt(_columns != null ? _columns.val : 3f);
            return h;
        }

        private bool HasSelectedPersonForRemoval()
        {
            return !IsCharacterCreationMode() &&
                   GetSelectedPerson() != null;
        }

        private void RemoveSelectedCharacter()
        {
            if (_controlledSpawnInProgress ||
                _lookApplyInProgress ||
                _hairPresetApplyInProgress)
                return;

            PersonEntry selected = GetSelectedPerson();

            if (selected == null ||
                selected.atom == null ||
                string.IsNullOrEmpty(selected.uid))
            {
                return;
            }

            StartCoroutine(
                RemoveSelectedCharacterCoroutine(
                    selected.atom,
                    selected.uid
                )
            );
        }

        // HeelAdjust2.21 subscribes to the global atom UID event. During a
        // Person removal VaM can fire that event after destroying HeelAdjust's
        // popup but before its OnDestroy unsubscribes. Remove this Person's
        // clothing plugin through its owning manager while the Person is live.
        private IEnumerator RemoveHeelAdjustBeforePerson(
            Atom person, Action<bool> completed)
        {
            bool ready = true;
            int found = 0;
            // Clothing plugin storables live below DAZClothingItem and do not
            // appear in Atom.GetStorableIDs(). Inspect their actual plugin
            // manager components instead of the Person's top-level registry.
            MVRPluginManager[] managers = person == null ? null :
                person.GetComponentsInChildren<MVRPluginManager>(true);
            for (int i = 0; managers != null && i < managers.Length; i++)
            {
                MVRPluginManager manager = managers[i];
                if (manager == null) continue;
                bool hadTarget = false;

                try
                {
                    JSONClass managerState = manager.GetJSON(true, true, true);
                    JSONClass plugins = managerState == null ? null :
                        managerState["plugins"].AsObject;
                    if (plugins == null) continue;

                    List<string> slots = new List<string>();
                    foreach (string slot in plugins.Keys)
                    {
                        string path = plugins[slot].Value;
                        if (path.IndexOf("CheesyFX.HeelAdjust2",
                                StringComparison.OrdinalIgnoreCase) >= 0)
                            slots.Add(slot);
                    }

                    for (int j = 0; j < slots.Count; j++)
                    {
                        string slot = slots[j];
                        hadTarget = true;
                        found++;
                        manager.RemovePluginWithUID(slot);
                        SuperController.LogMessage(
                            "CharacterRouter v240 REMOVE | stage=HEEL_REMOVED" +
                            " | person=" + person.uid + " | manager=" +
                            manager.name + " | slot=" + slot);
                    }
                }
                catch (Exception e)
                {
                    if (hadTarget) ready = false;
                    SuperController.LogError(
                        "CharacterRouter v240 REMOVE | stage=HEEL_REMOVE_ERROR" +
                        " | person=" + person.uid +
                        " | detail=" + e.Message);
                }
            }

            SuperController.LogMessage(
                "CharacterRouter v240 REMOVE | stage=HEEL_SCAN" +
                " | person=" + (person == null ? "" : person.uid) +
                " | managers=" + (managers == null ? 0 : managers.Length) +
                " | found=" + found + " | ready=" + ready);

            // Let Unity run HeelAdjust2.OnDestroy and unsubscribe from the
            // atom UID event before VaM changes the list of atoms.
            yield return new WaitForEndOfFrame();
            yield return null;
            if (completed != null) completed(ready);
        }

        private IEnumerator RemoveBlackWidowClothingPluginsBeforePerson(Atom person)
        {
            if (person == null)
                yield break;

            MVRPluginManager[] managers =
                person.GetComponentsInChildren<MVRPluginManager>(true);
            int removed = 0;
            for (int i = 0; managers != null && i < managers.Length; i++)
            {
                MVRPluginManager manager = managers[i];
                if (manager == null ||
                    !manager.name.StartsWith("DitzyDitz:BW_",
                        StringComparison.OrdinalIgnoreCase))
                    continue;

                try
                {
                    JSONClass state = manager.GetJSON(true, true, true);
                    JSONClass plugins = state == null ? null :
                        state["plugins"].AsObject;
                    if (plugins == null)
                        continue;

                    List<string> slots = new List<string>();
                    foreach (string slot in plugins.Keys)
                    {
                        string path = plugins[slot].Value;
                        if (path.IndexOf("Stopper.CUAClothing",
                                StringComparison.OrdinalIgnoreCase) >= 0)
                            slots.Add(slot);
                    }

                    for (int s = 0; s < slots.Count; s++)
                    {
                        try
                        {
                            manager.RemovePluginWithUID(slots[s]);
                            removed++;
                        }
                        catch (Exception e)
                        {
                            SuperController.LogError(
                                "CharacterRouter v240 REMOVE | stage=PLUGIN_REMOVE_ERROR" +
                                " | person=" + person.uid +
                                " | manager=" + manager.name +
                                " | slot=" + slots[s] +
                                " | detail=" + e);
                        }
                    }
                }
                catch (Exception e)
                {
                    SuperController.LogError(
                        "CharacterRouter v240 REMOVE | stage=PLUGIN_SCAN_ERROR" +
                        " | person=" + person.uid +
                        " | manager=" + manager.name +
                        " | detail=" + e);
                }
            }

            SuperController.LogMessage(
                "CharacterRouter v240 REMOVE | stage=BW_PLUGINS_REMOVED" +
                " | person=" + person.uid + " | count=" + removed);
            // Wait for CUAClothing.OnDisable to release its referenced CUA.
            yield return new WaitForEndOfFrame();
            yield return null;
        }

        private IEnumerator RemoveSelectedCharacterCoroutine(
            Atom atom,
            string uid)
        {
            if (atom == null)
                yield break;

            _controlledSpawnInProgress = true;

            bool heelReady = false;
            yield return StartCoroutine(RemoveHeelAdjustBeforePerson(
                atom, value => heelReady = value));
            if (!heelReady)
            {
                _controlledSpawnInProgress = false;
                if (_spawnStatus != null)
                    _spawnStatus.valNoCallback =
                        "Character removal blocked: HeelAdjust2 cleanup failed.";
                yield break;
            }

            AppendSceneLookDiagnostic(
                "=== REMOVE BEGIN | uid=" + (uid ?? "") + " ==="
            );
            DumpSceneLookRuntimeState(
                atom, 0, "REMOVE BEFORE RemoveAtom", uid
            );

            // prestigitis HeelAdjust leaves foot pose/colliders behind if its
            // plugin is destroyed while still enabled. Let OnDisable run on
            // this Person before ModelPluginAdapter removes its owned slot.
            int prestigitisDisabled =
                _modelPluginAdapter.DisableManagedPrestigitisHeel(atom);
            SuperController.LogMessage(
                "CharacterRouter v254 REMOVE | stage=PRESTIGITIS_DISABLED" +
                " | person=" + uid +
                " | count=" + prestigitisDisabled);
            if (prestigitisDisabled > 0)
            {
                yield return new WaitForEndOfFrame();
                yield return new WaitForFixedUpdate();
            }

            // v146: BODY presets are live transient geometry, including genital
            // morphs on native Futanari. They must be physically removed from the
            // live DAZMorphBanks BEFORE RemoveAtom; clearing only Router's preset
            // bookkeeping leaves adapter-owned morph objects/references behind and
            // can poison a later Person that reuses the same UID/runtime banks.
            _bodyPresetAdapter.ClearActive(atom, uid);

            // Clean up only adapter-owned DecalMaker instances before the Person
            // disappears; all other plugins remain outside adapter ownership.
            _decalMakerAdapter.ClearManaged(atom);
            _modelPluginAdapter.ClearManaged(atom);
            _sceneCuaAccessoryAdapter.ClearManaged(atom);

            int blackWidowCuaBeforeRemoval =
                GetBlackWidowClothingCuaAtoms(uid).Count;
            if (blackWidowCuaBeforeRemoval > 0)
            {
                SuperController.LogMessage(
                    "CharacterRouter v240 REMOVE | stage=CUA_BEFORE_PERSON" +
                    " | person=" + uid +
                    " | count=" + blackWidowCuaBeforeRemoval);

                yield return StartCoroutine(
                    RemoveBlackWidowClothingPluginsBeforePerson(atom));
            }

            try
            {
                SuperController.singleton.RemoveAtom(atom);
            }
            catch (Exception e)
            {
                SuperController.LogError(
                    "CharacterRouter: could not remove selected Character: " + e
                );

                _controlledSpawnInProgress = false;
                yield break;
            }

            _decalMakerAdapter.ForgetPerson(uid);
            _modelPluginAdapter.ForgetPerson(uid);

            // Clear per-Character state only after VaM accepts removal.
            // Favorites/Recent are intentionally global.
            ClearPerPersonStateForFreshAtom(uid);
            ClearBodyBaselineForPerson(uid);
            ClearFaceBaselineForPerson(uid);
            ClearBodyProfileForPerson(uid);
            ClearActiveBodyPresetForPerson(uid);

            // VaM removes atoms asynchronously enough that one or two frames can still
            // expose the old roster entry.
            yield return null;
            yield return new WaitForEndOfFrame();
            yield return null;

            if (blackWidowCuaBeforeRemoval > 0)
                yield return StartCoroutine(
                    RemoveBlackWidowClothingCuaAtoms(uid));

            Atom remainingAfterRemoval = null;
            try
            {
                remainingAfterRemoval =
                    SuperController.singleton.GetAtomByUid(uid);
            }
            catch { }

            AppendSceneLookDiagnostic(
                "REMOVE AFTER WAIT | uid=" + (uid ?? "") +
                " | atomStillPresent=" + (remainingAfterRemoval != null)
            );
            DumpCustomUnityAssetAtoms("REMOVE AFTER NORMAL WAIT | uid=" + (uid ?? ""));
            AppendSceneLookDiagnostic(
                "=== REMOVE END | uid=" + (uid ?? "") + " ===\n"
            );

            _controlledSpawnInProgress = false;

            RefreshRoster(true);
            RebuildLookCatalogPage();

            if (_spawnStatus != null)
                _spawnStatus.valNoCallback =
                    "Character removed.";
        }

        private void RebuildRosterButtons()
        {
            if (_rosterRoot == null)
                return;

            for (int i = _rosterRoot.transform.childCount - 1; i >= 0; i--)
                Destroy(_rosterRoot.transform.GetChild(i).gameObject);

            _rosterButtons.Clear();

            for (int i = 0; i < _persons.Count; i++)
            {
                PersonEntry p = _persons[i];
                CreatePersonButton(p);
            }

            ApplyLayout();
            UpdateButtonSelectionVisuals();
            UpdateCharacterContextVisuals();
        }

        private void CreateAddCharacterRosterButton(string sex)
        {
            if (_rosterRoot == null)
                return;

            string objectName =
                sex == "M"
                ? "AddMaleButton"
                : (sex == "X"
                    ? "AddFutanariButton"
                    : "AddFemaleButton");

            string buttonLabel =
                sex == "M"
                ? "+ ADD MALE"
                : (sex == "X"
                    ? "+ ADD FUTANARI"
                    : "+ ADD FEMALE");

            GameObject go =
                new GameObject(objectName);
            go.transform.SetParent(
                _rosterRoot.transform,
                false
            );

            Image img = go.AddComponent<Image>();
            img.color = _referenceButtonColor;

            Button button = go.AddComponent<Button>();

            if (_haveReferenceButtonColors)
                button.colors = _referenceButtonColors;

            if (sex == "M")
                button.onClick.AddListener(BeginAddMale);
            else if (sex == "X")
                button.onClick.AddListener(BeginAddFutanari);
            else
                button.onClick.AddListener(BeginAddFemale);

            GameObject textGo =
                new GameObject("Label");
            textGo.transform.SetParent(
                go.transform,
                false
            );

            RectTransform tr =
                textGo.AddComponent<RectTransform>();
            tr.anchorMin = Vector2.zero;
            tr.anchorMax = Vector2.one;
            tr.offsetMin = new Vector2(6f, 2f);
            tr.offsetMax = new Vector2(-6f, -2f);

            Text text = textGo.AddComponent<Text>();
            text.font = _referenceFont;
            text.fontSize = _referenceFontSize;
            text.alignment = TextAnchor.MiddleCenter;
            text.color = _referenceTextColor;
            text.resizeTextForBestFit = true;
            text.resizeTextMinSize = 11;
            text.resizeTextMaxSize =
                Mathf.Max(15, _referenceFontSize);
            text.text = buttonLabel;
        }

        private void CreateRemoveSelectedCharacterRosterButton()
        {
            if (_rosterRoot == null)
                return;

            GameObject go = new GameObject("RemoveSelectedCharacterButton");
            go.transform.SetParent(_rosterRoot.transform, false);

            Image img = go.AddComponent<Image>();
