            tr.anchorMax = Vector2.one;
            tr.offsetMin = new Vector2(6f, 2f);
            tr.offsetMax = new Vector2(-6f, -2f);

            Text text = textGo.AddComponent<Text>();
            text.font = _referenceFont;
            text.fontSize = _referenceFontSize;
            text.alignment = TextAnchor.MiddleCenter;
            text.color = _referenceTextColor;
            text.resizeTextForBestFit = true;
            text.resizeTextMinSize = 11;
            text.resizeTextMaxSize = Mathf.Max(15, _referenceFontSize);
            text.text = "- REMOVE CHARACTER";
        }

        private void SelectExistingCharacterFromRoster(string uid)
        {
            if (_selectedCharacter == null || string.IsNullOrEmpty(uid))
                return;

            // While the Add Female/Male/Futanari picker is open, the chooser can
            // already contain the UID of the character that was selected before
            // entering creation mode. Assigning that same value again does not fire
            // JSONStorableStringChooser's callback, so the old v61 HUD remained stuck
            // in NEW CHARACTER mode when the user clicked that same roster button.
            // Exit creation mode explicitly first, then select/refresh the requested
            // existing Person regardless of whether its UID changed.
            if (IsCharacterCreationMode())
                _creationModeSex = "";

            if (_selectedCharacter.val != uid)
            {
                _selectedCharacter.val = uid;
                return;
            }

            // Same chooser value: invoke the normal selection refresh path manually.
            OnSelectedCharacterChanged(uid);
        }

        private void CreatePersonButton(PersonEntry person)
        {
            GameObject go = new GameObject("PersonButton_" + person.uid);
            go.transform.SetParent(_rosterRoot.transform, false);

            Image img = go.AddComponent<Image>();
            img.color = _referenceButtonColor;

            Button button = go.AddComponent<Button>();
            if (_haveReferenceButtonColors)
                button.colors = _referenceButtonColors;

            string capturedUid = person.uid;
            button.onClick.AddListener(delegate {
                SelectExistingCharacterFromRoster(capturedUid);
            });

            GameObject textGo = new GameObject("Label");
            textGo.transform.SetParent(go.transform, false);

            RectTransform tr = textGo.AddComponent<RectTransform>();
            tr.anchorMin = Vector2.zero;
            tr.anchorMax = Vector2.one;
            tr.offsetMin = new Vector2(6f, 2f);
            tr.offsetMax = new Vector2(-6f, -2f);

            Text text = textGo.AddComponent<Text>();
            text.font = _referenceFont;
            text.fontSize = _referenceFontSize;
            text.alignment = TextAnchor.MiddleCenter;
            text.color = _referenceTextColor;
            text.resizeTextForBestFit = true;
            text.resizeTextMinSize = 12;
            text.resizeTextMaxSize = Mathf.Max(16, _referenceFontSize);

            string label = GetDisplayName(person);
            if (_showSexInLabel != null && _showSexInLabel.val && person.sex != "?")
                label += " [" + person.sex + "]";
            text.text = label;

            _rosterButtons.Add(button);
        }

        private void UpdateButtonSelectionVisuals()
        {
            string selected = _selectedCharacter != null ? _selectedCharacter.val : "";

            for (int i = 0; i < _rosterButtons.Count && i < _persons.Count; i++)
            {
                Button b = _rosterButtons[i];
                if (b == null) continue;

                Image img = b.GetComponent<Image>();
                if (img == null) continue;

                bool isSelected =
                    !IsCharacterCreationMode() &&
                    _persons[i].uid == selected;
                if (isSelected)
                    img.color = GetSelectedHudButtonColor();
                else
                    img.color = _referenceButtonColor;
            }

            UpdateCharacterContextVisuals();
        }

