        private void LateUpdate()
        {
            _sceneCuaAccessoryAdapter.Sync2BSceneHairAnchors();
        }

        private void Update()
        {
            try
            {
                UpdateSpawnStatus();

                if (_aliasesData != null &&
                    (_aliasesData.val == null ? "" : _aliasesData.val) != _lastAliasesData)
                {
                    LoadAliasesData();
                    SyncSelectedButtonName();
                    RebuildRosterButtons();
                }

                if (_activeLooksData != null &&
                    (_activeLooksData.val == null ? "" : _activeLooksData.val) != _lastActiveLooksData)
                {
                    LoadActiveLooksData();
                    RebuildLookCatalogPage();
                }

                if (_favoriteLooksData != null &&
                    (_favoriteLooksData.val == null ? "" : _favoriteLooksData.val) != _lastFavoriteLooksData)
                {
                    LoadFavoriteLooksData();
                    RebuildLookCatalogPage();
                }

                if (_favoriteHairPresetsData != null &&
                    (_favoriteHairPresetsData.val == null ? "" : _favoriteHairPresetsData.val) != _lastFavoriteHairPresetsData)
                {
                    LoadFavoriteHairPresetsData();
                    RebuildHairCatalogPage();
                }

                if (_activeHairPresetsData != null &&
                    (_activeHairPresetsData.val == null ? "" : _activeHairPresetsData.val) != _lastActiveHairPresetsData)
                {
                    LoadActiveHairPresetsData();
                    RebuildHairCatalogPage();
                }

                if (_originalHairSnapshotsData != null &&
                    (_originalHairSnapshotsData.val == null ? "" : _originalHairSnapshotsData.val) != _lastOriginalHairSnapshotsData)
                {
                    LoadOriginalHairSnapshotsData();
                    RebuildHairCatalogPage();
                }

                if (_recentLooksData != null &&
                    (_recentLooksData.val == null ? "" : _recentLooksData.val) != _lastRecentLooksData)
                {
                    LoadRecentLooksData();
                    RebuildLookCatalogPage();
                }

                if (_originalLooksData != null &&
                    (_originalLooksData.val == null ? "" : _originalLooksData.val) != _lastOriginalLooksData)
                {
                    LoadOriginalLooksData();
                }

                if (_favoriteBodyPresetsData != null &&
                    (_favoriteBodyPresetsData.val == null ? "" : _favoriteBodyPresetsData.val) != _lastFavoriteBodyPresetsData)
                {
                    LoadFavoriteBodyPresetsData();
                    RebuildBodyEditorPage();
                }

                if (_recentBodyPresetsData != null &&
                    (_recentBodyPresetsData.val == null ? "" : _recentBodyPresetsData.val) != _lastRecentBodyPresetsData)
                {
                    LoadRecentBodyPresetsData();
                    RebuildBodyEditorPage();
                }

                if (_activeBodyPresetsData != null &&
                    (_activeBodyPresetsData.val == null ? "" : _activeBodyPresetsData.val) != _lastActiveBodyPresetsData)
                {
                    LoadActiveBodyPresetsData();
                    RebuildBodyEditorPage();
                }

                if (_bodyBaselinesData != null &&
                    (_bodyBaselinesData.val == null ? "" : _bodyBaselinesData.val) != _lastBodyBaselinesData)
                {
                    LoadBodyBaselinesData();
                    RebuildBodyEditorPage();
                }

                if (_faceBaselinesData != null &&
                    (_faceBaselinesData.val == null ? "" : _faceBaselinesData.val) != _lastFaceBaselinesData)
                {
                    LoadFaceBaselinesData();
                    RebuildFaceEditorPage();
                }

                if (_bodyProfilesData != null &&
                    (_bodyProfilesData.val == null ? "" : _bodyProfilesData.val) != _lastBodyProfilesData)
                {
                    LoadBodyProfilesData();
                    _bodyFineGroup = "";
                    RebuildBodyMorphIndex();
                    RebuildFaceEditorPage();
                    RebuildBodyEditorPage();
                }

                if (_autoDiscover != null && _autoDiscover.val && Time.unscaledTime >= _nextScanTime)
                {
                    _nextScanTime = Time.unscaledTime + 0.75f;
                    RefreshRoster(false);
                }

                if (Time.unscaledTime >= _nextCanvasSearchTime)
                {
                    _nextCanvasSearchTime = Time.unscaledTime + 1.0f;
                    if (_multiMenuCanvas == null ||
                        _rosterRoot == null ||
                        _sectionNavRoot == null ||
                        _lookCatalogRoot == null ||
                        _hairCatalogRoot == null ||
                        _faceEditorRoot == null ||
                        _bodyEditorRoot == null)
                    {
                        ReacquireCanvas();
                    }
                }

                if (Time.unscaledTime >= _nextBindingSearchTime)
                {
                    _nextBindingSearchTime = Time.unscaledTime + 1.0f;

                    // Always reacquire. A ScreenDock plugin can be removed/replaced while
                    // CharacterRouter stays loaded; stale JSONStorable references may remain
                    // non-null but no longer track the live HUD Open / Active Page values.
                    FindScreenDockBindings();
                }

                bool showCharacterHud = ShouldShowRoster();

                if (_addCharacterRoot != null)
                    _addCharacterRoot.SetActive(showCharacterHud);

                if (_rosterRoot != null)
                    _rosterRoot.SetActive(showCharacterHud && _persons.Count > 0);

                UpdateCharacterContextVisuals();

                if (_sectionNavRoot != null)
                    _sectionNavRoot.SetActive(showCharacterHud);

                bool showLooksCatalog =
                    showCharacterHud &&
                    _section != null &&
                    string.Equals(
                        _section.val,
                        "Looks",
                        StringComparison.OrdinalIgnoreCase
                    ) &&
                    (GetSelectedPerson() != null ||
                     IsCharacterCreationMode());

                if (_lookCatalogRoot != null)
                    _lookCatalogRoot.SetActive(showLooksCatalog);

                bool showHairCatalog =
                    showCharacterHud &&
                    _section != null &&
                    string.Equals(
                        _section.val,
                        "Hair",
                        StringComparison.OrdinalIgnoreCase
                    ) &&
                    GetSelectedPerson() != null;

                if (showHairCatalog)
                {
                    EnsureHairCatalogRoot();
                    if (_hairCatalogRoot != null)
                    {
                        _hairCatalogRoot.SetActive(true);
                        _hairCatalogRoot.transform.SetAsLastSibling();
                    }
                }
                else if (_hairCatalogRoot != null)
                {
                    _hairCatalogRoot.SetActive(false);
                }

                if (showHairCatalog && _hairCatalogRoot != null)
                {
                    int liveHairPage = _catalogPage != null
                        ? Mathf.RoundToInt(_catalogPage.val)
                        : 1;
                    PersonEntry hairPerson = GetSelectedPerson();
                    string liveHairUid = hairPerson != null ? hairPerson.uid : "";
                    string liveHairSubsection = _subsection != null ? _subsection.val : "All";
                    string liveHairTargetSex = GetHairTargetSex(hairPerson);

                    if (liveHairPage != _lastRenderedHairPage ||
                        liveHairUid != _lastRenderedHairUid ||
                        liveHairSubsection != _lastRenderedHairSubsection ||
                        liveHairTargetSex != _lastRenderedHairTargetSex ||
                        _showIncompatibleHairPresets != _lastRenderedHairShowIncompatible)
                    {
                        RebuildHairCatalogPage();
                    }
                }

                bool showFaceEditor =
                    showCharacterHud &&
                    _section != null &&
                    string.Equals(
                        _section.val,
                        "Face",
                        StringComparison.OrdinalIgnoreCase
                    );

                if (_faceEditorRoot != null)
                    _faceEditorRoot.SetActive(showFaceEditor);

                if (showFaceEditor)
                {
                    int liveFacePage =
                        _catalogPage != null
                        ? Mathf.RoundToInt(_catalogPage.val)
                        : 1;

                    PersonEntry facePerson = GetSelectedPerson();

                    string liveFaceUid =
                        facePerson != null
                        ? facePerson.uid
                        : "";

                    string liveFaceSubsection =
                        _subsection != null
                        ? _subsection.val
                        : "Shape";

                    string liveFaceProfile =
                        GetBodyEditorProfile(facePerson);

                    if (liveFacePage != _lastRenderedFacePage ||
                        liveFaceUid != _lastRenderedFaceUid ||
                        liveFaceSubsection != _lastRenderedFaceSubsection ||
                        liveFaceProfile != _lastRenderedFaceProfile ||
                        _faceMode != _lastRenderedFaceMode)
                    {
                        RebuildFaceEditorPage();
                    }
                }

                bool showBodyEditor =
                    showCharacterHud &&
                    _section != null &&
                    string.Equals(
                        _section.val,
                        "Body",
                        StringComparison.OrdinalIgnoreCase
                    );

                if (_bodyEditorRoot != null)
                    _bodyEditorRoot.SetActive(showBodyEditor);

                if (showBodyEditor)
                {
                    int liveBodyPage =
                        _catalogPage != null
                        ? Mathf.RoundToInt(_catalogPage.val)
                        : 1;

                    PersonEntry bodyPerson =
                        GetSelectedPerson();

                    string liveBodyUid =
                        bodyPerson != null
                        ? bodyPerson.uid
                        : "";

                    string liveBodySubsection =
                        _subsection != null
                        ? _subsection.val
                        : "Presets";

                    string liveBodyProfile =
                        GetBodyEditorProfile(bodyPerson);

                    if (liveBodyPage != _lastRenderedBodyPage ||
                        liveBodyUid != _lastRenderedBodyUid ||
                        liveBodySubsection != _lastRenderedBodySubsection ||
                        liveBodyProfile != _lastRenderedBodyProfile ||
                        _bodyFineGroup != _lastRenderedBodyFineGroup ||
                        _bodyFineMode != _lastRenderedBodyFineMode ||
                        _bodyPresetView != _lastRenderedBodyPresetView ||
                        GetBodyPresetBrowseSex() != _lastRenderedBodyPresetBrowseSex ||
                        _showIncompatibleBodyPresets != _lastRenderedBodyPresetShowIncompatible)
                    {
                        RebuildBodyEditorPage();
                    }
                }

                // Catch page changes made from the ordinary Custom UI slider too.
                if (showLooksCatalog)
                {
                    int livePage = _catalogPage != null
                        ? Mathf.RoundToInt(_catalogPage.val)
                        : 1;

                    string liveSex =
                        GetCurrentAppearanceTargetSex();
                    string liveSubsection = _subsection != null ? _subsection.val : "All";
                    bool liveShowIncompatible =
                        _showIncompatible != null && _showIncompatible.val;

                    if (livePage != _lastRenderedLookPage ||
                        liveSex != _lastRenderedLookSex ||
                        liveSubsection != _lastRenderedLookSubsection ||
                        liveShowIncompatible != _lastRenderedShowIncompatible)
                    {
                        RebuildLookCatalogPage();
                    }
                }

                int layoutHash = GetLayoutHash();
                if (layoutHash != _lastLayoutHash)
                    ApplyLayout();
            }
            catch (Exception e)
            {
                SuperController.LogError("CharacterRouter v46 Update error: " + e);
            }
        }

        public void OnDestroy()
        {
            UnsubscribeSceneEvents();
            ClearHairThumbnailResources();
            DestroyRosterRoot();
        }
    }
}
